/**
 * Options for non-interactive marketplace commands
 */
interface MarketplaceOptions {
  // Common
  force?: boolean;
  json?: boolean;

  // Creator: list
  skillName?: string;
  displayName?: string;

  // Creator: publish, update, unlist, unpublish
  marketplaceId?: string;
  versionId?: string;
  changelog?: string;
  envVarsJson?: string;

  // Installer: search
  query?: string;
  page?: string;
  limit?: string;

  // Installer: install, update, uninstall
  envVars?: string;
}

// Valid creator actions
const CREATOR_ACTIONS = ['list', 'publish', 'update', 'unlist', 'unpublish', 'view'] as const;
type CreatorAction = (typeof CREATOR_ACTIONS)[number];

// Valid installer actions
const INSTALLER_ACTIONS = ['search', 'view', 'install', 'update', 'uninstall', 'installed'] as const;
type InstallerAction = (typeof INSTALLER_ACTIONS)[number];

/**
 * Shows marketplace usage help
 */
