/**
 * Non-interactive: Search marketplace skills
 */
async function searchSkillsNonInteractive(
  marketplaceApi: MarketplaceApiService,
  options: MarketplaceOptions
): Promise<void> {
  const page = options.page ? parseInt(options.page, 10) : 1;
  const limit = options.limit ? parseInt(options.limit, 10) : 10;

  writeProgress(options.query ? `🔍 Searching for "${options.query}"...` : '🔍 Loading marketplace skills...');

  const filters: any = { page, limit, publishedVersionsOnly: true };
  if (options.query) filters.search = options.query;

  const results = await marketplaceApi.searchSkills(filters);
  const skills = results?.data || [];
  const pagination = results?.pagination;

  if (options.json) {
    console.log(JSON.stringify(results, null, 2));
    return;
  }

  if (skills.length === 0) {
    writeInfo(
      options.query ? `📦 No skills found matching "${options.query}".` : '📦 No skills available on the marketplace.'
    );
    return;
  }

  const totalCount = pagination?.totalCount || skills.length;
  const totalPages = pagination?.totalPages || 1;
  console.log(`\n📊 Found ${totalCount} skill(s) (Page ${page}/${totalPages}):\n`);

  for (const skill of skills) {
    console.log(`📦 ${skill.displayName}`);
    console.log(`   ID: ${skill.id}`);
    console.log(`   Name: ${skill.name}`);
    if (skill.description) console.log(`   Description: ${skill.description}`);
    if (typeof skill.installCount !== 'undefined') console.log(`   Installs: ${skill.installCount}`);
    console.log('');
  }
}

/**
 * Non-interactive: View skill details
 */
async function viewSkillNonInteractive(
  marketplaceApi: MarketplaceApiService,
  options: MarketplaceOptions
): Promise<void> {
  const { marketplaceId } = options;

  if (!marketplaceId) {
    console.error('❌ Missing required option: --marketplace-id');
    console.log('\nUsage: lua marketplace install view --marketplace-id <id>');
    throw new Error('Missing required option: --marketplace-id');
  }

  writeProgress('🔄 Loading skill details...');
  const skill = await marketplaceApi.getSkillById(marketplaceId);

  if (options.json) {
    console.log(JSON.stringify(skill, null, 2));
    return;
  }

  console.log(`\n${'='.repeat(60)}`);
  console.log(`📦 ${skill.displayName}`);
  console.log(`${'='.repeat(60)}\n`);

  console.log(`ID: ${skill.id}`);
  console.log(`Name: ${skill.name}`);
  console.log(`Created: ${new Date(skill.createdAt).toLocaleDateString()}`);

  if (skill.description) console.log(`\nDescription: ${skill.description}`);
  if (skill.longDescription) console.log(`\nDetails:\n${skill.longDescription}`);
  if (skill.category) console.log(`\nCategory: ${skill.category}`);
  if (skill.tags?.length) console.log(`Tags: ${skill.tags.join(', ')}`);
  if (typeof skill.installCount !== 'undefined') console.log(`Installs: ${skill.installCount}`);

  if (skill.versions?.length) {
    const publishedVersions = skill.versions.filter((v) => v.published);
    console.log(`\nVersions: ${publishedVersions.length} published / ${skill.versions.length} total`);
    if (publishedVersions.length > 0) {
      const latest = publishedVersions.sort((a, b) => compareVersions(b.version, a.version))[0];
      console.log(`Latest: v${latest.version} (ID: ${latest.id})`);
    }
  }

  console.log(`\n${'='.repeat(60)}\n`);
}

/**
 * Non-interactive: Install a skill
 */
async function installSkillNonInteractive(
  marketplaceApi: MarketplaceApiService,
  config: YamlConfig,
  options: MarketplaceOptions
): Promise<void> {
  const { marketplaceId, versionId, envVars, force } = options;

  if (!marketplaceId || !versionId) {
    console.error('❌ Missing required options');
    console.log(
      '\nUsage: lua marketplace install install --marketplace-id <id> --version-id <id> [--env-vars <k=v,...>]'
    );
    throw new Error('Missing required options');
  }

  const agentId = config.agent?.agentId;
  if (!agentId) {
    console.error('❌ Agent ID not found in configuration.');
    throw new Error('Agent ID not found in configuration.');
  }

  // Parse env vars
  const envVarsConfig: Record<string, string> = {};
  if (envVars) {
    const pairs = envVars.split(',');
    for (const pair of pairs) {
      const [key, ...valueParts] = pair.split('=');
      if (key && valueParts.length > 0) {
        envVarsConfig[key.trim()] = valueParts.join('=').trim();
      }
    }
  }

  if (!force) {
    writeInfo(`\n📋 Installation Summary:`);
    writeInfo(`  Marketplace ID: ${marketplaceId}`);
    writeInfo(`  Version ID: ${versionId}`);
    writeInfo(`  Agent: ${agentId}`);
    if (Object.keys(envVarsConfig).length > 0) {
      writeInfo(`  Env vars: ${Object.keys(envVarsConfig).length} configured`);
    }
    console.error('\n❌ Use --force to confirm installation');
    throw new Error('Operation failed');
  }

  writeProgress('🔄 Installing skill...');
  await marketplaceApi.installSkill(marketplaceId, agentId, {
    versionId,
    envVars: Object.keys(envVarsConfig).length > 0 ? envVarsConfig : undefined,
  });

  writeSuccess('✅ Skill installed successfully!');
  writeInfo(`💡 The skill is now available on agent ${agentId}.`);
  writeHintBlock({
    headline: 'Skill installed locally. Make it live:',
    lines: [
      { label: 'Deploy:', command: 'lua push all --force --auto-deploy' },
      { label: 'Or stage only:', command: 'lua push all --force' },
    ],
    when: 'success',
  });
}

/**
 * Non-interactive: Update an installed skill
 */
async function updateInstalledSkillNonInteractive(
  marketplaceApi: MarketplaceApiService,
  config: YamlConfig,
  apiKey: string,
  options: MarketplaceOptions
): Promise<void> {
  const { skillName, versionId, envVars } = options;

  if (!skillName) {
    console.error('❌ Missing required option: --skill-name');
    console.log(
      '\nUsage: lua marketplace install update --skill-name <name> [--version-id <id>] [--env-vars <k=v,...>]'
    );
    throw new Error('Missing required option: --skill-name');
  }

  const agentId = config.agent?.agentId;
  if (!agentId) {
    console.error('❌ Agent ID not found in configuration.');
    throw new Error('Agent ID not found in configuration.');
  }

  // Find the installed skill
  writeProgress('🔄 Loading installed skills...');
  const installedSkills = await marketplaceApi.getInstalledSkills(agentId);
  const installedSkill = installedSkills?.find((s) => s.name === skillName || s.title === skillName);

  if (!installedSkill) {
    console.error(`❌ Installed skill not found: ${skillName}`);
    if (installedSkills?.length) {
      writeInfo('\nInstalled skills:');
      installedSkills.forEach((s) => {
        writeInfo(`  - ${s.title || s.name}`);
      });
    }
    throw new Error('Operation failed');
  }

  if (!installedSkill.marketplaceSkillId) {
    console.error('❌ Skill is missing marketplace skill ID.');
    throw new Error('Skill is missing marketplace skill ID.');
  }

  // Parse env vars
  let newEnvVars: Record<string, string> | undefined;
  if (envVars) {
    newEnvVars = {};
    const pairs = envVars.split(',');
    for (const pair of pairs) {
      const [key, ...valueParts] = pair.split('=');
      if (key && valueParts.length > 0) {
        newEnvVars[key.trim()] = valueParts.join('=').trim();
      }
    }
  }

  const updatePayload: { versionId?: string; envVars?: Record<string, string> } = {};
  if (versionId) updatePayload.versionId = versionId;
  if (newEnvVars) updatePayload.envVars = newEnvVars;

  if (!updatePayload.versionId && !updatePayload.envVars) {
    console.error('❌ No update specified. Provide --version-id or --env-vars.');
    throw new Error('No update specified. Provide --version-id or --env-vars.');
  }

  writeProgress('🔄 Updating installed skill...');
  await marketplaceApi.updateInstallation(installedSkill.marketplaceSkillId, agentId, updatePayload);
  writeSuccess(`✅ "${installedSkill.title || installedSkill.name}" updated successfully!`);
}

/**
 * Non-interactive: Uninstall a skill
 */
async function uninstallSkillNonInteractive(
  marketplaceApi: MarketplaceApiService,
  config: YamlConfig,
  options: MarketplaceOptions
): Promise<void> {
  const { skillName, force } = options;

  if (!skillName) {
    console.error('❌ Missing required option: --skill-name');
    console.log('\nUsage: lua marketplace install uninstall --skill-name <name> [--force]');
    throw new Error('Missing required option: --skill-name');
  }

  const agentId = config.agent?.agentId;
  if (!agentId) {
    console.error('❌ Agent ID not found in configuration.');
    throw new Error('Agent ID not found in configuration.');
  }

  // Find the installed skill
  writeProgress('🔄 Loading installed skills...');
  const installedSkills = await marketplaceApi.getInstalledSkills(agentId);
  const installedSkill = installedSkills?.find((s) => s.name === skillName || s.title === skillName);

  if (!installedSkill) {
    console.error(`❌ Installed skill not found: ${skillName}`);
    throw new Error('Installed skill not found: ${skillName}');
  }

  if (!installedSkill.marketplaceSkillId) {
    console.error('❌ Skill is missing marketplace skill ID.');
    throw new Error('Skill is missing marketplace skill ID.');
  }

  if (!force) {
    console.error(`❌ Use --force to confirm uninstalling "${installedSkill.title || installedSkill.name}"`);
    throw new Error('Use --force to confirm uninstalling');
  }

  writeProgress('🔄 Uninstalling skill...');
  await marketplaceApi.uninstallSkill(installedSkill.marketplaceSkillId, agentId);
  writeSuccess(`✅ "${installedSkill.title || installedSkill.name}" uninstalled successfully!`);
}

