// ===========================================================================
// DEVICE SANDBOX IDS
// ===========================================================================

export async function getSandboxDeviceId(deviceName: string): Promise<string | null> {
  const store = readStore();
  return store.devices[deviceName] ?? null;
}

export async function setSandboxDeviceId(sandboxId: string, deviceName: string): Promise<void> {
  const store = readStore();
  store.devices[deviceName] = sandboxId;
  writeStore(store);
}

export async function getAllSandboxDeviceIds(yamlConfig: any): Promise<{ deviceId: string; sandboxId: string }[]> {
  const overrides: { deviceId: string; sandboxId: string }[] = [];

  try {
    const devices = yamlConfig?.devices || [];
    for (const device of devices) {
      if (device.deviceId && device.name) {
        const sandboxId = await getSandboxDeviceId(device.name);
        if (sandboxId) {
          overrides.push({ deviceId: device.deviceId, sandboxId });
        }
      }
    }
  } catch (error) {
    console.error('Error getting sandbox device IDs:', error);
  }

  return overrides;
}
