/**
 * Device compilation plugin.
 *
 * Detects BOTH patterns:
 * 1. Class-based (legacy): new LuaDevice({ ... })
 * 2. Function-based (new): const myDevice = defineDevice({ ... })
 *
 * Devices are bidirectional:
 * - commands: agent → device (each becomes a Mastra tool at runtime)
 * - triggers: device → agent (each has an execute handler that runs on lua-core)
 */

import { Node, ObjectLiteralExpression, ClassDeclaration, SourceFile } from 'ts-morph';
import {
  type DeviceMetadata,
  type DeviceMetadataFields,
  type ValidationResult,
  type CompiledPrimitive,
  type ManifestPrimitive,
  type ManifestDevice,
} from '../types.js';
import { BasePlugin, readStringMember, deriveNameFromClassName, validationWarning } from './base.js';
import { extractStringProperty } from '../utils/ast-helpers.js';

/**
 * Plugin for compiling device primitives.
 * Extends BasePlugin for common detection/entry point/postProcess logic.
 */
export class DevicePlugin extends BasePlugin<DeviceMetadataFields> {
  readonly kind = 'device';
  readonly displayName = 'Device';
  readonly defineFunction = 'defineDevice';
  readonly legacyClassNames = ['LuaDevice'];

  protected readonly supportsClassDefinition = true;

  /**
   * Class-definition extraction. Reads `name`/`description`/`group`
   * off the inheritance chain.
   */
  protected extractFromClassDefinition(classDecl: ClassDeclaration, sourceFile: SourceFile): DeviceMetadata | null {
    const className = classDecl.getName();
    if (!className) return null;

    const isDefaultExport = classDecl.isDefaultExport();
    const exportName = isDefaultExport ? 'default' : className;

    const name = readStringMember(classDecl, 'name') ?? deriveNameFromClassName(className);
    const description = readStringMember(classDecl, 'description') ?? '';
    const group = readStringMember(classDecl, 'group');

    return {
      kind: this.kind,
      name,
      description,
      sourcePath: sourceFile.getFilePath(),
      exportName,
      isDefaultExport,
      line: classDecl.getStartLineNumber(),
      column: 1,
      metadata: {
        pattern: 'class-definition',
        group,
      },
    };
  }

  /**
   * Project the device class instance onto the runtime primitive shape.
   * Both `commands` and `triggers` maps come from the instance so they
   * pick up subclass overrides.
   */
  protected getClassDefinitionPrimitiveShape(metadata: DeviceMetadata): string {
    return `{
    kind: 'device',
    name: __lua_instance__.name ?? ${JSON.stringify(metadata.name)},
    description: __lua_instance__.description ?? ${JSON.stringify(metadata.description)},
    group: __lua_instance__.group,
    commands: __lua_instance__.commands,
    triggers: __lua_instance__.triggers,
  }`;
  }

  /**
   * Extract metadata from device config object.
   */
  protected extractFromConfig(
    config: ObjectLiteralExpression,
    exportName: string,
    sourcePath: string,
    position: { line: number; column: number },
    pattern: 'function' | 'class'
  ): DeviceMetadata | null {
    const common = this.extractCommonFields(config, exportName, sourcePath, position);
    if (!common) return null;

    const group = extractStringProperty(config, 'group');

    return {
      kind: this.kind,
      ...common,
      metadata: {
        pattern,
        group,
      },
    };
  }

  validate(metadata: DeviceMetadata): ValidationResult {
    const { errors, warnings } = this.baseValidation(metadata);

    if (metadata.name && !/^[a-z][a-z0-9-]*$/.test(metadata.name)) {
      warnings.push(
        validationWarning('Device name should be lowercase with hyphens only (e.g., "label-printer")', {
          line: metadata.line,
        })
      );
    }

    return { valid: errors.length === 0, errors, warnings };
  }

  protected getEntryPointFields(metadata: DeviceMetadata): string {
    const meta = metadata.metadata;
    return [meta.group ? `group: ${JSON.stringify(meta.group)},` : ''].filter(Boolean).join('\n  ');
  }

  /**
   * Runtime validation: device artifact must have commands or triggers map.
   */
  protected getRuntimeValidation(): string {
    return `
  const p = primitive.primitive;
  if (!p) {
    throw new Error('[Lua] Invalid device artifact: missing primitive export');
  }
  if (!p.commands && !p.triggers) {
    throw new Error('[Lua] Invalid device artifact: must have commands or triggers');
  }`;
  }

  toManifestEntry(compiled: CompiledPrimitive, _allPrimitives?: CompiledPrimitive[]): ManifestPrimitive {
    const meta = compiled.metadata as DeviceMetadataFields;

    return {
      ...this.baseManifestFields(compiled),
      group: meta.group,
    } as ManifestDevice;
  }
}
