/**
 * Logs Command
 * View and navigate agent/skill logs with pagination
 */

import inquirer from 'inquirer';
import chalk from 'chalk';
import {
  withErrorHandling,
  writeSuccess,
  writeInfo,
  writeError,
  clearPromptLines,
  writeHintBlock,
} from '../utils/cli.js';
import { initializeCommand } from '../utils/command-utils.js';
import LogsApi, { AGENT_LOG_SOURCES, type AgentLogSource } from '../api/logs.api.service.js';
import DeviceApi from '../api/device.api.service.js';
import { BASE_URLS } from '../config/constants.js';
import { LogEntry } from '../interfaces/logs.js';
import SkillApi from '../api/skills.api.service.js';
import JobApi from '../api/job.api.service.js';
import WebhookApi from '../api/webhook.api.service.js';
import PreprocessorApi from '../api/preprocessor.api.service.js';
import PostprocessorApi from '../api/postprocessor.api.service.js';
import { trackEvent } from '../services/analytics.js';
import { validateOrSuggest } from '../utils/aliases.js';
import CallMetricsApi from '../api/call-metrics.api.service.js';
import { renderTable } from '../utils/table.js';

// Entity-bearing log sources (can be further filtered by --name)
type PrimitiveLogSource = Extract<
  AgentLogSource,
  'skill' | 'job' | 'webhook' | 'preprocessor' | 'postprocessor' | 'device'
>;
// All filterable log sources, including non-entity ones
type FilterableLogSource = AgentLogSource;

// Derived directly from the canonical AGENT_LOG_SOURCES constant — never hardcode this list.
// Adding a new user-facing source to shared-schemas automatically makes it available here.
const ALL_VALID_SOURCES = AGENT_LOG_SOURCES as unknown as FilterableLogSource[];

// Entity sources: have a browsable list that users can filter by --name
const ENTITY_SOURCES = new Set<PrimitiveLogSource>([
  'skill',
  'job',
  'webhook',
  'preprocessor',
  'postprocessor',
  'device',
]);
// Non-entity sources: present in ALL_VALID_SOURCES but have no selectable entity list
const NON_ENTITY_SOURCES = new Set<FilterableLogSource>(
  ALL_VALID_SOURCES.filter((s) => !ENTITY_SOURCES.has(s as PrimitiveLogSource))
);

interface LogsOptions {
  type?: string;
  name?: string;
  limit?: number;
  page?: number;
  json?: boolean;
  userId?: string;
  agentId?: string;
  /** Only meaningful when `type === 'calls'`. */
  direction?: 'inbound' | 'outbound';
  /** Only meaningful when `type === 'calls'`. */
  status?: string;
}

interface LogFilters {
  logSource?: FilterableLogSource;
  primitiveId?: string;
  primitiveName?: string;
  toolId?: string;
  toolName?: string;
  logType?: string;
  userId?: string;
}

// ─────────────────────────────────────────────────────────────────────────────
// Main Command Entry
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Main logs command - displays agent/skill logs with navigation.
 *
 * Supports both interactive and non-interactive modes:
 * - Interactive: prompts for filter type and entity
 * - Non-interactive: use --type, -i, --limit, --page, --json flags
 */
export async function logsCommand(cmdObj?: any): Promise<void> {
  return withErrorHandling(async () => {
    const options: LogsOptions = {
      type: cmdObj?.type || null,
      name: cmdObj?.name || null,
      limit: cmdObj?.limit ? parseInt(cmdObj.limit, 10) : 20,
      page: cmdObj?.page ? parseInt(cmdObj.page, 10) : 1,
      json: cmdObj?.json || false,
      userId: cmdObj?.userId || null,
      agentId: cmdObj?.agentId || null,
      direction: cmdObj?.direction || null,
      status: cmdObj?.status || null,
    };

    // Initialize command (validates config + auth)
    const { agentId: configAgentId, apiKey } = await initializeCommand();
    const effectiveAgentId = options.agentId || configAgentId;

    // `--type calls` routes to a different data source entirely — call
    // records live in `voiceCallRecords`, not `vmExecutionLogs`. Branch
    // early so none of the primitive-log plumbing below runs.
    if (options.type === 'calls') {
      await listCallLogs(effectiveAgentId, apiKey, options);
      trackEvent('cli_logs_action', {
        filter_type: 'calls',
        json_output: options.json || false,
        non_interactive: true,
        page_requested: options.page || 1,
        agent_id_override: !!options.agentId,
      });
      return;
    }

    const logsApi = new LogsApi(BASE_URLS.API, apiKey);

    // Determine if non-interactive mode. --agent-id is intentionally excluded:
    // it's a scope override (which agent to query), not a "what to view" filter,
    // so it works in both modes and lets users browse another agent interactively.
    const hasNonInteractiveFlags = options.type || options.name || options.json || options.userId;

    if (hasNonInteractiveFlags) {
      await nonInteractiveLogs(logsApi, effectiveAgentId, apiKey, options);
    } else {
      writeInfo(`📊 Viewing logs for agent: ${effectiveAgentId}\n`);
      await interactiveLogs(logsApi, effectiveAgentId, apiKey);
    }
    trackEvent('cli_logs_action', {
      filter_type: options.type || null,
      json_output: options.json || false,
      non_interactive: hasNonInteractiveFlags,
      page_requested: options.page || 1,
      agent_id_override: !!options.agentId,
    });
  }, 'logs viewing');
}

// ─────────────────────────────────────────────────────────────────────────────
// Call Logs (--calls)
// ─────────────────────────────────────────────────────────────────────────────

/**
 * `lua logs --calls` — voice call records for the current agent.
 *
 * Routes around the primitive-log pipeline because call records live in
 * `voiceCallRecords` (populated by `LivekitBridgeService.reportSession`
 * + the compiled-path `SessionReporter.flush()`), not in
 * `vmExecutionLogs`. Renders rows as an aligned ASCII table; `--json`
 * dumps the raw payload.
 */
async function listCallLogs(agentId: string, apiKey: string, options: LogsOptions): Promise<void> {
  const api = new CallMetricsApi(BASE_URLS.API, apiKey, agentId);
  const resp = await api.listCalls({
    page: options.page,
    limit: options.limit,
    direction: options.direction,
    status: options.status,
  });
  if (!resp.success) throw new Error(resp.error?.message ?? 'Failed to fetch call logs');
  const { calls, total, page, totalPages } = resp.data!;

  if (options.json) {
    console.log(JSON.stringify(resp.data, null, 2));
    return;
  }

  if (calls.length === 0) {
    console.log('No calls found for this agent.');
    return;
  }

  console.log(`📞 ${total} call(s) — page ${page}/${totalPages}\n`);
  console.log(
    renderTable(
      ['Started', 'Dir', 'From', 'To', 'Status', 'Duration', 'Recording'],
      calls.map((c) => [
        new Date(c.startedAt).toLocaleString(),
        c.direction,
        c.from,
        c.to,
        c.status,
        c.durationSeconds ? `${c.durationSeconds}s` : '—',
        c.recordingUrl ? '✓' : '—',
      ])
    )
  );
  if (totalPages > 1) {
    console.log(`\n💡 Use --page <n> to navigate. Currently on page ${page}/${totalPages}.`);
  }
}

// ─────────────────────────────────────────────────────────────────────────────
// Shared Core Functions
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Renders a single log entry to the console.
 */
function renderLogEntry(log: LogEntry, isLast: boolean): void {
  const timestamp = new Date(log.timestamp).toLocaleString();
  const logSource = log.metadata?.logSource as FilterableLogSource | undefined;
  const primitiveId = log.metadata?.primitiveId;
  const primitiveName = log.metadata?.primitiveName;
  const { toolName, channel, userId } = log.metadata;

  const icon = getLogIcon(log.subType, logSource);
  const color = getLogColor(log.subType, logSource);

  console.log(color(`${icon} [${timestamp}] ${log.subType.toUpperCase()}`));

  const capitalizedType = logSource ? capitalize(logSource) : 'Item';

  // For message types and agent errors, show channel and userId
  if (logSource === 'user_message' || logSource === 'agent_response' || logSource === 'agent_error') {
    if (channel) {
      console.log(chalk.gray(`   Channel: ${channel}`));
    }
    if (userId) {
      console.log(chalk.gray(`   User ID: ${userId}`));
    }
  } else {
    // For skill/job/webhook types, show source id and name
    if (primitiveName) {
      console.log(chalk.gray(`   ${capitalizedType} Name: ${primitiveName}`));
    }
    if (primitiveId) {
      console.log(chalk.gray(`   ${capitalizedType} ID:   ${primitiveId}`));
    }
    // Show tool information for skills and MCP
    if ((logSource === 'skill' || logSource === 'mcp') && toolName) {
      console.log(chalk.gray(`   Tool Name: ${toolName}`));
    }
  }

  if (log.duration !== undefined) {
    console.log(chalk.gray(`   Duration: ${log.duration}ms`));
  }

  console.log(`   ${log.message}`);

  if (!isLast) {
    console.log(chalk.gray(`   ${'-'.repeat(78)}`));
  }
}

/**
 * Displays logs with pagination info (shared by both modes).
 */
function displayLogsCore(logs: LogEntry[], pagination: any, title: string, clearScreen: boolean = false): void {
  if (clearScreen) {
    console.clear();
  }

  writeSuccess(`\n${title}\n`);
  writeInfo(`${'─'.repeat(80)}`);
  writeInfo(`Page ${pagination.currentPage} of ${pagination.totalPages} (${pagination.totalCount} total logs)\n`);

  if (logs.length === 0) {
    writeInfo('No logs found.');
    return;
  }

  // Reverse logs so latest appears at the bottom
  const reversedLogs = [...logs].reverse();
  reversedLogs.forEach((log, index) => {
    renderLogEntry(log, index === reversedLogs.length - 1);
  });

  writeInfo(`\n${'─'.repeat(80)}\n`);
}

/**
 * Fetches entities by type for filtering.
 */
async function fetchEntitiesByType(apiKey: string, agentId: string, type: PrimitiveLogSource): Promise<any[]> {
  switch (type) {
    case 'skill': {
      const res = await new SkillApi(BASE_URLS.API, apiKey, agentId).getSkills();
      return res.data?.skills || [];
    }
    case 'job': {
      const res = await new JobApi(BASE_URLS.API, apiKey, agentId).getJobs({ includeDynamic: true });
      return res.data?.jobs || [];
    }
    case 'webhook': {
      const res = await new WebhookApi(BASE_URLS.API, apiKey, agentId).getWebhooks();
      return res.data?.webhooks || [];
    }
    case 'preprocessor': {
      const res = await new PreprocessorApi(BASE_URLS.API, apiKey, agentId).getPreProcessors();
      return res.data?.preprocessors || [];
    }
    case 'postprocessor': {
      const res = await new PostprocessorApi(BASE_URLS.API, apiKey, agentId).getPostProcessors();
      return res.data?.postprocessors || [];
    }
    case 'device': {
      const res = await new DeviceApi(BASE_URLS.API, apiKey, agentId).getDevices();
      return res.data?.devices || [];
    }
    default:
      return [];
  }
}

/**
 * Resolves an entity name/ID to its actual ID.
 */
async function resolveEntityId(
  apiKey: string,
  agentId: string,
  type: PrimitiveLogSource,
  nameOrId: string
): Promise<string | null> {
  const items = await fetchEntitiesByType(apiKey, agentId, type);
  const found = items.find((item: any) => item.id === nameOrId || item.name === nameOrId);
  return found?.id || null;
}

// ─────────────────────────────────────────────────────────────────────────────
// Non-Interactive Mode
// ─────────────────────────────────────────────────────────────────────────────

async function nonInteractiveLogs(
  logsApi: LogsApi,
  agentId: string,
  apiKey: string,
  options: LogsOptions
): Promise<void> {
  const filters: LogFilters = {};

  // Validate and set log source filter
  if (options.type && options.type !== 'all') {
    options.type = validateOrSuggest('logs.type', options.type) as FilterableLogSource;
    filters.logSource = options.type as FilterableLogSource;
  }

  // Resolve entity name if provided
  if (options.name) {
    if (!filters.logSource) {
      console.error('❌ --type is required when using --name');
      console.log('\nUsage: lua logs --type skill --name mySkill');
      throw new Error('--type is required when using --name');
    }

    // Non-entity log sources don't have IDs to resolve
    if (NON_ENTITY_SOURCES.has(filters.logSource)) {
      console.error(`❌ --name is not applicable for ${filters.logSource} type`);
      console.log(`\nUsage: lua logs --type ${filters.logSource} (no --name needed)`);
      throw new Error('--name is not applicable for ${filters.logSource} type');
    }

    const entityId = await resolveEntityId(apiKey, agentId, filters.logSource as PrimitiveLogSource, options.name);
    if (!entityId) {
      console.error(`❌ ${capitalize(filters.logSource ?? '')} "${options.name}" not found`);
      throw new Error(`${capitalize(filters.logSource ?? '')} "${options.name}" not found`);
    }
    filters.primitiveId = entityId;
  }

  // Set userId filter if provided
  if (options.userId) {
    filters.userId = options.userId;
  }

  // Fetch logs
  const response = await logsApi.getAgentLogs(agentId, options.limit || 20, options.page || 1, filters);

  if (!response.success) {
    console.error(`❌ Error: ${response.error?.message || 'Unknown error'}`);
    throw new Error(`Error: ${response.error?.message || 'Unknown error'}`);
  }

  const data = response.data!;

  // Output as JSON or formatted
  if (options.json) {
    console.log(
      JSON.stringify(
        {
          logs: data.logs,
          pagination: data.pagination,
        },
        null,
        2
      )
    );
  } else {
    const typeLabel = options.type ? capitalize(options.type) : 'All';
    displayLogsCore(data.logs, data.pagination, `📊 ${typeLabel} Logs`);
    writeHintBlock({
      headline: 'If you see errors:',
      lines: [
        { label: 'Fix code, re-push:', command: 'lua push all --force --auto-deploy' },
        { label: 'Test locally first:', command: 'lua test' },
        { label: 'Isolate a tool:', command: 'lua chat -e sandbox -m "trigger the tool"' },
      ],
      when: 'success',
    });
  }
}

// ─────────────────────────────────────────────────────────────────────────────
// Interactive Mode
// ─────────────────────────────────────────────────────────────────────────────

async function interactiveLogs(logsApi: LogsApi, agentId: string, apiKey: string): Promise<void> {
  const { viewType } = await inquirer.prompt([
    {
      type: 'list',
      name: 'viewType',
      message: 'What logs do you want to view?',
      choices: [
        { name: '📋 All agent logs', value: 'all' },
        { name: '🔎 Filter logs', value: 'filter' },
      ],
    },
  ]);

  clearPromptLines(2);

  if (viewType === 'all') {
    await viewAgentLogsInteractive(logsApi, agentId);
  } else {
    await filterAndShowLogsInteractive(logsApi, agentId, apiKey);
  }
}

async function filterAndShowLogsInteractive(logsApi: LogsApi, agentId: string, apiKey: string): Promise<void> {
  let keepFiltering = true;

  while (keepFiltering) {
    const { filterType } = await inquirer.prompt([
      {
        type: 'list',
        name: 'filterType',
        message: 'Filter by:',
        choices: [
          { name: '📋 All logs', value: 'all' },
          new inquirer.Separator(),
          { name: 'Skills', value: 'skill' },
          { name: 'Jobs', value: 'job' },
          { name: 'Webhooks', value: 'webhook' },
          { name: 'Preprocessors', value: 'preprocessor' },
          { name: 'Postprocessors', value: 'postprocessor' },
          { name: 'Devices', value: 'device' },
          new inquirer.Separator(),
          { name: '💬 User Messages', value: 'user_message' },
          { name: '🤖 Agent Responses', value: 'agent_response' },
          { name: '⚠️ Agent Errors', value: 'agent_error' },
          { name: '🔌 MCP Tools', value: 'mcp' },
          { name: '🧠 Runtime', value: 'runtime' },
          { name: '🔍 Knowledge Base (RAG)', value: 'rag' },
          { name: '📡 Device Triggers', value: 'device-trigger' },
          { name: '📞 Voice Calls', value: 'calls' },
          new inquirer.Separator(),
          { name: '← Back', value: 'back' },
          new inquirer.Separator(),
        ],
      },
    ]);

    if (filterType === 'calls') {
      // Calls live in `voiceCallRecords`, not `vmExecutionLogs` — branch
      // out of the primitive-log pipeline entirely. Returns to the
      // filter loop after the table renders so the dev can switch
      // filters without restarting the command.
      await listCallLogs(agentId, apiKey, { page: 1, limit: 20 });
      continue;
    }

    if (filterType === 'all') {
      await viewAgentLogsInteractive(logsApi, agentId);
      return;
    }

    if (filterType === 'back') {
      // Re-enter the top-level interactive prompt with the same agentId,
      // so any --agent-id override survives "Back" navigation.
      await interactiveLogs(logsApi, agentId, apiKey);
      return;
    }

    // Handle non-entity log sources (don't have selectable entity lists)
    if (NON_ENTITY_SOURCES.has(filterType as FilterableLogSource)) {
      await viewAgentLogsInteractive(logsApi, agentId, { logSource: filterType as FilterableLogSource });
      continue;
    }

    const entitySource = filterType as PrimitiveLogSource;
    const capitalizedType = capitalize(entitySource);

    const items = await fetchEntitiesByType(apiKey, agentId, entitySource);

    if (items.length === 0) {
      writeInfo(`ℹ️ No ${entitySource}s found for this agent.\n`);
      continue;
    }

    const { selectedId } = await inquirer.prompt([
      {
        type: 'list',
        name: 'selectedId',
        message: `Select a ${entitySource}:`,
        choices: [
          { name: `All ${capitalizedType}s`, value: 'all' },
          new inquirer.Separator(),
          ...items.map((item: any) => ({
            name: item.name,
            value: item.id,
          })),
          new inquirer.Separator(),
          { name: '← Back', value: 'back' },
          new inquirer.Separator(),
        ],
      },
    ]);

    if (selectedId === 'back') {
      continue;
    }

    const filters: LogFilters = { logSource: entitySource };
    if (selectedId !== 'all') {
      filters.primitiveId = selectedId;
    }

    await viewAgentLogsInteractive(logsApi, agentId, filters);
    return;
  }
}

async function viewAgentLogsInteractive(logsApi: LogsApi, agentId: string, filters: LogFilters = {}): Promise<void> {
  let currentPage = 1;
  const limit = 20;
  let keepViewing = true;

  while (keepViewing) {
    const response = await logsApi.getAgentLogs(agentId, limit, currentPage, filters);

    if (!response.success) {
      writeError(`❌ Error: ${response.error?.message || 'Unknown error'}`);
      throw new Error('Operation failed');
    }

    const data = response.data!;
    displayLogsCore(data.logs, data.pagination, 'All Agent Logs', true);

    const { action } = await inquirer.prompt([
      {
        type: 'list',
        name: 'action',
        message: 'Navigation:',
        choices: getNavigationChoices(data.pagination),
      },
    ]);

    clearPromptLines(2);

    keepViewing = await handleNavigation(action, data.pagination, (page) => {
      currentPage = page;
    });
  }
}

function getNavigationChoices(pagination: any): any[] {
  const choices: any[] = [];

  if (pagination.hasPrevPage) {
    choices.push({ name: '← Previous Page', value: 'prev' });
  }
  if (pagination.hasNextPage) {
    choices.push({ name: 'Next Page →', value: 'next' });
  }
  if (pagination.totalPages > 1) {
    choices.push({ name: '🔢 Go to specific page', value: 'goto' });
  }

  choices.push({ name: '🔄 Refresh', value: 'refresh' });
  choices.push({ name: '❌ Exit', value: 'exit' });

  return choices;
}

async function handleNavigation(action: string, pagination: any, setPage: (page: number) => void): Promise<boolean> {
  switch (action) {
    case 'prev':
      if (pagination.hasPrevPage) setPage(pagination.prevPage);
      return true;
    case 'next':
      if (pagination.hasNextPage) setPage(pagination.nextPage);
      return true;
    case 'goto':
      const { page } = await inquirer.prompt({
        type: 'number',
        name: 'page',
        message: `Enter page number (1-${pagination.totalPages}):`,
        validate: (input: number | undefined) => {
          if (input === undefined || input < 1 || input > pagination.totalPages) {
            return `Please enter a number between 1 and ${pagination.totalPages}`;
          }
          return true;
        },
      });
      setPage(page);
      return true;
    case 'refresh':
      return true;
    case 'exit':
      writeInfo('👋 Exiting logs viewer\n');
      return false;
    default:
      return false;
  }
}

// ─────────────────────────────────────────────────────────────────────────────
// Utility Functions
// ─────────────────────────────────────────────────────────────────────────────

function capitalize(str: string): string {
  return str.charAt(0).toUpperCase() + str.slice(1);
}

function getLogIcon(subType: string, logSource?: string): string {
  // Special icons for specific log sources
  if (logSource === 'user_message') {
    return '💬';
  }
  if (logSource === 'agent_response') {
    return '🤖';
  }
  if (logSource === 'mcp') {
    return '🔌'; // MCP tool execution
  }
  if (logSource === 'runtime') {
    return '🧠'; // Agent runtime logs
  }
  if (logSource === 'agent_error') {
    return '⚠️'; // Expected agent errors (billing, validation)
  }
  if (logSource === 'rag') {
    return '🔍'; // RAG knowledge base search
  }

  const icons: Record<string, string> = {
    error: '❌',
    warn: '⚠️',
    debug: '🔍',
    info: 'ℹ️',
    start: '▶️',
    complete: '✅',
  };
  return icons[subType] || '📝';
}

function getLogColor(subType: string, logSource?: string): any {
  // Special colors for specific log sources
  if (logSource === 'user_message') {
    return chalk.cyan;
  }
  if (logSource === 'agent_response') {
    return chalk.green;
  }
  if (logSource === 'mcp') {
    return chalk.magenta; // MCP tool execution
  }
  if (logSource === 'runtime') {
    return chalk.blue; // Agent runtime logs
  }
  if (logSource === 'agent_error') {
    return chalk.red; // Expected agent errors (billing, validation)
  }
  if (logSource === 'rag') {
    return chalk.yellow; // RAG knowledge base search
  }

  const colors: Record<string, any> = {
    error: chalk.red,
    warn: chalk.yellow,
    debug: chalk.blue,
    info: chalk.cyan,
    start: chalk.green,
    complete: chalk.green,
  };
  return colors[subType] || chalk.white;
}
