/**
 * MCP Server compilation plugin.
 *
 * BACKWARD COMPATIBLE: Detects BOTH patterns:
 * 1. Class-based (legacy): new LuaMCPServer({ ... })
 * 2. Function-based (new): const myServer = defineMCPServer({ ... })
 */

import { ObjectLiteralExpression, ClassDeclaration, SourceFile, Node } from 'ts-morph';
import {
  type MCPServerMetadata,
  type MCPServerMetadataFields,
  type ValidationResult,
  type CompiledPrimitive,
  type ManifestPrimitive,
  type ManifestMCPServer,
} from '../types.js';
import { BasePlugin, readStringMember, deriveNameFromClassName, validationError } from './base.js';
import {
  extractStringProperty,
  extractSchemaProperty,
  isFunction,
  extractFunctionProperty,
  evaluateNodeAsString,
} from '../utils/ast-helpers.js';
import { findClassMember } from '../utils/class-hierarchy.js';

/**
 * Plugin for compiling MCP server primitives.
 * Extends BasePlugin for common detection/entry point/postProcess logic.
 */
export class MCPServerPlugin extends BasePlugin<MCPServerMetadataFields> {
  readonly kind = 'mcp-server';
  readonly displayName = 'MCP Server';
  readonly defineFunction = 'defineMCPServer';
  readonly legacyClassNames = ['LuaMCPServer'];

  protected readonly supportsClassDefinition = true;

  /**
   * Class-definition extraction. Reads `name`/`description`/`transport`/
   * `url`/`headers` off the inheritance chain. `url` and `headers` may
   * be either string literals (static config) or methods/arrow functions
   * (resolvers), mirroring the config-literal shape.
   */
  protected extractFromClassDefinition(classDecl: ClassDeclaration, sourceFile: SourceFile): MCPServerMetadata | null {
    const className = classDecl.getName();
    if (!className) return null;

    const isDefaultExport = classDecl.isDefaultExport();
    const exportName = isDefaultExport ? 'default' : className;

    const name = readStringMember(classDecl, 'name') ?? deriveNameFromClassName(className);
    const description = readStringMember(classDecl, 'description') ?? '';

    const transport =
      (readStringMember(classDecl, 'transport') as 'stdio' | 'sse' | 'streamable-http' | undefined) ??
      'streamable-http';

    // url: string literal => static URL; arrow fn / method => resolver
    const urlHit = findClassMember(classDecl, 'url', 'either');
    let url: string | undefined;
    let hasUrlResolver = false;
    let urlResolverSource: string | undefined;
    if (urlHit) {
      if (Node.isMethodDeclaration(urlHit.node)) {
        hasUrlResolver = true;
        urlResolverSource = urlHit.node.getText();
      } else if (Node.isPropertyDeclaration(urlHit.node)) {
        const init = urlHit.node.getInitializer();
        if (init && isFunction(init)) {
          hasUrlResolver = true;
          urlResolverSource = init.getText();
        } else {
          url = evaluateNodeAsString(init);
        }
      }
    }

    // headers: method or property initialized to a function => resolver.
    // A static headers map could be added later — current API only
    // surfaces the resolver shape.
    const headersHit = findClassMember(classDecl, 'headers', 'either');
    let hasHeadersResolver = false;
    let headersResolverSource: string | undefined;
    if (headersHit) {
      if (Node.isMethodDeclaration(headersHit.node)) {
        hasHeadersResolver = true;
        headersResolverSource = headersHit.node.getText();
      } else if (Node.isPropertyDeclaration(headersHit.node)) {
        const init = headersHit.node.getInitializer();
        if (init && isFunction(init)) {
          hasHeadersResolver = true;
          headersResolverSource = init.getText();
        }
      }
    }

    return {
      kind: this.kind,
      name,
      description,
      sourcePath: sourceFile.getFilePath(),
      exportName,
      isDefaultExport,
      line: classDecl.getStartLineNumber(),
      column: 1,
      metadata: {
        pattern: 'class-definition',
        transport,
        url,
        hasUrlResolver,
        hasHeadersResolver,
        urlResolverSource,
        headersResolverSource,
      },
    };
  }

  /**
   * Project the MCP server class instance onto the standard primitive
   * shape. transport/url come from the instance to honor subclass
   * overrides; resolver methods are bound to preserve `this` context.
   */
  protected getClassDefinitionPrimitiveShape(metadata: MCPServerMetadata): string {
    return `{
    kind: 'mcp-server',
    name: __lua_instance__.name ?? ${JSON.stringify(metadata.name)},
    description: __lua_instance__.description ?? ${JSON.stringify(metadata.description)},
    transport: __lua_instance__.transport ?? ${JSON.stringify(metadata.metadata.transport)},
    url: typeof __lua_instance__.url === 'function' ? __lua_instance__.url.bind(__lua_instance__) : __lua_instance__.url,
    headers: typeof __lua_instance__.headers === 'function' ? __lua_instance__.headers.bind(__lua_instance__) : __lua_instance__.headers,
  }`;
  }

  /**
   * Extract metadata from MCP server config object.
   */
  protected extractFromConfig(
    config: ObjectLiteralExpression,
    exportName: string,
    sourcePath: string,
    position: { line: number; column: number },
    pattern: 'function' | 'class'
  ): MCPServerMetadata | null {
    const common = this.extractCommonFields(config, exportName, sourcePath, position);
    if (!common) return null;

    const transport =
      (extractStringProperty(config, 'transport') as 'stdio' | 'sse' | 'streamable-http') || 'streamable-http';
    const url = extractStringProperty(config, 'url');

    // Check for resolver functions and extract their source text
    // Try both AST extraction (inline functions) and evaluation (variable references)
    const urlProp = extractSchemaProperty(config, 'url');
    const headersProp = extractSchemaProperty(config, 'headers');

    const urlResolverEvaluated = extractFunctionProperty(config, 'url');
    const headersResolverEvaluated = extractFunctionProperty(config, 'headers');

    const hasUrlResolver = (urlProp && isFunction(urlProp)) || urlResolverEvaluated !== undefined;
    const hasHeadersResolver = (headersProp && isFunction(headersProp)) || headersResolverEvaluated !== undefined;

    const urlResolverSource = hasUrlResolver
      ? urlProp && isFunction(urlProp)
        ? urlProp.getText()
        : urlResolverEvaluated?.toString()
      : undefined;
    const headersResolverSource = hasHeadersResolver
      ? headersProp && isFunction(headersProp)
        ? headersProp.getText()
        : headersResolverEvaluated?.toString()
      : undefined;

    return {
      kind: this.kind,
      ...common,
      metadata: {
        pattern,
        transport,
        url,
        hasUrlResolver,
        hasHeadersResolver,
        urlResolverSource,
        headersResolverSource,
      },
    };
  }

  validate(metadata: MCPServerMetadata): ValidationResult {
    const { errors, warnings } = this.baseValidation(metadata);

    const transport = metadata.metadata.transport;
    const validTransports = ['streamable-http', 'sse'];

    if (transport === 'stdio') {
      errors.push(
        validationError('stdio transport is not supported. Use streamable-http or sse instead.', {
          line: metadata.line,
          suggestion: 'Change transport to "streamable-http" (recommended) or "sse"',
          docsUrl: 'https://docs.lua.ai/mcp-servers#transport',
        })
      );
    } else if (!validTransports.includes(transport)) {
      errors.push(
        validationError(`Invalid transport: ${transport}. Must be one of: ${validTransports.join(', ')}`, {
          line: metadata.line,
        })
      );
    }

    if (!metadata.metadata.url && !metadata.metadata.hasUrlResolver) {
      errors.push(validationError('MCP Server must have a url or url resolver', { line: metadata.line }));
    }

    return { valid: errors.length === 0, errors, warnings };
  }

  /**
   * Add transport field to the entry point.
   */
  protected getEntryPointFields(metadata: MCPServerMetadata): string {
    return `transport: ${JSON.stringify(metadata.metadata.transport)},`;
  }

  /**
   * Create the manifest entry for an MCP server.
   * url/headers resolver functions are bundled inside the artifact (same as all primitives).
   */
  toManifestEntry(compiled: CompiledPrimitive, _allPrimitives?: CompiledPrimitive[]): ManifestPrimitive {
    const mcpMeta = compiled.metadata as unknown as MCPServerMetadataFields;

    return {
      ...this.baseManifestFields(compiled),
      config: {
        transport: mcpMeta.transport,
        url: mcpMeta.url,
      },
      hasUrlResolver: mcpMeta.hasUrlResolver || undefined,
      hasHeadersResolver: mcpMeta.hasHeadersResolver || undefined,
    } as ManifestMCPServer;
  }
}
