interface DeployOptions {
  name?: string | null;
  version?: string | null;
  force?: boolean;
}

interface VersionedDeployConfig {
  type: string;
  handler: any;
  label: string;
  emoji: string;
  idField: string;
  getVersions: (apiKey: string, agentId: string, entityId: string) => Promise<VersionInfo[]>;
}

/**
 * Normalize a server version object to the VersionInfo shape expected by
 * sortVersionsByDate / promptVersionSelection / formatVersionChoice.
 *
 * Non-skill primitives use { createdAt, isActive/active } while VersionInfo
 * expects { createdDate, isCurrent }.
 */
function normalizeVersion(v: any): VersionInfo {
  return {
    version: v.version,
    createdDate: v.createdDate ?? v.createdAt ?? '',
    createdBy: v.createdBy ?? '',
    isCurrent: v.isCurrent ?? v.isActive ?? v.active ?? false,
    createdByEmail: v.createdByEmail ?? '',
    createdByFullName: v.createdByFullName ?? '',
  };
}

const VERSIONED_DEPLOY_TYPES: VersionedDeployConfig[] = [
  {
    type: 'skill',
    handler: skillHandler,
    label: 'Skill',
    emoji: '🛠️',
    idField: 'skillId',
    getVersions: async (apiKey, agentId, entityId) => {
      const api = new SkillApi(BASE_URLS.API, apiKey, agentId);
      const result = await api.getSkillVersions(entityId);
      return (result.data?.versions || []).map(normalizeVersion);
    },
  },
  {
    type: 'webhook',
    handler: webhookHandler,
    label: 'Webhook',
    emoji: '🪝',
    idField: 'webhookId',
    getVersions: async (apiKey, agentId, entityId) => {
      const api = new WebhookApi(BASE_URLS.API, apiKey, agentId);
      const result = await api.getWebhookVersions(entityId);
      return (result.data?.versions || []).map(normalizeVersion);
    },
  },
  {
    type: 'job',
    handler: jobHandler,
    label: 'Job',
    emoji: '⏰',
    idField: 'jobId',
    getVersions: async (apiKey, agentId, entityId) => {
      const api = new JobApi(BASE_URLS.API, apiKey, agentId);
      const result = await api.getJobVersions(entityId);
      // Job API returns the array directly (not wrapped in { versions: [...] })
      return (Array.isArray(result.data) ? result.data : []).map(normalizeVersion);
    },
  },
  {
    type: 'preprocessor',
    handler: preprocessorHandler,
    label: 'PreProcessor',
    emoji: '📥',
    idField: 'preprocessorId',
    getVersions: async (apiKey, agentId, entityId) => {
      const api = new PreProcessorApi(BASE_URLS.API, apiKey, agentId);
      const result = await api.getPreProcessorVersions(entityId);
      return (result.data?.versions || []).map(normalizeVersion);
    },
  },
  {
    type: 'postprocessor',
    handler: postprocessorHandler,
    label: 'PostProcessor',
    emoji: '📤',
    idField: 'postprocessorId',
    getVersions: async (apiKey, agentId, entityId) => {
      const api = new PostProcessorApi(BASE_URLS.API, apiKey, agentId);
      const result = await api.getPostProcessorVersions(entityId);
      return (result.data?.versions || []).map(normalizeVersion);
    },
  },
];

/**
 * Main deploy command — deploys a primitive version to production.
 *
 * Mirrors `lua push [type]`:
 * - No type: interactive menu
 * - With type: deploy that primitive directly
 * - 'all': deploy latest version of every primitive
 */
export async function deployCommand(type?: string, cmdObj?: any): Promise<void> {
  return withErrorHandling(async () => {
    const options: DeployOptions = {
      // Support both new generic flags and deprecated skill-specific flags
      name: cmdObj?.name || cmdObj?.skillName || null,
      version: cmdObj?.setVersion || cmdObj?.skillVersion || null,
      force: cmdObj?.force || false,
    };

    // Backward compat: if deprecated skill-specific flags used without a type arg, infer 'skill'
    if (!type && (cmdObj?.skillName || cmdObj?.skillVersion)) {
      type = 'skill';
    }

    // Normalize alias first (e.g. 'everything' → 'all') so the guard below can catch it
    if (type) {
      type = validateOrSuggest('deploy.type', type, { allowAll: true });
    }

    // Handle 'all' (requires --force, like `lua push all`)
    if (type === 'all') {
      if (!options.force) {
        console.log('\nUsage:');
        console.log('  lua deploy all --force    Deploy latest version of all primitives');
        throw new Error('The "all" type requires the --force flag');
      }
      return await deployAllCommand(options);
    }

    const config = readYamlConfig();
    validateSkillConfig(config);
    const agentId = config.agent!.agentId!;

    let selectedType: string;

    if (type) {
      selectedType = type;
    } else {
      const answer = await safePrompt<{ type: string }>([
        {
          type: 'list',
          name: 'type',
          message: 'What would you like to deploy?',
          choices: [
            { name: '🛠️  Skill', value: 'skill' },
            { name: '🪝  Webhook', value: 'webhook' },
            { name: '⏰  Job', value: 'job' },
            { name: '📥  PreProcessor', value: 'preprocessor' },
            { name: '📤  PostProcessor', value: 'postprocessor' },
            { name: '🤖  Persona', value: 'persona' },
          ],
        },
      ]);

      if (!answer) {
        console.log('Deployment cancelled.');
        return;
      }
      selectedType = answer.type;
    }

    const apiKey = await requireAuthOrExit();

    let personaDeployed = false;
    let versionedOutcome: { deployed: boolean; hintPrinted: boolean; entityName: string } | null = null;

    if (selectedType === 'persona') {
      personaDeployed = await deployPersonaVersion(apiKey, agentId, options);
    } else {
      const deployConfig = VERSIONED_DEPLOY_TYPES.find((dt) => dt.type === selectedType)!;
      versionedOutcome = await deployVersionedPrimitive(deployConfig, config, apiKey, agentId, options);
    }

    trackEvent('cli_deploy_completed', {
      primitive_type: selectedType,
      force_mode: options.force || false,
      entity_selected_by_name: !!options.name,
      version_selected_by_flag: !!options.version,
    });

    const deployed = selectedType === 'persona' ? personaDeployed : (versionedOutcome?.deployed ?? false);
    const hintPrintedAlready = selectedType !== 'persona' && !!versionedOutcome?.hintPrinted;

    if (!deployed) {
      return;
    }

    if (selectedType === 'webhook') {
      // B8: use the resolved entity name (available for both --name and interactive selections)
      const webhookNameToken = versionedOutcome?.entityName || options.name?.trim() || '<webhook-name>';
      writeHintBlock({
        headline: 'Webhook is live. Trigger it, then inspect logs:',
        lines: [
          { label: 'Find URL:', command: `lua webhooks view --webhook-name ${webhookNameToken}` },
          { label: 'Trigger:', command: 'curl -X POST <URL from above>' },
          {
            label: 'Inspect:',
            command: buildLogsCommand({
              primitiveType: 'webhook',
              name: webhookNameToken !== '<webhook-name>' ? webhookNameToken : undefined,
            }),
          },
        ],
        when: 'success',
      });
    } else if (selectedType === 'persona') {
      writeNextStep({
        command: 'lua chat -e production -m "test"',
        rationale: 'to verify the new persona responds correctly',
        when: 'success',
      });
    } else if (!hintPrintedAlready) {
      writeHintBlock({
        headline: 'Version is live. Generate traffic first, then inspect:',
        lines: [
          { label: 'Test:', command: `lua chat -e production -m "your test message"` },
          { label: 'Inspect:', command: buildLogsCommand({ primitiveType: selectedType }) },
        ],
        when: 'success',
      });
    }
  }, 'deployment');
}

/**
 * Generic deploy flow for versioned primitives (skill, webhook, job, preprocessor, postprocessor).
 */
async function deployVersionedPrimitive(
  deployConfig: VersionedDeployConfig,
  config: YamlConfig,
  apiKey: string,
  agentId: string,
  options: DeployOptions
): Promise<{ deployed: boolean; hintPrinted: boolean; entityName: string }> {
  const entities = deployConfig.handler.getFromYaml(config);

  if (entities.length === 0) {
    writeInfo(`ℹ️  No ${deployConfig.label}s found in configuration. Nothing to deploy.`);
    return { deployed: false, hintPrinted: false, entityName: '' };
  }

  // Select entity
  let selectedEntity: any;
  if (options.name) {
    selectedEntity = entities.find((e: any) => e.name === options.name);
    if (!selectedEntity) {
      console.log(`\nAvailable ${deployConfig.label}s:`);
      entities.forEach((e: any) => console.log(`  - ${e.name}`));
      throw new Error(`${deployConfig.label} "${options.name}" not found in configuration.`);
    }
  } else if (entities.length === 1) {
    selectedEntity = entities[0];
  } else {
    const answer = await safePrompt<{ entity: any }>([
      {
        type: 'list',
        name: 'entity',
        message: `Select a ${deployConfig.label} to deploy:`,
        choices: entities.map((e: any) => ({ name: `${e.name} (v${e.version})`, value: e })),
      },
    ]);
    if (!answer) {
      console.log('Deployment cancelled.');
      return { deployed: false, hintPrinted: false, entityName: '' };
    }
    clearPromptLines(2);
    selectedEntity = answer.entity;
  }

  const entityId = selectedEntity[deployConfig.idField];
  if (!entityId) {
    throw new Error(
      `${deployConfig.label} "${selectedEntity.name}" is missing its ID. Please push it first using: lua push ${deployConfig.type}`
    );
  }

  writeInfo(`📦 Deploying ${deployConfig.label}: ${selectedEntity.name}`);

  // Fetch available versions
  writeProgress('🔄 Fetching available versions...');
  const versions = await deployConfig.getVersions(apiKey, agentId, entityId);

  if (!versions || versions.length === 0) {
    throw new Error(
      `No versions found for ${deployConfig.label} "${selectedEntity.name}". Push it first using: lua push ${deployConfig.type}`
    );
  }

  const sortedVersions = sortVersionsByDate(versions);

  // Select version
  let selectedVersion: string;
  if (options.version) {
    if (options.version.toLowerCase() === 'latest') {
      selectedVersion = sortedVersions[0].version;
    } else {
      const exists = sortedVersions.some((v) => v.version === options.version);
      if (!exists) {
        console.log('\nAvailable versions:');
        sortedVersions.slice(0, 5).forEach((v) => console.log(`  - ${v.version}`));
        if (sortedVersions.length > 5) console.log(`  ... and ${sortedVersions.length - 5} more`);
        throw new Error(`Version "${options.version}" not found.`);
      }
      selectedVersion = options.version;
    }
  } else {
    selectedVersion = await promptVersionSelection(sortedVersions);
  }

  writeInfo(`📦 Selected version: ${selectedVersion}`);

  // Confirm
  if (!options.force) {
    const confirmed = await confirmDeployment();
    if (!confirmed) {
      console.log('❌ Deployment cancelled.');
      process.exit(0);
    }
  }

  // Publish
  writeProgress('🔄 Publishing version...');
  const result = await deployConfig.handler.publishVersion(apiKey, agentId, entityId, selectedVersion);
  if (!result.success) {
    // Publish is a management operation — no execution logs exist for a failed publish.
    // The error reason is already on screen.
    throw new Error(`Failed to deploy: ${result.error || 'Unknown error'}`);
  }

  writeSuccess(`✅ ${deployConfig.label} "${selectedEntity.name}" v${selectedVersion} deployed successfully`);

  // B11: consolidate YAML update to a single location (applies to all types including job).
  if (selectedVersion !== selectedEntity.version) {
    writeInfo(`📝 Updating YAML with deployed version: ${selectedVersion}`);
    deployConfig.handler.updateVersionInYaml(selectedEntity.name, selectedVersion);
  }

  // B6: job prints its own hint block; set hintPrinted so the outer deployCommand
  // skips the generic "Version is live" block (avoiding duplicate hints).
  if (deployConfig.type === 'job') {
    writeHintBlock({
      headline: 'Job is live. Trigger or wait for schedule, then inspect logs:',
      lines: [
        { label: 'Manual trigger:', command: `lua jobs trigger --job-name ${selectedEntity.name}` },
        { label: 'Inspect:', command: buildLogsCommand({ primitiveType: 'job', name: selectedEntity.name }) },
      ],
      when: 'success',
    });
    return { deployed: true, hintPrinted: true, entityName: selectedEntity.name };
  }

  return { deployed: true, hintPrinted: false, entityName: selectedEntity.name };
}

/**
 * Deploy a persona version. Persona uses integer version IDs (not semver).
 */
async function deployPersonaVersion(apiKey: string, agentId: string, options: DeployOptions): Promise<boolean> {
  const personaApi = new PersonaApi(BASE_URLS.API, apiKey, agentId);

  writeProgress('🔄 Fetching persona versions...');
  const result = await personaApi.getVersions('all');
  const versions = result.data?.versions || [];

  if (versions.length === 0) {
    throw new Error('No persona versions found. Push a persona first using: lua push agent');
  }

  // Sort by createdDate descending (persona versions use numeric timestamps)
  const sortedVersions = versions.sort((a, b) => b.createdDate - a.createdDate);

  // Select version
  let selectedVersion: number;
  if (options.version) {
    if (options.version.toLowerCase() === 'latest') {
      selectedVersion = sortedVersions[0].version;
    } else {
      const v = parseInt(options.version, 10);
      if (isNaN(v)) {
        throw new Error(`Invalid persona version: "${options.version}". Must be a number or 'latest'.`);
      }
      if (!sortedVersions.some((pv) => pv.version === v)) {
        throw new Error(`Persona version ${v} not found.`);
      }
      selectedVersion = v;
    }
  } else {
    const answer = await safePrompt<{ version: number }>([
      {
        type: 'list',
        name: 'version',
        message: 'Select a persona version to deploy:',
        choices: sortedVersions.map((v) => ({
          name: `v${v.version}${v.isCurrent ? ' (CURRENT)' : ''} — ${new Date(v.createdDate).toLocaleDateString()}`,
          value: v.version,
        })),
      },
    ]);
    if (!answer) {
      console.log('Deployment cancelled.');
      return false;
    }
    clearPromptLines(2);
    selectedVersion = answer.version;
  }

  writeInfo(`📦 Selected persona version: ${selectedVersion}`);

  if (!options.force) {
    const confirmed = await confirmDeployment();
    if (!confirmed) {
      console.log('❌ Deployment cancelled.');
      process.exit(0);
    }
  }

  writeProgress('🔄 Deploying persona...');
  const deployResult = await personaApi.deployVersion(selectedVersion);
  if (!deployResult.success) {
    // Persona deploy is a management operation — no execution logs exist.
    throw new Error(`Failed to deploy persona: ${(deployResult.error as any)?.message || 'Unknown error'}`);
  }

  writeSuccess(`✅ Persona v${selectedVersion} deployed successfully`);
  return true;
}

/**
 * Deploy latest version of every primitive — mirrors `lua push all --force --auto-deploy`.
 */
async function deployAllCommand(_options: DeployOptions): Promise<void> {
  const config = readYamlConfig();
  validateSkillConfig(config);
  const apiKey = await requireAuthOrExit();
  const agentId = config.agent!.agentId!;

  let deployedCount = 0;
  let failedCount = 0;
  const failedItems: Array<{ kind: string; name: string; error: string }> = [];

  console.log('\n🚀 Deploying latest versions of all primitives...\n');

  // Deploy all versioned primitives
  for (const deployConfig of VERSIONED_DEPLOY_TYPES) {
    const entities = deployConfig.handler.getFromYaml(config);
    for (const entity of entities) {
      const entityId = entity[deployConfig.idField];
      if (!entityId) {
        console.warn(`  ⚠️  ${deployConfig.label} "${entity.name}" missing ID, skipping`);
        continue;
      }

      try {
        const versions = await deployConfig.getVersions(apiKey, agentId, entityId);
        if (!versions || versions.length === 0) {
          writeInfo(`  ℹ️  No versions for ${deployConfig.label} "${entity.name}", skipping`);
          continue;
        }
        const latestVersion = sortVersionsByDate(versions)[0].version;

        const result = await deployConfig.handler.publishVersion(apiKey, agentId, entityId, latestVersion);
        if (result.success) {
          writeSuccess(`  ✅ ${deployConfig.label} "${entity.name}" v${latestVersion} deployed`);
          if (latestVersion !== entity.version) {
            deployConfig.handler.updateVersionInYaml(entity.name, latestVersion);
          }
          deployedCount++;
        } else {
          console.warn(`  ⚠️  Failed to deploy ${deployConfig.label} "${entity.name}": ${result.error}`);
          failedItems.push({ kind: deployConfig.type, name: entity.name, error: result.error || 'Unknown error' });
          failedCount++;
        }
      } catch (e: any) {
        console.warn(`  ⚠️  Error deploying ${deployConfig.label} "${entity.name}": ${e.message}`);
        failedItems.push({ kind: deployConfig.type, name: entity.name, error: e.message });
        failedCount++;
      }
    }
  }

  // Deploy persona (latest version)
  try {
    const personaApi = new PersonaApi(BASE_URLS.API, apiKey, agentId);
    const latestPersona = await personaApi.getLatestVersion();
    if (latestPersona) {
      const deployResult = await personaApi.deployVersion(latestPersona.version);
      if (deployResult.success) {
        writeSuccess(`  ✅ Persona v${latestPersona.version} deployed`);
        deployedCount++;
      } else {
        console.warn('  ⚠️  Failed to deploy persona');
        failedItems.push({
          kind: 'persona',
          name: 'persona',
          error: (deployResult.error as any)?.message || 'Unknown error',
        });
        failedCount++;
      }
    }
  } catch (e: any) {
    console.warn(`  ⚠️  Error deploying persona: ${e.message}`);
    failedItems.push({ kind: 'persona', name: 'persona', error: e.message });
    failedCount++;
  }

  console.log();
  if (deployedCount > 0) {
    writeSuccess(`✅ Deployed ${deployedCount} primitive${deployedCount !== 1 ? 's' : ''} successfully`);
  }
  if (deployedCount === 0 && failedCount === 0) {
    writeInfo('ℹ️  No primitives found to deploy.');
  }

  // Aggregate failure block. Deploy failures are management-plane — no execution logs
  // exist for them. Suggest retrying rather than checking logs.
  if (failedItems.length > 0) {
    console.warn(`\n⚠️  ${failedItems.length} deployment${failedItems.length !== 1 ? 's' : ''} failed:`);
    for (const item of failedItems) {
      console.warn(`     ${item.kind} "${item.name}": ${item.error}`);
    }
    writeTip('Re-deploy failed items with: lua deploy all --force');
  }

  trackEvent('cli_deploy_completed', {
    primitive_type: 'all',
    force_mode: true,
    deployed_count: deployedCount,
    failed_count: failedCount,
  });

  if (deployedCount > 0 && failedCount === 0) {
    writeHintBlock({
      headline: 'All deployed. Generate traffic first, then inspect:',
      lines: [
        { label: 'Test:', command: 'lua chat -e production -m "your test message"' },
        { label: 'Inspect:', command: buildLogsCommand({ limit: 10 }) },
      ],
      when: 'success',
    });
  } else if (deployedCount > 0 && failedCount > 0) {
    // Some succeeded — remind them to test what's live, and retry failures.
    writeHintBlock({
      headline: 'Partial deploy. Test what is live and re-deploy failures:',
      lines: [
        { label: 'Test live:', command: 'lua chat -e production -m "your test message"' },
        { label: 'Re-deploy:', command: 'lua deploy all --force' },
      ],
      when: 'partial',
    });
  }
  // Total failure: no hint — errors already shown above.
}
