/**
 * Telemetry Command
 * Manage usage data collection.
 */

import { withErrorHandling } from '../utils/cli.js';
import { setTelemetryEnabled, getTelemetryStatus, trackEvent } from '../services/analytics.js';
import { validateOrSuggest } from '../utils/aliases.js';

export async function telemetryCommand(action?: string): Promise<void> {
  return withErrorHandling(async () => {
    if (action) {
      action = validateOrSuggest('telemetry.action', action);
    }
    if (action === 'on') {
      setTelemetryEnabled(true);
      console.log('Telemetry enabled. Usage data will be collected.');
      console.log('Thank you for helping improve Lua CLI!');
      trackEvent('cli_telemetry_action', { action: 'on' });
      return;
    }

    if (action === 'off') {
      trackEvent('cli_telemetry_action', { action: 'off' });
      setTelemetryEnabled(false);
      console.log('Telemetry disabled. No usage data will be collected.');
      return;
    }

    // Default: status
    const { enabled, envOverride } = getTelemetryStatus();
    console.log(`Telemetry: ${enabled ? 'enabled' : 'disabled'}`);
    if (envOverride) {
      console.log('  (overridden by LUA_TELEMETRY environment variable)');
    }
    console.log('');
    console.log('Usage:');
    console.log('  lua telemetry on      Enable telemetry');
    console.log('  lua telemetry off     Disable telemetry');
    console.log('  lua telemetry status  Show current setting');
    console.log('');
    console.log('Or set LUA_TELEMETRY=false in your environment.');
    trackEvent('cli_telemetry_action', { action: action || 'status', current_status: enabled });
  }, 'telemetry');
}
