import { HttpClient } from './http.client.js';
import { ApiResponse } from '../interfaces/common.js';

export interface CallLogsFilters {
  from?: number;
  to?: number;
  direction?: 'inbound' | 'outbound';
  status?: string;
  provider?: 'vonage' | 'livekit' | 'recall';
  channel?: 'phone' | 'web' | 'whatsapp' | 'meeting';
  page?: number;
  limit?: number;
}

export interface CallLogRow {
  callUuid: string;
  from: string;
  to: string;
  userId: string;
  direction: 'inbound' | 'outbound';
  status: string;
  provider?: string;
  channel?: string;
  startedAt: number;
  answeredAt?: number;
  endedAt?: number;
  durationSeconds?: number;
  endReason?: string;
  recordingEnabled?: boolean;
  recordingUrl?: string;
  transcriptionEnabled?: boolean;
}

export interface CallLogsResponse {
  calls: CallLogRow[];
  total: number;
  page: number;
  limit: number;
  totalPages: number;
}

/**
 * Voice call records — paginated `voiceCallRecords` view. Reads the same
 * data the admin dashboard's call viewer uses; populated by lua-core's
 * `LivekitBridgeService.reportSession` (legacy path) and the
 * `SessionReporter.flush()` call at the end of every compiled-voice
 * session.
 *
 * Hits the admin route (`/admin/agents/:agentId/call-metrics/logs`) —
 * the AgentOwnershipMiddleware on that path accepts dev API keys for
 * the agents the dev owns, matching how `lua channels phone bind`
 * already hits `/admin/agents/:agentId/channels`.
 */
export default class CallMetricsApi extends HttpClient {
  private apiKey: string;
  private agentId: string;

  constructor(baseUrl: string, apiKey: string, agentId: string) {
    super(baseUrl);
    this.apiKey = apiKey;
    this.agentId = agentId;
  }

  async listCalls(filters: CallLogsFilters = {}): Promise<ApiResponse<CallLogsResponse>> {
    const params = new URLSearchParams();
    if (filters.from !== undefined) params.set('from', String(filters.from));
    if (filters.to !== undefined) params.set('to', String(filters.to));
    if (filters.direction) params.set('direction', filters.direction);
    if (filters.status) params.set('status', filters.status);
    if (filters.provider) params.set('provider', filters.provider);
    if (filters.channel) params.set('channel', filters.channel);
    if (filters.page !== undefined) params.set('page', String(filters.page));
    if (filters.limit !== undefined) params.set('limit', String(filters.limit));
    const qs = params.toString();
    const url = qs
      ? `/admin/agents/${this.agentId}/call-metrics/logs?${qs}`
      : `/admin/agents/${this.agentId}/call-metrics/logs`;
    return this.httpGet<CallLogsResponse>(url, { Authorization: `Bearer ${this.apiKey}` });
  }
}
