/**
 * Voice compilation plugin.
 *
 * Detects code-defined LuaVoice agents in two shapes:
 *   1. Class-based:    `new LuaVoice({ ... })`
 *   2. Function-based: `const v = defineVoice({ ... })`
 *
 * For the `llm` / `stt` / `tts` fields, three input forms are accepted and
 * normalized to the discriminated union the wire schema expects:
 *
 *   - String descriptor `'provider/model[:suffix]'` → `{ kind: 'inference', model, voice? }`
 *   - `new inference.LLM/STT/TTS({...})`            → `{ kind: 'inference', model, voice?, options? }`
 *   - `new <provider>.LLM/STT/TTS({...})`           → `{ kind: 'plugin', provider, class, options }`
 *
 * Only providers on the allowlist exported from `@lua/shared-types`
 * (deepgram, elevenlabs) are accepted in the plugin form — Lua's worker
 * holds keys for those. Anything else must use the descriptor route.
 *
 * Function-bearing fields — `tools`, `onEnter`, `onUserTurnCompleted`,
 * `onExit` — are detected by AST presence and surface as flags in the
 * manifest entry; their executable bodies belong to the artifact bundle
 * the worker loads at dispatch.
 */

import fs from 'fs/promises';
import {
  LuaVoiceConfigSchema,
  PluginProviderSchema,
  RealtimeProviderSchema,
  type LuaVoiceModel,
  type LuaVoicePluginProvider,
  type LuaVoiceRealtimeProvider,
} from '@lua/shared-types';
import type { ZodIssue } from 'zod';
import { Node, NewExpression, ObjectLiteralExpression } from 'ts-morph';
import {
  PrimitiveKind,
  type PrimitiveMetadata,
  type VoiceMetadata,
  type VoiceMetadataFields,
  type ValidationResult,
  type CompiledPrimitive,
  type ManifestPrimitive,
  type ManifestVoice,
  type BundledArtifact,
} from '../types.js';
import {
  extractStringProperty,
  extractNumberProperty,
  extractBooleanProperty,
  extractObjectProperty,
  hasProperty,
} from '../utils/ast-helpers.js';
import { hashContent } from '../utils/common.js';
import { BasePlugin, validationError } from './base.js';

const PLUGIN_PROVIDERS: ReadonlyArray<string> = PluginProviderSchema.options;
const REALTIME_PROVIDERS: ReadonlyArray<string> = RealtimeProviderSchema.options;
const PLUGIN_CLASSES = ['LLM', 'STT', 'STTv2', 'TTS'] as const;
type PluginClassName = (typeof PLUGIN_CLASSES)[number];

/**
 * Field → accepted classes. `stt` admits both `STT` (Deepgram v1, plus
 * elevenlabs Scribe) and `STTv2` (Deepgram Flux). Other fields stay
 * one-to-one.
 */
const FIELD_CLASSES: Record<ModelField, ReadonlyArray<PluginClassName>> = {
  llm: ['LLM'],
  stt: ['STT', 'STTv2'],
  tts: ['TTS'],
};

type ModelField = 'llm' | 'stt' | 'tts';

interface ExtractionError {
  field: ModelField;
  message: string;
}

interface ExtractionResult {
  model?: LuaVoiceModel;
  error?: ExtractionError;
}

/**
 * Convert a small ObjectLiteralExpression to a plain JS object. Handles
 * string / number / boolean / nested-object / array literals — the surface
 * LiveKit plugin constructors actually accept. Anything beyond that
 * (function refs, computed properties, identifiers that don't statically
 * evaluate) becomes `undefined` and is dropped from the bag.
 */
function astObjectToPlain(obj: ObjectLiteralExpression): Record<string, unknown> {
  const result: Record<string, unknown> = {};
  for (const prop of obj.getProperties()) {
    // Spread (`{ ...baseOpts, model: 'X' }`): try to evaluate the
    // spread expression to a plain object and merge. ts-evaluator
    // handles literal const refs + cross-file imports; opaque
    // expressions return undefined and the spread silently drops.
    if (Node.isSpreadAssignment(prop)) {
      const expr = prop.getExpression();
      const evaluated = astValueToPlain(expr);
      if (evaluated && typeof evaluated === 'object' && !Array.isArray(evaluated)) {
        Object.assign(result, evaluated);
      }
      continue;
    }
    // Shorthand (`{ voice }` where `voice` is in scope): `getNameNode()`
    // returns the bare Identifier; evaluating it walks the same
    // identifier-resolution chain as cross-file imports.
    if (Node.isShorthandPropertyAssignment(prop)) {
      const key = prop.getName();
      if (!key) continue;
      const v = astValueToPlain(prop.getNameNode());
      if (v !== undefined) result[key] = v;
      continue;
    }
    if (!Node.isPropertyAssignment(prop)) continue;
    const key = prop.getName();
    if (!key) continue;
    const value = prop.getInitializer();
    if (!value) continue;
    const v = astValueToPlain(value);
    if (v !== undefined) result[key] = v;
  }
  return result;
}

function astValueToPlain(value: Node): unknown {
  if (Node.isStringLiteral(value) || Node.isNoSubstitutionTemplateLiteral(value)) {
    return value.getLiteralText();
  }
  if (Node.isNumericLiteral(value)) {
    return Number(value.getLiteralText());
  }
  if (Node.isTrueLiteral(value)) return true;
  if (Node.isFalseLiteral(value)) return false;
  if (Node.isObjectLiteralExpression(value)) return astObjectToPlain(value);
  if (Node.isArrayLiteralExpression(value)) {
    return value
      .getElements()
      .map((el) => astValueToPlain(el))
      .filter((x) => x !== undefined);
  }
  return undefined;
}

function splitOnFirstColon(s: string): [string, string | undefined] {
  const idx = s.indexOf(':');
  if (idx < 0) return [s, undefined];
  return [s.slice(0, idx), s.slice(idx + 1)];
}

/**
 * Parse a `provider/model[:suffix]` descriptor. The suffix becomes `voice`
 * for TTS, `options.language` for STT, and is rejected for LLM (no suffix
 * convention there).
 */
function parseDescriptor(descriptor: string, field: ModelField): ExtractionResult {
  const [model, suffix] = splitOnFirstColon(descriptor);
  if (!model) {
    return { error: { field, message: `\`${field}\` descriptor must be a non-empty 'provider/model' string` } };
  }
  const out: LuaVoiceModel = { kind: 'inference', model };
  if (suffix !== undefined) {
    if (field === 'tts') {
      (out as { voice?: string }).voice = suffix;
    } else if (field === 'stt') {
      out.options = { language: suffix };
    } else {
      return {
        error: { field, message: 'LLM descriptor cannot carry a `:suffix` — use a plain `provider/model` string' },
      };
    }
  }
  return { model: out };
}

function stripKeys(obj: Record<string, unknown>, keys: string[]): Record<string, unknown> {
  const out: Record<string, unknown> = {};
  for (const [k, v] of Object.entries(obj)) {
    if (!keys.includes(k)) out[k] = v;
  }
  return out;
}

/**
 * Walk the leftmost identifier in a PropertyAccessExpression chain. For
 * `openai.realtime.RealtimeModel` returns "openai"; for the Gemini Node
 * SDK shape `google.beta.realtime.RealtimeModel` returns "google".
 * Returns undefined if the chain doesn't bottom out at an Identifier.
 */
function leftmostIdentifierName(node: Node): string | undefined {
  let current: Node = node;
  while (Node.isPropertyAccessExpression(current)) {
    current = current.getExpression();
  }
  return Node.isIdentifier(current) ? current.getText() : undefined;
}

/**
 * Realtime detection. Triggered when the constructed class is named
 * `RealtimeModel` and the immediate parent of that name is `.realtime`.
 * Accepts both shapes:
 *   - `<provider>.realtime.RealtimeModel({...})`        — openai, xai
 *   - `<provider>.beta.realtime.RealtimeModel({...})`   — google (Node SDK)
 *
 * Realtime models go in the `llm:` slot only. STT/TTS rejection is
 * handled by the schema's superRefine, but we shape-check the field here
 * for a clearer compile-time error.
 */
function extractRealtimeFromNewExpression(
  newExpr: NewExpression,
  classExpr: import('ts-morph').PropertyAccessExpression,
  field: ModelField
): ExtractionResult | undefined {
  if (classExpr.getName() !== 'RealtimeModel') return undefined;

  const realtimeNode = classExpr.getExpression();
  if (!Node.isPropertyAccessExpression(realtimeNode) || realtimeNode.getName() !== 'realtime') {
    return undefined;
  }

  if (field !== 'llm') {
    return {
      error: {
        field,
        message: `\`${field}\` cannot be a RealtimeModel — realtime models occupy the \`llm\` slot only. Move it to \`llm:\` and drop \`${field}:\` (full realtime), or keep \`${field}:\` and use a cascaded \`llm\`.`,
      },
    };
  }

  const provider = leftmostIdentifierName(realtimeNode.getExpression());
  if (!provider) {
    return {
      error: {
        field,
        message:
          '`llm` realtime form must be `new <provider>.realtime.RealtimeModel({...})` (or `new google.beta.realtime.RealtimeModel({...})` for Gemini)',
      },
    };
  }
  if (!REALTIME_PROVIDERS.includes(provider)) {
    return {
      error: {
        field,
        message:
          `Realtime provider \`${provider}\` is not on the allowlist ` +
          `(${REALTIME_PROVIDERS.join(', ')}). Lua holds API keys for the listed providers; add a new one by extending RealtimeProviderSchema in shared-types + the worker plugin import.`,
      },
    };
  }

  const optsArg = newExpr.getArguments()[0];
  let options: Record<string, unknown> = {};
  if (optsArg && Node.isObjectLiteralExpression(optsArg)) {
    options = astObjectToPlain(optsArg);
  }

  return {
    model: {
      kind: 'realtime',
      provider: provider as LuaVoiceRealtimeProvider,
      options,
    },
  };
}

function extractFromNewExpression(newExpr: NewExpression, field: ModelField): ExtractionResult {
  const expr = newExpr.getExpression();
  if (!Node.isPropertyAccessExpression(expr)) {
    return {
      error: { field, message: `\`${field}\` plugin form must be \`new <module>.<Class>({...})\`` },
    };
  }

  // Realtime check first — `openai.realtime.RealtimeModel` etc. is a
  // PropertyAccessExpression whose .getExpression() is itself a
  // PropertyAccessExpression. Plugin form (`deepgram.STT`) bottoms out
  // with an Identifier on .getExpression(), so the two are
  // unambiguously distinguishable.
  const realtimeResult = extractRealtimeFromNewExpression(newExpr, expr, field);
  if (realtimeResult) return realtimeResult;

  const moduleName = expr.getExpression().getText();
  const className = expr.getName();

  if (!(PLUGIN_CLASSES as readonly string[]).includes(className)) {
    return {
      error: {
        field,
        message: `\`${field}\` got \`new ${moduleName}.${className}(...)\` — class must be one of ${PLUGIN_CLASSES.join(', ')}`,
      },
    };
  }
  if (!FIELD_CLASSES[field].includes(className as PluginClassName)) {
    return {
      error: {
        field,
        message: `\`${field}\` cannot be assigned a \`.${className}\` instance — accepted classes for this field: ${FIELD_CLASSES[field].join(', ')}`,
      },
    };
  }

  const optsArg = newExpr.getArguments()[0];
  let options: Record<string, unknown> = {};
  if (optsArg && Node.isObjectLiteralExpression(optsArg)) {
    options = astObjectToPlain(optsArg);
  }

  // `inference.LLM/STT/TTS` is a typed shortcut for the descriptor route.
  if (moduleName === 'inference') {
    const model = typeof options.model === 'string' ? options.model : '';
    if (!model) {
      return {
        error: {
          field,
          message: `\`new inference.${className}(...)\` requires a string \`model\` option`,
        },
      };
    }
    const out: LuaVoiceModel = { kind: 'inference', model };
    if (field === 'tts' && typeof options.voice === 'string') {
      (out as { voice?: string }).voice = options.voice;
    }
    const rest = stripKeys(options, ['model', 'voice']);
    if (Object.keys(rest).length > 0) out.options = rest;
    return { model: out };
  }

  if (!PLUGIN_PROVIDERS.includes(moduleName)) {
    return {
      error: {
        field,
        message:
          `Provider \`${moduleName}\` is not on the plugin allowlist ` +
          `(${PLUGIN_PROVIDERS.join(', ')}). Use a string descriptor like \`'${moduleName}/<model>'\` ` +
          `to route through Inference instead.`,
      },
    };
  }

  return {
    model: {
      kind: 'plugin',
      provider: moduleName as LuaVoicePluginProvider,
      class: className as PluginClassName,
      options,
    },
  };
}

/**
 * Unwrap `(value as Foo)` / `(value satisfies Foo)` / `(value)` so the
 * AST shape checks below see the underlying expression. Devs reach for
 * `as any` to silence transient TS errors during refactors and the
 * compiler should still introspect the real value.
 */
function unwrapType(node: Node): Node {
  let current: Node = node;
  while (
    Node.isAsExpression(current) ||
    Node.isSatisfiesExpression(current) ||
    Node.isParenthesizedExpression(current)
  ) {
    const inner = (current as { getExpression?: () => Node | undefined }).getExpression?.();
    if (!inner) break;
    current = inner;
  }
  return current;
}

/**
 * Extract one of `llm` / `stt` / `tts`, normalizing the three accepted
 * input shapes to the wire's discriminated union. Returns `{}` when the
 * field is absent — that's a missing-required error caught later.
 */
function extractModelField(config: ObjectLiteralExpression, field: ModelField): ExtractionResult {
  const prop = config.getProperty(field);
  if (!prop || !Node.isPropertyAssignment(prop)) return {};
  const initializer = prop.getInitializer();
  if (!initializer) return {};
  const value = unwrapType(initializer);

  if (Node.isStringLiteral(value) || Node.isNoSubstitutionTemplateLiteral(value)) {
    const text = value.getLiteralText();
    if (!text) {
      return { error: { field, message: `\`${field}\` descriptor cannot be empty` } };
    }
    return parseDescriptor(text, field);
  }

  if (Node.isObjectLiteralExpression(value)) {
    // Object literal sugar is TTS-only ({ model, voice }).
    if (field !== 'tts') {
      return {
        error: {
          field,
          message: `\`${field}\` accepts a string descriptor or a plugin class instance — object literals are TTS-only sugar`,
        },
      };
    }
    const plain = astObjectToPlain(value);
    if (typeof plain.model !== 'string') {
      return { error: { field, message: 'TTS struct shorthand requires `{ model, voice }` with string model' } };
    }
    const out: LuaVoiceModel = { kind: 'inference', model: plain.model };
    if (typeof plain.voice === 'string') (out as { voice?: string }).voice = plain.voice;
    return { model: out };
  }

  if (Node.isNewExpression(value)) {
    return extractFromNewExpression(value, field);
  }

  return {
    error: {
      field,
      message: `\`${field}\` must be a string descriptor or a plugin class instance (e.g. \`new deepgram.STT({...})\`)`,
    },
  };
}

/**
 * Property name → "is the value a function (arrow or method)" check.
 * Used to detect presence of hook handlers without trying to evaluate them.
 */
function hasFunctionProperty(config: ObjectLiteralExpression, propertyName: string): boolean {
  const prop = config.getProperty(propertyName);
  if (!prop) return false;
  if (Node.isMethodDeclaration(prop)) return true;
  if (!Node.isPropertyAssignment(prop)) return false;
  const value = prop.getInitializer();
  if (!value) return false;
  if (Node.isArrowFunction(value) || Node.isFunctionExpression(value)) return true;
  // Identifier-referenced hooks (`{ onEnter: importedHandler }`) — common
  // when devs factor hook bodies into separate files. Pre-fix this returned
  // false and the worker skipped loading the bundle entirely; the runtime
  // type can't be confirmed AST-side so we treat any identifier reference
  // as "probably a function" and let the worker validate at load time.
  if (Node.isIdentifier(value)) return true;
  return false;
}

/**
 * Property name → "is the value an array" check. Element resolution is
 * the worker's job once the bundle is loaded; the manifest only needs
 * the presence flag.
 */
function hasArrayProperty(config: ObjectLiteralExpression, propertyName: string): boolean {
  const prop = config.getProperty(propertyName);
  if (!prop || !Node.isPropertyAssignment(prop)) return false;
  const value = prop.getInitializer();
  if (!value) return false;
  return Node.isArrayLiteralExpression(value);
}

/**
 * Filter the result of `extractObjectProperty('pronunciations')` to a
 * strict `Record<string, string>`. `ts-evaluator` returns
 * `Record<string, unknown>` even for shapes that should be all-string
 * (e.g. when reading a JSON-imported map), so we drop non-string values
 * here. Zod's `record(z.string(), z.string())` would reject the whole
 * map otherwise — letting one stray non-string entry tank the entire
 * pronunciations config is worse UX than dropping the bad entry.
 *
 * Returns the cleaned map plus the list of dropped keys so the caller
 * can surface them as warnings during `validate()`.
 */
function normalizePronunciations(raw: Record<string, unknown> | undefined): {
  map: Record<string, string> | undefined;
  droppedKeys: string[];
} {
  if (!raw) return { map: undefined, droppedKeys: [] };
  const out: Record<string, string> = {};
  const droppedKeys: string[] = [];
  for (const [key, value] of Object.entries(raw)) {
    if (typeof value === 'string') {
      out[key] = value;
    } else {
      droppedKeys.push(key);
    }
  }
  return { map: Object.keys(out).length > 0 ? out : undefined, droppedKeys };
}

/**
 * Voice metadata + carryover for AST-level extraction errors and
 * warnings. The compiler reads `metadata` for everything user-visible;
 * the `_extraction*` fields are internal (consumed by `validate()`).
 */
type VoiceExtractedMetadata = VoiceMetadata & {
  _extractionErrors?: ExtractionError[];
  _extractionWarnings?: string[];
};

export class VoicePlugin extends BasePlugin<VoiceMetadataFields> {
  readonly kind = PrimitiveKind.VOICE;
  readonly displayName = 'Voice';
  readonly defineFunction = 'defineVoice';
  readonly legacyClassNames = ['LuaVoice'];

  protected extractFromConfig(
    config: ObjectLiteralExpression,
    exportName: string,
    sourcePath: string,
    position: { line: number; column: number },
    pattern: 'function' | 'class'
  ): VoiceExtractedMetadata | null {
    const common = this.extractCommonFields(config, exportName, sourcePath, position);
    if (!common) return null;

    // Top-level scalar fields. ts-evaluator behind these so variable refs
    // and constant expressions resolve.
    const vad = extractStringProperty(config, 'vad');
    const vadOptions = extractObjectProperty(config, 'vadOptions') as VoiceMetadataFields['vadOptions'];
    const turnDetection = extractStringProperty(config, 'turnDetection');
    const greeting = extractStringProperty(config, 'greeting');
    const sttLanguage = extractStringProperty(config, 'sttLanguage');
    const maxToolSteps = extractNumberProperty(config, 'maxToolSteps');
    const userAwayTimeout = extractNumberProperty(config, 'userAwayTimeout');
    const preemptiveGeneration = extractBooleanProperty(config, 'preemptiveGeneration');

    const llm = extractModelField(config, 'llm');
    const stt = extractModelField(config, 'stt');
    const tts = extractModelField(config, 'tts');

    const krispEnabled = extractBooleanProperty(config, 'krispEnabled');
    const persistTranscript = extractBooleanProperty(config, 'persistTranscript');
    const volume = extractNumberProperty(config, 'volume');
    // Pre-fix the compiler captured `hasInterruption` (boolean presence)
    // but never the object itself — `mode` / `falseInterruptionTimeout` /
    // `minDelay` / `maxDelay` were validated, persisted, and ignored.
    const interruption = extractObjectProperty(config, 'interruption') as
      | VoiceMetadataFields['interruption']
      | undefined;
    // ts-evaluator handles inline objects, const refs, and JSON imports
    // for both pronunciations + backgroundAudio. Devs can keep their map
    // in a separate file and reference it: `import pron from './pron.json'`.
    const pronunciationsRaw = extractObjectProperty(config, 'pronunciations');
    const { map: pronunciations, droppedKeys: droppedPronunciationKeys } = normalizePronunciations(pronunciationsRaw);
    const extractionWarnings: string[] = [];
    if (droppedPronunciationKeys.length > 0) {
      extractionWarnings.push(
        `\`pronunciations\` map dropped ${droppedPronunciationKeys.length} non-string ` +
          `value(s) (keys: ${droppedPronunciationKeys.join(', ')}). Each value must be the spoken-form string.`
      );
    }
    const backgroundAudio = extractObjectProperty(config, 'backgroundAudio') as
      | { ambient?: unknown; thinking?: unknown }
      | undefined;

    const errors: ExtractionError[] = [];
    if (llm.error) errors.push(llm.error);
    if (stt.error) errors.push(stt.error);
    if (tts.error) errors.push(tts.error);

    return {
      kind: this.kind,
      ...common,
      metadata: {
        pattern,
        llm: llm.model,
        stt: stt.model,
        tts: tts.model,
        vad,
        vadOptions,
        turnDetection,
        greeting,
        maxToolSteps,
        userAwayTimeout,
        preemptiveGeneration,
        sttLanguage,
        hasInterruption: hasProperty(config, 'interruption'),
        hasOnEnter: hasFunctionProperty(config, 'onEnter'),
        hasOnUserTurnCompleted: hasFunctionProperty(config, 'onUserTurnCompleted'),
        hasOnExit: hasFunctionProperty(config, 'onExit'),
        hasTools: hasArrayProperty(config, 'tools'),
        krispEnabled,
        persistTranscript,
        volume,
        pronunciations,
        backgroundAudio,
        interruption,
      },
      _extractionErrors: errors.length > 0 ? errors : undefined,
      _extractionWarnings: extractionWarnings.length > 0 ? extractionWarnings : undefined,
    };
  }

  validate(metadata: VoiceMetadata): ValidationResult {
    const { errors, warnings } = this.baseValidation(metadata);
    const fields = metadata.metadata;
    const line = metadata.line;
    const extractionErrors = (metadata as VoiceExtractedMetadata)._extractionErrors ?? [];
    const extractionWarnings = (metadata as VoiceExtractedMetadata)._extractionWarnings ?? [];

    // AST-level extraction errors first — these point at the developer's
    // exact mistake (e.g. unsupported provider plugin) and trump the
    // generic "field missing" emitted by zod afterwards.
    for (const err of extractionErrors) {
      errors.push(validationError(err.message, { line }));
    }
    for (const warningMessage of extractionWarnings) {
      warnings.push({ message: warningMessage, line });
    }

    if (!fields.llm) {
      errors.push(
        validationError(
          'Voice must declare an `llm` model — pass a descriptor like `"openai/gpt-5.2-chat-latest"` or a plugin class instance.',
          { line }
        )
      );
    }
    // STT/TTS are required only for cascaded LLMs. Realtime models occupy
    // the LLM slot and handle audio in/out themselves; the schema's
    // superRefine catches mismatches (realtime + stt = error;
    // cascaded - stt = error). Skip the AST-level "missing" emission for
    // realtime so the dev sees the right zod path, not a duplicate
    // generic "stt is required" message.
    const isRealtimeLlm = fields.llm?.kind === 'realtime';
    if (!fields.stt && !isRealtimeLlm) {
      errors.push(
        validationError(
          'Voice must declare an `stt` model — pass a descriptor like `"deepgram/nova-3"` or a plugin class instance.',
          { line }
        )
      );
    }
    if (!fields.tts && !isRealtimeLlm) {
      errors.push(
        validationError(
          'Voice must declare a `tts` model — pass a descriptor like `"cartesia/sonic-3:<voiceId>"`, `{ model, voice }`, or a plugin class instance.',
          { line }
        )
      );
    }

    // Run zod even on partial configs. Pre-fix this gate required
    // `llm && stt && tts && !extractionErrors` to all be present, which
    // meant a config with `llm: someResolverCall()` (resolved to undefined
    // by ts-evaluator) skipped zod entirely — and any deeper enum / regex
    // / numeric-range error on OTHER fields was silently passed. Now we
    // build a candidate from whatever IS present and filter out zod's
    // "field is required" issues that we already report at AST level.
    if (extractionErrors.length === 0) {
      const candidate: Record<string, unknown> = { name: metadata.name };
      if (fields.llm) candidate.llm = fields.llm;
      if (fields.stt) candidate.stt = fields.stt;
      if (fields.tts) candidate.tts = fields.tts;
      if (fields.vad !== undefined) candidate.vad = fields.vad;
      if (fields.vadOptions !== undefined) candidate.vadOptions = fields.vadOptions;
      if (fields.turnDetection !== undefined) candidate.turnDetection = fields.turnDetection;
      if (fields.greeting !== undefined) candidate.greeting = fields.greeting;
      if (fields.maxToolSteps !== undefined) candidate.maxToolSteps = fields.maxToolSteps;
      if (fields.userAwayTimeout !== undefined) candidate.userAwayTimeout = fields.userAwayTimeout;
      if (fields.preemptiveGeneration !== undefined) candidate.preemptiveGeneration = fields.preemptiveGeneration;
      if (fields.sttLanguage !== undefined) candidate.sttLanguage = fields.sttLanguage;
      if (fields.krispEnabled !== undefined) candidate.krispEnabled = fields.krispEnabled;
      if (fields.persistTranscript !== undefined) candidate.persistTranscript = fields.persistTranscript;
      if (fields.volume !== undefined) candidate.volume = fields.volume;
      if (fields.pronunciations !== undefined) candidate.pronunciations = fields.pronunciations;
      if (fields.backgroundAudio !== undefined) candidate.backgroundAudio = fields.backgroundAudio;
      if (fields.interruption !== undefined) candidate.interruption = fields.interruption;

      const parsed = LuaVoiceConfigSchema.safeParse(candidate);
      if (!parsed.success) {
        // Skip zod's "Required" / "expected ..., received undefined" issues
        // on the top-level llm/stt/tts paths — we already report those at
        // AST level. Issues at any other path (turnDetection enum drift,
        // greeting too long, name regex, interruption.minDelay range, etc.)
        // come through.
        const isMissingTopLevelRequired = (issue: ZodIssue): boolean => {
          if (issue.path.length !== 1) return false;
          const top = issue.path[0];
          if (top !== 'llm' && top !== 'stt' && top !== 'tts') return false;
          // Zod marks missing-required as `code: 'invalid_type'` with
          // `received: 'undefined'`, OR (in newer zod) `code: 'invalid_union_discriminator'`
          // when the discriminated union sees `undefined`. Both shape into
          // a "field is missing" semantic; suppress.
          const code = (issue as { code?: string }).code;
          return code === 'invalid_type' || code === 'invalid_union_discriminator';
        };
        for (const issue of parsed.error.issues as ZodIssue[]) {
          if (isMissingTopLevelRequired(issue)) continue;
          const path = issue.path.length > 0 ? issue.path.join('.') : '<root>';
          errors.push(validationError(`Voice config invalid at \`${path}\`: ${issue.message}`, { line }));
        }
      }
    }

    return { valid: errors.length === 0, errors, warnings };
  }

  /**
   * Entry-point emitter for the bundled JS path. Imports the dev's
   * LuaVoice instance and re-exports its hooks + voice-only tools in
   * the flat shape the worker sandbox expects (sandbox.ts:extractExports).
   *
   * Tools land as a name-keyed map; sandbox.normalizeTools also accepts
   * arrays, but pre-normalizing here avoids one walk per session start
   * and keeps the bundle's wire shape obvious to anyone inspecting it.
   *
   * Only invoked by the compiler when `buildArtifact` returns undefined
   * (i.e. when the voice declares hooks or voice-only tools) — see
   * the conditional in `buildArtifact` below.
   */
  generateEntryPoint(metadata: PrimitiveMetadata): string {
    const importStatement = metadata.isDefaultExport
      ? `import __voice__ from ${JSON.stringify(metadata.sourcePath)};`
      : `import { __lua_target__ as __voice__ } from ${JSON.stringify(metadata.sourcePath)};`;

    return `// AUTO-GENERATED ENTRY POINT — Voice: ${metadata.name}
${importStatement}

const __luaTools = {};
if (__voice__ && Array.isArray(__voice__.tools)) {
  for (const t of __voice__.tools) {
    if (t && typeof t === 'object' && typeof t.name === 'string') {
      __luaTools[t.name] = {
        name: t.name,
        description: t.description,
        execute: t.execute,
        condition: t.condition,
        voice: t.voice,
      };
    }
  }
}

export const onEnter = __voice__ && __voice__.onEnter;
export const onUserTurnCompleted = __voice__ && __voice__.onUserTurnCompleted;
export const onExit = __voice__ && __voice__.onExit;
export const tools = __luaTools;
`;
  }

  /**
   * Emit a JSON metadata sidecar OR fall through to esbuild bundling.
   *
   * Conditional path:
   *   - No hooks + no voice-only tools → JSON metadata sidecar (cheap; no
   *     bundle ships, no sandbox runs at session start).
   *   - Any of `onEnter` / `onUserTurnCompleted` / `onExit` / `tools` → return
   *     undefined to fall through to the standard esbuild path. The
   *     resulting JS artifact is what the voice handler gzips + base64s
   *     into the push body's `bundle` field, which the worker sandbox
   *     evaluates per-call.
   *
   * The worker reads the same `hasOnEnter` / `hasOnUserTurnCompleted` /
   * `hasOnExit` / `hasTools` flags from the voice version doc to decide
   * whether to call `loadBundle` — so a metadata-only voice never even
   * looks for a bundle.
   */
  async buildArtifact(metadata: PrimitiveMetadata): Promise<BundledArtifact | undefined> {
    const fields = metadata.metadata as VoiceMetadataFields;
    const hasCode = !!(fields.hasOnEnter || fields.hasOnUserTurnCompleted || fields.hasOnExit || fields.hasTools);
    if (hasCode) return undefined;

    const sanitized = this.sanitizeForPersistence(metadata.metadata);
    const code = JSON.stringify(
      {
        kind: metadata.kind,
        name: metadata.name,
        description: metadata.description,
        metadata: sanitized,
      },
      null,
      2
    );

    const originalSource = await fs.readFile(metadata.sourcePath, 'utf-8');

    return {
      code,
      sourceMap: '',
      originalSource,
      size: Buffer.byteLength(code, 'utf8'),
      hash: hashContent(code),
    };
  }

  /**
   * `_extractionErrors` lives on the OUTER VoiceMetadata, not on the
   * inner field map this hook receives — `toManifestEntry` reads only
   * the typed fields, so the carryover never reaches the artifact. No
   * sanitization required; default identity wins.
   */

  toManifestEntry(compiled: CompiledPrimitive): ManifestPrimitive {
    const fields = compiled.metadata as VoiceMetadataFields;
    const entry: ManifestVoice = {
      kind: PrimitiveKind.VOICE,
      name: compiled.name,
      description: compiled.description,
      sourcePath: compiled.sourcePath,
      // Compiler writes every primitive's `artifact.code` to
      // `outDir/artifacts/<kind>/<name>.js` regardless of content. For
      // metadata-only voices that's a JSON string in a .js file; for
      // hook-bearing voices it's the bundled JS. The handler reads with
      // loadArtifact() which doesn't care about content type.
      path: compiled.artifact ? `artifacts/${compiled.kind}/${compiled.name}.js` : '',
      hash: compiled.artifact?.hash ?? '',
      // `llm` is always required and validate() guarantees presence. STT/TTS
      // are optional — realtime LLMs run without them (full mode) or with
      // only `tts` (half-cascade). Stubbing them with `{kind: 'inference', model: ''}`
      // would round-trip an invalid model through the wire.
      llm: fields.llm ?? ({ kind: 'inference', model: '' } as LuaVoiceModel),
      stt: fields.stt,
      tts: fields.tts,
      vad: fields.vad,
      vadOptions: fields.vadOptions,
      turnDetection: fields.turnDetection,
      greeting: fields.greeting,
      maxToolSteps: fields.maxToolSteps,
      userAwayTimeout: fields.userAwayTimeout,
      preemptiveGeneration: fields.preemptiveGeneration,
      sttLanguage: fields.sttLanguage,
      hasInterruption: fields.hasInterruption,
      hasOnEnter: fields.hasOnEnter,
      hasOnUserTurnCompleted: fields.hasOnUserTurnCompleted,
      hasOnExit: fields.hasOnExit,
      hasTools: fields.hasTools,
      krispEnabled: fields.krispEnabled,
      backgroundAudio: fields.backgroundAudio,
      volume: fields.volume,
      pronunciations: fields.pronunciations,
      persistTranscript: fields.persistTranscript,
      interruption: fields.interruption,
    };
    return entry;
  }
}
