import * as readline from 'readline';
import inquirer from 'inquirer';
import {
  withErrorHandling,
  writeProgress,
  writeSuccess,
  writeNextStep,
  writeHintBlock,
  hintsDisabled,
  writeInfo,
} from '../utils/cli.js';
import { compileCommand } from './compile.js';
import { pushSkillsToSandbox, pushProcessorsToSandbox, sendChatMessage } from '../services/sandbox.service.js';
import {
  getAllSandboxSkillIds,
  getAllSandboxPreProcessorIds,
  getAllSandboxPostProcessorIds,
} from '../utils/sandbox-storage.js';
import ChatApi from '../api/chat.api.service.js';
import { BASE_URLS } from '../config/constants.js';
import { ChatRequest, ChatMessage } from '../interfaces/chat.js';
import { parseMessageWithAttachments } from '../utils/chat-attachments.js';
