interface ChatEnvironment {
  type: 'sandbox' | 'production';
  agentId: string;
  apiKey: string;
  yamlConfig?: any;
  persona?: PersonaText;
  preprocessorOverrides?: Array<{ preprocessorId: string; sandboxId: string }>;
  postprocessorOverrides?: Array<{ postprocessorId: string; sandboxId: string }>;
  threadId?: string;
  autoClear?: boolean;
}

/**
 * Mutable holder for the per-session probe window. Passed into the
 * single-message and REPL paths so each turn can advance the high-water
 * mark without rebuilding the env object. Initialized to "now" at the
 * top of `chatCommand` after auth.
 */
interface ProbeWindow {
  value: string;
}

/**
 * Run a best-effort agent_error probe for the just-completed turn,
 * advance the per-session window, and print a one-line warning to
 * stdout when new errors were observed.
 *
 * Uses {@link probeAgentErrorsSince}, which never throws — but we wrap
 * defensively here too so a probe slip can never break the chat UX.
 */
async function runChatProbe(chatEnv: ChatEnvironment, window: ProbeWindow): Promise<void> {
  // Honour LUA_NO_HINTS — skip both the HTTP call and the print when hints are disabled.
  if (hintsDisabled()) return;
  try {
    const result = await probeAgentErrorsSince(chatEnv.apiKey, chatEnv.agentId, window.value);
    window.value = result.latestISO;
    if (result.count > 0) {
      const cmd = buildLogsCommand({ logSourceOverride: 'agent_error', limit: result.count });
      let line = `⚠️  ${result.count} new agent error(s) during this turn — run \`${cmd}\` to inspect.`;
      if (result.firstMessage) {
        line += `\n   First: ${result.firstMessage}`;
      }
      writeInfo(line);
    }
  } catch {
    // Probe must never break a chat session.
  }
}

type ChatEnvResolution =
  | { type: 'resolved'; environment: 'sandbox' | 'production' }
  | { type: 'default_sandbox'; environment: 'sandbox' }
  | { type: 'prompt' }
  | { type: 'error'; message: string };

/**
 * Resolves which environment to use for chat based on provided options
 *
 * Valid resolutions:
 * - resolved:        --env provided and valid
 * - default_sandbox: --message provided without --env → default to sandbox with notice
 * - prompt:          no --env, no --message → show interactive prompt
 *
 * Invalid:
 * - Invalid --env value
 */
function resolveChatEnvironment(env: string | undefined, hasMessage: boolean): ChatEnvResolution {
  // --env provided
  if (env) {
    const normalizedEnv = env.toLowerCase();

    if (normalizedEnv === 'sandbox' || normalizedEnv === 'staging') {
      return { type: 'resolved', environment: 'sandbox' };
    }

    if (normalizedEnv === 'production') {
      return { type: 'resolved', environment: 'production' };
    }

    return {
      type: 'error',
      message: `Invalid environment: "${env}". Must be "sandbox", "staging", or "production".`,
    };
  }

  // --message without --env → default to sandbox with notice
  if (hasMessage) {
    return { type: 'default_sandbox', environment: 'sandbox' };
  }

  // No flags → interactive prompt
  return { type: 'prompt' };
}

/**
 * Main chat command - starts interactive chat session or sends a single non-interactive message
 *
 * Features:
 * - Environment selection (sandbox or production)
 * - Interactive chat loop
 * - Skill and persona overrides for sandbox
 * - Real-time conversation
 * - Non-interactive mode: send single message and exit
 * - Exit with Ctrl+C
 *
 * @param cmdObj - Commander command object with options
 * @returns Promise that resolves when chat session ends
 */
export async function chatCommand(cmdObj?: any): Promise<void> {
  return withErrorHandling(async () => {
    // Extract options
    const message = cmdObj?.message || null;
    const batch: string[] | null = cmdObj?.batch || null;
    const delay = parseInt(cmdObj?.delay || '100', 10);
    const env = cmdObj?.env || null;
    const autoClear = !!cmdObj?.clear || !!cmdObj?.clearThread;

    // Resolve thread ID: true means flag present with no value (auto-generate), string means explicit ID
    const rawThread = cmdObj?.thread;
    let threadId: string | undefined;
    if (rawThread === true) {
      threadId = crypto.randomUUID();
    } else if (typeof rawThread === 'string' && rawThread.length > 0) {
      threadId = rawThread;
    }

    // Initialize command (validates config + auth)
    const { config, agentId, apiKey } = await initializeCommand();

    // Determine environment
    let selectedEnvironment: 'sandbox' | 'production';

    // Resolve environment
    const envResolution = resolveChatEnvironment(env, !!(message || batch));

    switch (envResolution.type) {
      case 'resolved':
        selectedEnvironment = envResolution.environment;
        break;

      case 'default_sandbox':
        console.log(`\nℹ️  No --env provided, defaulting to sandbox. Use --env production for production.\n`);
        selectedEnvironment = envResolution.environment;
        break;

      case 'prompt':
        const { environment } = await inquirer.prompt([
          {
            type: 'list',
            name: 'environment',
            message: 'Select environment:',
            choices: [
              { name: '🔧 Sandbox (Agent will execute skills etc from your local machine)', value: 'sandbox' },
              { name: '🚀 Production (Agent will execute latest version of skills etc)', value: 'production' },
            ],
          },
        ]);
        selectedEnvironment = environment;
        break;

      case 'error':
        console.log(`❌ ${envResolution.message}`);
        throw new Error(`${envResolution.message}`);
    }

    let chatEnv: ChatEnvironment = {
      type: selectedEnvironment,
      agentId,
      apiKey,
      threadId,
      autoClear,
    };

    // Step 4: Setup sandbox if selected
    if (selectedEnvironment === 'sandbox') {
      writeInfo('💡 Sandbox mode: uses your locally compiled code — no lua push needed.');
      await setupChatEnvironment(chatEnv, config);
    }

    // Print thread info if a thread is active
    if (chatEnv.threadId) {
      console.log(`ℹ️  Thread: ${chatEnv.threadId}\n`);
    }

    trackEvent('cli_chat_started', {
      environment: selectedEnvironment,
      non_interactive_message: !!message,
      env_resolution_type: envResolution.type,
      has_preprocessor_overrides: (chatEnv.preprocessorOverrides?.length || 0) > 0,
      has_postprocessor_overrides: (chatEnv.postprocessorOverrides?.length || 0) > 0,
      has_thread_id: !!chatEnv.threadId,
      auto_clear: chatEnv.autoClear || false,
    });

    // Per-session window for the agent_error probe. Initialized after
    // auth so we don't surface logs that landed before the session began.
    // Mutated in place across turns by `runChatProbe`.
    const probeWindow: ProbeWindow = { value: new Date().toISOString() };

    // Step 5: Handle message/batch if provided (non-interactive mode)
    if (batch) {
      await sendBatchMessages(chatEnv, batch, delay);
      if (chatEnv.autoClear) {
        await clearOnExit(chatEnv);
      }
    } else if (message) {
      await sendSingleMessage(chatEnv, message, probeWindow);
      if (chatEnv.autoClear) {
        await clearOnExit(chatEnv);
      }
    } else {
      // Step 6: Start interactive chat
      await startChatLoop(chatEnv, probeWindow);
    }
  }, 'chat');
}

/**
 * Sets up the chat environment by compiling and pushing skills, preprocessors, and postprocessors
 * This is used for both interactive and non-interactive modes
 */
async function setupChatEnvironment(chatEnv: ChatEnvironment, config: any): Promise<void> {
  writeProgress('🔄 Setting up sandbox environment...');

  // Compile the skill
  writeProgress('🔄 Compiling skill...');
  await compileCommand();

  // Load manifest
  const manifest = loadManifest();
  const skills = getPrimitivesByKind<ManifestSkill>(manifest, PrimitiveKind.SKILL);

  // Push skills to sandbox (if any exist)
  let sandboxIds: Record<string, string> = {};
  if (skills.length > 0) {
    writeProgress('🔄 Pushing skills to sandbox...');
    sandboxIds = await pushSkillsToSandbox(chatEnv.apiKey, chatEnv.agentId, manifest, config, true);

    if (Object.keys(sandboxIds).length > 0) {
      writeSuccess(`✅ Pushed ${Object.keys(sandboxIds).length} skills to sandbox`);
    } else {
      console.warn('⚠️  No skills were pushed to sandbox. Continuing with processors only.');
    }
  } else {
    writeProgress('ℹ️  No skills found - continuing with processors/webhooks only...');
  }

  // Push preprocessors and postprocessors to sandbox
  const preprocessors = getPrimitivesByKind<ManifestPreProcessor>(manifest, PrimitiveKind.PREPROCESSOR);
  const postprocessors = getPrimitivesByKind<ManifestPostProcessor>(manifest, PrimitiveKind.POSTPROCESSOR);

  if (preprocessors.length > 0 || postprocessors.length > 0) {
    writeProgress('🔄 Pushing processors to sandbox...');
    const processorCounts = await pushProcessorsToSandbox(chatEnv.apiKey, chatEnv.agentId, manifest, config, true);

    if (processorCounts.preprocessors > 0 || processorCounts.postprocessors > 0) {
      writeSuccess(
        `✅ Pushed ${processorCounts.preprocessors} preprocessor(s) and ${processorCounts.postprocessors} postprocessor(s) to sandbox`
      );
    }
  }

  // Store config for skill overrides
  chatEnv.yamlConfig = config;

  // Get processor overrides for sandbox
  chatEnv.preprocessorOverrides = await getAllSandboxPreProcessorIds(config);
  chatEnv.postprocessorOverrides = await getAllSandboxPostProcessorIds(config);

  // Check for persona in config
  chatEnv.persona = getAgentPersona() ?? undefined;
}

/**
 * Starts the interactive chat loop
 */
async function startChatLoop(chatEnv: ChatEnvironment, probeWindow: ProbeWindow): Promise<void> {
  console.log('\n' + '='.repeat(60));
  console.log('🌙 Lua Chat Interface');
  console.log(`Environment: ${chatEnv.type === 'sandbox' ? '🔧 Sandbox' : '🚀 Production'}`);
  if (chatEnv.threadId) {
    console.log(`Thread: ${chatEnv.threadId}`);
  }
  console.log('Press Ctrl+C to exit');
  console.log('Tip: attach files with @/path/to/file.ext (e.g. @screenshot.png)');
  console.log('='.repeat(60) + '\n');

  // Welcome message
  console.log('🌙 Assistant: Hi there! How can I help you today?\n');

  // Create readline interface
  const rl = readline.createInterface({
    input: process.stdin,
    output: process.stdout,
    prompt: '💬 You: ',
  });

  let cleared = false;

  // Handle Ctrl+C gracefully
  rl.on('SIGINT', async () => {
    if (chatEnv.autoClear && !cleared) {
      cleared = true;
      await clearOnExit(chatEnv);
    }
    console.log('\n\n👋 Goodbye!');
    rl.close();
    process.exit(0);
  });

  // Show prompt
  rl.prompt();

  // Handle user input
  rl.on('line', async (input: string) => {
    const trimmed = input.trim();

    if (!trimmed) {
      rl.prompt();
      return;
    }

    let messages: ChatMessage[];
    try {
      messages = await parseMessageWithAttachments(trimmed);
    } catch (error) {
      // Attachment parsing is a local file error — no server call was made, so
      // no agent_error logs exist. Give a local-only hint.
      console.error(`\n❌ ${error instanceof Error ? error.message : 'Failed to process attachments'}\n`);
      writeInfo('💡 Check the file path — attachments use @/path/to/file.ext syntax.');
      rl.prompt();
      return;
    }

    // Start typing indicator
    const typingInterval = startTypingIndicator();
    let firstChunk = true;
    let postprocessingOccurred = false;

    try {
      // Create callbacks for streaming
      const callbacks: StreamCallbacks = {
        onChunk: (chunk: string) => {
          if (firstChunk) {
            // Stop typing indicator and show assistant label
            stopTypingIndicator(typingInterval);
            process.stdout.write('🌙 Assistant: ');
            firstChunk = false;
          }
          // Write the chunk immediately
          process.stdout.write(chunk);
        },
        onPostprocessComplete: (originalResponse: string, modifiedResponse: string) => {
          postprocessingOccurred = true;
          // Show post-processing notice with the modified response
          console.log('\n\n📝 [Post-processed response]:');
          console.log(modifiedResponse);
        },
        onPreprocessorBlocked: (message: string) => {
          stopTypingIndicator(typingInterval);
          firstChunk = false;
          console.log(`🚫 Message blocked: ${message}\n`);
          writeNextStep({
            command: buildLogsCommand({ primitiveType: 'preprocessor', limit: 10 }),
            rationale: 'to see which preprocessor blocked the message',
            when: 'error',
          });
        },
      };

      if (chatEnv.type === 'sandbox') {
        // Send to sandbox with skill overrides (streaming)
        await sendSandboxMessageStream(chatEnv, messages, callbacks);
      } else {
        // Send to production (streaming)
        await sendProductionMessageStream(chatEnv, messages, callbacks);
      }

      // If no chunks arrived, stop the typing indicator
      if (firstChunk) {
        stopTypingIndicator(typingInterval);
      }

      // Add newline after response (only if post-processing didn't already add one)
      if (!postprocessingOccurred) {
        console.log('\n');
      } else {
        console.log('');
      }

      // B9: postprocessors reply without streaming any text-delta chunks; guard
      // the empty-response warning so it doesn't fire when a postprocessor already
      // printed its modified response (parity with sendSingleMessage).
      if (firstChunk && !postprocessingOccurred) {
        console.warn('\n⚠️  The agent returned an empty response.');
        writeHintBlock({
          headline: 'Possible causes:',
          lines: [
            { label: 'Check errors:', command: 'lua logs --type agent_error --limit 5' },
            { label: 'Check runtime:', command: 'lua logs --type runtime --limit 5' },
          ],
          when: 'partial',
        });
      }

      await runChatProbe(chatEnv, probeWindow);
    } catch (error) {
      // Make sure typing indicator is stopped on error
      if (firstChunk) {
        stopTypingIndicator(typingInterval);
      }
      console.error(`\n❌ Error: ${error instanceof Error ? error.message : 'Unknown error'}\n`);
      writeHintBlock({
        headline: 'Something went wrong. Debug options:',
        lines: [
          { label: 'Check agent errors:', command: 'lua logs --type agent_error --limit 5' },
          { label: 'Isolate the tool:', command: 'lua test skill --name <toolName>  (runs locally, no LLM)' },
        ],
        when: 'error',
      });
      await runChatProbe(chatEnv, probeWindow);
    }

    rl.prompt();
  });

  rl.on('close', async () => {
    if (chatEnv.autoClear && !cleared) {
      cleared = true;
      await clearOnExit(chatEnv);
    }
    console.log('\n👋 Goodbye!');
    process.exit(0);
  });
}

/**
 * Helper to clear conversation history when auto-clear is enabled
 */
async function clearOnExit(chatEnv: ChatEnvironment): Promise<void> {
  try {
    const chatApi = new ChatApi(BASE_URLS.CHAT, chatEnv.apiKey);
    const response = await chatApi.clearHistory(chatEnv.agentId, undefined, chatEnv.threadId);
    if (response.success) {
      const scope = chatEnv.threadId ? ` for thread "${chatEnv.threadId}"` : '';
      console.log(`\n🧹 Chat history cleared${scope}.`);
    }
  } catch {
    // Best-effort — user is exiting, don't block on failure
  }
}

/**
 * Starts a typing indicator animation with dots
 * @returns The interval ID to stop the animation later
 */
function startTypingIndicator(): NodeJS.Timeout {
  const frames = ['   ', '.  ', '.. ', '...'];
  let frameIndex = 0;

  // Initial frame
  process.stdout.write(`\r🌙 Assistant: ${frames[frameIndex]}`);

  const interval = setInterval(() => {
    frameIndex = (frameIndex + 1) % frames.length;
    process.stdout.write(`\r🌙 Assistant: ${frames[frameIndex]}`);
  }, 500);

  return interval;
}

/**
 * Stops the typing indicator animation and clears the line
 * @param interval The interval ID from startTypingIndicator
 */
function stopTypingIndicator(interval: NodeJS.Timeout): void {
  clearInterval(interval);
  // Clear the typing indicator line
  process.stdout.write('\r\x1b[K');
}

/**
 * Callback options for streaming messages
 */
interface StreamCallbacks {
  onChunk: (text: string) => void;
  onPostprocessComplete?: (originalResponse: string, modifiedResponse: string) => void;
  onPreprocessorBlocked?: (message: string) => void;
  onBatchAbort?: (message: string) => void;
  onBatchHandled?: (message: string) => void;
}

/**
 * Sends a message to the sandbox environment with skill overrides (streaming)
 */
async function sendSandboxMessageStream(
  chatEnv: ChatEnvironment,
  messages: ChatMessage[],
  callbacks: StreamCallbacks
): Promise<void> {
  if (!chatEnv.yamlConfig) {
    throw new Error('Sandbox environment not properly initialized.');
  }

  // Get all sandbox skill IDs for skill override (may be empty if no skills exist)
  const allSkillOverrides = await getAllSandboxSkillIds(chatEnv.yamlConfig);

  const chatRequest: ChatRequest = {
    messages,
    navigate: true,
    skillOverride: allSkillOverrides,
    preprocessorOverride: chatEnv.preprocessorOverrides || [],
    postprocessorOverride: chatEnv.postprocessorOverrides || [],
  };

  // Add persona override if available
  if (chatEnv.persona) {
    chatRequest.personaOverride = chatEnv.persona;
  }

  // Add thread ID if scoped
  if (chatEnv.threadId) {
    chatRequest.threadId = chatEnv.threadId;
  }

  const chatApi = new ChatApi(BASE_URLS.CHAT, chatEnv.apiKey);
  await chatApi.sendMessageStream(
    chatEnv.agentId,
    chatRequest,
    callbacks.onChunk,
    callbacks.onPostprocessComplete,
    callbacks.onPreprocessorBlocked,
    callbacks.onBatchAbort,
    callbacks.onBatchHandled
  );
}

/**
 * Sends a message to the production environment (streaming)
 */
async function sendProductionMessageStream(
  chatEnv: ChatEnvironment,
  messages: ChatMessage[],
  callbacks: StreamCallbacks
): Promise<void> {
  const chatRequest: ChatRequest = {
    messages,
    navigate: true,
    skillOverride: [],
    preprocessorOverride: [],
    postprocessorOverride: [],
  };

  // Add thread ID if scoped
  if (chatEnv.threadId) {
    chatRequest.threadId = chatEnv.threadId;
  }

  const chatApi = new ChatApi(BASE_URLS.CHAT, chatEnv.apiKey);
  await chatApi.sendMessageStream(
    chatEnv.agentId,
    chatRequest,
    callbacks.onChunk,
    callbacks.onPostprocessComplete,
    callbacks.onPreprocessorBlocked,
    callbacks.onBatchAbort,
    callbacks.onBatchHandled
  );
}

/**
 * Sends a single message in non-interactive mode and displays the response
 * This function completes and exits after receiving the response
 */
async function sendSingleMessage(chatEnv: ChatEnvironment, message: string, probeWindow: ProbeWindow): Promise<void> {
  // Visual separator between build logs and response
  console.log('\n' + '─'.repeat(50));
  console.log('🌙 Response:');
  if (chatEnv.threadId) {
    console.log(`Thread: ${chatEnv.threadId}`);
  }
  console.log('─'.repeat(50) + '\n');

  let postprocessingOccurred = false;
  let preprocessorBlocked = false;

  try {
    const callbacks: StreamCallbacks = {
      onChunk: (chunk: string) => {
        process.stdout.write(chunk);
      },
      onPostprocessComplete: (originalResponse: string, modifiedResponse: string) => {
        postprocessingOccurred = true;
        // Show post-processing notice with the modified response
        console.log('\n\n📝 [Post-processed response]:');
        console.log(modifiedResponse);
      },
      onPreprocessorBlocked: (message: string) => {
        preprocessorBlocked = true;
        console.log(`🚫 Message blocked: ${message}`);
        writeNextStep({
          command: buildLogsCommand({ primitiveType: 'preprocessor', limit: 10 }),
          rationale: 'to see which preprocessor blocked the message',
          when: 'error',
        });
      },
    };

    const messages = await parseMessageWithAttachments(message);
    let receivedChunk = false;
    const streamCallbacks: StreamCallbacks = {
      ...callbacks,
      onChunk: (chunk: string) => {
        receivedChunk = true;
        callbacks.onChunk(chunk);
      },
    };
    if (chatEnv.type === 'sandbox') {
      await sendSandboxMessageStream(chatEnv, messages, streamCallbacks);
    } else {
      await sendProductionMessageStream(chatEnv, messages, streamCallbacks);
    }

    // Add newline at end (only if post-processing didn't already add one)
    if (!postprocessingOccurred) {
      console.log('\n');
    } else {
      console.log('');
    }

    if (!receivedChunk && !postprocessingOccurred && !preprocessorBlocked) {
      console.warn('\n⚠️  The agent returned an empty response.');
      writeHintBlock({
        headline: 'Possible causes:',
        lines: [
          { label: 'Check errors:', command: 'lua logs --type agent_error --limit 5' },
          { label: 'Check runtime:', command: 'lua logs --type runtime --limit 5' },
        ],
        when: 'partial',
      });
    }

    await runChatProbe(chatEnv, probeWindow);
  } catch (error) {
    console.error(`\n❌ Error: ${error instanceof Error ? error.message : 'Unknown error'}`);
    writeHintBlock({
      headline: 'Something went wrong. Debug options:',
      lines: [
        { label: 'Check agent errors:', command: 'lua logs --type agent_error --limit 5' },
        { label: 'Isolate the tool:', command: 'lua test skill --name <toolName>  (runs locally, no LLM)' },
      ],
      when: 'error',
    });
    await runChatProbe(chatEnv, probeWindow);
    throw new Error('Operation failed');
  }
}

type BatchResult = {
  message: string;
  status: 'responded' | 'batched' | 'batch-handled' | 'error';
  response?: string;
  error?: string;
};

/**
 * Sends multiple messages concurrently with staggered delays to test batching behavior.
 * Each message is sent `delay` ms after the previous one starts.
 */
async function sendBatchMessages(chatEnv: ChatEnvironment, messages: string[], delay: number): Promise<void> {
  console.log('\n' + '─'.repeat(60));
  console.log(`🧪 Batch test: ${messages.length} messages, ${delay}ms stagger`);
  console.log('─'.repeat(60) + '\n');

  const results: BatchResult[] = messages.map((m) => ({ message: m, status: 'error' as const }));

  const sendOne = async (msg: string, index: number): Promise<void> => {
    // Stagger start time
    await new Promise((r) => setTimeout(r, index * delay));

    console.log(`📤 [t+${index * delay}ms] Sending msg ${index + 1}: "${msg}"`);

    let responseText = '';
    let resolved = false;

    try {
      const callbacks: StreamCallbacks = {
        onChunk: (chunk: string) => {
          responseText += chunk;
        },
        onBatchAbort: (message: string) => {
          resolved = true;
          results[index] = { message: msg, status: 'batched', response: message || '(absorbed into batch)' };
          console.log(`⏸️  [msg ${index + 1}] Batched/absorbed: ${message || '(no message)'}`);
        },
        onBatchHandled: (message: string) => {
          resolved = true;
          results[index] = { message: msg, status: 'batch-handled', response: message || '(batch handled)' };
          console.log(`✅ [msg ${index + 1}] Batch handled: ${message || '(no message)'}`);
        },
      };

      const payload: ChatMessage[] = [{ type: 'text', text: msg }];
      if (chatEnv.type === 'sandbox') {
        await sendSandboxMessageStream(chatEnv, payload, callbacks);
      } else {
        await sendProductionMessageStream(chatEnv, payload, callbacks);
      }

      if (!resolved) {
        results[index] = { message: msg, status: 'responded', response: responseText };
        console.log(
          `💬 [msg ${index + 1}] Responded: ${responseText.slice(0, 80)}${responseText.length > 80 ? '…' : ''}`
        );
      }
    } catch (err) {
      results[index] = { message: msg, status: 'error', error: err instanceof Error ? err.message : String(err) };
      console.error(`❌ [msg ${index + 1}] Error: ${results[index].error}`);
    }
  };

  // Fire all sends concurrently (each waits its own stagger delay internally)
  await Promise.all(messages.map((msg, i) => sendOne(msg, i)));

  // Summary table
  console.log('\n' + '─'.repeat(60));
  console.log('📊 Batch summary:');
  console.log('─'.repeat(60));
  for (const r of results) {
    const icon =
      r.status === 'responded' ? '💬' : r.status === 'batched' ? '⏸️ ' : r.status === 'batch-handled' ? '✅' : '❌';
    console.log(`${icon} "${r.message.slice(0, 40)}" → ${r.status}`);
  }
  const responded = results.filter((r) => r.status === 'responded').length;
  const batched = results.filter((r) => r.status === 'batched' || r.status === 'batch-handled').length;
  console.log(
    `\n   ${responded} responded · ${batched} batched/handled · ${results.filter((r) => r.status === 'error').length} errors`
  );
  console.log('─'.repeat(60) + '\n');
}
