interface VoiceTestOptions {
  pattern?: string;
  voice?: string;
  watch?: boolean;
  runner?: 'jest' | 'vitest' | 'auto';
  bail?: boolean;
}

export async function voiceTestCommand(options: VoiceTestOptions = {}): Promise<void> {
  return withErrorHandling(async () => {
    const cwd = process.cwd();
    const runner = options.runner === 'auto' || !options.runner ? detectRunner(cwd) : options.runner;
    if (!runner) {
      console.error('❌ No supported test runner found.');
      console.log('   Install jest or vitest in this project, then re-run.');
      console.log('   Example: pnpm add -D jest ts-jest @types/jest');
      throw new Error('no test runner');
    }

    // --voice filters by filename — `<name>.voice.test.ts` only. The
    // helper escapes regex metachars in the user-supplied voice name so
    // names with dots/dashes match exactly: "support-line" matches
    // `support-line.voice.test.ts` but not `support-lineN.voice.test.ts`.
    const pattern =
      options.pattern ?? (options.voice ? `${escapeRegex(options.voice)}\\.voice\\.test\\.` : '\\.voice\\.test\\.');
    const files = findVoiceTestFiles(cwd);
    if (files.length === 0) {
      writeProgress(`No \`*.voice.test.ts\` files found under ${cwd}`);
      console.log('   Create one next to your LuaVoice (e.g. `support.voice.test.ts`).');
      trackEvent('cli_voice_test_completed', { runner, files_found: 0, non_interactive: true });
      return;
    }

    writeProgress(`Found ${files.length} voice test file${files.length === 1 ? '' : 's'} (runner: ${runner})`);
    for (const f of files) {
      console.log(`   • ${relative(cwd, f)}`);
    }

    const args = buildRunnerArgs(runner, { pattern, watch: !!options.watch, bail: !!options.bail });
    const exit = await spawnRunner(runner, args, cwd);

    trackEvent('cli_voice_test_completed', {
      runner,
      files_found: files.length,
      exit_code: exit,
      watch: !!options.watch,
      non_interactive: !!options.pattern,
    });

    if (exit === 0) {
      writeSuccess('Voice tests passed');
    } else {
      throw new Error(`Voice tests failed (exit ${exit})`);
    }
  }, 'voice test');
}

function escapeRegex(s: string): string {
  return s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

function detectRunner(cwd: string): 'jest' | 'vitest' | null {
  const pkgPath = join(cwd, 'package.json');
  if (!existsSync(pkgPath)) return null;
  try {
    const pkg = JSON.parse(require('fs').readFileSync(pkgPath, 'utf8'));
    const deps = { ...(pkg.dependencies ?? {}), ...(pkg.devDependencies ?? {}) };
    if (deps.vitest) return 'vitest';
    if (deps.jest) return 'jest';
  } catch {
    return null;
  }
  return null;
}

function buildRunnerArgs(
  runner: 'jest' | 'vitest',
  opts: { pattern: string; watch: boolean; bail: boolean }
): string[] {
  if (runner === 'jest') {
    const args = ['--testPathPattern', opts.pattern];
    if (opts.watch) args.push('--watch');
    if (opts.bail) args.push('--bail');
    return args;
  }
  // vitest
  const args = ['run', '--testNamePattern', '.*', opts.pattern];
  if (opts.watch) {
    args[0] = 'watch';
  }
  if (opts.bail) args.push('--bail', '1');
  return args;
}

async function spawnRunner(runner: 'jest' | 'vitest', args: string[], cwd: string): Promise<number> {
  return new Promise((resolveExit) => {
    const proc = spawn('npx', [runner, ...args], {
      cwd,
      stdio: 'inherit',
      env: { ...process.env, LUA_VOICE_TEST: '1' },
    });
    proc.on('exit', (code) => resolveExit(code ?? 1));
    proc.on('error', () => resolveExit(1));
  });
}

// ─── lua voice list ────────────────────────────────────────────────────────

interface VoiceListOptions {
  json?: boolean;
}

export async function voiceListCommand(options: VoiceListOptions = {}): Promise<void> {
  return withErrorHandling(async () => {
    const manifest = loadManifest();
    const voices = getPrimitivesByKind<ManifestVoice>(manifest, PrimitiveKind.VOICE);
    const agents = getPrimitivesByKind<ManifestAgent>(manifest, PrimitiveKind.AGENT);

    // Map voice name → { owningAgent, isPrimary } where primary is the
    // agent's first voiceRef (used as default for outbound dispatch).
    const ownerByVoice = new Map<string, { agent: string; isPrimary: boolean }>();
    for (const a of agents) {
      const refs = a.voiceRefs ?? [];
      refs.forEach((ref, idx) => {
        if (!ownerByVoice.has(ref.name)) {
          ownerByVoice.set(ref.name, { agent: a.name, isPrimary: idx === 0 });
        }
      });
    }

    if (options.json) {
      console.log(
        JSON.stringify(
          voices.map((v) => ({
            name: v.name,
            llm: modelLabel(v.llm),
            stt: v.stt ? modelLabel(v.stt) : null,
            tts: v.tts ? modelLabel(v.tts) : null,
            greeting: v.greeting ?? null,
            hasOnEnter: !!v.hasOnEnter,
            hasOnUserTurnCompleted: !!v.hasOnUserTurnCompleted,
            hasOnExit: !!v.hasOnExit,
            hasTools: !!v.hasTools,
            agent: ownerByVoice.get(v.name)?.agent ?? null,
            primary: ownerByVoice.get(v.name)?.isPrimary ?? false,
          })),
          null,
          2
        )
      );
      trackEvent('cli_voice_list_completed', { count: voices.length, json: true });
      return;
    }

    if (voices.length === 0) {
      writeProgress('No LuaVoice primitives found. Run `lua compile` first.');
      trackEvent('cli_voice_list_completed', { count: 0, json: false });
      return;
    }

    console.log(`\n🎙️  ${voices.length} voice${voices.length === 1 ? '' : 's'}:\n`);
    for (const v of voices) {
      const owner = ownerByVoice.get(v.name);
      const hooks =
        [v.hasOnEnter && 'onEnter', v.hasOnUserTurnCompleted && 'onUserTurnCompleted', v.hasOnExit && 'onExit']
          .filter(Boolean)
          .join(', ') || '—';
      const star = owner?.isPrimary ? '★ ' : '  ';
      const primaryTag = owner?.isPrimary ? ' (primary)' : '';
      const ownerTag = owner ? `  (${owner.agent}${primaryTag})` : '';
      console.log(`${star}${v.name}${ownerTag}`);
      console.log(`    llm: ${modelLabel(v.llm)}`);
      if (v.stt) console.log(`    stt: ${modelLabel(v.stt)}`);
      if (v.tts) console.log(`    tts: ${modelLabel(v.tts)}`);
      console.log(`    hooks: ${hooks}${v.hasTools ? ', voice-tools' : ''}`);
      if (v.greeting) console.log(`    greeting: "${v.greeting}"`);
      console.log('');
    }

    trackEvent('cli_voice_list_completed', { count: voices.length, json: false });
  }, 'voice list');
}

function modelLabel(m: ManifestVoice['llm']): string {
  if (!m) return '';
  if ('kind' in m) {
    if (m.kind === 'inference') return `inference:${m.model}${m.voice ? `/${m.voice}` : ''}`;
    if (m.kind === 'plugin') return `${m.provider}.${m.class}`;
    if (m.kind === 'realtime') return `realtime:${m.provider}`;
  }
  return JSON.stringify(m);
}

// ─── lua voice (default action: try the voice live) ────────────────────────

interface VoiceTryOptions {
  voice?: string;
  agent?: string;
  terminal?: boolean;
  phone?: string;
  callerId?: string;
  context?: string;
  threadId?: string;
}

type VoiceMode = 'browser' | 'phone' | 'terminal';

export async function voiceCommand(options: VoiceTryOptions = {}): Promise<void> {
  return withErrorHandling(async () => {
    // Resolve agent → voice → mode interactively when not flag-pinned.
    // Pre-mode resolution lets the picker offer modes that make sense
    // for the chosen voice (e.g. could later disable phone if the agent
    // has no provisioned outbound numbers).
    const { agentName, voiceName } = await resolveAgentAndVoice(options);
    const mode = await pickMode(options);

    if (mode === 'phone' && !/^\+\d{6,15}$/.test(options.phone!)) {
      throw new Error(`Invalid phone number "${options.phone}" — must be E.164 (e.g. +15551234567)`);
    }
    if (mode === 'phone' && options.callerId && !/^\+\d{6,15}$/.test(options.callerId)) {
      throw new Error(`Invalid caller-id "${options.callerId}" — must be E.164 (e.g. +15551234567)`);
    }

    const context = parseContext(options.context);
    const { apiKey, agentId } = await initializeCommand({ showProgress: false });
    const api = new VoiceApi(BASE_URLS.API, apiKey, agentId);

    // Browser and terminal modes both want a web join URL with a
    // returnable token; only the consumer differs (browser opens the
    // URL, terminal connects via @livekit/rtc-node + sox).
    const dispatchInput: VoiceDispatchInput =
      mode === 'phone'
        ? {
            to: { kind: 'phone', number: options.phone!, ...(options.callerId && { callerId: options.callerId }) },
            voice: voiceName,
            context,
            threadId: options.threadId,
          }
        : { to: { kind: 'web', returnToken: true }, voice: voiceName, context, threadId: options.threadId };

    const targetLabel = mode === 'phone' ? options.phone! : mode === 'terminal' ? 'terminal (mic/speaker)' : 'browser';
    const voiceLabel = voiceName ?? 'default voice';
    const agentLabel = agentName ? ` on ${agentName}` : '';
    writeProgress(`Dispatching ${voiceLabel}${agentLabel} → ${targetLabel}…`);
    const result = await api.dispatch(dispatchInput);
    if (!result.success || !result.data) {
      throw new Error(result.error?.message ?? 'Dispatch failed');
    }

    await handleDispatchResult(mode, result.data, options.phone);

    trackEvent('cli_voice_completed', {
      mode,
      voice_explicit: !!options.voice,
      agent_explicit: !!options.agent,
      with_context: !!context,
    });
  }, 'voice');
}

interface ResolvedAgentVoice {
  /** Owning agent's manifest name (for display only); undefined if no manifest. */
  agentName?: string;
  /** Voice name forwarded to the dispatch endpoint as `voice:`. Undefined → server picks. */
  voiceName?: string;
}

async function resolveAgentAndVoice(options: VoiceTryOptions): Promise<ResolvedAgentVoice> {
  // No manifest → no idea what's deployed. Forward whatever the dev
  // passed (or nothing) and let lua-api default to the agent's first voice.
  let manifest;
  try {
    manifest = loadManifest();
  } catch {
    return { voiceName: options.voice };
  }

  const agents = getPrimitivesByKind<ManifestAgent>(manifest, PrimitiveKind.AGENT);
  const agentsWithVoices = agents.filter((a) => (a.voiceRefs ?? []).length > 0);

  if (agentsWithVoices.length === 0) {
    if (options.voice) return { voiceName: options.voice };
    throw new Error(
      'No voice agents found in the project. Add `voice: <yourLuaVoice>` to a LuaAgent and run `lua compile`.'
    );
  }

  // Resolve the owning agent.
  let agent: ManifestAgent;
  if (options.agent) {
    const match = agentsWithVoices.find((a) => a.name === options.agent);
    if (!match) {
      throw new Error(
        `Agent "${options.agent}" has no voices in this project. Available: ${agentsWithVoices.map((a) => a.name).join(', ')}`
      );
    }
    agent = match;
  } else if (agentsWithVoices.length === 1) {
    agent = agentsWithVoices[0];
  } else {
    const answer = await safePrompt<{ agent: ManifestAgent }>([
      {
        type: 'list',
        name: 'agent',
        message: 'Which agent?',
        choices: agentsWithVoices.map((a) => ({
          name: `${a.name}  (${a.voiceRefs?.length ?? 0} voice${(a.voiceRefs?.length ?? 0) === 1 ? '' : 's'})`,
          value: a,
        })),
      },
    ]);
    if (!answer?.agent) throw new Error('Agent selection cancelled.');
    agent = answer.agent;
  }

  const refs = agent.voiceRefs ?? [];
  // Hydrate each ref with manifest metadata for the rich picker.
  const voicesByName = new Map(
    getPrimitivesByKind<ManifestVoice>(manifest, PrimitiveKind.VOICE).map((v) => [v.name, v])
  );
  const hydrated = refs.map((r, idx) => ({
    name: r.name,
    isPrimary: idx === 0,
    meta: voicesByName.get(r.name),
  }));

  if (options.voice) {
    const match = hydrated.find((v) => v.name === options.voice);
    if (!match) {
      throw new Error(
        `Voice "${options.voice}" not bound to agent "${agent.name}". Available: ${hydrated.map((v) => v.name).join(', ')}`
      );
    }
    return { agentName: agent.name, voiceName: match.name };
  }

  if (hydrated.length === 1) {
    return { agentName: agent.name, voiceName: hydrated[0].name };
  }

  const answer = await safePrompt<{ choice: string }>([
    {
      type: 'list',
      name: 'choice',
      message: 'Which voice?',
      pageSize: 8,
      choices: hydrated.map((v) => {
        const star = v.isPrimary ? '★ ' : '  ';
        const llm = v.meta ? modelLabel(v.meta.llm) : '';
        const greet = v.meta?.greeting
          ? ` · "${v.meta.greeting.slice(0, 60)}${v.meta.greeting.length > 60 ? '…' : ''}"`
          : '';
        const trailer = llm ? `   ${llm}${greet}` : '';
        return {
          name: `${star}${v.name}${v.isPrimary ? ' (primary)' : ''}\n${trailer}`,
          short: v.name,
          value: v.name,
        };
      }),
    },
  ]);
  if (!answer?.choice) throw new Error('Voice selection cancelled.');
  return { agentName: agent.name, voiceName: answer.choice };
}

async function pickMode(options: VoiceTryOptions): Promise<VoiceMode> {
  // Flag-pinned: skip the prompt. Phone is implicit (--phone <e164>).
  const explicitFlags = [options.phone && 'phone', options.terminal && 'terminal'].filter(Boolean);
  if (explicitFlags.length > 1) {
    throw new Error(`Pick one of --phone / --terminal (got: ${explicitFlags.join(', ')})`);
  }
  if (options.phone) return 'phone';
  if (options.terminal) return 'terminal';

  // No flag → ask. TTY only; CI-mode safePrompt throws so the caller
  // pins via flags.
  const answer = await safePrompt<{ mode: VoiceMode }>([
    {
      type: 'list',
      name: 'mode',
      message: 'How would you like to test?',
      default: 'browser',
      choices: [
        { name: 'Browser  — open in your browser, mic/speaker via WebRTC', value: 'browser' },
        { name: 'Terminal — mic/speaker through this terminal (requires sox)', value: 'terminal' },
      ],
    },
  ]);
  return answer?.mode ?? 'browser';
}

function parseContext(raw: string | undefined): Record<string, unknown> | undefined {
  if (!raw) return undefined;
  try {
    const parsed = JSON.parse(raw);
    if (typeof parsed !== 'object' || parsed === null || Array.isArray(parsed)) {
      throw new Error('not a JSON object');
    }
    return parsed as Record<string, unknown>;
  } catch (err) {
    throw new Error(`--context must be a JSON object: ${(err as Error).message}`);
  }
}

async function handleDispatchResult(mode: VoiceMode, data: VoiceDispatchOutput, phone?: string): Promise<void> {
  if (mode === 'browser') {
    if (!data.joinUrl) {
      throw new Error(
        'Server did not return a joinUrl. Update lua-api so the dispatch endpoint includes returnToken on web targets.'
      );
    }
    // Spin up an ephemeral local HTTP server with a Lua-branded try
    // page; opens http://localhost:<port> so the URL bar isn't a
    // third-party domain. Server stays up until the page POSTs /end
    // or the safety timeout fires.
    console.log(`   session: ${data.sessionId}`);
    await runBrowserMode(data.joinUrl);
    return;
  }
  if (mode === 'terminal') {
    if (!data.joinUrl) {
      throw new Error('Server did not return a joinUrl for terminal mode.');
    }
    writeSuccess(`Voice room ready (session ${data.sessionId})`);
    await runTerminalMode(data.joinUrl);
    return;
  }
  if (mode === 'phone') {
    writeSuccess(`Calling ${phone} (session ${data.sessionId}${data.callId ? `, sid ${data.callId}` : ''})`);
    console.log('   Pick up to talk to the agent.');
    return;
  }
}

function findVoiceTestFiles(root: string): string[] {
  const out: string[] = [];
  const skipDirs = new Set(['node_modules', 'dist', 'dist-v2', '.git', '.lua', 'coverage']);
  const walk = (dir: string): void => {
    let entries: string[];
    try {
      entries = readdirSync(dir);
    } catch {
      return;
    }
    for (const entry of entries) {
      const full = join(dir, entry);
      let s;
      try {
        s = statSync(full);
      } catch {
        continue;
      }
      if (s.isDirectory()) {
        if (skipDirs.has(entry)) continue;
        walk(full);
      } else if (s.isFile() && /\.voice\.test\.(t|j)sx?$/.test(entry)) {
        out.push(resolve(full));
      }
    }
  };
  walk(root);
  return out;
}
