/**
 * PreProcessor compilation plugin.
 *
 * Extends ProcessorPluginBase for shared validation and runtime checks.
 * Only adds: isAsync extraction + isAsync in manifest entry.
 */

import { ObjectLiteralExpression, ClassDeclaration, SourceFile, Node } from 'ts-morph';
import {
  type PreProcessorMetadata,
  type PreProcessorMetadataFields,
  type CompiledPrimitive,
  type ManifestPrimitive,
  type ManifestPreProcessor,
} from '../types.js';
import { ProcessorPluginBase } from './processor-base.js';
import { readStringMember, deriveNameFromClassName } from './base.js';
import {
  extractBooleanProperty,
  extractNumberProperty,
  evaluateNodeAsBoolean,
  evaluateNodeAsNumber,
} from '../utils/ast-helpers.js';
import { findClassMember } from '../utils/class-hierarchy.js';

export class PreProcessorPlugin extends ProcessorPluginBase<PreProcessorMetadataFields> {
  readonly kind = 'preprocessor';
  readonly displayName = 'PreProcessor';
  readonly defineFunction = 'definePreProcessor';
  readonly legacyClassNames = ['PreProcessor', 'LuaPreprocessor'];

  /**
   * Class-definition extraction. Reads `name`/`description`/`async`/
   * `priority`/`execute` off the inheritance chain (most-derived wins).
   */
  protected extractFromClassDefinition(
    classDecl: ClassDeclaration,
    sourceFile: SourceFile
  ): PreProcessorMetadata | null {
    const className = classDecl.getName();
    if (!className) return null;

    const isDefaultExport = classDecl.isDefaultExport();
    const exportName = isDefaultExport ? 'default' : className;

    const name = readStringMember(classDecl, 'name') ?? deriveNameFromClassName(className);
    const description = readStringMember(classDecl, 'description') ?? '';

    const asyncHit = findClassMember(classDecl, 'async', 'property');
    const isAsync =
      asyncHit && Node.isPropertyDeclaration(asyncHit.node)
        ? (evaluateNodeAsBoolean(asyncHit.node.getInitializer()) ?? false)
        : false;

    const priorityHit = findClassMember(classDecl, 'priority', 'property');
    const priority =
      priorityHit && Node.isPropertyDeclaration(priorityHit.node)
        ? evaluateNodeAsNumber(priorityHit.node.getInitializer())
        : undefined;

    return {
      kind: this.kind,
      name,
      description,
      sourcePath: sourceFile.getFilePath(),
      exportName,
      isDefaultExport,
      line: classDecl.getStartLineNumber(),
      column: 1,
      metadata: {
        pattern: 'class-definition',
        hasExecute: findClassMember(classDecl, 'execute', 'either') !== undefined,
        isAsync,
        priority,
      },
    };
  }

  protected extractFromConfig(
    config: ObjectLiteralExpression,
    exportName: string,
    sourcePath: string,
    position: { line: number; column: number },
    pattern: 'function' | 'class'
  ): PreProcessorMetadata | null {
    const common = this.extractCommonFields(config, exportName, sourcePath, position);
    if (!common) return null;

    const isAsync = extractBooleanProperty(config, 'async') ?? false;
    const priority = extractNumberProperty(config, 'priority');

    return {
      kind: this.kind,
      ...common,
      metadata: { pattern, hasExecute: config.getProperty('execute') !== undefined, isAsync, priority },
    };
  }

  toManifestEntry(compiled: CompiledPrimitive, _allPrimitives?: CompiledPrimitive[]): ManifestPrimitive {
    const meta = compiled.metadata as PreProcessorMetadataFields;
    return {
      ...this.baseManifestFields(compiled),
      isAsync: meta?.isAsync ?? false,
      ...(meta?.priority !== undefined ? { priority: meta.priority } : {}),
    } as ManifestPreProcessor;
  }
}
