/**
 * Models Command
 * Lists available LLM models and optionally sets the model for the current project.
 */

import chalk from 'chalk';
import { withErrorHandling, writeSuccess, writeInfo, writeError, writeProgress } from '../utils/cli.js';
import { getToken } from '../services/auth.js';
import { readYamlConfig } from '../utils/files.js';
import { fetchApprovedModels, validateModelCode, updateAgentModel, clearAgentModel } from '../utils/init-agent.js';
import { promptModelSelection } from '../utils/init-prompts.js';
import { setAgentModel, removeAgentModel } from '../compiler/index.js';
import { getAgentModel } from '../utils/artifact-loader.js';
import { fetchServerModel } from '../utils/sync-fetch.js';
import { trackEvent } from '../services/analytics.js';
import { ApprovedModel } from '../interfaces/agent.js';
import { validateOrSuggest } from '../utils/aliases.js';

interface ModelsCommandOptions {
  model?: string;
  json?: boolean;
}

/**
 * Resolves the currently configured model code for the project.
 * Prefers the server (authoritative, always fresh) and falls back
 * to the compiled artifact only when the server call fails entirely.
 *
 * fetchServerModel returns:
 *   - model string → agent has this model
 *   - ''           → agent exists but no model configured
 *   - null         → API call failed
 */
async function resolveCurrentModel(apiKey: string, agentId: string): Promise<string | null> {
  const serverModel = await fetchServerModel(apiKey, agentId);
  if (serverModel) return serverModel;
  if (serverModel === '') return null;
  // serverModel === null → API failure, fall back to local compiled artifact
  const localModel = getAgentModel();
  return localModel || null;
}

/**
 * Displays all available models grouped by provider,
 * highlighting the currently configured model.
 */
async function listModels(
  models: ApprovedModel[],
  currentModel: string | null,
  opts: { json?: boolean }
): Promise<void> {
  if (opts.json) {
    console.log(JSON.stringify({ currentModel, models }, null, 2));
    return;
  }

  const providers = [...new Set(models.map((m) => m.provider))].sort();

  console.log('');
  console.log('============================================================');
  console.log('  🧠 Available LLM Models');
  console.log('============================================================');
  console.log('');

  if (currentModel) {
    console.log(`  Current model: ${chalk.bold.cyan(currentModel)}`);
  } else {
    console.log(`  Current model: ${chalk.gray('(platform default)')}`);
  }
  console.log('');

  for (const provider of providers) {
    const providerModels = models.filter((m) => m.provider === provider);
    console.log(chalk.yellow(`  ── ${provider} ──`));
    for (const m of providerModels) {
      const isCurrent = m.code === currentModel;
      const code = isCurrent ? chalk.bold.cyan(m.code.padEnd(30)) : m.code.padEnd(30);
      const desc = chalk.gray(m.description);
      const marker = isCurrent ? chalk.bold.green(' ← current') : '';
      console.log(`    ${code}  ${desc}${marker}`);
    }
    console.log('');
  }

  console.log('============================================================');
  if (!currentModel) {
    console.log(`  💡 Run ${chalk.cyan('lua models set')} to choose a model for your agent`);
  } else {
    console.log(`  💡 Run ${chalk.cyan('lua models set')} to change your model`);
  }
  console.log('============================================================');
  console.log('');
}

/**
 * Main models command handler.
 *
 * Actions:
 *  - list (default): display all approved models, mark the current one
 *  - set: interactively select (or non-interactively via --model) and apply it
 */
export async function modelsCommand(action: string | undefined, opts: ModelsCommandOptions): Promise<void> {
  return withErrorHandling(async () => {
    const resolvedAction = action ? validateOrSuggest('models.action', action) : 'list';
    const apiKey = getToken();
    const config = readYamlConfig();
    const agentId = config?.agent?.agentId;

    // -------------------------------------------------------------------------
    // LIST
    // -------------------------------------------------------------------------
    if (resolvedAction === 'list') {
      writeProgress('🔄 Fetching available models...');
      const models = await fetchApprovedModels(apiKey);
      writeProgress('');

      if (models.length === 0) {
        writeError('❌ Could not fetch models from the server. Check your connection and API key.');
        return;
      }

      const currentModel = agentId ? await resolveCurrentModel(apiKey, agentId) : null;

      await listModels(models, currentModel, opts);

      trackEvent('cli_models_listed', {
        models_count: models.length,
        has_current_model: !!currentModel,
        json_output: opts.json ?? false,
      });
      return;
    }

    // -------------------------------------------------------------------------
    // SET
    // -------------------------------------------------------------------------
    if (resolvedAction === 'set') {
      if (!agentId) {
        writeError('❌ No agent configured. Run `lua init` first to set up a project.');
        process.exit(1);
      }

      writeProgress('🔄 Fetching available models...');
      const models = await fetchApprovedModels(apiKey);
      writeProgress('');

      if (models.length === 0) {
        writeError('❌ Could not fetch models from the server. Check your connection and API key.');
        process.exit(1);
      }

      let selectedModel: string | undefined;

      if (opts.model) {
        selectedModel = validateModelCode(models, opts.model);
      } else {
        const currentModel = await resolveCurrentModel(apiKey, agentId);
        if (!opts.json) {
          writeInfo(
            `  Current model: ${currentModel ? chalk.bold.cyan(currentModel) : chalk.gray('(platform default)')}\n`
          );
        }
        selectedModel = await promptModelSelection(models);
      }

      if (!selectedModel) {
        writeInfo('ℹ️  No model selected. Keeping existing configuration.');
        return;
      }

      // Write to local source code
      const localWriteOk = setAgentModel(selectedModel);
      if (localWriteOk) {
        writeSuccess(`✅ Model written to source: ${chalk.bold(selectedModel)}`);
      } else {
        writeInfo(
          `⚠️  Could not write model to source file (no LuaAgent constructor found). You can set it manually in your code.`
        );
      }

      // Push to server
      try {
        await updateAgentModel(apiKey, agentId, selectedModel);
        writeSuccess(`✅ Model pushed to server: ${chalk.bold(selectedModel)}`);
      } catch (err: any) {
        writeInfo(`⚠️  Could not push model to server: ${err.message}. Run \`lua push agent\` to retry.`);
      }

      trackEvent('cli_models_set', {
        model: selectedModel,
        local_write_ok: localWriteOk,
        non_interactive: !!opts.model,
      });
      return;
    }

    // -------------------------------------------------------------------------
    // UNSET
    // -------------------------------------------------------------------------
    if (resolvedAction === 'unset') {
      if (!agentId) {
        writeError('❌ No agent configured. Run `lua init` first to set up a project.');
        process.exit(1);
      }

      const currentModel = await resolveCurrentModel(apiKey, agentId);

      if (!currentModel) {
        writeInfo('ℹ️  No model is currently set — the platform default is already in use.');
        return;
      }

      writeInfo(`  Current model: ${chalk.bold.cyan(currentModel)}`);
      writeInfo(`  This will remove the model and let the Lua platform use its default.\n`);

      // Remove from local source code
      const localRemoveOk = removeAgentModel();
      if (localRemoveOk) {
        writeSuccess('✅ Model removed from source code');
      } else {
        writeInfo(
          '⚠️  Could not remove model from source file. Remove the `model` property manually from your LuaAgent config.'
        );
      }

      // Clear on server
      try {
        await clearAgentModel(apiKey, agentId);
        writeSuccess('✅ Model cleared on server — platform default will be used');
      } catch (err: any) {
        writeInfo(`⚠️  Could not clear model on server: ${err.message}. Run \`lua push agent\` to retry.`);
      }

      trackEvent('cli_models_unset', {
        previous_model: currentModel,
        local_remove_ok: localRemoveOk,
      });
      return;
    }

    writeError(`❌ Unknown action '${resolvedAction}'. Use 'list', 'set', or 'unset'.`);
    process.exit(1);
  }, 'models');
}
