import { HttpClient } from './http.client.js';
import { ApiResponse } from '../interfaces/common.js';

/**
 * Available-number search filters (mirrors lua-api's
 * `developer/phone-numbers/available` query parameters).
 */
export interface SearchAvailableFilters {
  country: string;
  type?: 'mobile-lvn' | 'landline' | 'landline-toll-free';
  features?: string;
  contains?: string;
  searchPattern?: number;
  limit?: number;
  transport?: 'livekit' | 'vonage' | 'byo-sip';
}

export interface AvailableNumber {
  msisdn: string;
  country: string;
  type?: string;
  features?: string[];
  monthlyCost?: string;
  currency?: string;
  transport?: string;
}

export interface PurchaseNumberRequest {
  msisdn: string;
  country?: string;
  transport?: 'livekit' | 'vonage' | 'byo-sip';
}

export interface PhoneNumberRecord {
  msisdn: string;
  country?: string;
  status: 'active' | 'suspended' | 'released';
  transport?: 'livekit' | 'vonage' | 'byo-sip';
  agentId?: string;
  voiceId?: string;
  purchasedAt?: string;
}

export interface BindPhoneRequest {
  msisdn: string;
  voiceId?: string;
  transport?: 'livekit' | 'vonage' | 'byo-sip';
  threadScoping?: boolean;
}

/**
 * Phone channel + provisioning client. Wraps both:
 *   - `/developer/orgs/:orgId/phone-numbers/*` (search / purchase / list / release)
 *   - `/admin/agents/:agentId/channels` (bind a phone number to an agent —
 *     accepts `type: 'phone'` after BAC-223 Part B).
 *
 * Two URL families because lua-api keeps developer-owned org operations
 * (purchasing) under `/developer` while channel binding stays under
 * `/admin/agents`. The CLI hides the split — devs use `lua channels
 * phone` for both.
 */
export default class ChannelsApi extends HttpClient {
  private apiKey: string;

  constructor(baseUrl: string, apiKey: string) {
    super(baseUrl);
    this.apiKey = apiKey;
  }

  async searchAvailable(
    filters: SearchAvailableFilters
  ): Promise<ApiResponse<{ numbers: AvailableNumber[]; count: number }>> {
    const params = new URLSearchParams();
    params.set('country', filters.country.toUpperCase());
    if (filters.type) params.set('type', filters.type);
    if (filters.features) params.set('features', filters.features);
    if (filters.contains) params.set('contains', filters.contains);
    if (filters.searchPattern !== undefined) params.set('search_pattern', String(filters.searchPattern));
    if (filters.limit !== undefined) params.set('limit', String(filters.limit));
    if (filters.transport) params.set('transport', filters.transport);
    return this.httpGet<{ numbers: AvailableNumber[]; count: number }>(
      `/developer/phone-numbers/available?${params.toString()}`,
      { Authorization: `Bearer ${this.apiKey}` }
    );
  }

  async purchase(orgId: string, body: PurchaseNumberRequest): Promise<ApiResponse<PhoneNumberRecord>> {
    return this.httpPost<PhoneNumberRecord>(`/developer/orgs/${orgId}/phone-numbers`, body, {
      Authorization: `Bearer ${this.apiKey}`,
    });
  }

  async list(
    orgId: string,
    filters: { status?: string; country?: string; limit?: number; offset?: number; transport?: string } = {}
  ): Promise<ApiResponse<{ numbers: PhoneNumberRecord[]; count: number }>> {
    const params = new URLSearchParams();
    if (filters.status) params.set('status', filters.status);
    if (filters.country) params.set('country', filters.country);
    if (filters.limit !== undefined) params.set('limit', String(filters.limit));
    if (filters.offset !== undefined) params.set('offset', String(filters.offset));
    if (filters.transport) params.set('transport', filters.transport);
    const qs = params.toString();
    const url = qs ? `/developer/orgs/${orgId}/phone-numbers?${qs}` : `/developer/orgs/${orgId}/phone-numbers`;
    return this.httpGet<{ numbers: PhoneNumberRecord[]; count: number }>(url, {
      Authorization: `Bearer ${this.apiKey}`,
    });
  }

  async release(orgId: string, msisdn: string): Promise<ApiResponse<{ success: boolean }>> {
    return this.httpDelete<{ success: boolean }>(
      `/developer/orgs/${orgId}/phone-numbers/${encodeURIComponent(msisdn)}`,
      {
        Authorization: `Bearer ${this.apiKey}`,
      }
    );
  }

  /**
   * Bind a phone number to the configured agent. Calls
   * `POST /admin/agents/:agentId/channels` with `type: 'phone'`. The
   * msisdn must already be in the org's phone_numbers (purchased
   * earlier via `purchase`). Server creates or upserts the
   * ChannelConfig record so inbound dispatch resolves the agent.
   */
  async bind(agentId: string, body: BindPhoneRequest): Promise<ApiResponse<{ id?: string }>> {
    return this.httpPost<{ id?: string }>(
      `/admin/agents/${agentId}/channels`,
      { type: 'phone', phone: body },
      { Authorization: `Bearer ${this.apiKey}` }
    );
  }

  /**
   * Unbind by deleting the channel record. Hits the phone-specific
   * route registered before the generic `:channelId` matcher so the
   * lua-auth-driven path isn't reached. Does NOT release the phone
   * number — that's a separate `release(...)` call on this client.
   */
  async unbind(agentId: string, msisdn: string): Promise<ApiResponse<{ message: string; deleted: boolean }>> {
    return this.httpDelete<{ message: string; deleted: boolean }>(
      `/admin/agents/${agentId}/channels/phone/${encodeURIComponent(msisdn)}`,
      { Authorization: `Bearer ${this.apiKey}` }
    );
  }
}
