/**
 * Update Command
 * Updates the globally installed lua-cli to the latest version from npm.
 */

import { execSync } from 'child_process';
import { withErrorHandling, writeProgress, writeSuccess, writeInfo } from '../utils/cli.js';
import { fetchLatestVersion, saveCachedVersionCheck } from '../utils/version-check.js';
import { compareVersions, parseVersion } from '../utils/semver.js';
import { trackEvent } from '../services/analytics.js';
import { getCliVersion } from '../utils/package-root.js';

/**
 * Detect if lua-cli is a local dev install (npm link) rather than a global npm install.
 */
function isDevInstall(): boolean {
  try {
    const result = execSync('npm ls -g lua-cli --depth=0 --json 2>/dev/null', { encoding: 'utf8' });
    const parsed = JSON.parse(result);
    const resolved = parsed?.dependencies?.['lua-cli']?.resolved;
    // Registry installs have resolved URLs (https://...), linked installs have file: paths
    return typeof resolved === 'string' && resolved.startsWith('file:');
  } catch {
    return false;
  }
}

/**
 * Update command - checks npm for the latest version and installs it globally.
 *
 * 1. Force-fetches latest version from npm (bypasses cache)
 * 2. If already up to date, informs user and exits
 * 3. Detects dev installs (npm link) and warns instead of updating
 * 4. Runs npm install -g lua-cli@latest with live output
 */
export async function updateCommand(): Promise<void> {
  return withErrorHandling(async () => {
    const currentVersion = getCliVersion();
    writeProgress(`Current version: ${currentVersion}. Checking for updates...`);

    // Force a fresh check (bypass cache)
    const latestVersion = await fetchLatestVersion(currentVersion);
    if (!latestVersion) {
      throw new Error('Could not reach the npm registry. Check your internet connection and try again.');
    }

    // Update cache with fresh result
    saveCachedVersionCheck(latestVersion);

    // Check if already up to date
    if (compareVersions(currentVersion, latestVersion) >= 0) {
      writeSuccess(`✅ lua-cli is already up to date (v${currentVersion})`);
      trackEvent('cli_update_executed', {
        current_version: currentVersion,
        latest_version: latestVersion,
        outcome: 'up_to_date',
      });
      return;
    }

    // Detect npm link (dev install)
    if (isDevInstall()) {
      writeInfo(`⚠️  lua-cli appears to be installed via \`npm link\` (local development).`);
      writeInfo(`   To update, pull the latest changes in your local repo and run \`npm run build\`.`);
      writeInfo(`   Latest version on npm: ${latestVersion}`);
      trackEvent('cli_update_executed', {
        current_version: currentVersion,
        latest_version: latestVersion,
        outcome: 'dev_install',
      });
      return;
    }

    // Perform the update
    console.log(`\n  Updating lua-cli: ${currentVersion} → ${latestVersion}\n`);

    // Use the matching dist-tag for install (e.g. "alpha" for alpha users, "latest" for stable)
    const { preRelease } = parseVersion(currentVersion);
    const installTag = preRelease ? preRelease.split('.')[0].replace(/[0-9]/g, '') || 'latest' : 'latest';
    const installCmd = `npm install -g lua-cli@${installTag}`;

    try {
      execSync(installCmd, { stdio: 'inherit' });
      writeSuccess(`\n✅ Successfully updated lua-cli to v${latestVersion}`);
    } catch {
      throw new Error(
        `Failed to update lua-cli. You may need to run with sudo:\n` +
          `  sudo ${installCmd}\n\n` +
          `Or fix npm permissions: https://docs.npmjs.com/resolving-eacces-permissions-errors-when-installing-packages-globally`
      );
    }
    trackEvent('cli_update_executed', {
      current_version: currentVersion,
      latest_version: latestVersion,
      outcome: 'updated',
    });
  }, 'update');
}
