/**
 * MCP Server Handler
 *
 * Handles CLI operations for MCP server primitives.
 *
 * MCP Servers:
 * - Don't have versions (non-versioned primitive)
 * - Use create-or-update-by-name (upsert) rather than push-then-publish
 * - Bidirectional sync: servers can originate on the server via integrations
 *   (UnifiedTo OAuth, demo website) — lua sync pulls those into YAML
 * - Use `active` field on the entity
 */

import { PrimitiveKind, CompilationManifest } from '../compiler/types.js';
import type { ManifestMCPServer } from '../compiler/types.js';
import { loadManifest, getPrimitivesByKind, loadArtifact, compressForPush } from '../utils/artifact-loader.js';
import { BASE_URLS } from '../config/constants.js';
import DeveloperApi from '../api/developer.api.service.js';
import { BaseNonVersionedHandler, UpsertResult } from './base.handler.js';
import type { YamlPrimitiveConfig, ServerSyncData, SyncResult } from './types.js';
import type { YamlConfig, YamlConfigMCPServer } from '../types/yaml.types.js';

/**
 * Shape bundled from the manifest and pushed to the server.
 * `url` is intentionally optional: when a server uses a resolver lambda the
 * field is omitted entirely so the upsert does not clear a previously stored URL.
 */
export interface BundledMCPServer {
  name: string;
  transport: string;
  url?: string;
  urlResolver?: string;
  headersResolver?: string;
}

/**
 * MCP Server primitive handler
 */
export class MCPServerHandler extends BaseNonVersionedHandler<YamlConfigMCPServer, BundledMCPServer> {
  readonly kind = PrimitiveKind.MCP_SERVER;
  readonly displayName = 'MCP server';
  readonly displayNamePlural = 'MCP servers';
  readonly deleteCommand = 'lua mcp delete';
  readonly yamlConfig: YamlPrimitiveConfig = {
    yamlKey: 'mcpServers',
    idField: 'mcpServerId',
  };

  protected getApi(apiKey: string, agentId: string): DeveloperApi {
    return new DeveloperApi(BASE_URLS.API, apiKey, agentId);
  }

  protected async fetchFromServer(api: DeveloperApi): Promise<any[] | null> {
    const response = await api.getMCPServers();
    if (!response.success || !response.data) {
      return null;
    }
    return response.data;
  }

  cleanItem(server: YamlConfigMCPServer): YamlConfigMCPServer {
    return {
      name: server.name || '',
      mcpServerId: server.mcpServerId || '',
    };
  }

  /**
   * Load bundled MCP server data from the compilation manifest.
   *
   * If the server has url/headers resolver functions (flagged in the manifest),
   * loads the bundled artifact and includes it as urlResolver/headersResolver —
   * same pattern as agent model resolver: artifact loaded at push time, not
   * compile time.
   *
   * `url` is only included when it is a static string. When url is a resolver
   * function the field is omitted entirely (not set to undefined) so the
   * existing DB value is not accidentally cleared during upsert.
   */
  loadBundledItems(projectPath: string = process.cwd()): BundledMCPServer[] {
    try {
      const manifest = loadManifest(projectPath);
      const mcpServers = getPrimitivesByKind<ManifestMCPServer>(manifest, PrimitiveKind.MCP_SERVER);

      return mcpServers.map((server) => {
        let compressedArtifact: string | undefined;
        if ((server.hasUrlResolver || server.hasHeadersResolver) && server.path) {
          const artifactCode = loadArtifact(server, projectPath);
          compressedArtifact = compressForPush(artifactCode);
        }

        const result: BundledMCPServer = {
          name: server.name,
          transport: (server.config?.transport as string) || 'streamable-http',
        };

        if (server.config?.url !== undefined) {
          result.url = server.config.url as string;
        }

        if (server.hasUrlResolver) result.urlResolver = compressedArtifact;
        if (server.hasHeadersResolver) result.headersResolver = compressedArtifact;

        return result;
      });
    } catch (error) {
      console.warn(`⚠️  Failed to load bundled MCP servers: ${error instanceof Error ? error.message : String(error)}`);
      return [];
    }
  }

  /**
   * Upsert an MCP server (create or update by name).
   *
   * Persists the server-assigned id into lua.skill.yaml as a side effect on
   * success, so the id is tracked locally from the very first push. This
   * keeps single-server push and pushAll consistent without making callers
   * remember the follow-up.
   */
  async upsertOnServer(apiKey: string, agentId: string, serverData: BundledMCPServer): Promise<UpsertResult> {
    const api = this.getApi(apiKey, agentId);
    const response = await api.upsertMCPServer(serverData as any);
    const result: UpsertResult = {
      success: response.success,
      id: response.data?.id,
      active: response.data?.active,
      error: response.error?.message,
    };

    if (result.success && result.id) {
      this.persistItemId(serverData.name, result.id);
    }

    return result;
  }

  /**
   * Activate an MCP server on the server.
   */
  async activate(apiKey: string, agentId: string, serverId: string): Promise<{ success: boolean; error?: string }> {
    const api = this.getApi(apiKey, agentId);
    const response = await api.activateMCPServer(serverId);
    return { success: response.success, error: response.error?.message };
  }

  /**
   * pushAll autoDeploy hook: activate the server if it isn't already active.
   */
  protected async postUpsert(
    _item: BundledMCPServer,
    upsert: UpsertResult,
    apiKey: string,
    agentId: string
  ): Promise<boolean> {
    if (!upsert.id || upsert.active) return false;
    const activated = await this.activate(apiKey, agentId, upsert.id);
    return activated.success;
  }

  /**
   * MCP servers use `active` field directly on the entity.
   * Excludes integration-sourced servers (e.g. UnifiedTo) from orphan detection.
   */
  isActive(serverItem: any): boolean {
    if (serverItem.source && serverItem.source !== 'manual') {
      return false;
    }
    return serverItem.active !== false;
  }

  /**
   * Bidirectional sync — pull missing server MCP servers into YAML.
   *
   * Base non-versioned sync only prints orphan warnings. MCP servers can be
   * created on the server via integrations (UnifiedTo OAuth, demo website, etc.)
   * so bidirectional sync needs to pull those into the local YAML. For each
   * active, syncable server entry we:
   *   1. Link its id into an existing YAML entry by name if the id is missing.
   *   2. Append a new YAML entry if no local match by id or name exists.
   */
  async applySyncToYaml(
    serverData: ServerSyncData,
    config: YamlConfig | null,
    _manifest?: CompilationManifest
  ): Promise<SyncResult> {
    const messages: string[] = [];
    let yamlUpdated = false;

    if (!serverData.serverItems) {
      if (serverData.fetchError) {
        console.error(`❌ Error syncing server ${this.displayNamePlural}: ${serverData.fetchError}`);
      } else {
        console.warn(`⚠️  Could not retrieve server ${this.displayNamePlural}. Skipping sync.`);
      }
      return { messages, yamlUpdated, orphanedCount: 0 };
    }

    try {
      const idField = this.yamlConfig.idField;
      const getId = (item: YamlConfigMCPServer): string =>
        ((item as unknown as Record<string, unknown>)[idField] as string) || '';

      const items: YamlConfigMCPServer[] = this.getFromYaml(config).map((item) => ({ ...item }));
      const syncableServers = serverData.serverItems.filter((item) => this.isActive(item));

      const idToIndex = new Map<string, number>();
      const nameToIndex = new Map<string, number>();
      items.forEach((item, idx) => {
        const id = getId(item);
        if (id) idToIndex.set(id, idx);
        nameToIndex.set(item.name, idx);
      });

      for (const serverItem of syncableServers) {
        const id = serverItem.id as string;
        const name = serverItem.name as string;

        if (idToIndex.has(id)) continue;

        const nameIdx = nameToIndex.get(name);
        if (nameIdx !== undefined) {
          if (!getId(items[nameIdx])) {
            (items[nameIdx] as unknown as Record<string, unknown>)[idField] = id;
            idToIndex.set(id, nameIdx);
            const msg = `🔗 Linked "${name}" ${this.displayName} to server (ID: ${id})`;
            messages.push(msg);
            console.log(msg);
            yamlUpdated = true;
          }
          continue;
        }

        const newItem: YamlConfigMCPServer = { name, mcpServerId: id };
        items.push(newItem);
        idToIndex.set(id, items.length - 1);
        nameToIndex.set(name, items.length - 1);
        const msg = `📥 Added "${name}" ${this.displayName} from server`;
        messages.push(msg);
        console.log(msg);
        yamlUpdated = true;
      }

      if (yamlUpdated) {
        this.updateYaml(items, config);
        console.log(`✅ YAML ${this.displayNamePlural} synced with server`);
      } else {
        console.log(`✅ Server ${this.displayNamePlural} and YAML are fully in sync`);
      }
    } catch (error) {
      console.error(`❌ Error syncing server ${this.displayNamePlural}:`, error);
    }

    return { messages, yamlUpdated, orphanedCount: 0 };
  }
}

// Export singleton instance
export const mcpServerHandler = new MCPServerHandler();
