/**
 * Helpers for the post-push / post-deploy / post-chat `lua logs` nudges.
 *
 * Two builders are exported:
 *
 * - {@link buildLogsCommandHint} — narrow, primitive-type → command. Kept for
 *   back-compat with the original LUA-184 call sites.
 * - {@link buildLogsCommand} — rich, accepts `name`, `limit`, `json`, and
 *   `logSourceOverride`. New code (LUA-180) should use this.
 *
 * Maps the push/deploy primitive type onto a valid `lua logs --type` value,
 * or returns null when there's no matching log filter (e.g. "agent",
 * "persona", "backup", "device") — in which case the caller drops the
 * `--type` flag.
 */

const LOG_TYPE_BY_PRIMITIVE: Record<string, string> = {
  skill: 'skill',
  webhook: 'webhook',
  job: 'job',
  preprocessor: 'preprocessor',
  postprocessor: 'postprocessor',
  mcp: 'mcp',
};

/**
 * Log types that accept a `--name <entity>` filter. The CLI rejects
 * `--name` for non-entity sources (`mcp`, `mastra`/`runtime`, `rag`,
 * `user_message`, `agent_response`, `agent_error`), so we only emit the
 * `--name` flag for entity-bearing types.
 */
const ENTITY_LOG_TYPES = new Set<string>(['skill', 'webhook', 'job', 'preprocessor', 'postprocessor']);

/**
 * Map a push/deploy primitive type to a `lua logs --type` value, or null if
 * none applies (caller should drop the --type flag in that case).
 */
export function logTypeForPrimitive(primitiveType: string | undefined | null): string | null {
  if (!primitiveType) return null;
  return LOG_TYPE_BY_PRIMITIVE[primitiveType] ?? null;
}

/**
 * Build the `lua logs ...` command shown in the tip line.
 * Falls back to `lua logs --limit 10` when no specific log type applies.
 */
export function buildLogsCommandHint(primitiveType: string | undefined | null): string {
  const logType = logTypeForPrimitive(primitiveType);
  return logType ? `lua logs --type ${logType} --limit 10` : `lua logs --limit 10`;
}

/**
 * Options for {@link buildLogsCommand}.
 */
export interface BuildLogsCommandOptions {
  /**
   * Push/deploy primitive type (e.g. "skill", "webhook"). Mapped through
   * {@link logTypeForPrimitive} to a `--type` value. Ignored when
   * `logSourceOverride` is set.
   */
  primitiveType?: string | null;
  /**
   * Entity name. Only emitted when the resolved log type accepts `--name`
   * (skill / webhook / job / preprocessor / postprocessor). Silently dropped
   * for non-entity sources (e.g. `agent_error`, `mcp`).
   */
  name?: string | null;
  /**
   * Number passed to `--limit`. Defaults to `10`.
   */
  limit?: number;
  /**
   * If true, append `--json` (used in scripted/non-interactive recipes).
   */
  json?: boolean;
  /**
   * Direct `--type` value, used by the chat probe and any caller that
   * already knows the canonical log source name (e.g. `"agent_error"`,
   * `"runtime"`). Wins over `primitiveType`.
   */
  logSourceOverride?: string | null;
}

/**
 * Rich `lua logs ...` command builder. Use this in post-action hints
 * (success, error, partial-failure) when you have entity-name context.
 *
 * Examples:
 *
 *   buildLogsCommand({ primitiveType: 'skill' })
 *     → "lua logs --type skill --limit 10"
 *
 *   buildLogsCommand({ primitiveType: 'skill', name: 'search_tool', limit: 20 })
 *     → "lua logs --type skill --name search_tool --limit 20"
 *
 *   buildLogsCommand({ logSourceOverride: 'agent_error', limit: 5 })
 *     → "lua logs --type agent_error --limit 5"
 *
 *   buildLogsCommand({ primitiveType: 'mcp', name: 'foo' })
 *     → "lua logs --type mcp --limit 10"   // name dropped — mcp is non-entity
 *
 *   buildLogsCommand({ json: true })
 *     → "lua logs --limit 10 --json"
 */
export function buildLogsCommand(opts: BuildLogsCommandOptions = {}): string {
  const limit = opts.limit ?? 10;
  const logType = opts.logSourceOverride ?? logTypeForPrimitive(opts.primitiveType);

  const parts: string[] = ['lua logs'];
  if (logType) parts.push(`--type ${logType}`);
  if (opts.name && logType && ENTITY_LOG_TYPES.has(logType)) {
    parts.push(`--name ${opts.name}`);
  }
  parts.push(`--limit ${limit}`);
  if (opts.json) parts.push('--json');
  return parts.join(' ');
}
