/**
 * Device Trigger Handler
 *
 * Handles CLI operations for device trigger primitives.
 *
 * Device triggers:
 * - Use 'active' field on entity
 * - Use 'isActive' field on versions
 */

import { PrimitiveKind, ManifestPrimitive, ManifestDeviceTrigger } from '../compiler/types.js';
import { BASE_URLS } from '../config/constants.js';
import DeviceTriggerApi from '../api/device-trigger.api.service.js';
import type { PushDeviceTriggerVersionDTO } from '../interfaces/device-triggers.js';
import { BaseVersionedHandler } from './base.handler.js';
import type { YamlPrimitiveConfig, ServerSyncData } from './types.js';
import type { YamlConfigDeviceTrigger } from '../types/yaml.types.js';

/**
 * Device trigger primitive handler
 */
export class DeviceTriggerHandler extends BaseVersionedHandler<YamlConfigDeviceTrigger, PushDeviceTriggerVersionDTO> {
  readonly kind = PrimitiveKind.DEVICE_TRIGGER;
  readonly displayName = 'device trigger';
  readonly displayNamePlural = 'device triggers';
  readonly deleteCommand = 'lua device-triggers delete';
  readonly yamlConfig: YamlPrimitiveConfig = {
    yamlKey: 'deviceTriggers',
    idField: 'deviceTriggerId',
  };

  /**
   * Override fetchServerState to treat auth/network errors as non-fatal.
   *
   * The Device Gateway is feature-gated on the server
   * (DEVICE_GATEWAY_ENABLED). When the feature is off or the endpoint
   * doesn't exist for a given agent, the server returns 401 or 404.
   * Device triggers are an optional primitive. A missing or inaccessible
   * endpoint should not block compiling other primitives.
   */
  async fetchServerState(apiKey: string, agentId: string): Promise<ServerSyncData> {
    try {
      const api = this.getApi(apiKey, agentId);
      const serverItems = await this.fetchFromServer(api);
      return { serverItems };
    } catch {
      // Silently degrade — device trigger sync is optional.
      return { serverItems: null };
    }
  }

  protected getApi(apiKey: string, agentId: string): DeviceTriggerApi {
    return new DeviceTriggerApi(BASE_URLS.API, apiKey, agentId);
  }

  protected async fetchFromServer(api: DeviceTriggerApi): Promise<any[] | null> {
    const response = await api.getDeviceTriggers();
    if (!response.success || !response.data?.deviceTriggers) {
      return null;
    }
    return response.data.deviceTriggers;
  }

  protected async createOnServer(api: DeviceTriggerApi, primitive: ManifestPrimitive): Promise<string | null> {
    const response = await api.createDeviceTrigger({
      name: primitive.name,
      description: primitive.description || `A Lua device trigger for ${primitive.name}`,
    });
    if (!response.success || !response.data?.id) return null;
    return response.data.id;
  }

  /**
   * Device triggers use 'active' field directly on the entity.
   */
  isActive(serverItem: any): boolean {
    return serverItem.active !== false;
  }

  async pushToServer(apiKey: string, agentId: string, entityId: string, pushData: PushDeviceTriggerVersionDTO) {
    const api = this.getApi(apiKey, agentId);
    const response = await api.pushDeviceTrigger(entityId, { ...pushData, deviceTriggerId: entityId });
    return { success: response.success, error: response.error?.message };
  }

  async publishVersion(apiKey: string, agentId: string, entityId: string, version: string) {
    const api = this.getApi(apiKey, agentId);
    const response = await api.publishDeviceTriggerVersion(entityId, version);
    return { success: response.success, error: response.error?.message };
  }

  /**
   * Override to include device trigger payload schema in push data.
   */
  protected buildPushData(
    primitive: ManifestPrimitive,
    compressedCode: string | undefined,
    codeS3Hash?: string
  ): Record<string, unknown> {
    const deviceTrigger = primitive as ManifestDeviceTrigger;
    return {
      name: deviceTrigger.name,
      description: deviceTrigger.description,
      ...(codeS3Hash ? { codeS3Hash } : { code: compressedCode }),
      payloadSchema: deviceTrigger.schemas?.payload || undefined,
    };
  }
}

// Export singleton instance
export const deviceTriggerHandler = new DeviceTriggerHandler();
