/**
 * Webhooks Command
 * Manages agent webhooks for sandbox and production environments
 */

import { withErrorHandling, writeProgress, writeSuccess, writeInfo, writeHintBlock } from '../utils/cli.js';
import { BASE_URLS } from '../config/constants.js';
import { safePrompt } from '../utils/prompt-handler.js';
import { initializeCommand } from '../utils/command-utils.js';
import WebhookApi from '../api/webhook.api.service.js';
import { webhookHandler } from '../primitives/webhook.handler.js';
import { YamlConfig } from '../types/yaml.types.js';
import { trackEvent } from '../services/analytics.js';
import { validateOrSuggest } from '../utils/aliases.js';

interface WebhooksCommandContext {
  environment: 'sandbox' | 'production';
  agentId: string;
  apiKey: string;
}

interface WebhooksOptions {
  webhookName?: string;
  webhookVersion?: string;
  event?: string;
}

type WebhookAction =
  | 'view'
  | 'versions'
  | 'deploy'
  | 'activate'
  | 'deactivate'
  | 'delete'
  | 'list-events'
  | 'subscribe'
  | 'unsubscribe';

const AVAILABLE_EVENT_TYPES = ['message.sent', 'message.delivered', 'message.read', 'message.failed', 'message.played'];

// ─────────────────────────────────────────────────────────────────────────────
// Main Command Entry
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Main webhooks command - manages agent webhooks.
 *
 * Supports both interactive and non-interactive modes:
 * - Interactive: prompts for action and webhook selection
 * - Non-interactive: use action argument with -i and -v flags
 */
export async function webhooksCommand(action?: string, cmdObj?: any): Promise<void> {
  return withErrorHandling(async () => {
    const options: WebhooksOptions = {
      webhookName: cmdObj?.webhookName || null,
      webhookVersion: cmdObj?.webhookVersion || null,
      event: cmdObj?.event || null,
    };

    // Initialize command (validates config + auth)
    const { config, agentId, apiKey } = await initializeCommand();

    const context: WebhooksCommandContext = {
      environment: 'production',
      agentId,
      apiKey,
    };

    // Determine mode
    if (action) {
      await executeNonInteractive(context, config, action, options);
    } else {
      await manageWebhooksInteractive(context, config);
    }
    trackEvent('cli_webhooks_action', {
      action: action || 'interactive',
      webhook_name: options.webhookName || null,
      non_interactive: !!action,
    });
  }, 'webhooks');
}

// ─────────────────────────────────────────────────────────────────────────────
// Shared Core Functions
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Displays all webhooks with their current status.
 */
async function displayWebhooksCore(context: WebhooksCommandContext, webhooks: any[]): Promise<void> {
  console.log('\n' + '='.repeat(60));
  console.log('⚙️  Production Webhooks');
  console.log('='.repeat(60) + '\n');

  const webhookApi = new WebhookApi(BASE_URLS.API, context.apiKey, context.agentId);

  for (const webhook of webhooks) {
    try {
      const response = await webhookApi.getWebhookVersions(webhook.webhookId);

      if (response.success && response.data) {
        const versions = response.data.versions || [];
        const activeVersionId = response.data.activeVersionId;
        const activeVersion = versions.find((v: any) => v.webhookId === activeVersionId);

        console.log(`🪝 ${webhook.name}`);
        console.log(`   Webhook ID: ${webhook.webhookId}`);

        if (activeVersion) {
          console.log(`   Deployed Version: ${activeVersion.version} ⭐`);
          console.log(`   Deployed: ${new Date(activeVersion.createdAt).toLocaleString()}`);
        } else {
          console.log(`   Deployed Version: Not deployed`);
        }

        console.log(`   Total Versions: ${versions.length}`);
        console.log();
      } else {
        displayWebhookError(webhook, 'Unable to fetch version info');
      }
    } catch {
      displayWebhookError(webhook, 'Error loading versions');
    }
  }

  console.log('='.repeat(60));
}

function displayWebhookError(webhook: any, status: string): void {
  console.log(`🪝 ${webhook.name}`);
  console.log(`   Webhook ID: ${webhook.webhookId}`);
  console.log(`   Status: ${status}`);
  console.log();
}

/**
 * Fetches and returns sorted webhook versions.
 */
async function fetchVersionsCore(
  context: WebhooksCommandContext,
  webhook: any
): Promise<{ versions: any[]; activeVersionId: string | undefined } | null> {
  const webhookApi = new WebhookApi(BASE_URLS.API, context.apiKey, context.agentId);
  const response = await webhookApi.getWebhookVersions(webhook.webhookId);

  if (!response.success || !response.data) {
    console.error(`❌ Failed to fetch versions: ${response.error?.message || 'Unknown error'}`);
    return null;
  }

  const versions = (response.data.versions || []).sort(
    (a: any, b: any) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime()
  );

  return { versions, activeVersionId: response.data.activeVersionId };
}

/**
 * Displays versions for a webhook.
 */
function displayVersionsCore(webhook: any, versions: any[], activeVersionId: string | undefined): void {
  console.log('\n' + '='.repeat(60));
  console.log(`📜 Versions for ${webhook.name}`);
  console.log('='.repeat(60) + '\n');

  versions.forEach((version: any, index: number) => {
    const isActive = version.webhookId === activeVersionId;
    console.log(`${index + 1}. Version ${version.version}${isActive ? ' ⭐ DEPLOYED' : ''}`);
    console.log(`   Created: ${new Date(version.createdAt).toLocaleString()}`);
    console.log(`   Version ID: ${version.webhookId}`);
    console.log();
  });

  console.log('='.repeat(60));
}

/**
 * Deploys a specific version of a webhook.
 */
async function deployVersionCore(context: WebhooksCommandContext, webhook: any, version: string): Promise<boolean> {
  writeProgress(`🔄 Deploying version ${version} of "${webhook.name}"...`);

  const webhookApi = new WebhookApi(BASE_URLS.API, context.apiKey, context.agentId);
  const deployResponse = await webhookApi.publishWebhookVersion(webhook.webhookId, version);

  if (!deployResponse.success) {
    console.error(`❌ Deploy Error: ${deployResponse.error?.message || 'Unknown error'}`);
    return false;
  }

  writeSuccess(`✅ Version ${version} of "${webhook.name}" deployed successfully`);
  writeHintBlock({
    headline: 'Webhook is live. Trigger it, then inspect logs:',
    lines: [
      { label: 'Find URL:', command: `lua webhooks view --webhook-name ${webhook.name}` },
      { label: 'Trigger:', command: 'curl -X POST <URL from above>' },
      { label: 'Inspect:', command: `lua logs --type webhook --name ${webhook.name} --limit 10` },
    ],
    when: 'success',
  });
  return true;
}

/**
 * Activates a webhook.
 */
async function activateWebhookCore(context: WebhooksCommandContext, webhook: any): Promise<boolean> {
  writeProgress(`🔄 Activating webhook "${webhook.name}"...`);

  const webhookApi = new WebhookApi(BASE_URLS.API, context.apiKey, context.agentId);
  const response = await webhookApi.activateWebhook(webhook.webhookId);

  if (response.success) {
    writeSuccess(`✅ Webhook "${webhook.name}" activated successfully`);
    writeInfo('💡 The webhook is now enabled and can receive requests.');
    return true;
  } else {
    console.error(`❌ Failed to activate webhook: ${response.error?.message || 'Unknown error'}`);
    return false;
  }
}

/**
 * Deactivates a webhook.
 */
async function deactivateWebhookCore(context: WebhooksCommandContext, webhook: any): Promise<boolean> {
  writeProgress(`🔄 Deactivating webhook "${webhook.name}"...`);

  const webhookApi = new WebhookApi(BASE_URLS.API, context.apiKey, context.agentId);
  const response = await webhookApi.deactivateWebhook(webhook.webhookId);

  if (response.success) {
    writeSuccess(`✅ Webhook "${webhook.name}" deactivated successfully`);
    writeInfo('💡 The webhook is now disabled and will not receive requests.');
    return true;
  } else {
    console.error(`❌ Failed to deactivate webhook: ${response.error?.message || 'Unknown error'}`);
    return false;
  }
}

/**
 * Deletes a webhook from the server.
 * If the webhook has versions, it will be deactivated instead of deleted.
 */
async function deleteWebhookCore(context: WebhooksCommandContext, webhook: any): Promise<boolean> {
  writeProgress(`🗑️  Deleting webhook "${webhook.name}"...`);

  const webhookApi = new WebhookApi(BASE_URLS.API, context.apiKey, context.agentId);
  const response = await webhookApi.deleteWebhook(webhook.webhookId);

  if (!response.success || !response.data) {
    console.error(`❌ Delete Error: ${response.error?.message || 'Unknown error'}`);
    return false;
  }

  if (response.data.deleted) {
    writeSuccess(`✅ Webhook "${webhook.name}" deleted successfully`);
    writeInfo('💡 Remove this webhook from your lua.skill.yaml to keep it in sync.');
  } else if (response.data.deactivated) {
    writeSuccess(`⚠️  Webhook "${webhook.name}" has versions and was deactivated instead of deleted`);
    writeInfo("💡 The webhook is now inactive and won't receive requests.");
  }

  return true;
}

function listEventsCore(): void {
  console.log('\n' + '='.repeat(60));
  console.log('📡 Available event types');
  console.log('='.repeat(60) + '\n');

  for (const event of AVAILABLE_EVENT_TYPES) {
    console.log(`  • ${event}`);
  }

  console.log('\n' + '='.repeat(60));
  console.log('\nSubscribe a webhook to an event:');
  console.log('  lua webhooks subscribe --webhook-name <name> --event <eventType>\n');
}

async function subscribeCore(
  context: WebhooksCommandContext,
  webhookId: string,
  webhookName: string,
  eventType: string
): Promise<boolean> {
  if (!AVAILABLE_EVENT_TYPES.includes(eventType)) {
    console.error(`❌ Invalid event type: "${eventType}"`);
    console.log('\nAvailable event types:');
    AVAILABLE_EVENT_TYPES.forEach((e) => console.log(`  • ${e}`));
    return false;
  }

  const webhookApi = new WebhookApi(BASE_URLS.API, context.apiKey, context.agentId);
  const webhooksResponse = await webhookApi.getWebhooks();
  if (!webhooksResponse.success || !webhooksResponse.data?.webhooks) {
    console.error('❌ Failed to fetch webhooks');
    return false;
  }

  const webhook = webhooksResponse.data.webhooks.find((w) => w.id === webhookId || w.name === webhookName);
  if (!webhook) {
    console.error(`❌ Webhook "${webhookName}" not found on server`);
    return false;
  }

  const currentSubs = webhook.eventSubscriptions || [];
  if (currentSubs.includes(eventType)) {
    writeInfo(`ℹ️  Webhook "${webhookName}" is already subscribed to ${eventType}`);
    return true;
  }

  writeProgress(`🔄 Subscribing webhook "${webhookName}" to ${eventType}...`);
  const response = await webhookApi.updateWebhook(webhook.id, {
    eventSubscriptions: [...currentSubs, eventType],
  });

  if (response.success) {
    writeSuccess(`✅ Webhook "${webhookName}" subscribed to ${eventType}`);
    return true;
  } else {
    console.error(`❌ Failed to subscribe: ${response.error?.message || 'Unknown error'}`);
    return false;
  }
}

async function unsubscribeCore(
  context: WebhooksCommandContext,
  webhookId: string,
  webhookName: string,
  eventType: string
): Promise<boolean> {
  if (!AVAILABLE_EVENT_TYPES.includes(eventType)) {
    console.error(`❌ Invalid event type: "${eventType}"`);
    console.log('\nAvailable event types:');
    AVAILABLE_EVENT_TYPES.forEach((e) => console.log(`  • ${e}`));
    return false;
  }

  const webhookApi = new WebhookApi(BASE_URLS.API, context.apiKey, context.agentId);
  const webhooksResponse = await webhookApi.getWebhooks();
  if (!webhooksResponse.success || !webhooksResponse.data?.webhooks) {
    console.error('❌ Failed to fetch webhooks');
    return false;
  }

  const webhook = webhooksResponse.data.webhooks.find((w) => w.id === webhookId || w.name === webhookName);
  if (!webhook) {
    console.error(`❌ Webhook "${webhookName}" not found on server`);
    return false;
  }

  const currentSubs = webhook.eventSubscriptions || [];
  if (!currentSubs.includes(eventType)) {
    writeInfo(`ℹ️  Webhook "${webhookName}" is not subscribed to ${eventType}`);
    return true;
  }

  writeProgress(`🔄 Unsubscribing webhook "${webhookName}" from ${eventType}...`);
  const response = await webhookApi.updateWebhook(webhook.id, {
    eventSubscriptions: currentSubs.filter((e) => e !== eventType),
  });

  if (response.success) {
    writeSuccess(`✅ Webhook "${webhookName}" unsubscribed from ${eventType}`);
    return true;
  } else {
    console.error(`❌ Failed to unsubscribe: ${response.error?.message || 'Unknown error'}`);
    return false;
  }
}

/**
 * Resolves a version string to an actual version, supporting "latest".
 */
function resolveVersion(versions: any[], versionArg: string): string | null {
  if (versionArg.toLowerCase() === 'latest') {
    return versions[0].version;
  }

  const exists = versions.some((v: any) => v.version === versionArg);
  if (!exists) {
    console.error(`❌ Version "${versionArg}" not found`);
    console.log('\nAvailable versions:');
    versions.slice(0, 5).forEach((v: any) => console.log(`  - ${v.version}`));
    return null;
  }
  return versionArg;
}

/**
 * Prompts user to select a webhook from a list.
 */
async function promptWebhookSelection(webhooks: any[], message: string): Promise<any | null> {
  const answer = await safePrompt<{ selectedWebhook: any }>([
    {
      type: 'list',
      name: 'selectedWebhook',
      message,
      choices: webhooks.map((webhook: any) => ({
        name: `${webhook.name} (${webhook.webhookId})`,
        value: webhook,
      })),
    },
  ]);
  return answer?.selectedWebhook || null;
}

/**
 * Prompts user to select a version from a list.
 */
async function promptVersionSelection(versions: any[], activeVersionId: string | undefined): Promise<any | null> {
  const answer = await safePrompt<{ selectedVersion: any }>([
    {
      type: 'list',
      name: 'selectedVersion',
      message: 'Select a version to deploy:',
      choices: versions.map((version: any) => {
        const isActive = version.webhookId === activeVersionId;
        return {
          name: `Version ${version.version} (${new Date(version.createdAt).toLocaleDateString()})${isActive ? ' ⭐ CURRENT' : ''}`,
          value: version,
        };
      }),
    },
  ]);
  return answer?.selectedVersion || null;
}

// ─────────────────────────────────────────────────────────────────────────────
// Non-Interactive Mode
// ─────────────────────────────────────────────────────────────────────────────

async function executeNonInteractive(
  context: WebhooksCommandContext,
  config: YamlConfig,
  action: string,
  options: WebhooksOptions
): Promise<void> {
  const normalizedAction = validateOrSuggest('webhooks.action', action);

  const webhooks = config.webhooks || [];

  if (normalizedAction === 'list-events') {
    listEventsCore();
    return;
  }

  // View action doesn't require webhook selection
  if (normalizedAction === 'view') {
    if (webhooks.length === 0) {
      console.log('ℹ️  No webhooks found in configuration.');
      return;
    }
    await displayWebhooksCore(context, webhooks);
    return;
  }

  // All other actions require webhook selection
  if (!options.webhookName) {
    console.error(`❌ --webhook-name is required for action "${normalizedAction}"`);
    console.log(`\nUsage: lua webhooks ${normalizedAction} --webhook-name <name>`);
    throw new Error(`--webhook-name is required for action "${normalizedAction}"`);
  }

  let selectedWebhook = webhooks.find((w) => w.webhookId === options.webhookName || w.name === options.webhookName);

  // For delete action, also check server webhooks (for orphaned webhooks not in local YAML)
  if (!selectedWebhook && normalizedAction === 'delete') {
    const webhookApi = new WebhookApi(BASE_URLS.API, context.apiKey, context.agentId);
    const serverResponse = await webhookApi.getWebhooks();

    if (serverResponse.success && serverResponse.data?.webhooks) {
      const serverWebhook = serverResponse.data.webhooks.find(
        (w) => w.id === options.webhookName || w.name === options.webhookName
      );
      if (serverWebhook) {
        const activeVersion = serverWebhook.versions.find((v) => v.isActive) ?? serverWebhook.versions[0];
        selectedWebhook = {
          name: serverWebhook.name,
          webhookId: serverWebhook.id,
          version: activeVersion?.version ?? '',
        };
      }
    }
  }

  if (!selectedWebhook) {
    console.error(`❌ Webhook "${options.webhookName}" not found`);
    console.log('\nAvailable webhooks in local config:');
    webhooks.forEach((w) => console.log(`  - ${w.name} (${w.webhookId})`));
    if (normalizedAction === 'delete') {
      console.log('\n💡 Tip: The webhook may have already been deleted from the server.');
    }
    throw new Error(`Webhook "${options.webhookName}" not found`);
  }

  switch (normalizedAction as WebhookAction) {
    case 'versions': {
      const data = await fetchVersionsCore(context, selectedWebhook);
      if (!data) throw new Error('Failed to fetch webhook versions');
      if (data.versions.length === 0) {
        console.log(`ℹ️  No versions found for ${selectedWebhook.name}.`);
        console.log("💡 Push a version first using 'lua push webhook'.");
        return;
      }
      displayVersionsCore(selectedWebhook, data.versions, data.activeVersionId);
      break;
    }
    case 'deploy': {
      if (!options.webhookVersion) {
        console.error('❌ --webhook-version is required for deploy action');
        console.log('\nUsage: lua webhooks deploy --webhook-name myWebhook --webhook-version 1.0.3');
        console.log('       lua webhooks deploy -i myWebhook -v latest');
        throw new Error('--webhook-version is required for deploy action');
      }
      const data = await fetchVersionsCore(context, selectedWebhook);
      if (!data) throw new Error('Failed to fetch webhook versions');
      if (data.versions.length === 0) {
        console.error(`❌ No versions found for ${selectedWebhook.name}.`);
        console.log("💡 Push a version first using 'lua push webhook'.");
        throw new Error(`No versions found for ${selectedWebhook.name}`);
      }
      const resolvedVersion = resolveVersion(data.versions, options.webhookVersion);
      if (!resolvedVersion) throw new Error('Failed to resolve webhook version');
      const success = await deployVersionCore(context, selectedWebhook, resolvedVersion);
      if (!success) throw new Error('Failed to deploy webhook version');
      break;
    }
    case 'activate': {
      const success = await activateWebhookCore(context, selectedWebhook);
      if (!success) throw new Error('Failed to activate webhook');
      break;
    }
    case 'deactivate': {
      const success = await deactivateWebhookCore(context, selectedWebhook);
      if (!success) throw new Error('Failed to deactivate webhook');
      break;
    }
    case 'delete': {
      const success = await deleteWebhookCore(context, selectedWebhook);
      if (!success) throw new Error('Failed to delete webhook');
      break;
    }
    case 'subscribe': {
      if (!options.event) {
        console.error('❌ --event is required for subscribe action');
        console.log('\nUsage: lua webhooks subscribe --webhook-name myWebhook --event message.delivered');
        console.log('\nAvailable events:');
        AVAILABLE_EVENT_TYPES.forEach((e) => console.log(`  • ${e}`));
        throw new Error('--event is required for subscribe action');
      }
      const success = await subscribeCore(context, selectedWebhook.webhookId, selectedWebhook.name, options.event);
      if (!success) throw new Error('Failed to subscribe webhook to event');
      break;
    }
    case 'unsubscribe': {
      if (!options.event) {
        console.error('❌ --event is required for unsubscribe action');
        console.log('\nUsage: lua webhooks unsubscribe --webhook-name myWebhook --event message.delivered');
        throw new Error('--event is required for unsubscribe action');
      }
      const success = await unsubscribeCore(context, selectedWebhook.webhookId, selectedWebhook.name, options.event);
      if (!success) throw new Error('Failed to unsubscribe webhook from event');
      break;
    }
  }
}

// ─────────────────────────────────────────────────────────────────────────────
// Interactive Mode
// ─────────────────────────────────────────────────────────────────────────────

async function manageWebhooksInteractive(context: WebhooksCommandContext, config: YamlConfig): Promise<void> {
  let continueManaging = true;

  while (continueManaging) {
    console.log('\n' + '='.repeat(60));
    console.log('🚀 Production Webhooks');
    console.log('='.repeat(60) + '\n');

    const actionAnswer = await safePrompt<{ action: string }>([
      {
        type: 'list',
        name: 'action',
        message: 'What would you like to do?',
        choices: [
          { name: '👁️  View deployed webhooks', value: 'view' },
          { name: '📜 View webhook versions', value: 'versions' },
          { name: '🚀 Deploy a version', value: 'deploy' },
          { name: '✅ Activate a webhook', value: 'activate' },
          { name: '🚫 Deactivate a webhook', value: 'deactivate' },
          { name: '🗑️  Delete a webhook', value: 'delete' },
          { name: '❌ Exit', value: 'exit' },
        ],
      },
    ]);

    if (!actionAnswer) return;
    const { action } = actionAnswer;

    switch (action) {
      case 'view':
        await viewWebhooksInteractive(context, config);
        break;
      case 'versions':
        await viewVersionsInteractive(context, config);
        break;
      case 'deploy':
        await deployVersionInteractive(context, config);
        break;
      case 'activate':
        await activateWebhookInteractive(context, config);
        break;
      case 'deactivate':
        await deactivateWebhookInteractive(context, config);
        break;
      case 'delete':
        await deleteWebhookInteractive(context, config);
        break;
      case 'exit':
        continueManaging = false;
        console.log('\n👋 Goodbye!\n');
        break;
    }
  }
}

async function viewWebhooksInteractive(context: WebhooksCommandContext, config: YamlConfig): Promise<void> {
  writeProgress('🔄 Loading webhook information...');
  const webhooks = config.webhooks || [];

  if (webhooks.length === 0) {
    console.log('\nℹ️  No webhooks found in configuration.\n');
  } else {
    await displayWebhooksCore(context, webhooks);
    console.log();
  }

  await safePrompt([{ type: 'input', name: 'continue', message: 'Press Enter to continue...' }]);
}

async function viewVersionsInteractive(context: WebhooksCommandContext, config: YamlConfig): Promise<void> {
  const webhooks = config.webhooks || [];

  if (webhooks.length === 0) {
    console.log('\nℹ️  No webhooks found in configuration.\n');
    await safePrompt([{ type: 'input', name: 'continue', message: 'Press Enter to continue...' }]);
    return;
  }

  const selectedWebhook = await promptWebhookSelection(webhooks, 'Select a webhook to view versions:');
  if (!selectedWebhook) return;

  writeProgress(`🔄 Loading versions for ${selectedWebhook.name}...`);
  const data = await fetchVersionsCore(context, selectedWebhook);

  if (!data) {
    await safePrompt([{ type: 'input', name: 'continue', message: 'Press Enter to continue...' }]);
    return;
  }

  if (data.versions.length === 0) {
    console.log(`\nℹ️  No versions found for ${selectedWebhook.name}.\n`);
    console.log("💡 Push a version first using 'lua push webhook'.\n");
  } else {
    displayVersionsCore(selectedWebhook, data.versions, data.activeVersionId);
    console.log();
  }

  await safePrompt([{ type: 'input', name: 'continue', message: 'Press Enter to continue...' }]);
}

async function deployVersionInteractive(context: WebhooksCommandContext, config: YamlConfig): Promise<void> {
  const webhooks = config.webhooks || [];

  if (webhooks.length === 0) {
    console.log('\nℹ️  No webhooks found in configuration.\n');
    await safePrompt([{ type: 'input', name: 'continue', message: 'Press Enter to continue...' }]);
    return;
  }

  const selectedWebhook = await promptWebhookSelection(webhooks, 'Select a webhook to deploy:');
  if (!selectedWebhook) return;

  writeProgress(`🔄 Loading versions for ${selectedWebhook.name}...`);
  const data = await fetchVersionsCore(context, selectedWebhook);

  if (!data) {
    await safePrompt([{ type: 'input', name: 'continue', message: 'Press Enter to continue...' }]);
    return;
  }

  if (data.versions.length === 0) {
    console.log(`\nℹ️  No versions found for ${selectedWebhook.name}.\n`);
    console.log("💡 Push a version first using 'lua push webhook'.\n");
    await safePrompt([{ type: 'input', name: 'continue', message: 'Press Enter to continue...' }]);
    return;
  }

  const selectedVersion = await promptVersionSelection(data.versions, data.activeVersionId);
  if (!selectedVersion) return;

  // Show warning and confirm
  console.log('\n⚠️  WARNING: You are about to deploy to PRODUCTION!');
  console.log('⚠️  This will affect ALL users immediately.\n');
  console.log(`Webhook: ${selectedWebhook.name}`);
  console.log(`Version: ${selectedVersion.version}\n`);

  const confirmAnswer = await safePrompt<{ confirm: boolean }>([
    {
      type: 'confirm',
      name: 'confirm',
      message: 'Are you absolutely sure you want to deploy this version?',
      default: false,
    },
  ]);

  if (!confirmAnswer || !confirmAnswer.confirm) {
    console.log('\n❌ Deployment cancelled.\n');
    return;
  }

  await deployVersionCore(context, selectedWebhook, selectedVersion.version);
  await safePrompt([{ type: 'input', name: 'continue', message: 'Press Enter to continue...' }]);
}

async function activateWebhookInteractive(context: WebhooksCommandContext, config: YamlConfig): Promise<void> {
  const webhooks = config.webhooks || [];

  if (webhooks.length === 0) {
    console.log('\nℹ️  No webhooks found in configuration.\n');
    await safePrompt([{ type: 'input', name: 'continue', message: 'Press Enter to continue...' }]);
    return;
  }

  const selectedWebhook = await promptWebhookSelection(webhooks, 'Select a webhook to activate:');
  if (!selectedWebhook) return;

  await activateWebhookCore(context, selectedWebhook);
  await safePrompt([{ type: 'input', name: 'continue', message: 'Press Enter to continue...' }]);
}

