async function deleteWebhookInteractive(context: WebhooksCommandContext, config: YamlConfig): Promise<void> {
  const { merged, orphanIds, serverFailed } = await webhookHandler.fetchMergedForInteraction(
    context.apiKey,
    context.agentId,
    config
  );
  if (serverFailed) {
    console.log('\n⚠️  Could not reach server. Showing local items only.\n');
  }

  if (merged.length === 0) {
    console.log('\nℹ️  No webhooks found in configuration.\n');
    await safePrompt([{ type: 'input', name: 'continue', message: 'Press Enter to continue...' }]);
    return;
  }

  const answer = await safePrompt<{ selected: (typeof merged)[number] }>([
    {
      type: 'list',
      name: 'selected',
      message: 'Select a webhook to delete:',
      choices: merged.map((item) => ({
        name: orphanIds.has(item.webhookId)
          ? `${item.name} (${item.webhookId}) [server only]`
          : `${item.name} (${item.webhookId})`,
        value: item,
      })),
    },
  ]);
  const selectedWebhook = answer?.selected ?? null;
  if (!selectedWebhook) return;

  console.log('\n⚠️  WARNING: You are about to delete a webhook!');
  console.log('⚠️  If the webhook has versions, it will be deactivated instead.\n');

  const confirmAnswer = await safePrompt<{ confirm: boolean }>([
    {
      type: 'confirm',
      name: 'confirm',
      message: `Are you sure you want to delete "${selectedWebhook.name}"?`,
      default: false,
    },
  ]);

  if (!confirmAnswer || !confirmAnswer.confirm) {
    console.log('\n❌ Deletion cancelled.\n');
    return;
  }

  await deleteWebhookCore(context, selectedWebhook);
  await safePrompt([{ type: 'input', name: 'continue', message: 'Press Enter to continue...' }]);
}
