/**
 * File Discovery Utilities
 *
 * Centralized logic for finding entry points and index files in Lua agent projects.
 * Used by source-writer and agent-traverser.
 */

import path from 'path';
import fs from 'fs';

/**
 * Priority order for finding entry point files.
 * Common conventions for where agents define their LuaAgent.
 */
const ENTRY_POINT_PRIORITY = ['index.ts', 'src/index.ts', 'agent.ts', 'src/agent.ts', 'main.ts', 'src/main.ts'];

/**
 * Find the entry point file for a Lua agent project.
 *
 * Searches in priority order:
 * 1. index.ts (root)
 * 2. src/index.ts
 * 3. agent.ts (root)
 * 4. src/agent.ts
 * 5. main.ts (root)
 * 6. src/main.ts
 *
 * @param projectDir - Project directory to search (defaults to cwd)
 * @returns Absolute path to entry point, or null if not found
 */
export function findEntryPoint(projectDir?: string): string | null {
  const baseDir = projectDir || process.cwd();

  for (const relativePath of ENTRY_POINT_PRIORITY) {
    const fullPath = path.join(baseDir, relativePath);
    if (fs.existsSync(fullPath)) {
      return fullPath;
    }
  }

  return null;
}

/**
 * Find the index file for a Lua agent project.
 * Same as findEntryPoint but throws if not found.
 *
 * @param projectDir - Project directory to search (defaults to cwd)
 * @returns Absolute path to entry point
 * @throws Error if no entry point found
 */
export function findIndexFile(projectDir?: string): string {
  const entryPoint = findEntryPoint(projectDir);

  if (!entryPoint) {
    const baseDir = projectDir || process.cwd();
    throw new Error(`No entry point found in ${baseDir}. ` + `Expected one of: ${ENTRY_POINT_PRIORITY.join(', ')}`);
  }

  return entryPoint;
}

/**
 * Get the list of priority entry point paths (for documentation/debugging).
 */
export function getEntryPointPriority(): readonly string[] {
  return ENTRY_POINT_PRIORITY;
}
