/**
 * Resources Command
 * Manages agent resources (knowledge base documents)
 */

import { withErrorHandling, writeProgress, writeSuccess, writeInfo } from '../utils/cli.js';
import { BASE_URLS } from '../config/constants.js';
import { safePrompt } from '../utils/prompt-handler.js';
import { initializeCommand } from '../utils/command-utils.js';
import ResourceApi from '../api/resource.api.service.js';
import { trackEvent } from '../services/analytics.js';
import type { Resource } from '../api/resource.api.service.js';
import { validateOrSuggest } from '../utils/aliases.js';

interface ResourcesContext {
  agentId: string;
  apiKey: string;
}

interface ResourcesOptions {
  resourceName?: string;
}

type ResourceAction = 'list' | 'view' | 'delete';

// ─────────────────────────────────────────────────────────────────────────────
// Main Command Entry
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Main resources command - manages agent resources.
 *
 * Supports both interactive and non-interactive modes:
 * - Interactive: prompts for action and resource selection
 * - Non-interactive: use action argument with -i flag
 */
export async function resourcesCommand(action?: string, cmdObj?: any): Promise<void> {
  return withErrorHandling(async () => {
    const options: ResourcesOptions = {
      resourceName: cmdObj?.resourceName || null,
    };

    // Initialize command (validates config + auth)
    const { agentId, apiKey } = await initializeCommand();

    const context: ResourcesContext = {
      agentId,
      apiKey,
    };

    // Determine mode
    if (action) {
      await executeNonInteractive(context, action, options);
    } else {
      await manageResourcesInteractive(context);
    }
    trackEvent('cli_resources_action', {
      action: action || 'interactive',
      resource_name: options.resourceName || null,
      non_interactive: !!action,
    });
  }, 'resources');
}

// ─────────────────────────────────────────────────────────────────────────────
// Shared Core Functions
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Fetches all resources from the API.
 */
async function fetchResourcesCore(context: ResourcesContext): Promise<Resource[]> {
  try {
    const resourceApi = new ResourceApi(BASE_URLS.API, context.apiKey, context.agentId);
    const response = await resourceApi.getResources();

    if (!response.success || !response.data) {
      return [];
    }

    if (Array.isArray(response.data)) {
      return response.data;
    }

    return [];
  } catch (error) {
    console.error('⚠️  Error loading resources');
    return [];
  }
}

/**
 * Displays all resources with preview.
 */
function displayResourcesCore(resources: Resource[]): void {
  console.log('\n' + '='.repeat(60));
  console.log('📚 Agent Resources');
  console.log('='.repeat(60) + '\n');

  if (resources.length === 0) {
    console.log('ℹ️  No resources configured.\n');
    console.log('💡 Resources are knowledge base documents your agent can reference.\n');
    return;
  }

  resources.forEach((resource, index) => {
    const preview = resource.content.length > 60 ? resource.content.substring(0, 60) + '...' : resource.content;
    console.log(`${index + 1}. ${resource.name}`);
    console.log(`   Preview: ${preview}`);
    console.log();
  });

  console.log('='.repeat(60));
}

/**
 * Displays full content of a resource.
 */
function viewResourceCore(resource: Resource): void {
  console.log('\n' + '='.repeat(60));
  console.log(`📄 Resource: ${resource.name}`);
  console.log('='.repeat(60));
  if (resource.createdAt) {
    console.log(`Created: ${new Date(resource.createdAt).toLocaleString()}`);
  }
  if (resource.updatedAt) {
    console.log(`Updated: ${new Date(resource.updatedAt).toLocaleString()}`);
  }
  console.log('='.repeat(60) + '\n');
  console.log(resource.content);
  console.log('\n' + '='.repeat(60));
}

/**
 * Deletes a resource.
 */
async function deleteResourceCore(context: ResourcesContext, resource: Resource): Promise<boolean> {
  writeProgress(`🔄 Deleting resource "${resource.name}"...`);

  try {
    const resourceApi = new ResourceApi(BASE_URLS.API, context.apiKey, context.agentId);
    const response = await resourceApi.deleteResource(resource.id);

    if (!response.success) {
      console.error(`❌ Failed to delete resource: ${response.error?.message || 'Unknown error'}`);
      return false;
    }

    writeSuccess(`✅ Resource "${resource.name}" deleted successfully`);
    return true;
  } catch (error) {
    console.error(`❌ Error deleting resource: ${error}`);
    return false;
  }
}

/**
 * Finds a resource by name or ID (case-insensitive for name).
 */
function findResource(resources: Resource[], resourceId: string): Resource | null {
  const normalizedId = resourceId.toLowerCase();
  return resources.find((r) => r.id === resourceId || r.name.toLowerCase() === normalizedId) || null;
}

/**
 * Prompts user to select a resource from a list.
 */
async function promptResourceSelection(resources: Resource[], message: string): Promise<Resource | null> {
  const answer = await safePrompt<{ selectedId: string }>([
    {
      type: 'list',
      name: 'selectedId',
      message,
      choices: resources.map((r) => ({
        name: r.name,
        value: r.id,
      })),
    },
  ]);

  if (!answer) return null;
  return resources.find((r) => r.id === answer.selectedId) || null;
}

// ─────────────────────────────────────────────────────────────────────────────
// Non-Interactive Mode
// ─────────────────────────────────────────────────────────────────────────────

async function executeNonInteractive(
  context: ResourcesContext,
  action: string,
  options: ResourcesOptions
): Promise<void> {
  const normalizedAction = validateOrSuggest('resources.action', action);

  const resources = await fetchResourcesCore(context);

  // List action doesn't require resource selection
  if (normalizedAction === 'list') {
    displayResourcesCore(resources);
    return;
  }

  // All other actions require resource selection
  if (!options.resourceName) {
    console.error(`❌ --resource-name is required for action "${normalizedAction}"`);
    console.log(`\nUsage: lua resources ${normalizedAction} --resource-name <name>`);
    if (resources.length > 0) {
      console.log('\nAvailable resources:');
      resources.forEach((r) => console.log(`  - ${r.name}`));
    }
    throw new Error('Operation failed');
  }

  const selectedResource = findResource(resources, options.resourceName);
  if (!selectedResource) {
    console.error(`❌ Resource "${options.resourceName}" not found`);
    if (resources.length > 0) {
      console.log('\nAvailable resources:');
      resources.forEach((r) => console.log(`  - ${r.name}`));
    } else {
      console.log('\nNo resources found.');
    }
    throw new Error('Operation failed');
  }

  switch (normalizedAction as ResourceAction) {
    case 'view':
      viewResourceCore(selectedResource);
      break;
    case 'delete': {
      const success = await deleteResourceCore(context, selectedResource);
      if (!success) throw new Error('Operation failed');
      break;
    }
  }
}

// ─────────────────────────────────────────────────────────────────────────────
// Interactive Mode
// ─────────────────────────────────────────────────────────────────────────────

async function manageResourcesInteractive(context: ResourcesContext): Promise<void> {
  let continueManaging = true;

  while (continueManaging) {
    const resources = await fetchResourcesCore(context);

    displayResourcesCore(resources);

    const actionAnswer = await safePrompt<{ action: string }>([
      {
        type: 'list',
        name: 'action',
        message: 'What would you like to do?',
        choices: [
          { name: '➕ Create new resource', value: 'create' },
          { name: '✏️  Update existing resource', value: 'update' },
          { name: '🗑️  Delete resource', value: 'delete' },
          { name: '👁️  View resource content', value: 'view' },
          { name: '🔄 Refresh list', value: 'refresh' },
          { name: '❌ Exit', value: 'exit' },
        ],
      },
    ]);

    if (!actionAnswer) return;
    const { action } = actionAnswer;

    switch (action) {
      case 'create':
        await createResourceInteractive(context);
        break;
      case 'update':
        await updateResourceInteractive(context, resources);
        break;
      case 'delete':
        await deleteResourceInteractive(context, resources);
        break;
      case 'view':
        await viewResourceInteractive(resources);
        break;
      case 'refresh':
        break;
      case 'exit':
        continueManaging = false;
        console.log('\n👋 Goodbye!\n');
        break;
    }
  }
}

async function createResourceInteractive(context: ResourcesContext): Promise<void> {
  const answers = await safePrompt<{ name: string; content: string }>([
    {
      type: 'input',
      name: 'name',
      message: 'Resource name:',
      validate: (input: string) => {
        if (!input.trim()) return 'Resource name is required';
        return true;
      },
    },
    {
      type: 'editor',
      name: 'content',
      message: 'Resource content (will open in your default editor):',
      validate: (input: string) => {
        if (!input.trim()) return 'Resource content cannot be empty';
        return true;
      },
    },
  ]);

  if (!answers) return;

  writeProgress('🔄 Creating resource...');

  try {
    const resourceApi = new ResourceApi(BASE_URLS.API, context.apiKey, context.agentId);
    const response = await resourceApi.createResource({
      name: answers.name.trim(),
      content: answers.content.trim(),
    });

    if (!response.success) {
      throw new Error(response.error?.message || 'Failed to create resource');
    }

    writeSuccess(`✅ Resource "${answers.name}" created successfully`);
  } catch (error) {
    console.error('❌ Error creating resource:', error);
  }
}

async function updateResourceInteractive(context: ResourcesContext, resources: Resource[]): Promise<void> {
  if (resources.length === 0) {
    console.log('\nℹ️  No resources to update.\n');
    return;
  }

  const selectedResource = await promptResourceSelection(resources, 'Select resource to update:');
  if (!selectedResource) return;

  const updateAnswers = await safePrompt<{ name: string; content: string }>([
    {
      type: 'input',
      name: 'name',
      message: 'Resource name:',
      default: selectedResource.name,
      validate: (input: string) => {
        if (!input.trim()) return 'Resource name is required';
        return true;
      },
    },
    {
      type: 'editor',
      name: 'content',
      message: 'Resource content (will open in your default editor):',
      default: selectedResource.content,
      validate: (input: string) => {
        if (!input.trim()) return 'Resource content cannot be empty';
        return true;
      },
    },
  ]);

  if (!updateAnswers) return;

  writeProgress('🔄 Updating resource...');

  try {
    const resourceApi = new ResourceApi(BASE_URLS.API, context.apiKey, context.agentId);
    const response = await resourceApi.updateResource(selectedResource.id, {
      name: updateAnswers.name.trim(),
      content: updateAnswers.content.trim(),
    });

    if (!response.success) {
      throw new Error(response.error?.message || 'Failed to update resource');
    }

    writeSuccess(`✅ Resource "${updateAnswers.name}" updated successfully`);
  } catch (error) {
    console.error('❌ Error updating resource:', error);
  }
}

async function deleteResourceInteractive(context: ResourcesContext, resources: Resource[]): Promise<void> {
  if (resources.length === 0) {
    console.log('\nℹ️  No resources to delete.\n');
    return;
  }

  const selectedResource = await promptResourceSelection(resources, 'Select resource to delete:');
  if (!selectedResource) return;

  const confirmAnswer = await safePrompt<{ confirm: boolean }>([
    {
      type: 'confirm',
      name: 'confirm',
      message: `Are you sure you want to delete "${selectedResource.name}"?`,
      default: false,
    },
  ]);

  if (!confirmAnswer || !confirmAnswer.confirm) {
    console.log('\nℹ️  Deletion cancelled.\n');
    return;
  }

  await deleteResourceCore(context, selectedResource);
}

async function viewResourceInteractive(resources: Resource[]): Promise<void> {
  if (resources.length === 0) {
    console.log('\nℹ️  No resources to view.\n');
    return;
  }

  const selectedResource = await promptResourceSelection(resources, 'Select resource to view:');
  if (!selectedResource) return;

  viewResourceCore(selectedResource);
  console.log();

  await safePrompt([
    {
      type: 'input',
      name: 'continue',
      message: 'Press Enter to continue...',
    },
  ]);
}
