export type AliasGroup =
  | 'push.type'
  | 'logs.type'
  | 'test.type'
  | 'deploy.type'
  | 'env.environment'
  | 'persona.env'
  | 'persona.action'
  | 'production.action'
  | 'resources.action'
  | 'channels.action'
  | 'skills.actionOrEnv'
  | 'skills.action'
  | 'webhooks.action'
  | 'jobs.action'
  | 'preprocessors.action'
  | 'postprocessors.action'
  | 'devices.action'
  | 'features.action'
  | 'mcp.action'
  | 'integrations.action'
  | 'triggers.action'
  | 'marketplace.role'
  | 'marketplace.action.create'
  | 'marketplace.action.install'
  | 'models.action'
  | 'telemetry.action'
  | 'governance.action'
  | 'completion.shell';

interface AliasEntry {
  canonical: string[];
  aliases: Record<string, string>;
}

function lowerKeys(aliases: Record<string, string>): Record<string, string> {
  const out: Record<string, string> = {};
  for (const k of Object.keys(aliases)) {
    out[k.toLowerCase()] = aliases[k];
  }
  return out;
}

