export function normalizeArg(group: AliasGroup, input?: string): string | undefined {
  if (input === undefined || input === '') return input;
  const entry = ALIAS_MAP[group];
  const lower = input.toLowerCase();
  if (Object.prototype.hasOwnProperty.call(entry.aliases, lower)) {
    return entry.aliases[lower];
  }
  if (entry.canonical.includes(lower)) {
    return lower;
  }
  return input;
}

export function getCanonicalValues(group: AliasGroup): string[] {
  return [...ALIAS_MAP[group].canonical].sort();
}

export function validateOrSuggest(group: AliasGroup, input: string, opts?: { allowAll?: boolean }): string {
  const normalized = normalizeArg(group, input);
  const candidates = getCanonicalValues(group);
  if (opts?.allowAll === true) {
    candidates.push('all');
  }
  if (normalized !== undefined && candidates.includes(normalized)) {
    return normalized;
  }
  const suggestion = suggestClosest(normalized ?? input, candidates);
  if (suggestion) {
    throw new Error(
      `lua: "${input}" is not a valid ${group} value. Did you mean "${suggestion}"?\nValid values: ${candidates.join(', ')}`
    );
  }
  throw new Error(`lua: "${input}" is not a valid ${group} value.\nValid values: ${candidates.join(', ')}`);
}
