/**
 * Shared helpers for the `lua voice` CLI surface. Pulled out of
 * voice-browser / voice-terminal so the two consumers can't drift on
 * how they interpret the dispatch response's `joinUrl`.
 */

/**
 * Split a LiveKit web join URL (`wss://host/path?token=<jwt>`) into
 * the bare WebSocket URL and the token. Throws if the URL doesn't
 * carry a token — empty-string tokens produce confusing
 * "connect failed" UIs downstream rather than a clear "server
 * forgot to mint a token" diagnostic.
 */
export function parseJoinUrl(joinUrl: string): { wsUrl: string; token: string } {
  const u = new URL(joinUrl);
  const token = u.searchParams.get('token');
  if (!token) {
    throw new Error('Dispatch joinUrl is missing ?token=…; cannot connect.');
  }
  u.searchParams.delete('token');
  // Reconstruct without the token query param. Trailing `?` is
  // possible when token was the only param; strip it. Search/hash
  // (other than token) are preserved verbatim for forward compat
  // with future query params LiveKit might add.
  const wsUrl = `${u.protocol}//${u.host}${u.pathname}${u.search}${u.hash}`.replace(/\?$/, '');
  return { wsUrl, token };
}
