/**
 * Tiny ASCII-table renderer — pads columns to the widest cell,
 * surrounds with box-drawing chars. Kept inline so we don't pull in
 * `cli-table3` for the handful of places that need a table. Empty
 * `rows` renders as a single `(no rows)` line.
 *
 * Used by `lua channels phone list` and `lua logs --calls`.
 */
export function renderTable(headers: string[], rows: string[][]): string {
  if (rows.length === 0) return '(no rows)';
  const widths = headers.map((h, i) => Math.max(h.length, ...rows.map((r) => (r[i] ?? '').length)));
  const top = '┌' + widths.map((w) => '─'.repeat(w + 2)).join('┬') + '┐';
  const sep = '├' + widths.map((w) => '─'.repeat(w + 2)).join('┼') + '┤';
  const bottom = '└' + widths.map((w) => '─'.repeat(w + 2)).join('┴') + '┘';
  const renderRow = (cells: string[]): string =>
    '│ ' + cells.map((c, i) => (c ?? '').padEnd(widths[i])).join(' │ ') + ' │';
  return [top, renderRow(headers), sep, ...rows.map(renderRow), bottom].join('\n');
}
