/**
 * Marketplace API Service
 * Handles all communication with the Lua Marketplace API.
 */
import { BASE_URLS } from '../config/constants.js';
import {
  MarketplaceSkillWithVersionsResponse,
  MarketplaceVersionResponse,
  SkillResponse,
  UnpublishVersionResponse,
  UnlistSkillResponse,
  PaginatedMarketplaceSkillsResponse,
  ListSkillRequest,
  UpdateSkillRequest,
  PublishVersionRequest,
  InstallSkillRequest,
  UpdateInstallationRequest,
} from '../interfaces/marketplace.js';

export class MarketplaceApiService {
  private apiKey: string;
  private baseUrl: string = BASE_URLS.API;

  constructor(apiKey: string) {
    this.apiKey = apiKey;
  }

  private async _fetch(endpoint: string, options: RequestInit = {}): Promise<any> {
    const url = `${this.baseUrl}${endpoint}`;
    const headers = {
      Authorization: `Bearer ${this.apiKey}`,
      'Content-Type': 'application/json',
      ...options.headers,
    };

    const response = await fetch(url, { ...options, headers });

    if (!response.ok) {
      const errorText = await response.text();
      throw new Error(`API Error: ${response.status} ${response.statusText} - ${errorText}`);
    }

    if (response.status === 204) {
      // No content
      return null;
    }

    return response.json();
  }

  // --- Creator Methods ---

  async listSkill(data: ListSkillRequest): Promise<MarketplaceSkillWithVersionsResponse> {
    return this._fetch('/marketplace/skills/list', {
      method: 'POST',
      body: JSON.stringify(data),
    });
  }

  async updateSkill(
    marketplaceSkillId: string,
    data: UpdateSkillRequest
  ): Promise<MarketplaceSkillWithVersionsResponse> {
    return this._fetch(`/marketplace/skills/${marketplaceSkillId}`, {
      method: 'PATCH',
      body: JSON.stringify(data),
    });
  }

  async unlistSkill(marketplaceSkillId: string): Promise<UnlistSkillResponse> {
    return this._fetch(`/marketplace/skills/${marketplaceSkillId}/unlist`, {
      method: 'PUT',
    });
  }

  async publishVersion(marketplaceSkillId: string, data: PublishVersionRequest): Promise<MarketplaceVersionResponse> {
    return this._fetch(`/marketplace/skills/${marketplaceSkillId}/versions/publish`, {
      method: 'POST',
      body: JSON.stringify(data),
    });
  }

  async unpublishVersion(marketplaceSkillId: string, versionId: string): Promise<UnpublishVersionResponse> {
    return this._fetch(`/marketplace/skills/${marketplaceSkillId}/unpublish`, {
      method: 'PUT',
      body: JSON.stringify({ versionId }),
    });
  }

  async getCreatorSkills(): Promise<MarketplaceSkillWithVersionsResponse[]> {
    return this._fetch('/marketplace/creator/skills');
  }

  // --- Installer Methods ---

  async searchSkills(filters?: {
    search?: string;
    name?: string;
    creatorId?: string;
    publishedVersionsOnly?: boolean;
    page?: number;
    limit?: number;
  }): Promise<PaginatedMarketplaceSkillsResponse> {
    const params = new URLSearchParams();
    if (filters?.search) {
      params.append('search', filters.search);
    }
    if (filters?.name) {
      params.append('name', filters.name);
    }
    if (filters?.creatorId) {
      params.append('creatorId', filters.creatorId);
    }
    if (filters?.publishedVersionsOnly !== undefined) {
      params.append('publishedVersionsOnly', String(filters.publishedVersionsOnly));
    }
    if (filters?.page !== undefined) {
      params.append('page', String(filters.page));
    }
    if (filters?.limit !== undefined) {
      params.append('limit', String(filters.limit));
    }
    return this._fetch(`/marketplace/skills?${params.toString()}`);
  }

  async getSkillById(marketplaceSkillId: string): Promise<MarketplaceSkillWithVersionsResponse> {
    return this._fetch(`/marketplace/skills/${marketplaceSkillId}`);
  }

  async getSkillVersions(marketplaceSkillId: string): Promise<MarketplaceVersionResponse[]> {
    return this._fetch(`/marketplace/skills/${marketplaceSkillId}/versions`);
  }

  async installSkill(marketplaceSkillId: string, agentId: string, data: InstallSkillRequest): Promise<SkillResponse> {
    return this._fetch(`/marketplace/install/${marketplaceSkillId}/${agentId}`, {
      method: 'POST',
      body: JSON.stringify(data),
    });
  }

  async updateInstallation(
    marketplaceSkillId: string,
    agentId: string,
    data: UpdateInstallationRequest
  ): Promise<SkillResponse> {
    return this._fetch(`/marketplace/install/${marketplaceSkillId}/${agentId}`, {
      method: 'PUT',
      body: JSON.stringify(data),
    });
  }

  async uninstallSkill(marketplaceSkillId: string, agentId: string): Promise<SkillResponse> {
    return this._fetch(`/marketplace/install/${marketplaceSkillId}/${agentId}`, {
      method: 'DELETE',
    });
  }

  async getInstalledSkills(agentId: string): Promise<SkillResponse[]> {
    return this._fetch(`/marketplace/installations/${agentId}`);
  }
}
