/**
 * Phone-number management sub-flow for `lua channels`. Entered via the
 * "☎️  Manage phone numbers" branch of the interactive picker; not
 * registered as a top-level Commander command (one entry point, one
 * docs surface).
 *
 * Each branch under the action picker maps 1:1 onto an existing
 * developer / admin endpoint:
 *
 *   search   → GET  /developer/phone-numbers/available
 *   purchase → POST /developer/orgs/:orgId/phone-numbers
 *   bind     → POST /admin/agents/:agentId/channels  (type: 'phone')
 *   unbind   → DELETE /admin/agents/:agentId/channels/phone/:msisdn
 *   list     → GET  /developer/orgs/:orgId/phone-numbers
 *   release  → DELETE /developer/orgs/:orgId/phone-numbers/:msisdn
 */

import { writeSuccess, writeInfo, writeProgress } from '../utils/cli.js';
import ChannelsApi from '../api/channels.api.service.js';
import VoiceApi from '../api/voice.api.service.js';
import { BASE_URLS } from '../config/constants.js';
import { trackEvent } from '../services/analytics.js';
import { safePrompt } from '../utils/prompt-handler.js';
import { renderTable } from '../utils/table.js';

type Action = 'search' | 'purchase' | 'bind' | 'unbind' | 'list' | 'release';

/**
 * Entry point used by `channelsInteractive`. The orgId comes from the
 * surrounding command's resolved CommandContext so the caller never has
 * to re-prompt for it. `apiKey` is needed to construct VoiceApi for the
 * bind path's voice picker — channels.ts could have passed VoiceApi
 * directly, but threading the apiKey keeps the sub-flow's external
 * surface to one client and lets it construct VoiceApi lazily (most
 * branches never need it).
 */
export async function runPhoneInteractive(
  api: ChannelsApi,
  agentId: string,
  orgId: string,
  apiKey: string
): Promise<void> {
  const { action } = await safePrompt([
    {
      type: 'list',
      name: 'action',
      message: 'Phone numbers — what would you like to do?',
      choices: [
        { name: 'Search available numbers', value: 'search' },
        { name: 'Purchase a number', value: 'purchase' },
        { name: 'Bind a number to this agent', value: 'bind' },
        { name: 'Unbind a number from this agent', value: 'unbind' },
        { name: 'List my numbers', value: 'list' },
        { name: 'Release a number', value: 'release' },
      ],
    },
  ]);

  switch (action as Action) {
    case 'search':
      await doSearch(api);
      break;
    case 'purchase':
      await doPurchase(api, agentId, orgId, apiKey);
      break;
    case 'bind':
      await doBind(api, agentId, apiKey);
      break;
    case 'unbind':
      await doUnbind(api, agentId);
      break;
    case 'list':
      await doList(api, orgId);
      break;
    case 'release':
      await doRelease(api, orgId);
      break;
  }
  trackEvent('cli_channels_phone_completed', { action });
}

/**
 * Pretty-print a stored msisdn (no leading "+") as `+<digits>` — what
 * humans expect to see and what their phone keypad needs.
 */
function formatTel(msisdn: string): string {
  return msisdn.startsWith('+') ? msisdn : `+${msisdn}`;
}

/**
 * Post-bind / post-purchase-and-bind call-to-action. Same shape both
 * places so the dev experience reads identically.
 */
function announceReachable(agentId: string, msisdn: string, voiceName: string): void {
  writeSuccess(`📞 Your agent (${agentId}) is now reachable at ${formatTel(msisdn)} via voice "${voiceName}"`);
}

/**
 * Fetch the agent's authored LuaVoices and require the dev to choose
 * one. A code-defined LuaVoice is the contract for the compiled-voice
 * path — without one the inbound call would silently fall through to
 * platform-default STT/LLM/TTS plus no hooks / no voice-only tools /
 * no greeting. Easier to reject the bind here with a clear next step
 * than to ship a quiet downgrade.
 */
async function pickVoiceForBind(apiKey: string, agentId: string): Promise<{ voiceId: string; voiceName: string }> {
  const voiceApi = new VoiceApi(BASE_URLS.API, apiKey, agentId);
  const resp = await voiceApi.getVoices();
  const voices = resp.success ? (resp.data?.voices ?? []) : [];
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const active = voices.filter((v: any) => v.active !== false);
  if (active.length === 0) {
    throw new Error(
      'This agent has no LuaVoice. Author one in code, push it via `lua push`, then re-run `lua channels` → Manage phone numbers.'
    );
  }

  const { picked } = await safePrompt([
    {
      type: 'list',
      name: 'picked',
      pageSize: 15,
      message: 'Which voice should answer inbound calls on this number?',
      choices: active.map((v: { id: string; name: string }) => ({
        name: `${v.name} (id: ${v.id})`,
        value: v.id,
      })),
    },
  ]);
  const match = active.find((v: { id: string }) => v.id === picked);
  if (!match) throw new Error('No voice selected');
  return { voiceId: match.id, voiceName: match.name };
}

async function promptCountry(): Promise<string> {
  const { country } = await safePrompt([
    { type: 'input', name: 'country', message: 'Country (ISO code, e.g. US, GB, NG):', default: 'US' },
  ]);
  return country.toUpperCase();
}

/**
 * Area code or substring filter, passed to the upstream search as
 * `contains` (Vonage's match-substring parameter — empty means no
 * filter). The phrasing avoids "area code" because not every country
 * uses the same concept; "digits" works for both NANP area codes
 * (415, 212) and arbitrary patterns (8888 for vanity tail numbers).
 */
async function promptAreaCode(): Promise<string | undefined> {
  const { pattern } = await safePrompt([
    {
      type: 'input',
      name: 'pattern',
      message: 'Digits to match (area code or substring, optional):',
      default: '',
    },
  ]);
  const trimmed = (pattern as string).trim();
  return trimmed.length > 0 ? trimmed : undefined;
}

/**
 * Human label for "does this number do SMS too?". Derived from the
 * underlying carrier — Vonage delivers SMS for its inventory, LiveKit
 * doesn't. Devs never see the carrier name; they see the capability.
 */
function smsLabel(transportOrUndefined: string | undefined): string {
  return transportOrUndefined === 'vonage' ? 'voice + SMS' : 'voice only';
}

/**
 * Pick the underlying carrier from the dev's product question instead of
 * making them learn provider names. Today the mapping is:
 *
 *   "Allow SMS?" yes → Vonage (voice + SMS on the same msisdn)
 *   "Allow SMS?" no  → LiveKit (voice-only, lower-latency inbound, no SMS)
 *
 * Hidden from the CLI: `byo-sip`. BYO trunk numbers are provisioned
 * outside this flow (admin-side trunk setup); a dev who knows they want
 * BYO can bind via the admin API directly.
 */
async function promptSmsCapable(): Promise<'livekit' | 'vonage'> {
  const { sms } = await safePrompt([
    {
      type: 'confirm',
      name: 'sms',
      message: 'Allow customers to text this number too? (otherwise voice-only)',
      default: false,
    },
  ]);
  return sms ? 'vonage' : 'livekit';
}

async function doSearch(api: ChannelsApi): Promise<void> {
  const country = await promptCountry();
  const transport = await promptSmsCapable();
  const contains = await promptAreaCode();
  writeProgress(`🔍 Searching available numbers in ${country}...`);
  const resp = await api.searchAvailable({ country, transport, contains, limit: 50 });
  if (!resp.success) throw new Error(resp.error?.message ?? 'Search failed');
  const numbers = resp.data?.numbers ?? [];
  if (numbers.length === 0) {
    writeInfo('No matching numbers found.');
    return;
  }
  writeSuccess(`Found ${numbers.length} number(s):`);
  for (const n of numbers) {
    console.log(
      `  ${n.msisdn}  ${n.country ?? ''}  ${n.type ?? ''}  ${smsLabel(n.transport)}  ${n.monthlyCost ?? ''} ${n.currency ?? ''}`
    );
  }
}

async function doPurchase(api: ChannelsApi, agentId: string, orgId: string, apiKey: string): Promise<void> {
  const country = await promptCountry();
  const transport = await promptSmsCapable();
  const contains = await promptAreaCode();
  const resp = await api.searchAvailable({ country, transport, contains, limit: 50 });
  if (!resp.success) throw new Error(resp.error?.message ?? 'Search failed');
  const numbers = resp.data?.numbers ?? [];
  if (numbers.length === 0) throw new Error('No matching numbers found — adjust your filters and try again.');

  const { chosen } = await safePrompt([
    {
      type: 'list',
      name: 'chosen',
      // pageSize scrolls the list when the result set is bigger than the
      // visible area; without it inquirer truncates at the terminal
      // height and silently hides later entries.
      pageSize: 15,
      message: `Pick a number (${numbers.length} available):`,
      choices: numbers.map((n) => ({
        name: `${n.msisdn} (${n.country}, ${n.type ?? '—'}) — ${smsLabel(n.transport)}`,
        value: n.msisdn,
      })),
    },
  ]);
  const { ok } = await safePrompt([
    {
      type: 'confirm',
      name: 'ok',
      message: `Purchase ${chosen} (${smsLabel(transport)})? (charges may apply)`,
      default: false,
    },
  ]);
  if (!ok) {
    writeInfo('Cancelled.');
    return;
  }

  writeProgress(`💳 Purchasing ${chosen}...`);
  const purchase = await api.purchase(orgId, { msisdn: chosen, country, transport });
  if (!purchase.success) throw new Error(purchase.error?.message ?? 'Purchase failed');
  writeSuccess(`Purchased ${chosen}`);

  // Suggestive next step — the number does nothing until it's bound, so
  // offer the bind right here instead of making the dev re-enter the
  // "Bind a number" branch and retype the msisdn.
  const { bindNow } = await safePrompt([
    {
      type: 'confirm',
      name: 'bindNow',
      message: `Bind ${chosen} to agent ${agentId} now?`,
      default: true,
    },
  ]);
  if (!bindNow) {
    writeInfo(`💡 Run \`lua channels\` → "Manage phone numbers" → Bind later to attach ${chosen} to an agent.`);
    return;
  }
  const voicePick = await pickVoiceForBind(apiKey, agentId);
  writeProgress(`🔗 Binding ${chosen} to agent ${agentId}...`);
  // No transport on the bind body — the server reads it from the
  // already-purchased phoneNumbers record. Re-asking would let a dev
  // accidentally bind a Vonage-purchased number under transport: 'livekit'.
  const bindResp = await api.bind(agentId, { msisdn: chosen, voiceId: voicePick.voiceId });
  if (!bindResp.success) throw new Error(bindResp.error?.message ?? 'Bind failed');
  announceReachable(agentId, chosen, voicePick.voiceName);
}

async function doBind(api: ChannelsApi, agentId: string, apiKey: string): Promise<void> {
  // Manual msisdn entry — a list-picker pulling from the org's owned
  // numbers is a nice follow-up, but requires plumbing orgId through
  // this fn. The dev usually just bought the number two seconds ago
  // (the purchase branch chains into bind automatically), so manual
  // entry is fine here.
  const { msisdn } = await safePrompt([{ type: 'input', name: 'msisdn', message: 'Msisdn to bind to this agent:' }]);
  const voicePick = await pickVoiceForBind(apiKey, agentId);
  writeProgress(`🔗 Binding ${msisdn} to agent ${agentId}...`);
  // Transport derived server-side from the phoneNumbers record.
  const resp = await api.bind(agentId, { msisdn, voiceId: voicePick.voiceId });
  if (!resp.success) throw new Error(resp.error?.message ?? 'Bind failed');
  announceReachable(agentId, msisdn, voicePick.voiceName);
}

async function doUnbind(api: ChannelsApi, agentId: string): Promise<void> {
  const { msisdn } = await safePrompt([{ type: 'input', name: 'msisdn', message: 'Msisdn to unbind:' }]);
  const { ok } = await safePrompt([
    { type: 'confirm', name: 'ok', message: `Unbind ${msisdn} from agent ${agentId}?`, default: false },
  ]);
  if (!ok) {
    writeInfo('Cancelled.');
    return;
  }
  const resp = await api.unbind(agentId, msisdn);
  if (!resp.success) throw new Error(resp.error?.message ?? 'Unbind failed');
  writeSuccess(`Unbound ${msisdn}`);
}

async function doList(api: ChannelsApi, orgId: string): Promise<void> {
  const resp = await api.list(orgId, {});
  if (!resp.success) throw new Error(resp.error?.message ?? 'List failed');
  const numbers = resp.data?.numbers ?? [];
  if (numbers.length === 0) {
    writeInfo('No phone numbers provisioned for this org.');
    return;
  }
  writeSuccess(`${numbers.length} number(s):`);
  console.log(
    renderTable(
      ['MSISDN', 'Country', 'Status', 'Modality', 'Agent', 'Voice'],
      numbers.map((n) => [
        n.msisdn,
        n.country ?? '—',
        n.status,
        smsLabel(n.transport),
        n.agentId ?? '—',
        n.voiceId ?? '—',
      ])
    )
  );
}

async function doRelease(api: ChannelsApi, orgId: string): Promise<void> {
  const { msisdn } = await safePrompt([{ type: 'input', name: 'msisdn', message: 'Msisdn to release:' }]);
  const { ok } = await safePrompt([
    {
      type: 'confirm',
      name: 'ok',
      message: `Release ${msisdn}? This is irreversible — the org loses ownership.`,
      default: false,
    },
  ]);
  if (!ok) {
    writeInfo('Cancelled.');
    return;
  }
  const resp = await api.release(orgId, msisdn);
  if (!resp.success) throw new Error(resp.error?.message ?? 'Release failed');
  writeSuccess(`Released ${msisdn}`);
}
