/**
 * Environment Variables Command
 * Manages environment variables for sandbox and production environments
 */

import fs from 'fs';
import path from 'path';
import inquirer from 'inquirer';
import { withErrorHandling, writeProgress, writeSuccess, writeInfo, writeNextStep } from '../utils/cli.js';
import { BASE_URLS } from '../config/constants.js';
import { initializeCommand } from '../utils/command-utils.js';
import DeveloperApi from '../api/developer.api.service.js';
import { loadEnvironmentVariables } from '../utils/env-loader.utils.js';
import { trackEvent } from '../services/analytics.js';
import { validateOrSuggest } from '../utils/aliases.js';

export interface EnvVariable {
  key: string;
  value: string;
}

export interface EnvCommandContext {
  environment: 'sandbox' | 'production';
  agentId: string;
  apiKey: string;
  developerApi?: DeveloperApi;
}

type EnvMode =
  | { type: 'list' }
  | { type: 'delete' }
  | { type: 'set' }
  | { type: 'interactive' }
  | { type: 'error'; message: string; examples?: string[] };

interface EnvOptions {
  key: string | null;
  value: string | null;
  deleteFlag: boolean;
  listFlag: boolean;
}

type EnvResolution =
  | { type: 'resolved'; environment: 'sandbox' | 'production' }
  | { type: 'prompt' }
  | { type: 'error'; message: string; usage?: string[] };

/**
 * Resolves which environment to use based on provided argument and flags
 *
 * Valid resolutions:
 * - resolved:  env argument provided and valid (sandbox/staging/production)
 * - prompt:    no env argument, no non-interactive flags → show interactive prompt
 *
 * Invalid combinations:
 * - Invalid env value
 * - Non-interactive flags without env specified
 */
function resolveEnvironment(env: string | undefined, hasNonInteractiveFlags: boolean): EnvResolution {
  // Environment argument provided
  if (env) {
    const normalized = validateOrSuggest('env.environment', env);
    if (normalized === 'staging') {
      return { type: 'resolved', environment: 'sandbox' };
    }
    return { type: 'resolved', environment: normalized as 'sandbox' | 'production' };
  }

  // No env argument but has non-interactive flags → must specify environment
  if (hasNonInteractiveFlags) {
    return {
      type: 'error',
      message: 'Environment must be specified when using non-interactive options.',
      usage: [
        'lua env sandbox --list                    List sandbox variables',
        'lua env production -k KEY -v VALUE        Set variable',
        'lua env production -k KEY --delete        Delete variable',
      ],
    };
  }

  // No env, no flags → interactive prompt
  return { type: 'prompt' };
}

/**
 * Determines which operation mode to use based on provided options
 *
 * Valid modes:
 * - list:        --list flag provided
 * - delete:      -k KEY --delete
 * - set:         -k KEY -v VALUE
 * - interactive: no flags (opens interactive menu)
 *
 * Invalid combinations result in error mode with helpful message
 */
function determineEnvMode(options: EnvOptions): EnvMode {
  const { key, value, deleteFlag, listFlag } = options;
  const hasKey = !!key;
  const hasValue = value !== null;

  // --list: list all variables
  if (listFlag) {
    return { type: 'list' };
  }

  // -k KEY --delete: delete a variable
  if (hasKey && deleteFlag) {
    return { type: 'delete' };
  }

  // -k KEY -v VALUE: set/update a variable
  if (hasKey && hasValue) {
    return { type: 'set' };
  }

  // Error: -k KEY without -v or --delete
  if (hasKey && !hasValue && !deleteFlag) {
    return {
      type: 'error',
      message: 'Invalid usage: -k requires either -v VALUE to set or --delete to remove',
      examples: [
        'lua env production -k MY_VAR -v "value"     # Set variable',
        'lua env production -k MY_VAR --delete       # Delete variable',
      ],
    };
  }

  // Error: --delete without -k KEY
  if (deleteFlag && !hasKey) {
    return {
      type: 'error',
      message: 'Delete operation requires -k KEY with --delete flag',
    };
  }

  // Error: -v VALUE without -k KEY
  if (hasValue && !hasKey) {
    return {
      type: 'error',
      message: 'Invalid usage: -v requires -k KEY to specify which variable to set',
      examples: ['lua env production -k MY_VAR -v "value"     # Set variable'],
    };
  }

  // No flags: interactive mode
  return { type: 'interactive' };
}

/**
 * Main env command - manages environment variables
 *
 * Features:
 * - Environment selection (sandbox/staging or production)
 * - List all environment variables
 * - Add new variables
 * - Update existing variables
 * - Delete variables
 * - Sandbox: manages .env file
 * - Production: uses API endpoints
 * - Non-interactive mode: direct operations with --key, --value, --delete, --list
 *
 * @param env - Optional environment argument ('sandbox', 'staging', or 'production')
 * @param cmdObj - Commander command object with options
 * @returns Promise that resolves when command completes
 */
export async function envCommand(env?: string, cmdObj?: any): Promise<void> {
  return withErrorHandling(async () => {
    // Extract options
    const key = cmdObj?.key || null;
    const value = cmdObj?.value ?? null;
    const deleteFlag = cmdObj?.delete || false;
    const listFlag = cmdObj?.list || false;

    // Initialize command (validates config + auth)
    const { agentId, apiKey } = await initializeCommand();

    let selectedEnvironment: 'sandbox' | 'production';

    // Resolve environment
    const hasNonInteractiveFlags = listFlag || !!key || value !== null || deleteFlag;
    const envResolution = resolveEnvironment(env, hasNonInteractiveFlags);

    switch (envResolution.type) {
      case 'resolved':
        selectedEnvironment = envResolution.environment;
        break;

      case 'prompt':
        const { environment } = await inquirer.prompt([
          {
            type: 'list',
            name: 'environment',
            message: 'Select environment:',
            choices: [
              { name: '🔧 Sandbox (.env file)', value: 'sandbox' },
              { name: '🚀 Production (API)', value: 'production' },
            ],
          },
        ]);
        selectedEnvironment = environment as 'sandbox' | 'production';
        break;

      case 'error':
        console.log(`❌ ${envResolution.message}`);
        if (envResolution.usage) {
          console.log('\nUsage:');
          envResolution.usage.forEach((line) => console.log(`  ${line}`));
        }
        throw new Error('Operation failed');
    }

    let context: EnvCommandContext = {
      environment: selectedEnvironment,
      agentId,
      apiKey,
    };

    // Set up API for production
    if (selectedEnvironment === 'production') {
      context.developerApi = new DeveloperApi(BASE_URLS.API, apiKey, agentId);
    }

    // Determine operation mode and execute
    const mode = determineEnvMode({ key, value, deleteFlag, listFlag });

    switch (mode.type) {
      case 'list':
        await listVariables(context);
        break;
      case 'delete':
        await removeVariable(context, key);
        break;
      case 'set':
        await setVariable(context, key, value);
        break;
      case 'interactive':
        await manageEnvironmentVariables(context);
        break;
      case 'error':
        console.log(`❌ ${mode.message}`);
        if (mode.examples) {
          console.log('\nExamples:');
          mode.examples.forEach((ex) => console.log(`  ${ex}`));
        }
        throw new Error('Operation failed');
    }
    trackEvent('cli_env_action', {
      environment: env || 'interactive',
      mode: mode.type,
      non_interactive: hasNonInteractiveFlags,
    });
  }, 'env');
}

// ============================================================================
// Core Operations (shared by interactive and non-interactive modes)
// ============================================================================

/**
 * Masks a value for display (shows first 4 chars, rest as asterisks)
 */
function maskValue(value: string): string {
  return value.length > 4
    ? value.substring(0, 4) + '*'.repeat(Math.min(value.length - 4, 20))
    : '*'.repeat(value.length);
}

/**
 * Validates a variable key format
 * @returns Error message if invalid, null if valid
 */
function validateKeyFormat(key: string): string | null {
  if (!key.trim()) {
    return 'Variable name cannot be empty';
  }
  if (!/^[A-Z_][A-Z0-9_]*$/i.test(key.trim())) {
    return 'Variable name must start with a letter or underscore and contain only letters, numbers, and underscores';
  }
  return null;
}

/**
 * Displays environment variables with masked values
 */
function displayVariables(variables: EnvVariable[], context: EnvCommandContext, numbered: boolean = false): void {
  console.log(`\n🌙 Environment Variables (${context.environment === 'sandbox' ? 'Sandbox' : 'Production'})\n`);

  if (variables.length === 0) {
    console.log('ℹ️  No environment variables configured.\n');
  } else {
    variables.forEach((v, index) => {
      const prefix = numbered ? `${index + 1}. ` : '';
      console.log(`${prefix}${v.key} = ${maskValue(v.value)}`);
    });
    console.log();
  }
}

/**
 * Core: Save or update a variable (no prompts)
 * @returns true on success, throws on error
 */
async function saveVariableCore(context: EnvCommandContext, key: string, value: string): Promise<{ created: boolean }> {
  const variables = await loadEnvironmentVariables(context);
  const trimmedKey = key.trim();
  const existingIndex = variables.findIndex((v) => v.key === trimmedKey);
  const created = existingIndex < 0;

  if (created) {
    variables.push({ key: trimmedKey, value });
  } else {
    variables[existingIndex].value = value;
  }

  let success = false;
  if (context.environment === 'sandbox') {
    success = saveSandboxEnvVariables(variables);
  } else {
    success = await saveProductionEnvVariables(context, variables);
  }

  if (!success) {
    throw new Error(`Failed to save variable "${trimmedKey}"`);
  }

  return { created };
}

/**
 * Core: Delete a variable by key (no prompts)
 * @returns true on success, throws on error
 */
async function deleteVariableCore(context: EnvCommandContext, key: string): Promise<void> {
  const variables = await loadEnvironmentVariables(context);
  const trimmedKey = key.trim();
  const indexToDelete = variables.findIndex((v) => v.key === trimmedKey);

  if (indexToDelete < 0) {
    throw new Error(`Variable "${trimmedKey}" not found`);
  }

  if (context.environment === 'sandbox') {
    variables.splice(indexToDelete, 1);
    const success = saveSandboxEnvVariables(variables);
    if (!success) {
      throw new Error(`Failed to delete variable "${trimmedKey}"`);
    }
  } else {
    if (!context.developerApi) {
      throw new Error('Developer API not initialized');
    }
    const response = await context.developerApi.deleteEnvironmentVariable(trimmedKey);
    if (!response.success) {
      throw new Error(response.error?.message || 'Failed to delete environment variable');
    }
  }
}

// ============================================================================
// Non-Interactive Mode Functions
// ============================================================================

/**
 * List all environment variables (non-interactive mode)
 */
async function listVariables(context: EnvCommandContext): Promise<void> {
  const variables = await loadEnvironmentVariables(context);
  displayVariables(variables, context);
}

/**
 * Set an environment variable (non-interactive mode)
 */
async function setVariable(context: EnvCommandContext, key: string, value: string): Promise<void> {
  const validationError = validateKeyFormat(key);
  if (validationError) {
    console.log(`❌ ${validationError}`);
    throw new Error(`${validationError}`);
  }

  try {
    const { created } = await saveVariableCore(context, key, value);
    writeInfo(`${created ? 'Created' : 'Updated'} ${key.trim()}`);
    writeSuccess(`✅ Successfully set ${key.trim()}`);
    if (context.environment === 'production') {
      writeNextStep({
        command: 'lua chat -e production -m "test"',
        rationale: 'to verify your agent uses the updated env vars',
        when: 'success',
      });
    }
  } catch (error) {
    console.log(`❌ Error setting variable: ${error instanceof Error ? error.message : 'Unknown error'}`);
    throw new Error(`Error setting variable: ${error instanceof Error ? error.message : 'Unknown error'}`);
  }
}

/**
 * Remove an environment variable (non-interactive mode)
 */
async function removeVariable(context: EnvCommandContext, key: string): Promise<void> {
  try {
    await deleteVariableCore(context, key);
    writeSuccess(`✅ Successfully deleted ${key.trim()}`);
    if (context.environment === 'production') {
      writeNextStep({
        command: 'lua chat -e production -m "test"',
        rationale: 'to verify your agent uses the updated env vars',
        when: 'success',
      });
    }
  } catch (error) {
    console.log(`❌ ${error instanceof Error ? error.message : 'Unknown error'}`);
    throw new Error(`${error instanceof Error ? error.message : 'Unknown error'}`);
  }
}

/**
 * Main management loop for environment variables
 */
async function manageEnvironmentVariables(context: EnvCommandContext): Promise<void> {
  let continueManaging = true;

  while (continueManaging) {
    // Load and display current variables
    const variables = await loadEnvironmentVariables(context);
    console.log('\n' + '='.repeat(60));
    displayVariables(variables, context, true);

    // Show menu
    const { action } = await inquirer.prompt([
      {
        type: 'list',
        name: 'action',
        message: 'What would you like to do?',
        choices: [
          { name: '➕ Add new variable', value: 'add' },
          { name: '✏️  Update existing variable', value: 'update' },
          { name: '🗑️  Delete variable', value: 'delete' },
          { name: '👁️  View variable value', value: 'view' },
          { name: '🔄 Refresh list', value: 'refresh' },
          { name: '❌ Exit', value: 'exit' },
        ],
      },
    ]);

    switch (action) {
      case 'add':
        await addVariable(context, variables);
        break;
      case 'update':
        await updateVariable(context, variables);
        break;
      case 'delete':
        await deleteVariable(context, variables);
        break;
      case 'view':
        await viewVariable(variables);
        break;
      case 'refresh':
        // Just loop again
        break;
      case 'exit':
        continueManaging = false;
        console.log('\n👋 Goodbye!\n');
        break;
    }
  }
}

/**
 * Convert variables array to .env file content
 */
function variablesToEnvContent(variables: EnvVariable[]): string {
  return variables.map((v) => `${v.key}=${v.value}`).join('\n');
}

/**
 * Save sandbox environment variables to .env file
 */
function saveSandboxEnvVariables(variables: EnvVariable[]): boolean {
  const envFilePath = path.join(process.cwd(), '.env');

  try {
    const content = variablesToEnvContent(variables);
    fs.writeFileSync(envFilePath, content, 'utf8');
    return true;
  } catch (error) {
    console.error('❌ Error saving .env file:', error);
    return false;
  }
}

/**
 * Save production environment variables via API
 */
async function saveProductionEnvVariables(context: EnvCommandContext, variables: EnvVariable[]): Promise<boolean> {
  try {
    if (!context.developerApi) {
      throw new Error('Developer API not initialized');
    }

    const envData: Record<string, string> = {};
    variables.forEach((v) => {
      if (v.key.trim()) {
        envData[v.key.trim()] = v.value;
      }
    });

    const response = await context.developerApi.updateEnvironmentVariables(envData);

    if (!response.success) {
      throw new Error(response.error?.message || 'Failed to save environment variables');
    }

    return true;
  } catch (error) {
    console.error('❌ Error saving production env variables:', error);
    return false;
  }
}

/**
 * Add a new environment variable (interactive)
 */
async function addVariable(context: EnvCommandContext, currentVariables: EnvVariable[]): Promise<void> {
  const answers = await inquirer.prompt([
    {
      type: 'input',
      name: 'key',
      message: 'Variable name:',
      validate: (input) => {
        const error = validateKeyFormat(input);
        if (error) return error;
        if (currentVariables.some((v) => v.key === input.trim())) {
          return 'Variable already exists. Use update to modify it.';
        }
        return true;
      },
    },
    {
      type: 'input',
      name: 'value',
      message: 'Variable value:',
    },
  ]);

  writeProgress('🔄 Saving...');

  try {
    await saveVariableCore(context, answers.key, answers.value);
    writeSuccess(`✅ Variable "${answers.key.trim()}" added successfully`);
    if (context.environment === 'production') {
      writeNextStep({
        command: 'lua chat -e production -m "test"',
        rationale: 'to verify your agent uses the updated env vars',
        when: 'success',
      });
    }
  } catch (error) {
    console.log(`❌ Failed to save variable: ${error instanceof Error ? error.message : 'Unknown error'}`);
  }
}

/**
 * Update an existing environment variable (interactive)
 */
async function updateVariable(context: EnvCommandContext, currentVariables: EnvVariable[]): Promise<void> {
  if (currentVariables.length === 0) {
    console.log('\nℹ️  No variables to update.\n');
    return;
  }

  const { selectedKey } = await inquirer.prompt([
    {
      type: 'list',
      name: 'selectedKey',
      message: 'Select variable to update:',
      choices: currentVariables.map((v) => ({
        name: v.key,
        value: v.key,
      })),
    },
  ]);

  const currentVariable = currentVariables.find((v) => v.key === selectedKey)!;

  const { newValue } = await inquirer.prompt([
    {
      type: 'input',
      name: 'newValue',
      message: `New value for ${selectedKey}:`,
      default: currentVariable.value,
    },
  ]);

  writeProgress('🔄 Saving...');

  try {
    await saveVariableCore(context, selectedKey, newValue);
    writeSuccess(`✅ Variable "${selectedKey}" updated successfully`);
    if (context.environment === 'production') {
      writeNextStep({
        command: 'lua chat -e production -m "test"',
        rationale: 'to verify your agent uses the updated env vars',
        when: 'success',
      });
    }
  } catch (error) {
    console.log(`❌ Failed to update variable: ${error instanceof Error ? error.message : 'Unknown error'}`);
  }
}

/**
 * Delete an environment variable (interactive)
 */
async function deleteVariable(context: EnvCommandContext, currentVariables: EnvVariable[]): Promise<void> {
  if (currentVariables.length === 0) {
    console.log('\nℹ️  No variables to delete.\n');
    return;
  }

  const { selectedKey } = await inquirer.prompt([
    {
      type: 'list',
      name: 'selectedKey',
      message: 'Select variable to delete:',
      choices: currentVariables.map((v) => ({
        name: v.key,
        value: v.key,
      })),
    },
  ]);

  const { confirm } = await inquirer.prompt([
    {
      type: 'confirm',
      name: 'confirm',
      message: `Are you sure you want to delete "${selectedKey}"?`,
      default: false,
    },
  ]);

  if (!confirm) {
    console.log('\nℹ️  Deletion cancelled.\n');
    return;
  }

  writeProgress('🔄 Deleting...');

  try {
    await deleteVariableCore(context, selectedKey);
    writeSuccess(`✅ Variable "${selectedKey}" deleted successfully`);
    if (context.environment === 'production') {
      writeNextStep({
        command: 'lua chat -e production -m "test"',
        rationale: 'to verify your agent uses the updated env vars',
        when: 'success',
      });
    }
  } catch (error) {
    console.log(`❌ ${error instanceof Error ? error.message : 'Failed to delete variable'}`);
  }
}

/**
 * View a variable's full value (unmasked)
 */
async function viewVariable(currentVariables: EnvVariable[]): Promise<void> {
  if (currentVariables.length === 0) {
    console.log('\nℹ️  No variables to view.\n');
    return;
  }

  const { selectedKey } = await inquirer.prompt([
    {
      type: 'list',
      name: 'selectedKey',
      message: 'Select variable to view:',
      choices: currentVariables.map((v) => ({
        name: v.key,
        value: v.key,
      })),
    },
  ]);

  const variable = currentVariables.find((v) => v.key === selectedKey)!;

  console.log('\n' + '='.repeat(60));
  console.log(`Variable: ${variable.key}`);
  console.log('='.repeat(60));
  console.log(variable.value);
  console.log('='.repeat(60) + '\n');

  await inquirer.prompt([
    {
      type: 'input',
      name: 'continue',
      message: 'Press Enter to continue...',
    },
  ]);
}
