/**
 * Webhook Handler
 *
 * Handles CLI operations for webhook primitives.
 *
 * Webhooks:
 * - Use 'active' field on entity
 * - Use 'active' field on versions
 */

import { PrimitiveKind, ManifestPrimitive, ManifestWebhook } from '../compiler/types.js';
import { BASE_URLS } from '../config/constants.js';
import WebhookApi from '../api/webhook.api.service.js';
import type { PushWebhookVersionDTO } from '../interfaces/webhooks.js';
import { BaseVersionedHandler } from './base.handler.js';
import type { YamlPrimitiveConfig } from './types.js';
import type { YamlConfigWebhook } from '../types/yaml.types.js';

/**
 * Webhook primitive handler
 */
export class WebhookHandler extends BaseVersionedHandler<YamlConfigWebhook, PushWebhookVersionDTO> {
  readonly kind = PrimitiveKind.WEBHOOK;
  readonly displayName = 'webhook';
  readonly displayNamePlural = 'webhooks';
  readonly deleteCommand = 'lua webhooks delete';
  readonly yamlConfig: YamlPrimitiveConfig = {
    yamlKey: 'webhooks',
    idField: 'webhookId',
  };

  protected getApi(apiKey: string, agentId: string): WebhookApi {
    return new WebhookApi(BASE_URLS.API, apiKey, agentId);
  }

  protected async fetchFromServer(api: WebhookApi): Promise<any[] | null> {
    const response = await api.getWebhooks();
    if (!response.success || !response.data?.webhooks) {
      return null;
    }
    return response.data.webhooks;
  }

  protected async createOnServer(api: WebhookApi, primitive: ManifestPrimitive): Promise<string | null> {
    const response = await api.createWebhook({
      name: primitive.name,
      description: primitive.description || `A Lua webhook for ${primitive.name}`,
    });
    if (!response.success || !response.data?.id) return null;
    return response.data.id;
  }

  /**
   * Webhooks use 'active' field directly on the entity.
   */
  isActive(serverItem: any): boolean {
    return serverItem.active !== false;
  }

  getActiveVersion(serverItem: any): string | null {
    if (serverItem.activeVersionId) {
      return serverItem.versions?.find((v: any) => v.id === serverItem.activeVersionId)?.version ?? null;
    }
    return serverItem.versions?.find((v: any) => v.active === true)?.version ?? null;
  }

  async pushToServer(apiKey: string, agentId: string, entityId: string, pushData: PushWebhookVersionDTO) {
    const api = this.getApi(apiKey, agentId);
    const response = await api.pushWebhook(entityId, { ...pushData, webhookId: entityId });
    return { success: response.success, error: response.error?.message };
  }

  async publishVersion(apiKey: string, agentId: string, entityId: string, version: string) {
    const api = this.getApi(apiKey, agentId);
    const response = await api.publishWebhookVersion(entityId, version);
    return { success: response.success, error: response.error?.message };
  }

  /**
   * Override to include webhook schemas in push data.
   */
  protected buildPushData(
    primitive: ManifestPrimitive,
    compressedCode: string | undefined,
    codeS3Hash?: string
  ): Record<string, unknown> {
    const webhook = primitive as ManifestWebhook;
    return {
      name: webhook.name,
      description: webhook.description,
      ...(codeS3Hash ? { codeS3Hash } : { code: compressedCode }),
      querySchema: webhook.schemas?.query || undefined,
      headerSchema: webhook.schemas?.headers || undefined,
      bodySchema: webhook.schemas?.body || undefined,
    };
  }
}

// Export singleton instance
export const webhookHandler = new WebhookHandler();
