/**
 * Class-hierarchy walking for primitive detection.
 *
 * Plugins detect primitives written as class definitions
 * (`class MyTool extends LuaTool`). The cleanest authoring shape is to
 * factor shared logic into an intermediate base — `class MyTool extends
 * SharedTool` where `SharedTool extends LuaTool` — and to override
 * config via field initializers on the leaf class. That requires the
 * compiler to walk the inheritance chain rather than match the literal
 * `extends` text.
 *
 * This module is the single source of truth for that walk. Every plugin
 * routes through these three helpers; drift between sites was the
 * original bug surface that motivated extracting them.
 */

import { ClassDeclaration, Node, PropertyDeclaration, MethodDeclaration } from 'ts-morph';

const DEFAULT_MAX_DEPTH = 10;

/**
 * Walk the `extends` chain most-derived → ancestor, bounded.
 * Always includes the input class at index 0.
 *
 * Stops on:
 *   - depth cap (runaway / pathological types)
 *   - cycle (A extends B, B extends A)
 *   - unresolvable base (e.g. base lives in a `.d.ts` that ts-morph
 *     can't follow, or the base is a generic type parameter)
 */
export function getClassHierarchy(classDecl: ClassDeclaration, maxDepth = DEFAULT_MAX_DEPTH): ClassDeclaration[] {
  const chain: ClassDeclaration[] = [classDecl];
  const visited = new Set<string>([classKey(classDecl)]);
  let current: ClassDeclaration | undefined = classDecl;

  for (let depth = 0; depth < maxDepth; depth++) {
    const parent = safeGetBaseClass(current);
    if (!parent) break;
    const key = classKey(parent);
    if (visited.has(key)) break;
    visited.add(key);
    chain.push(parent);
    current = parent;
  }

  return chain;
}

/**
 * True if any class in the hierarchy `extends` or `implements` one of
 * the given base names.
 *
 * Matches against the EXPRESSION TEXT (`extendsClause.getExpression().getText()`)
 * rather than relying solely on ts-morph's resolved `getBaseClass()`,
 * because the ultimate base is often declared in a `.d.ts` (e.g.
 * `LuaTool` lives in `lua-cli`'s `api-exports.d.ts`). The text check
 * catches that direct shape even when the resolved walk stops short.
 */
export function extendsAny(classDecl: ClassDeclaration, baseNames: readonly string[]): boolean {
  const targets = new Set(baseNames);

  // Direct extends/implements on the leaf class — caught by the chain
  // walk below as well, but checking explicitly here also covers the
  // `getBaseClass() === undefined` case where the parent is ambient.
  if (matchesHeritage(classDecl, targets)) return true;

  const chain = getClassHierarchy(classDecl);
  for (let i = 1; i < chain.length; i++) {
    if (matchesHeritage(chain[i], targets)) return true;
  }

  return false;
}

/**
 * Find a property or method by name across the inheritance chain,
 * most-derived first. Returns the declaring class plus the node, so
 * callers can both read the value AND know which class owns it
 * (useful for diagnostics and source-mapping).
 *
 * "Most-derived wins" — exactly how JS resolves field initializers
 * and methods at runtime. The leaf class overriding `ragSearchPath = "/x"`
 * is returned over a parent that declares `ragSearchPath: string`.
 */
export function findClassMember(
  classDecl: ClassDeclaration,
  memberName: string,
  kind: 'property' | 'method' | 'either' = 'either'
): { owner: ClassDeclaration; node: PropertyDeclaration | MethodDeclaration } | undefined {
  const chain = getClassHierarchy(classDecl);

  for (const cls of chain) {
    if (kind === 'property' || kind === 'either') {
      const prop = cls.getProperty(memberName);
      if (prop && Node.isPropertyDeclaration(prop)) {
        return { owner: cls, node: prop };
      }
    }
    if (kind === 'method' || kind === 'either') {
      const method = cls.getMethod(memberName);
      if (method) {
        return { owner: cls, node: method };
      }
    }
  }

  return undefined;
}

function matchesHeritage(classDecl: ClassDeclaration, targets: Set<string>): boolean {
  const ext = classDecl.getExtends();
  if (ext && targets.has(ext.getExpression().getText())) return true;

  for (const impl of classDecl.getImplements()) {
    if (targets.has(impl.getExpression().getText())) return true;
  }

  return false;
}

function safeGetBaseClass(classDecl: ClassDeclaration | undefined): ClassDeclaration | undefined {
  if (!classDecl) return undefined;
  try {
    return classDecl.getBaseClass();
  } catch {
    // ts-morph occasionally throws on malformed heritage expressions or
    // when the type checker can't resolve a generic base. Treat as "no
    // resolvable parent" rather than aborting the whole walk.
    return undefined;
  }
}

function classKey(c: ClassDeclaration): string {
  return `${c.getSourceFile().getFilePath()}#${c.getName() ?? '<anonymous>'}#${c.getStartLineNumber()}`;
}
