/**
 * Walk a project directory and produce a fresh BackupManifest from disk —
 * captures every source file currently on disk, not just what the most recent
 * compile knew about. Used by `runBackupPush({ fresh: true })`.
 */

import { walkWorkspace } from '@lua/shared-source-sync';
import type { BackupManifest } from '../interfaces/backup.js';

export function buildManifestFromDisk(projectPath: string, agentId: string): BackupManifest {
  const walked = walkWorkspace(projectPath);
  return {
    agentId,
    // orgId is filled in by the caller (runBackupPush) before sending.
    orgId: '',
    projectHash: walked.projectHash,
    fileCount: walked.files.length,
    totalSize: walked.totalSize,
    createdBy: 'cli',
    createdAt: new Date().toISOString(),
    files: walked.files,
  };
}
