/**
 * Voice handler — CLI-side push / sync / deploy for code-defined LuaVoice
 * agents. Versions use `active` (not `isActive`) and orphan detection is
 * gated on `source === 'cli'` so server-managed voices aren't deleted by
 * a sync from a developer who didn't author them.
 */

import { PrimitiveKind, CompilationManifest, ManifestPrimitive, ManifestVoice } from '../compiler/types.js';
import { YamlConfig, YamlConfigVoice } from '../types/yaml.types.js';
import { BASE_URLS } from '../config/constants.js';
import VoiceApi from '../api/voice.api.service.js';
import type { PushVoiceVersionRequest } from '../interfaces/voices.js';
import { BaseVersionedHandler } from './base.handler.js';
import { findPrimitive, loadArtifact, compressForPush } from '../utils/artifact-loader.js';
import { readYamlConfig, writeYamlConfig } from '../utils/files.js';
import type { YamlPrimitiveConfig } from './types.js';

export class VoiceHandler extends BaseVersionedHandler<YamlConfigVoice, PushVoiceVersionRequest> {
  readonly kind = PrimitiveKind.VOICE;
  readonly displayName = 'voice';
  readonly displayNamePlural = 'voices';
  readonly deleteCommand = 'lua voices delete';
  readonly yamlConfig: YamlPrimitiveConfig = {
    yamlKey: 'voices',
    idField: 'voiceId',
  };

  protected getApi(apiKey: string, agentId: string): VoiceApi {
    return new VoiceApi(BASE_URLS.API, apiKey, agentId);
  }

  protected async fetchFromServer(api: VoiceApi): Promise<any[] | null> {
    const response = await api.getVoices();
    if (!response.success || !response.data?.voices) return null;
    return response.data.voices;
  }

  protected async createOnServer(api: VoiceApi, primitive: ManifestPrimitive): Promise<string | null> {
    const voice = primitive as ManifestVoice;
    const response = await api.createVoice({
      name: voice.name,
      description: voice.description || `A Lua voice agent named ${voice.name}`,
    });
    if (!response.success || !response.data?.id) return null;
    return response.data.id;
  }

  // Versions carry `active` rather than the base handler's `isActive`,
  // and the entity uses the same field for orphan detection.
  isActive(serverItem: any): boolean {
    return serverItem.active !== false;
  }

  getActiveVersion(serverItem: any): string | null {
    const active = serverItem.versions?.find((v: any) => v.active === true);
    return active?.version ?? null;
  }

  protected shouldConsiderForOrphan(serverItem: any): boolean {
    return serverItem.source === 'cli' || !serverItem.source;
  }

  // ===========================================================================
  // YAML
  // ===========================================================================

  getFromYaml(config: YamlConfig | null): YamlConfigVoice[] {
    if (!config?.voices || !Array.isArray(config.voices)) return [];
    return config.voices.map((voice) => ({
      name: voice.name || '',
      version: voice.version || '',
      voiceId: voice.voiceId || '',
    }));
  }

  updateVersionInYaml(name: string, newVersion: string, options?: { silent?: boolean }): void {
    try {
      const config = readYamlConfig();
      if (!config) {
        if (options?.silent) return;
        throw new Error('lua.skill.yaml not found');
      }

      const voice = config.voices?.find((v: YamlConfigVoice) => v.name === name);
      if (!voice) {
        if (options?.silent) return;
        throw new Error(`Voice "${name}" not found in configuration`);
      }

      voice.version = newVersion;
      writeYamlConfig(config);
    } catch (error) {
      if (options?.silent) {
        console.warn('⚠️  Could not update voice version in YAML:', error);
        return;
      }
      throw error;
    }
  }

  syncYamlWithManifest(manifest: CompilationManifest, config: YamlConfig | null): void {
    super.syncYamlWithManifest(manifest, config);
    if (manifest.primitives.some((p) => p.kind === this.kind)) {
      console.log('✅ YAML synced with manifest');
    }
  }

  // ===========================================================================
  // PUSH
  // ===========================================================================

  async pushToServer(apiKey: string, agentId: string, entityId: string, pushData: PushVoiceVersionRequest) {
    const api = this.getApi(apiKey, agentId);
    // The lua-api route is `POST /developer/voice-agents/:agentId/:voiceId/version`
    // — voiceId rides in the path. No need to also stamp it on the body.
    const response = await api.pushVoice(entityId, pushData);
    return { success: response.success, error: response.error?.message };
  }

  async publishVersion(apiKey: string, agentId: string, entityId: string, version: string) {
    const api = this.getApi(apiKey, agentId);
    const response = await api.publishVoiceVersion(entityId, version);
    return { success: response.success, error: response.error?.message };
  }

  /**
   * Build the push request body from the manifest's voice entry.
   *
   * Voices come in two artifact shapes:
   *   - Metadata-only — JSON sidecar emitted by `voice.plugin.buildArtifact`.
   *     Server gets the config from the body's flat fields; no `bundle`
   *     ships.
   *   - Hooks / voice-tools — JS artifact emitted by the standard esbuild
   *     path (when buildArtifact returns undefined). The handler gzip +
   *     base64s it and rides it through as `bundle`. Worker's sandbox
   *     evaluates it per-call.
   *
   * `version` and `voiceId` are added by the caller — every versioned
   * handler relies on `pushVersionedPrimitive` for that wiring.
   */
  prepareForPush(
    manifest: CompilationManifest,
    name: string,
    _projectPath: string = process.cwd(),
    _bundleAccumulator?: Map<string, Buffer>
  ): Record<string, unknown> | null {
    const voice = findPrimitive<ManifestVoice>(manifest, name, PrimitiveKind.VOICE);
    if (!voice) return null;

    const body: Record<string, unknown> = {
      description: voice.description,
      llm: voice.llm,
      stt: voice.stt,
      tts: voice.tts,
    };

    // Optional runtime config — only emit fields the manifest carries so
    // the server can distinguish "unset" (use platform default) from
    // "explicitly empty".
    if (voice.vad !== undefined) body.vad = voice.vad;
    if (voice.vadOptions !== undefined) body.vadOptions = voice.vadOptions;
    if (voice.turnDetection !== undefined) body.turnDetection = voice.turnDetection;
    if (voice.greeting !== undefined) body.greeting = voice.greeting;
    if (voice.maxToolSteps !== undefined) body.maxToolSteps = voice.maxToolSteps;
    if (voice.userAwayTimeout !== undefined) body.userAwayTimeout = voice.userAwayTimeout;
    if (voice.preemptiveGeneration !== undefined) body.preemptiveGeneration = voice.preemptiveGeneration;
    if (voice.sttLanguage !== undefined) body.sttLanguage = voice.sttLanguage;
    if (voice.interruption !== undefined) body.interruption = voice.interruption;

    // Hook + tool presence flags — passthrough so the admin surface
    // doesn't need to re-parse the artifact.
    if (voice.hasInterruption !== undefined) body.hasInterruption = voice.hasInterruption;
    if (voice.hasOnEnter !== undefined) body.hasOnEnter = voice.hasOnEnter;
    if (voice.hasOnUserTurnCompleted !== undefined) body.hasOnUserTurnCompleted = voice.hasOnUserTurnCompleted;
    if (voice.hasOnExit !== undefined) body.hasOnExit = voice.hasOnExit;
    if (voice.hasTools !== undefined) body.hasTools = voice.hasTools;

    // Audio-effects + Krisp + background audio config — passed verbatim.
    if (voice.krispEnabled !== undefined) body.krispEnabled = voice.krispEnabled;
    if (voice.persistTranscript !== undefined) body.persistTranscript = voice.persistTranscript;
    if (voice.volume !== undefined) body.volume = voice.volume;
    if (voice.pronunciations !== undefined) body.pronunciations = voice.pronunciations;
    if (voice.backgroundAudio !== undefined) body.backgroundAudio = voice.backgroundAudio;

    // Bundle ride-along when the voice declares executable code. Voices
    // that only carry config (no hooks, no voice-only tools) write a
    // JSON metadata sidecar instead of a JS artifact, so there's nothing
    // to gzip and the field stays absent.
    const hasCode = !!(voice.hasOnEnter || voice.hasOnUserTurnCompleted || voice.hasOnExit || voice.hasTools);
    if (hasCode) {
      const artifactCode = loadArtifact(voice);
      const compressed = compressForPush(artifactCode);
      const bytes = Buffer.byteLength(compressed, 'utf8');
      // Mirror the lua-api DTO cap. Failing on the CLI side gives a
      // clear error pointing at the artifact rather than a generic 400
      // from the server.
      if (bytes > VOICE_BUNDLE_MAX_BYTES) {
        throw new Error(
          `Voice "${voice.name}" compiled bundle is ${(bytes / 1024 / 1024).toFixed(2)} MB, exceeds the ${VOICE_BUNDLE_MAX_BYTES / 1024 / 1024} MB limit. ` +
            `Trim hooks/voice tools or split into multiple voices.`
        );
      }
      body.bundle = compressed;
    }

    return body;
  }
}

const VOICE_BUNDLE_MAX_BYTES = 10 * 1024 * 1024;

export const voiceHandler = new VoiceHandler();
