/**
 * Common utility functions for the compiler.
 */

import path from 'path';
import { hashContentTruncated } from '@lua/shared-source-sync';

// Re-exported so the rest of lua-cli imports skip/hash helpers from a single
// place. The shared package is the source of truth — diverging breaks the
// per-agent backup dedupe.
export { shouldSkipFile, shouldSkipDirectory } from '@lua/shared-source-sync';

export function hashContent(content: string): string {
  return hashContentTruncated(content);
}

/**
 * Return `true` when `child` is contained in `parent` (or is `parent` itself).
 * Uses normalized absolute paths so trailing slashes, `..` segments, and mixed
 * separators don't cause false negatives — `child.startsWith(parent)` would
 * incorrectly match `/foo/bar-baz` against `/foo/bar`.
 */
export function isInside(child: string, parent: string): boolean {
  const resolvedChild = path.resolve(child);
  const resolvedParent = path.resolve(parent);
  if (resolvedChild === resolvedParent) return true;
  const rel = path.relative(resolvedParent, resolvedChild);
  return !!rel && !rel.startsWith('..') && !path.isAbsolute(rel);
}

/**
 * Classify a project file by its name so the backup manifest knows whether
 * it's a source file, a config file, or something else.
 */
export function classifyProjectFile(name: string): 'source' | 'config' | 'other' {
  if (name.endsWith('.ts') || name.endsWith('.tsx') || name.endsWith('.js')) {
    return 'source';
  }
  if (
    name === 'package.json' ||
    name === 'tsconfig.json' ||
    name === 'lua.skill.yaml' ||
    name.endsWith('.yaml') ||
    name.endsWith('.yml') ||
    name.endsWith('.json')
  ) {
    return 'config';
  }
  return 'other';
}

/**
 * Format file size in human-readable format.
 */
export function formatSize(bytes: number): string {
  if (bytes < 1024) return `${bytes}B`;
  if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)}KB`;
  return `${(bytes / 1024 / 1024).toFixed(1)}MB`;
}
