/**
 * Persona Command
 * Manages agent persona for sandbox and production environments
 */

import type { PersonaText } from '@lua/shared-types';
import { flattenPersonaTextAll } from '@lua/shared-types';
import inquirer from 'inquirer';
import { withErrorHandling, writeProgress, writeSuccess, writeInfo } from '../utils/cli.js';
import { BASE_URLS } from '../config/constants.js';
import { safePrompt } from '../utils/prompt-handler.js';
import { initializeCommand } from '../utils/command-utils.js';
import { setAgentPersona } from '../compiler/index.js';
import { getAgentPersona } from '../utils/artifact-loader.js';
import PersonaApi from '../api/persona.api.service.js';
import { trackEvent } from '../services/analytics.js';
import { validateOrSuggest } from '../utils/aliases.js';

interface PersonaCommandContext {
  environment: 'sandbox' | 'production';
  agentId: string;
  apiKey: string;
}

interface PersonaVersion {
  version: number;
  persona: PersonaText;
  createdDate: number;
  createdBy?: string;
  isCurrent: boolean;
  status?: 'draft' | 'published';
  config?: any;
}

interface PersonaOptions {
  personaVersion?: string;
  force?: boolean;
}

type ProductionAction = 'view' | 'versions' | 'deploy';

// ─────────────────────────────────────────────────────────────────────────────
// Main Command Entry
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Main persona command - manages agent persona.
 *
 * Supports both interactive and non-interactive modes:
 * - Interactive: prompts for environment and action selection
 * - Non-interactive (production): use env + action with optional flags
 */
export async function personaCommand(env?: string, action?: string, cmdObj?: any): Promise<void> {
  return withErrorHandling(async () => {
    const options: PersonaOptions = {
      personaVersion: cmdObj?.personaVersion || null,
      force: cmdObj?.force || false,
    };

    // Initialize command (validates config + auth)
    const { agentId, apiKey } = await initializeCommand();

    let selectedEnvironment: 'sandbox' | 'production';

    // Check if environment was provided as argument
    if (env) {
      const normalizedEnv = validateOrSuggest('persona.env', env);
      selectedEnvironment = normalizedEnv === 'staging' ? 'sandbox' : (normalizedEnv as 'sandbox' | 'production');
    } else {
      // Step 4: Prompt for environment selection
      const envAnswer = await safePrompt<{ environment: string }>([
        {
          type: 'list',
          name: 'environment',
          message: 'Select environment:',
          choices: [
            { name: '🔧 Sandbox (edit and test)', value: 'sandbox' },
            { name: '🚀 Production (view and deploy versions)', value: 'production' },
          ],
        },
      ]);

      if (!envAnswer) return;
      selectedEnvironment = envAnswer.environment as 'sandbox' | 'production';
    }

    const context: PersonaCommandContext = {
      environment: selectedEnvironment,
      agentId,
      apiKey,
    };

    // Step 5: Handle based on environment and action
    if (selectedEnvironment === 'sandbox') {
      if (action === 'view') {
        // Non-interactive: display persona and exit
        const currentPersona = flattenPersonaTextAll(getAgentPersona());
        if (currentPersona.trim()) {
          console.log(currentPersona);
        } else {
          console.log('ℹ️  No persona configured.');
        }
        return;
      }
      // Other sandbox actions are interactive (editing requires editor)
      await manageSandboxPersonaInteractive(context);
    } else {
      // Production mode supports non-interactive actions
      if (action) {
        await executeProductionNonInteractive(context, action, options);
      } else {
        await manageProductionPersonaInteractive(context);
      }
    }
    trackEvent('cli_persona_action', {
      environment: selectedEnvironment,
      action: action || null,
      non_interactive: !!env,
      force_mode: options.force || false,
    });
  }, 'persona');
}

// ─────────────────────────────────────────────────────────────────────────────
// Shared Core Functions
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Fetches all persona versions from the API.
 */
async function fetchVersionsCore(context: PersonaCommandContext): Promise<PersonaVersion[] | null> {
  try {
    const personaApi = new PersonaApi(BASE_URLS.API, context.apiKey, context.agentId);
    const response = await personaApi.getVersions();

    if (!response.success || !response.data) {
      console.error(`❌ API Error: ${response.error?.message || 'Unknown error'}`);
      return null;
    }

    const versions = response.data.versions || [];
    return versions.sort((a, b) => b.createdDate - a.createdDate);
  } catch (error) {
    console.error('❌ Error loading persona versions:', error);
    return null;
  }
}

/**
 * Displays the current deployed persona.
 */
function displayCurrentPersonaCore(versions: PersonaVersion[]): void {
  const currentVersion = versions.find((v) => v.isCurrent);

  console.log('\n' + '='.repeat(60));
  console.log('🤖 Current Production Persona');
  console.log('='.repeat(60) + '\n');

  if (currentVersion) {
    const date = new Date(currentVersion.createdDate);
    console.log(`Version: ${currentVersion.version} ⭐`);
    console.log(`Deployed: ${date.toLocaleString()}`);
    if (currentVersion.createdBy) {
      console.log(`Created by: ${currentVersion.createdBy}`);
    }
    console.log('\n' + '-'.repeat(60) + '\n');
    console.log(currentVersion.persona);
    console.log('\n' + '='.repeat(60));
  } else {
    console.log('⚠️  No persona currently deployed.');
    console.log('💡 Deploy a version using: lua persona production deploy -v <version>\n');
    console.log('='.repeat(60));
  }
}

/**
 * Displays all persona versions.
 */
function displayVersionsCore(versions: PersonaVersion[]): void {
  console.log('\n' + '='.repeat(60));
  console.log('🌙 Persona Versions');
  console.log('='.repeat(60) + '\n');

  if (versions.length === 0) {
    console.log('ℹ️  No persona versions found.');
    console.log('💡 Create a version first from sandbox mode.\n');
    return;
  }

  versions.forEach((v) => {
    const date = new Date(v.createdDate);
    const dateStr = date.toLocaleDateString();
    const timeStr = date.toLocaleTimeString();
    const currentMark = v.isCurrent ? ' ⭐ CURRENT' : '';
    const status = v.status === 'draft' ? ' [DRAFT]' : '';
    console.log(`  Version ${v.version}${status} - ${dateStr} ${timeStr}${currentMark}`);
  });

  console.log('\n' + '='.repeat(60));
  console.log(`Total: ${versions.length} version(s)`);
}

/**
 * Deploys a persona version.
 */
async function deployVersionCore(context: PersonaCommandContext, version: number): Promise<boolean> {
  writeProgress(`🔄 Deploying persona version ${version}...`);

  try {
    const personaApi = new PersonaApi(BASE_URLS.API, context.apiKey, context.agentId);
    const response = await personaApi.deployVersion(version);

    if (!response.success) {
      console.error(`❌ Deploy Error: ${response.error?.message || 'Unknown error'}`);
      return false;
    }

    writeSuccess(`✅ Persona version ${version} deployed successfully to production`);
    writeInfo('💡 The new persona is now active for all users.');
    return true;
  } catch (error) {
    console.error('❌ Error deploying persona version:', error);
    return false;
  }
}

// ─────────────────────────────────────────────────────────────────────────────
// Non-Interactive Mode (Production)
// ─────────────────────────────────────────────────────────────────────────────

async function executeProductionNonInteractive(
  context: PersonaCommandContext,
  action: string,
  options: PersonaOptions
): Promise<void> {
  const normalizedAction = validateOrSuggest('persona.action', action);

  writeProgress('🔄 Loading persona versions...');
  const versions = await fetchVersionsCore(context);
  if (!versions) throw new Error('Failed to fetch persona versions');

  switch (normalizedAction as ProductionAction) {
    case 'view':
      displayCurrentPersonaCore(versions);
      break;

    case 'versions':
      displayVersionsCore(versions);
      break;

    case 'deploy': {
      if (!options.personaVersion) {
        console.error('❌ --persona-version is required for deploy action');
        console.log('\nUsage: lua persona production deploy --persona-version <version>');
        console.log('       lua persona production deploy -v latest');
        if (versions.length > 0) {
          console.log('\nAvailable versions:');
          versions.slice(0, 5).forEach((v) => {
            const mark = v.isCurrent ? ' (current)' : '';
            console.log(`  - ${v.version}${mark}`);
          });
        }
        throw new Error('--persona-version is required for deploy action');
      }

      // Resolve version number
      let versionNumber: number;
      if (options.personaVersion.toLowerCase() === 'latest') {
        if (versions.length === 0) {
          console.error('❌ No versions available to deploy');
          throw new Error('No versions available to deploy');
        }
        versionNumber = versions[0].version; // Already sorted newest first
        console.log(`ℹ️  Latest version is ${versionNumber}`);
      } else {
        versionNumber = parseInt(options.personaVersion, 10);
        if (isNaN(versionNumber)) {
          console.error(`❌ Invalid version number: "${options.personaVersion}"`);
          throw new Error(`Invalid version number: "${options.personaVersion}"`);
        }
      }

      // Check if version exists
      const versionExists = versions.find((v) => v.version === versionNumber);
      if (!versionExists) {
        console.error(`❌ Version ${versionNumber} not found`);
        console.log('\nAvailable versions:');
        versions.forEach((v) => console.log(`  - ${v.version}`));
        throw new Error(`Version ${versionNumber} not found`);
      }

      // Check if already current
      if (versionExists.isCurrent) {
        console.log(`ℹ️  Version ${versionNumber} is already deployed.`);
        return;
      }

      // Confirm unless --force
      if (!options.force) {
        console.log('\n⚠️  WARNING: You are about to deploy to PRODUCTION!');
        console.log('⚠️  This will affect ALL users immediately.\n');

        const confirmAnswer = await safePrompt<{ confirm: boolean }>([
          {
            type: 'confirm',
            name: 'confirm',
            message: `Deploy version ${versionNumber} to production?`,
            default: false,
          },
        ]);

        if (!confirmAnswer || !confirmAnswer.confirm) {
          console.log('\n❌ Deployment cancelled.\n');
          return;
        }
      }

      const success = await deployVersionCore(context, versionNumber);
      if (!success) throw new Error('Failed to deploy persona version');
      break;
    }
  }
}

// ─────────────────────────────────────────────────────────────────────────────
// Interactive Mode (Sandbox)
// ─────────────────────────────────────────────────────────────────────────────

async function manageSandboxPersonaInteractive(context: PersonaCommandContext): Promise<void> {
  let continueManaging = true;

  while (continueManaging) {
    const currentPersona = flattenPersonaTextAll(getAgentPersona());

    console.log('\n' + '='.repeat(60));
    console.log('🌙 Sandbox Persona Management');
    console.log('='.repeat(60) + '\n');

    if (currentPersona && currentPersona.trim()) {
      const preview = currentPersona.length > 100 ? currentPersona.substring(0, 100) + '...' : currentPersona;
      console.log('Current persona:');
      console.log(preview);
      console.log();
    } else {
      console.log('ℹ️  No persona configured.\n');
    }

    const actionAnswer = await safePrompt<{ action: string }>([
      {
        type: 'list',
        name: 'action',
        message: 'What would you like to do?',
        choices: [
          { name: '👁️  View full persona', value: 'view' },
          { name: '✏️  Edit persona', value: 'edit' },
          { name: '📦 Create version (push to production)', value: 'create_version' },
          { name: '📋 List versions', value: 'list_versions' },
          { name: '❌ Exit', value: 'exit' },
        ],
      },
    ]);

    if (!actionAnswer) return;
    const { action } = actionAnswer;

    switch (action) {
      case 'view':
        await viewPersonaInteractive(currentPersona);
        break;
      case 'edit':
        await editSandboxPersonaInteractive(context, currentPersona);
        break;
      case 'create_version':
        await createPersonaVersionInteractive(context, currentPersona);
        break;
      case 'list_versions':
        await listPersonaVersionsInteractive(context);
        break;
      case 'exit':
        continueManaging = false;
        console.log('\n👋 Goodbye!\n');
        break;
    }
  }
}

async function viewPersonaInteractive(persona: string | null): Promise<void> {
  console.log('\n' + '='.repeat(60));
  console.log('Agent Persona');
  console.log('='.repeat(60));

  if (persona && persona.trim()) {
    console.log(persona);
  } else {
    console.log('No persona configured.');
  }

  console.log('='.repeat(60) + '\n');

  await inquirer.prompt([
    {
      type: 'input',
      name: 'continue',
      message: 'Press Enter to continue...',
    },
  ]);
}

async function editSandboxPersonaInteractive(
  context: PersonaCommandContext,
  currentPersona: string | null
): Promise<void> {
  const defaultPersona =
    currentPersona ||
    `# Write your agent persona here
# 
# Example:
# You are a helpful customer service assistant for [Your Company].
# You help users with product inquiries and order management.
# You are friendly, professional, and knowledgeable.`;

  const personaAnswer = await safePrompt<{ newPersona: string }>([
    {
      type: 'editor',
      name: 'newPersona',
      message: 'Edit persona (will open in your default editor):',
      default: defaultPersona,
      validate: (input: string) => {
        if (!input.trim()) {
          return 'Persona cannot be empty';
        }
        const withoutComments = input
          .split('\n')
          .filter((line: string) => !line.trim().startsWith('#'))
          .join('\n')
          .trim();
        if (!withoutComments) {
          return 'Persona cannot be empty (only comments found)';
        }
        return true;
      },
    },
  ]);

  if (!personaAnswer) return;
  const { newPersona } = personaAnswer;

  const trimmedPersona = newPersona.trim();

  writeProgress('🔄 Saving persona to code (LuaAgent)...');
  const success = setAgentPersona(trimmedPersona);

  if (success) {
    writeSuccess('✅ Persona saved to code successfully');
  } else {
    console.error('❌ Failed to save persona to code');
  }
}

async function createPersonaVersionInteractive(
  context: PersonaCommandContext,
  currentPersona: string | null
): Promise<void> {
  if (!currentPersona || !currentPersona.trim()) {
    console.log('\n❌ No persona to create version from. Please edit and save a persona first.\n');
    return;
  }

  console.log('\n⚠️  This will create a new persona version that can be deployed to production.');

  const confirmAnswer = await safePrompt<{ confirm: boolean }>([
    {
      type: 'confirm',
      name: 'confirm',
      message: 'Create new persona version?',
      default: true,
    },
  ]);

  if (!confirmAnswer || !confirmAnswer.confirm) {
    console.log('\nℹ️  Version creation cancelled.\n');
    return;
  }

  writeProgress('🔄 Creating persona version...');

  try {
    const personaApi = new PersonaApi(BASE_URLS.API, context.apiKey, context.agentId);
    const response = await personaApi.createVersion(currentPersona);

    if (!response.success || !response.data) {
      throw new Error(response.error?.message || 'Failed to create persona version');
    }

    const versionNum = response.data.version || 'N/A';
    writeSuccess(`✅ Persona version created successfully (version: ${versionNum})`);
    writeInfo('💡 You can deploy this version from the production environment.');
  } catch (error) {
    console.error('❌ Error creating persona version:', error);
  }
}

async function listPersonaVersionsInteractive(context: PersonaCommandContext): Promise<void> {
  writeProgress('🔄 Loading persona versions...');
  const versions = await fetchVersionsCore(context);

  if (!versions || versions.length === 0) {
    console.log('\nℹ️  No persona versions found.\n');
    console.log('💡 Create a version first from sandbox mode.\n');
    return;
  }

  const versionAnswer = await safePrompt<{ selectedVersionIndex: number }>([
    {
      type: 'list',
      name: 'selectedVersionIndex',
      message: 'Select a persona version to view:',
      choices: versions.map((version, index) => {
        const date = new Date(version.createdDate);
        const dateStr = date.toLocaleDateString();
        const timeStr = date.toLocaleTimeString();
        const status = version.status === 'draft' ? '[DRAFT]' : '';
        const currentMark = version.isCurrent ? ' ⭐ CURRENT' : '';
        return {
          name: `Version ${version.version} ${status} - (${dateStr}) ${timeStr} ${currentMark}`,
          value: index,
        };
      }),
    },
  ]);

  if (!versionAnswer) return;

  await viewVersionDetailsInteractive(versions[versionAnswer.selectedVersionIndex]);
}

async function viewVersionDetailsInteractive(version: PersonaVersion): Promise<void> {
  const date = new Date(version.createdDate);

  console.log('\n' + '='.repeat(60));
  console.log(`Persona Version ${version.version}`);
  console.log('='.repeat(60));
  console.log(`Created: ${date.toLocaleString()}`);
  const versionStatus = version.status === 'draft' ? '🔨 DRAFT' : '';
  console.log(`Version Status: ${versionStatus}`);
  console.log(`Active Status: ${version.isCurrent ? '⭐ CURRENT' : 'Available'}`);
  if (version.createdBy) {
    console.log(`Created by: ${version.createdBy}`);
  }
  console.log('='.repeat(60) + '\n');
  console.log(version.persona);
  console.log('\n' + '='.repeat(60) + '\n');

  await inquirer.prompt([
    {
      type: 'input',
      name: 'continue',
      message: 'Press Enter to continue...',
    },
  ]);
}

// ─────────────────────────────────────────────────────────────────────────────
// Interactive Mode (Production)
// ─────────────────────────────────────────────────────────────────────────────

async function manageProductionPersonaInteractive(context: PersonaCommandContext): Promise<void> {
  let continueManaging = true;

  while (continueManaging) {
    console.log('\n' + '='.repeat(60));
    console.log('🌙 Production Persona Management');
    console.log('='.repeat(60) + '\n');

    const actionAnswer = await safePrompt<{ action: string }>([
      {
        type: 'list',
        name: 'action',
        message: 'What would you like to do?',
        choices: [
          { name: '👁️  View persona versions', value: 'view' },
          { name: '🚀 Deploy persona version', value: 'deploy' },
          { name: '❌ Exit', value: 'exit' },
        ],
      },
    ]);

    if (!actionAnswer) return;
    const { action } = actionAnswer;

    switch (action) {
      case 'view':
        await listPersonaVersionsInteractive(context);
        break;
      case 'deploy':
        await deployPersonaVersionInteractive(context);
        break;
      case 'exit':
        continueManaging = false;
        console.log('\n👋 Goodbye!\n');
        break;
    }
  }
}

async function deployPersonaVersionInteractive(context: PersonaCommandContext): Promise<void> {
  writeProgress('🔄 Loading persona versions...');
  const versions = await fetchVersionsCore(context);

  if (!versions || versions.length === 0) {
    console.log('\nℹ️  No persona versions available to deploy.\n');
    console.log('💡 Create a version first from sandbox mode.\n');
    return;
  }

  console.log('\n' + '='.repeat(60));
  console.log('🌙 Select Persona Version to Deploy');
  console.log('='.repeat(60) + '\n');

  const versionAnswer = await safePrompt<{ selectedVersion: number }>([
    {
      type: 'list',
      name: 'selectedVersion',
      message: 'Select version to deploy:',
      choices: versions.map((v) => {
        const date = new Date(v.createdDate);
        const dateStr = date.toLocaleDateString();
        const timeStr = date.toLocaleTimeString();
        const currentMark = v.isCurrent ? ' ⭐ CURRENTLY DEPLOYED' : '';
        const status = v.status === 'draft' ? '[DRAFT]' : '';
        return {
          name: `Version ${v.version} ${status} - (${dateStr}) ${timeStr} ${currentMark}`,
          value: v.version,
        };
      }),
    },
  ]);

  if (!versionAnswer) return;
  const { selectedVersion } = versionAnswer;

  console.log('\n⚠️  WARNING: You are about to deploy to PRODUCTION!');
  console.log('⚠️  This will affect ALL users immediately.\n');

  const confirmAnswer = await safePrompt<{ confirm: boolean }>([
    {
      type: 'confirm',
      name: 'confirm',
      message: 'Are you absolutely sure you want to deploy this persona version?',
      default: false,
    },
  ]);

  if (!confirmAnswer || !confirmAnswer.confirm) {
    console.log('\n❌ Deployment cancelled.\n');
    return;
  }

  await deployVersionCore(context, selectedVersion);
}
