import { readFile } from 'fs/promises';
import { resolve, extname } from 'path';
import { ChatMessage } from '../interfaces/chat.js';

const MIME_TYPES: Record<string, string> = {
  // Images (natively supported by vision models)
  '.png': 'image/png',
  '.jpg': 'image/jpeg',
  '.jpeg': 'image/jpeg',
  '.gif': 'image/gif',
  '.webp': 'image/webp',
  '.bmp': 'image/bmp',
  '.tiff': 'image/tiff',
  '.tif': 'image/tiff',
  '.heic': 'image/heic',
  // Documents
  '.pdf': 'application/pdf',
  '.doc': 'application/msword',
  '.docx': 'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
  '.xls': 'application/vnd.ms-excel',
  '.xlsx': 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
  '.ppt': 'application/vnd.ms-powerpoint',
  '.pptx': 'application/vnd.openxmlformats-officedocument.presentationml.presentation',
  '.odt': 'application/vnd.oasis.opendocument.text',
  '.epub': 'application/epub+zip',
  // Text / markup
  '.txt': 'text/plain',
  '.md': 'text/plain',
  '.csv': 'text/csv',
  '.tsv': 'text/tab-separated-values',
  '.html': 'text/html',
  '.htm': 'text/html',
  '.xml': 'application/xml',
  '.rtf': 'application/rtf',
  '.rst': 'text/plain',
  '.org': 'text/plain',
  '.json': 'application/json',
  // Email
  '.eml': 'message/rfc822',
  '.msg': 'application/vnd.ms-outlook',
};

const IMAGE_MIME_TYPES = new Set(['image/png', 'image/jpeg', 'image/gif', 'image/webp']);

// Zero-width lookbehind: only match @<path> when @ is at start of string or
// preceded by whitespace. This prevents email addresses like user@domain.com
// from matching, since their @ is preceded by a non-whitespace character.
const AT_FILE_PATTERN = /(?<!\S)@([^\s,;'"!?()[\]{}|<>]+)/g;

const MAX_FILE_SIZE = 10 * 1024 * 1024; // 10MB

/**
 * Parses a chat input string for @<filepath> tokens, reads and base64-encodes
 * each referenced file, and returns a ChatMessage array suitable for ChatRequest.messages.
 *
 * Only tokens where @ is at the start of the string or preceded by whitespace are
 * treated as file references — this prevents false positives on email addresses.
 * Tokens with unsupported or missing extensions are left as text.
 *
 * A plain message with no tokens returns [{ type: 'text', text: input }].
 * A message like "check @screen.png please" returns a text part (token stripped)
 * followed by an image or file part.
 */
export async function parseMessageWithAttachments(input: string): Promise<ChatMessage[]> {
  const matches = [...input.matchAll(AT_FILE_PATTERN)];

  if (matches.length === 0) {
    return [{ type: 'text', text: input }];
  }

  // Only treat tokens with a known extension as file references; leave the rest
  // as-is in the message text so emails / unknown @-references aren't silently stripped.
  const fileMatches = matches.filter((m) => extname(m[1]).toLowerCase() in MIME_TYPES);

  if (fileMatches.length === 0) {
    return [{ type: 'text', text: input }];
  }

  // Strip confirmed file tokens using positional splicing (right-to-left so earlier
  // indices stay valid). String.replace would match the first substring occurrence,
  // which corrupts a non-file token that shares a prefix with a file token
  // (e.g. @report.pdf.bak vs @report.pdf).
  const sortedMatches = [...fileMatches].sort((a, b) => b.index! - a.index!);
  let text = input;
  for (const match of sortedMatches) {
    const start = match.index!;
    text = text.slice(0, start) + text.slice(start + match[0].length);
  }
  text = text.replace(/\s{2,}/g, ' ').trim();

  const parts: ChatMessage[] = [];

  if (text) {
    parts.push({ type: 'text', text });
  }

  for (const match of fileMatches) {
    const filePath = match[1];
    const ext = extname(filePath).toLowerCase();
    const mediaType = MIME_TYPES[ext];

    let buffer: Buffer;
    try {
      buffer = await readFile(resolve(filePath));
    } catch (error: unknown) {
      const code = (error as NodeJS.ErrnoException).code;
      if (code === 'ENOENT') throw new Error(`File not found: ${filePath}`);
      if (code === 'EACCES') throw new Error(`Permission denied: ${filePath}`);
      if (code === 'EISDIR') throw new Error(`Path is a directory, not a file: ${filePath}`);
      throw new Error(`Could not read file ${filePath}: ${error instanceof Error ? error.message : String(error)}`);
    }

    if (buffer.length > MAX_FILE_SIZE) {
      const sizeMb = (buffer.length / 1024 / 1024).toFixed(1);
      throw new Error(`File too large: ${filePath} (${sizeMb}MB, max 10MB)`);
    }

    const base64 = buffer.toString('base64');

    if (IMAGE_MIME_TYPES.has(mediaType)) {
      parts.push({ type: 'image', image: base64, mediaType });
    } else {
      parts.push({ type: 'file', data: base64, mediaType });
    }
  }

  return parts;
}
