/**
 * Device Trigger compilation plugin.
 *
 * BACKWARD COMPATIBLE: Detects BOTH patterns:
 * 1. Class-based (legacy): new LuaDeviceTrigger({ ... })
 * 2. Function-based (new): const myTrigger = defineDeviceTrigger({ ... })
 */

import { Project, Node, ObjectLiteralExpression, ClassDeclaration, SourceFile } from 'ts-morph';
import {
  type DeviceTriggerMetadata,
  type DeviceTriggerMetadataFields,
  type ValidationResult,
  type SchemaSet,
  type CompiledPrimitive,
  type ManifestPrimitive,
  type ManifestDeviceTrigger,
} from '../types.js';
import {
  BasePlugin,
  readStringMember,
  deriveNameFromClassName,
  locateClassDefinition,
  validationError,
  validationWarning,
} from './base.js';
import { extractSchemaProperty } from '../utils/ast-helpers.js';
import { findClassMember } from '../utils/class-hierarchy.js';
import { zodToJsonSchema } from '../utils/schema-converter.js';

/**
 * Plugin for compiling device trigger primitives.
 * Extends BasePlugin for common detection/entry point/postProcess logic.
 */
export class DeviceTriggerPlugin extends BasePlugin<DeviceTriggerMetadataFields> {
  readonly kind = 'device-trigger';
  readonly displayName = 'Device Trigger';
  readonly defineFunction = 'defineDeviceTrigger';
  readonly legacyClassNames = ['LuaDeviceTrigger'];

  protected readonly supportsClassDefinition = true;

  /**
   * Class-definition extraction. Reads `name`/`description`/has-flags
   * off the inheritance chain.
   */
  protected extractFromClassDefinition(
    classDecl: ClassDeclaration,
    sourceFile: SourceFile
  ): DeviceTriggerMetadata | null {
    const className = classDecl.getName();
    if (!className) return null;

    const isDefaultExport = classDecl.isDefaultExport();
    const exportName = isDefaultExport ? 'default' : className;

    const name = readStringMember(classDecl, 'name') ?? deriveNameFromClassName(className);
    const description = readStringMember(classDecl, 'description') ?? '';

    return {
      kind: this.kind,
      name,
      description,
      sourcePath: sourceFile.getFilePath(),
      exportName,
      isDefaultExport,
      line: classDecl.getStartLineNumber(),
      column: 1,
      metadata: {
        pattern: 'class-definition',
        hasExecute: findClassMember(classDecl, 'execute', 'either') !== undefined,
        hasPayloadSchema: findClassMember(classDecl, 'payloadSchema', 'property') !== undefined,
      },
    };
  }

  /**
   * Project the device-trigger class instance onto the standard
   * execute-having primitive shape, with payloadSchema bound from the
   * instance so subclass overrides win.
   */
  protected getClassDefinitionPrimitiveShape(metadata: DeviceTriggerMetadata): string {
    return `{
    kind: 'device-trigger',
    name: __lua_instance__.name ?? ${JSON.stringify(metadata.name)},
    description: __lua_instance__.description ?? ${JSON.stringify(metadata.description)},
    payloadSchema: __lua_instance__.payloadSchema,
    execute: typeof __lua_instance__.execute === 'function' ? __lua_instance__.execute.bind(__lua_instance__) : undefined,
  }`;
  }

  /**
   * Extract metadata from device trigger config object.
   */
  protected extractFromConfig(
    config: ObjectLiteralExpression,
    exportName: string,
    sourcePath: string,
    position: { line: number; column: number },
    pattern: 'function' | 'class'
  ): DeviceTriggerMetadata | null {
    const common = this.extractCommonFields(config, exportName, sourcePath, position);
    if (!common) return null;

    return {
      kind: this.kind,
      ...common,
      metadata: {
        pattern,
        hasExecute: config.getProperty('execute') !== undefined,
        hasPayloadSchema: config.getProperty('payloadSchema') !== undefined,
      },
    };
  }

  validate(metadata: DeviceTriggerMetadata): ValidationResult {
    const { errors, warnings } = this.baseValidation(metadata);

    if (!metadata.metadata.hasExecute) {
      errors.push(validationError('Device trigger must have an execute function', { line: metadata.line }));
    }

    if (metadata.name && !/^[a-z][a-z0-9_-]*$/.test(metadata.name)) {
      warnings.push(
        validationWarning('Device trigger name should be lowercase with hyphens or underscores only', {
          line: metadata.line,
        })
      );
    }

    return { valid: errors.length === 0, errors, warnings };
  }

  /**
   * Add runtime validation for execute function.
   */
  protected getRuntimeValidation(): string {
    return `
  if (typeof primitive.primitive?.execute !== 'function') {
    throw new Error('[Lua] Invalid device trigger artifact: execute is not a function');
  }`;
  }

  /**
   * Extract payload schema from device trigger.
   */
  async extractSchemas(metadata: DeviceTriggerMetadata, project: Project): Promise<SchemaSet | undefined> {
    const sourceFile = project.getSourceFile(metadata.sourcePath);
    if (!sourceFile) return undefined;

    const schemas: SchemaSet = {};

    if (metadata.metadata.pattern === 'class-definition') {
      if (!metadata.metadata.hasPayloadSchema) return undefined;
      const classDecl = locateClassDefinition(sourceFile, metadata.exportName);
      if (!classDecl) return undefined;
      const hit = findClassMember(classDecl, 'payloadSchema', 'property');
      if (!hit || !Node.isPropertyDeclaration(hit.node)) return undefined;
      const schemaNode = hit.node.getInitializer();
      if (!schemaNode) return undefined;
      try {
        schemas['payload'] = await zodToJsonSchema(schemaNode);
      } catch (error) {
        console.warn(`Warning: Could not convert payloadSchema for ${metadata.name}:`, error);
      }
      return Object.keys(schemas).length > 0 ? schemas : undefined;
    }

    const varDecl = sourceFile.getVariableDeclaration(metadata.exportName);
    if (!varDecl) return undefined;

    const initializer = varDecl.getInitializer();
    if (!initializer || !Node.isCallExpression(initializer)) return undefined;

    const args = initializer.getArguments();
    if (args.length === 0) return undefined;

    const config = args[0];
    if (!Node.isObjectLiteralExpression(config)) return undefined;

    if (metadata.metadata.hasPayloadSchema) {
      const schemaNode = extractSchemaProperty(config, 'payloadSchema');
      if (schemaNode) {
        try {
          const jsonSchema = await zodToJsonSchema(schemaNode);
          schemas['payload'] = jsonSchema;
        } catch (error) {
          console.warn(`Warning: Could not convert payloadSchema for ${metadata.name}:`, error);
        }
      }
    }

    return Object.keys(schemas).length > 0 ? schemas : undefined;
  }

  toManifestEntry(compiled: CompiledPrimitive, _allPrimitives?: CompiledPrimitive[]): ManifestPrimitive {
    return {
      ...this.baseManifestFields(compiled),
      schemas: compiled.schemas
        ? {
            payload: compiled.schemas.payload,
          }
        : undefined,
    } as ManifestDeviceTrigger;
  }
}
