/**
 * PostProcessor Handler
 *
 * Handles CLI operations for postprocessor primitives.
 *
 * PostProcessors:
 * - Use 'activeVersionId' for active detection (no top-level 'active' field)
 * - Use 'isActive' field on versions
 */

import { PrimitiveKind, ManifestPrimitive, ManifestPostProcessor } from '../compiler/types.js';
import { BASE_URLS } from '../config/constants.js';
import PostProcessorApi from '../api/postprocessor.api.service.js';
import { BaseVersionedHandler } from './base.handler.js';
import type { YamlPrimitiveConfig } from './types.js';
import type { YamlConfigPostprocessor } from '../types/yaml.types.js';

/**
 * PostProcessor primitive handler
 */
type PostProcessorPushData = Parameters<PostProcessorApi['pushPostProcessor']>[1];

export class PostprocessorHandler extends BaseVersionedHandler<YamlConfigPostprocessor, PostProcessorPushData> {
  readonly kind = PrimitiveKind.POSTPROCESSOR;
  readonly displayName = 'postprocessor';
  readonly displayNamePlural = 'postprocessors';
  readonly deleteCommand = 'lua postprocessors delete';
  readonly yamlConfig: YamlPrimitiveConfig = {
    yamlKey: 'postprocessors',
    idField: 'postprocessorId',
  };

  protected getApi(apiKey: string, agentId: string): PostProcessorApi {
    return new PostProcessorApi(BASE_URLS.API, apiKey, agentId);
  }

  protected async fetchFromServer(api: PostProcessorApi): Promise<any[] | null> {
    const response = await api.getPostProcessors();
    if (!response.success || !response.data?.postprocessors) {
      return null;
    }
    return response.data.postprocessors;
  }

  protected async createOnServer(api: PostProcessorApi, primitive: ManifestPrimitive): Promise<string | null> {
    const response = await api.createPostProcessor({
      name: primitive.name,
      description: primitive.description || `A Lua postprocessor for ${primitive.name}`,
    });
    if (!response.success || !response.data?.id) return null;
    return response.data.id;
  }

  async pushToServer(apiKey: string, agentId: string, entityId: string, pushData: PostProcessorPushData) {
    const api = this.getApi(apiKey, agentId);
    const response = await api.pushPostProcessor(entityId, { ...pushData, postprocessorId: entityId });
    return { success: response.success, error: response.error?.message };
  }

  async publishVersion(apiKey: string, agentId: string, entityId: string, version: string) {
    const api = this.getApi(apiKey, agentId);
    const response = await api.publishPostProcessorVersion(entityId, version);
    return { success: response.success, error: response.error?.message };
  }

  /**
   * Override to include source-declared priority in push data so the parent
   * postprocessor doc gets updated alongside the new version.
   */
  protected buildPushData(
    primitive: ManifestPrimitive,
    compressedCode: string | undefined,
    codeS3Hash?: string
  ): Record<string, unknown> {
    const postProcessor = primitive as ManifestPostProcessor;
    return {
      name: primitive.name,
      description: primitive.description,
      ...(codeS3Hash ? { codeS3Hash } : { code: compressedCode }),
      ...(postProcessor.priority !== undefined ? { priority: postProcessor.priority } : {}),
    };
  }
}

// Export singleton instance
export const postprocessorHandler = new PostprocessorHandler();
