/**
 * Device Handler
 *
 * Handles CLI operations for device primitives.
 *
 * Devices are versioned primitives (like webhooks, jobs) because
 * their trigger handlers are compiled artifacts that need to be
 * uploaded and versioned alongside the definition.
 */

import { PrimitiveKind, ManifestPrimitive, ManifestDevice } from '../compiler/types.js';
import { BASE_URLS } from '../config/constants.js';
import DeviceApi from '../api/device.api.service.js';
import type { PushDeviceVersionDTO } from '../interfaces/devices.js';
import { BaseVersionedHandler } from './base.handler.js';
import type { YamlPrimitiveConfig, ServerSyncData } from './types.js';
import type { YamlConfigDevice } from '../types/yaml.types.js';

/**
 * Device primitive handler
 */
export class DeviceHandler extends BaseVersionedHandler<YamlConfigDevice, PushDeviceVersionDTO> {
  readonly kind = PrimitiveKind.DEVICE;
  readonly displayName = 'device';
  readonly displayNamePlural = 'devices';
  readonly deleteCommand = 'lua devices remove';
  readonly yamlConfig: YamlPrimitiveConfig = {
    yamlKey: 'devices',
    idField: 'deviceId',
  };

  protected getApi(apiKey: string, agentId: string): DeviceApi {
    return new DeviceApi(BASE_URLS.API, apiKey, agentId);
  }

  /**
   * Override fetchServerState to treat auth/network errors as non-fatal.
   *
   * The Device Gateway is feature-gated on the server
   * (DEVICE_GATEWAY_ENABLED). When the feature is off or the endpoint
   * doesn't exist for a given agent, the server returns 401 or 404.
   * The base class re-throws AuthenticationError as fatal — which kills
   * the entire compile/sync flow for ALL primitives, not just devices.
   *
   * Devices are an optional primitive. A missing or inaccessible device
   * endpoint should not block compiling skills, webhooks, or anything
   * else. We catch all errors and return empty server state.
   */
  async fetchServerState(apiKey: string, agentId: string): Promise<ServerSyncData> {
    try {
      const api = this.getApi(apiKey, agentId);
      const serverItems = await this.fetchFromServer(api);
      return { serverItems };
    } catch {
      // Silently degrade — device sync is optional.
      return { serverItems: null };
    }
  }

  protected async fetchFromServer(api: DeviceApi): Promise<any[] | null> {
    const response = await api.getDevices();
    if (!response.success || !response.data?.devices) {
      return null;
    }
    return response.data.devices;
  }

  protected async createOnServer(api: DeviceApi, primitive: ManifestPrimitive): Promise<string | null> {
    const device = primitive as ManifestDevice;
    const response = await api.createDevice({
      name: primitive.name,
      description: primitive.description || `A Lua device for ${primitive.name}`,
      group: device.group,
    });
    if (!response.success || !response.data?.id) return null;
    return response.data.id;
  }

  isActive(serverItem: any): boolean {
    return serverItem.active !== false;
  }

  async pushToServer(apiKey: string, agentId: string, entityId: string, pushData: PushDeviceVersionDTO) {
    const api = this.getApi(apiKey, agentId);
    const response = await api.pushDevice(entityId, { ...pushData, deviceId: entityId });
    return { success: response.success, error: response.error?.message };
  }

  async publishVersion(apiKey: string, agentId: string, entityId: string, version: string) {
    const api = this.getApi(apiKey, agentId);
    const response = await api.publishDeviceVersion(entityId, version);
    return { success: response.success, error: response.error?.message };
  }

  /**
   * Override to include device commands, triggers, and artifact in push data.
   */
  protected buildPushData(
    primitive: ManifestPrimitive,
    compressedCode: string | undefined,
    codeS3Hash?: string
  ): Record<string, unknown> {
    const device = primitive as ManifestDevice;
    return {
      name: device.name,
      description: device.description,
      group: device.group,
      ...(codeS3Hash ? { codeS3Hash } : { code: compressedCode }),
      artifactHash: device.hash,
    };
  }
}

// Export singleton instance
export const deviceHandler = new DeviceHandler();
