/**
 * Tool compilation plugin.
 *
 * Three authoring shapes are detected:
 *   1. Function-based:       `const t = defineTool({ ... })`
 *   2. Class config:         `new LuaTool({ ... })`              (rare; symmetry with other primitives)
 *   3. Class-definition:     `class MyTool extends LuaTool { ... }`
 *                            `class MyTool extends SharedTool { ... }` (where SharedTool extends LuaTool)
 *                            `class MyTool implements LuaTool { ... }`
 *
 * Shape (3) walks the full `extends` chain via the shared
 * `class-hierarchy` helper, so a leaf class extending a shared base in
 * a workspace package is detected just like a direct subclass. Field
 * initializers on the leaf (`ragSearchPath = "/blk/search"`) provide
 * the canonical override mechanism — JS handles inheritance natively
 * during construction.
 */

import { SourceFile, Project, Node, ObjectLiteralExpression, ClassDeclaration } from 'ts-morph';
import {
  type ToolMetadata,
  type ToolMetadataFields,
  type ValidationResult,
  type SchemaSet,
  type CompiledPrimitive,
  type ManifestPrimitive,
  type ManifestTool,
  type PrimitiveMetadata,
} from '../types.js';
import {
  BasePlugin,
  readStringMember,
  deriveNameFromClassName,
  locateClassDefinition,
  validationError,
  validationWarning,
} from './base.js';
import { extractSchemaProperty } from '../utils/ast-helpers.js';
import { findClassMember } from '../utils/class-hierarchy.js';
import { zodToJsonSchema } from '../utils/schema-converter.js';

/**
 * Plugin for compiling tool primitives.
 */
export class ToolPlugin extends BasePlugin<ToolMetadataFields> {
  readonly kind = 'tool';
  readonly displayName = 'Tool';
  readonly defineFunction = 'defineTool';
  readonly legacyClassNames = ['LuaTool'];

  protected readonly supportsClassDefinition = true;

  /**
   * Extract metadata from a `defineTool({...})` / `new LuaTool({...})`
   * config object literal. (Class-definition shape is handled by the
   * inherited `extractFromClassDefinition` override below.)
   */
  protected extractFromConfig(
    config: ObjectLiteralExpression,
    exportName: string,
    sourcePath: string,
    position: { line: number; column: number },
    pattern: 'function' | 'class'
  ): ToolMetadata | null {
    const common = this.extractCommonFields(config, exportName, sourcePath, position);
    if (!common) return null;

    return {
      kind: this.kind,
      ...common,
      metadata: {
        pattern,
        hasInputSchema: config.getProperty('inputSchema') !== undefined,
        hasCondition: config.getProperty('condition') !== undefined,
        hasExecute: config.getProperty('execute') !== undefined,
      },
    };
  }

  /**
   * Tool-specific class-definition extraction.
   *
   * Reads `name` / `description` / has* flags off the full inheritance
   * chain via `findClassMember`, so a leaf that only declares
   * `ragSearchPath = "/blk/search"` still inherits a parent's
   * `inputSchema`/`execute`/`description`.
   */
  protected extractFromClassDefinition(classDecl: ClassDeclaration, sourceFile: SourceFile): ToolMetadata | null {
    const className = classDecl.getName();
    if (!className) return null;

    const isDefaultExport = classDecl.isDefaultExport();
    const exportName = isDefaultExport ? 'default' : className;

    const name = readStringMember(classDecl, 'name') ?? deriveNameFromClassName(className);
    const description = readStringMember(classDecl, 'description') ?? '';

    const hasInputSchema = findClassMember(classDecl, 'inputSchema', 'property') !== undefined;
    const hasCondition = findClassMember(classDecl, 'condition', 'either') !== undefined;
    const hasExecute = findClassMember(classDecl, 'execute', 'either') !== undefined;

    return {
      kind: this.kind,
      name,
      description,
      sourcePath: sourceFile.getFilePath(),
      exportName,
      isDefaultExport,
      line: classDecl.getStartLineNumber(),
      column: 1,
      metadata: {
        pattern: 'class-definition',
        className,
        hasInputSchema,
        hasCondition,
        hasExecute,
      },
    };
  }

  validate(metadata: ToolMetadata): ValidationResult {
    const { errors, warnings } = this.baseValidation(metadata);

    if (!metadata.metadata.hasExecute) {
      errors.push(
        validationError('Tool must have an execute function', {
          line: metadata.line,
          suggestion: 'Add an execute function: execute: async (input, context) => { ... }',
        })
      );
    }

    if (!metadata.metadata.hasInputSchema) {
      warnings.push(
        validationWarning('Tool should have an inputSchema for type safety', {
          line: metadata.line,
          suggestion: 'Add a schema: inputSchema: z.object({ ... })',
        })
      );
    }

    if (metadata.name && !/^[a-z][a-z0-9-_]*$/.test(metadata.name)) {
      warnings.push(
        validationWarning('Tool name should be lowercase with hyphens or underscores', { line: metadata.line })
      );
    }

    return { valid: errors.length === 0, errors, warnings };
  }

  /**
   * Project the class instance onto the standard tool primitive shape.
   * Binds `execute` / `condition` to the instance so `this` references
   * (incl. inherited fields like `ragSearchPath`) resolve correctly.
   */
  protected getClassDefinitionPrimitiveShape(metadata: ToolMetadata): string {
    return `{
    kind: 'tool',
    name: __lua_instance__.name ?? ${JSON.stringify(metadata.name)},
    description: __lua_instance__.description ?? ${JSON.stringify(metadata.description)},
    inputSchema: __lua_instance__.inputSchema,
    execute: typeof __lua_instance__.execute === 'function' ? __lua_instance__.execute.bind(__lua_instance__) : undefined,
    condition: typeof __lua_instance__.condition === 'function' ? __lua_instance__.condition.bind(__lua_instance__) : undefined,
  }`;
  }

  /**
   * Runtime validation — every tool entry-point must produce a callable
   * `execute`. The check is shape-only; argument validation happens at
   * call time via the inputSchema.
   */
  protected getRuntimeValidation(): string {
    return `
  if (typeof primitive.primitive?.execute !== 'function') {
    throw new Error('[Lua] Invalid tool artifact: execute is not a function');
  }`;
  }

  async extractSchemas(metadata: ToolMetadata, project: Project): Promise<SchemaSet | undefined> {
    if (!metadata.metadata.hasInputSchema) return undefined;

    const sourceFile = project.getSourceFile(metadata.sourcePath);
    if (!sourceFile) return undefined;

    let schemaNode: Node | undefined;

    const pattern = metadata.metadata.pattern;
    if ((pattern === 'class' || pattern === 'class-definition') && metadata.metadata.className) {
      const classDecl =
        pattern === 'class-definition'
          ? locateClassDefinition(sourceFile, metadata.exportName)
          : sourceFile.getClass(metadata.metadata.className);
      if (!classDecl) return undefined;

      // For class-definition shape, walk the chain — parent may
      // declare `inputSchema` while the leaf only overrides config.
      const hit = findClassMember(classDecl, 'inputSchema', 'property');
      if (!hit || !Node.isPropertyDeclaration(hit.node)) return undefined;
      schemaNode = hit.node.getInitializer();
    } else {
      // Function-based: const x = defineTool({ inputSchema: z.object(...) })
      const varDecl = sourceFile.getVariableDeclaration(metadata.exportName);
      if (!varDecl) return undefined;

      const initializer = varDecl.getInitializer();
      if (!initializer || !Node.isCallExpression(initializer)) return undefined;

      const args = initializer.getArguments();
      if (args.length === 0) return undefined;

      const config = args[0];
      if (!Node.isObjectLiteralExpression(config)) return undefined;

      schemaNode = extractSchemaProperty(config, 'inputSchema');
    }

    if (!schemaNode) return undefined;

    try {
      const jsonSchema = await zodToJsonSchema(schemaNode);
      return { input: jsonSchema };
    } catch (error) {
      console.warn(`Warning: Could not convert schema for ${metadata.name}:`, error);
      return undefined;
    }
  }

  toManifestEntry(compiled: CompiledPrimitive, _allPrimitives?: CompiledPrimitive[]): ManifestPrimitive {
    return {
      ...this.baseManifestFields(compiled),
      hasCondition: (compiled.metadata as ToolMetadataFields)?.hasCondition || false,
      schemas: compiled.schemas
        ? {
            input: compiled.schemas.input,
            output: compiled.schemas.output,
          }
        : undefined,
    } as ManifestTool;
  }
}
