/**
 * Skills Command
 * Manages agent skills for sandbox and production environments
 */

import { withErrorHandling, writeProgress, writeSuccess, writeInfo, writeHintBlock } from '../utils/cli.js';
import { readYamlConfig } from '../utils/files.js';
import { BASE_URLS } from '../config/constants.js';
import { safePrompt } from '../utils/prompt-handler.js';
import { initializeCommand } from '../utils/command-utils.js';
import SkillApi from '../api/skills.api.service.js';
import { skillHandler } from '../primitives/skill.handler.js';
import { YamlConfig } from '../types/yaml.types.js';
import { trackEvent } from '../services/analytics.js';
import { validateOrSuggest } from '../utils/aliases.js';

interface SkillsCommandContext {
  environment: 'sandbox' | 'production';
  agentId: string;
  apiKey: string;
}

interface SkillsOptions {
  skillName?: string;
  skillVersion?: string;
}

type SkillAction = 'view' | 'versions' | 'deploy' | 'delete';

// ─────────────────────────────────────────────────────────────────────────────
// Main Command Entry
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Main skills command - manages agent skills.
 *
 * Supports both interactive and non-interactive modes:
 * - Interactive: prompts for environment and action
 * - Non-interactive: use action argument with -i and -v flags
 */
export async function skillsCommand(actionOrEnv?: string, actionArg?: string, cmdObj?: any): Promise<void> {
  return withErrorHandling(async () => {
    const options: SkillsOptions = {
      skillName: cmdObj?.skillName || null,
      skillVersion: cmdObj?.skillVersion || null,
    };

    // Initialize command (validates config + auth)
    const { config, agentId, apiKey } = await initializeCommand();

    if (actionOrEnv) {
      const normalized = validateOrSuggest('skills.actionOrEnv', actionOrEnv);
      const envSet = new Set(['sandbox', 'production']);

      // Check if it's an environment selection
      if (envSet.has(normalized)) {
        const selectedEnvironment = normalized as 'sandbox' | 'production';
        const context: SkillsCommandContext = {
          environment: selectedEnvironment,
          agentId,
          apiKey,
        };

        let resolvedAction = actionArg;
        if (resolvedAction) {
          resolvedAction = validateOrSuggest('skills.action', resolvedAction);
        }

        if (selectedEnvironment === 'sandbox') {
          if (resolvedAction === 'view') {
            // Non-interactive: list local skills and exit
            const skills = config.skills || [];
            if (skills.length === 0) {
              console.log('ℹ️  No skills found in configuration.');
            } else {
              for (const skill of skills) {
                console.log(`📦 ${skill.name}  v${skill.version}  (${skill.skillId})`);
              }
            }
            return;
          }
          await manageSandboxSkillsInteractive(context, config);
        } else {
          await manageProductionSkillsInteractive(context, config);
        }
        trackEvent('cli_skills_action', {
          environment: selectedEnvironment,
          action: resolvedAction || 'interactive',
          non_interactive: true,
        });
        return;
      }

      // Otherwise it's a non-interactive action against production
      const context: SkillsCommandContext = {
        environment: 'production',
        agentId,
        apiKey,
      };
      await executeNonInteractive(context, config, normalized, options);
      trackEvent('cli_skills_action', {
        environment: 'production',
        action: normalized,
        skill_name: options.skillName || null,
        non_interactive: true,
      });
      return;
    }

    // Interactive mode - prompt for environment
    const envAnswer = await safePrompt<{ environment: string }>([
      {
        type: 'list',
        name: 'environment',
        message: 'Select environment:',
        choices: [
          { name: '🔧 Sandbox (local skills)', value: 'sandbox' },
          { name: '🚀 Production (deployed skills)', value: 'production' },
        ],
      },
    ]);

    if (!envAnswer) return;

    const context: SkillsCommandContext = {
      environment: envAnswer.environment as 'sandbox' | 'production',
      agentId,
      apiKey,
    };

    if (context.environment === 'sandbox') {
      await manageSandboxSkillsInteractive(context, config);
    } else {
      await manageProductionSkillsInteractive(context, config);
    }
    trackEvent('cli_skills_action', {
      environment: context.environment,
      action: 'interactive',
      non_interactive: false,
    });
  }, 'skills');
}

// ─────────────────────────────────────────────────────────────────────────────
// Shared Core Functions
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Displays all skills with their current status.
 */
async function displaySkillsCore(context: SkillsCommandContext, skills: any[]): Promise<void> {
  console.log('\n' + '='.repeat(60));
  console.log('⚙️  Production Skills');
  console.log('='.repeat(60) + '\n');

  const skillApi = new SkillApi(BASE_URLS.API, context.apiKey, context.agentId);

  for (const skill of skills) {
    try {
      const response = await skillApi.getSkillVersions(skill.skillId);

      if (response.success && response.data) {
        const versions = response.data.versions || [];
        const activeVersion = versions.find((v: any) => v.isCurrent === true);

        console.log(`📦 ${skill.name}`);
        console.log(`   Skill ID: ${skill.skillId}`);

        if (activeVersion) {
          console.log(`   Deployed Version: ${activeVersion.version} ⭐`);
          const dateStr = activeVersion.createdDate ? new Date(activeVersion.createdDate).toLocaleString() : 'Unknown';
          console.log(`   Deployed: ${dateStr}`);
        } else {
          console.log(`   Deployed Version: Not deployed`);
        }

        console.log(`   Total Versions: ${versions.length}`);
        console.log();
      } else {
        displaySkillError(skill, 'Unable to fetch version info');
      }
    } catch {
      displaySkillError(skill, 'Error loading versions');
    }
  }

  console.log('='.repeat(60));
}

function displaySkillError(skill: any, status: string): void {
  console.log(`📦 ${skill.name}`);
  console.log(`   Skill ID: ${skill.skillId}`);
  console.log(`   Status: ${status}`);
  console.log();
}

/**
 * Fetches and returns sorted skill versions.
 */
async function fetchVersionsCore(
  context: SkillsCommandContext,
  skill: any
): Promise<{ versions: any[]; activeVersionId: string } | null> {
  const skillApi = new SkillApi(BASE_URLS.API, context.apiKey, context.agentId);
  const response = await skillApi.getSkillVersions(skill.skillId);

  if (!response.success || !response.data) {
    console.error(`❌ Failed to fetch versions: ${response.error?.message || 'Unknown error'}`);
    return null;
  }

  const versions = (response.data.versions || []).sort(
    (a: any, b: any) => new Date(b.createdDate || 0).getTime() - new Date(a.createdDate || 0).getTime()
  );

  return { versions, activeVersionId: response.data.activeVersionId || '' };
}

/**
 * Displays versions for a skill.
 */
function displayVersionsCore(skill: any, versions: any[], activeVersionId: string): void {
  console.log('\n' + '='.repeat(60));
  console.log(`📜 Versions for ${skill.name}`);
  console.log('='.repeat(60) + '\n');

  versions.forEach((version: any, index: number) => {
    const isActive = version.isCurrent === true;
    console.log(`${index + 1}. Version ${version.version}${isActive ? ' ⭐ DEPLOYED' : ''}`);
    console.log(`   Created: ${version.createdDate ? new Date(version.createdDate).toLocaleString() : 'Unknown'}`);
    if (version.createdByFullName) {
      console.log(`   Created by: ${version.createdByFullName}`);
    }
    console.log();
  });

  console.log('='.repeat(60));
}

/**
 * Deploys a specific version of a skill.
 */
async function deployVersionCore(context: SkillsCommandContext, skill: any, version: string): Promise<boolean> {
  writeProgress(`🔄 Deploying version ${version} of "${skill.name}"...`);

  const skillApi = new SkillApi(BASE_URLS.API, context.apiKey, context.agentId);
  const response = await skillApi.publishSkillVersion(skill.skillId, version);

  if (!response.success) {
    console.error(`❌ Deploy Error: ${response.error?.message || 'Unknown error'}`);
    return false;
  }

  writeSuccess(`✅ Version ${version} of "${skill.name}" deployed successfully`);
  writeHintBlock({
    headline: 'Skill is live. Generate traffic to see it in action:',
    lines: [
      { label: 'Test:', command: 'lua chat -e production -m "trigger your skill"' },
      { label: 'Inspect:', command: `lua logs --type skill --name ${skill.name} --limit 10` },
    ],
    when: 'success',
  });
  return true;
}

/**
 * Deletes a skill from the server.
 * If the skill has versions, it will be deactivated instead of deleted.
 */
async function deleteSkillCore(context: SkillsCommandContext, skill: any): Promise<boolean> {
  writeProgress(`🗑️  Deleting skill "${skill.name}"...`);

  const skillApi = new SkillApi(BASE_URLS.API, context.apiKey, context.agentId);
  const response = await skillApi.deleteSkill(skill.skillId);

  if (!response.success || !response.data) {
    console.error(`❌ Delete Error: ${response.error?.message || 'Unknown error'}`);
    return false;
  }

  if (response.data.deleted) {
    writeSuccess(`✅ Skill "${skill.name}" deleted successfully`);
    writeInfo('💡 Remove this skill from your lua.skill.yaml to keep it in sync.');
  } else if (response.data.deactivated) {
    writeSuccess(`⚠️  Skill "${skill.name}" has versions and was deactivated instead of deleted`);
    writeInfo("💡 The skill is now inactive and won't be available to the agent.");
  }

  return true;
}

/**
 * Resolves a version string to an actual version, supporting "latest".
 */
function resolveVersion(versions: any[], versionArg: string): string | null {
  if (versionArg.toLowerCase() === 'latest') {
    return versions[0].version;
  }

  const exists = versions.some((v: any) => v.version === versionArg);
  if (!exists) {
    console.error(`❌ Version "${versionArg}" not found`);
    console.log('\nAvailable versions:');
    versions.slice(0, 5).forEach((v: any) => console.log(`  - ${v.version}`));
    return null;
  }
  return versionArg;
}

/**
 * Prompts user to select a skill from a list.
 */
async function promptSkillSelection(skills: any[], message: string): Promise<any | null> {
  const answer = await safePrompt<{ selectedSkill: any }>([
    {
      type: 'list',
      name: 'selectedSkill',
      message,
      choices: skills.map((skill: any) => ({
        name: `${skill.name} (${skill.skillId})`,
        value: skill,
      })),
    },
  ]);
  return answer?.selectedSkill || null;
}

/**
 * Prompts user to select a version from a list.
 */
async function promptVersionSelection(versions: any[], activeVersionId: string): Promise<any | null> {
  const answer = await safePrompt<{ selectedVersion: any }>([
    {
      type: 'list',
      name: 'selectedVersion',
      message: 'Select a version to deploy:',
      choices: versions.map((version: any) => {
        const isActive = version.isCurrent === true;
        const dateStr = version.createdDate ? new Date(version.createdDate).toLocaleDateString() : 'Unknown date';
        return {
          name: `Version ${version.version} (${dateStr})${isActive ? ' ⭐ CURRENT' : ''}`,
          value: version,
        };
      }),
    },
  ]);
  return answer?.selectedVersion || null;
}

// ─────────────────────────────────────────────────────────────────────────────
// Non-Interactive Mode
// ─────────────────────────────────────────────────────────────────────────────

async function executeNonInteractive(
  context: SkillsCommandContext,
  config: YamlConfig,
  action: string,
  options: SkillsOptions
): Promise<void> {
  const skills = config.skills || [];

  // View action doesn't require skill selection
  if (action === 'view') {
    if (skills.length === 0) {
      console.log('ℹ️  No skills found in configuration.');
      return;
    }
    await displaySkillsCore(context, skills);
    return;
  }

  // All other actions require skill selection
  if (!options.skillName) {
    console.error(`❌ --skill-name is required for action "${action}"`);
    console.log(`\nUsage: lua skills ${action} --skill-name <name>`);
    throw new Error(`--skill-name is required for action "${action}"`);
  }

  let selectedSkill = skills.find((s) => s.skillId === options.skillName || s.name === options.skillName);

  // For delete action, also check server skills (for orphaned skills not in local YAML)
  if (!selectedSkill && action === 'delete') {
    const skillApi = new SkillApi(BASE_URLS.API, context.apiKey, context.agentId);
    const serverResponse = await skillApi.getSkills();

    if (serverResponse.success && serverResponse.data?.skills) {
      const serverSkill = serverResponse.data.skills.find(
        (s) => s.id === options.skillName || s.name === options.skillName
      );
      if (serverSkill) {
        const activeVersion = serverSkill.versions.find((v) => v.active) ?? serverSkill.versions[0];
        selectedSkill = {
          name: serverSkill.name,
          skillId: serverSkill.id,
          version: activeVersion?.version ?? '',
        };
      }
    }
  }

  if (!selectedSkill) {
    console.error(`❌ Skill "${options.skillName}" not found`);
    console.log('\nAvailable skills in local config:');
    skills.forEach((s) => console.log(`  - ${s.name} (${s.skillId})`));
    if (action === 'delete') {
      console.log('\n💡 Tip: The skill may have already been deleted from the server.');
    }
    throw new Error(`Skill "${options.skillName}" not found`);
  }

  switch (action as SkillAction) {
    case 'versions': {
      const data = await fetchVersionsCore(context, selectedSkill);
      if (!data) throw new Error('Failed to fetch skill versions');
      if (data.versions.length === 0) {
        console.log(`ℹ️  No versions found for ${selectedSkill.name}.`);
        console.log("💡 Push a version first using 'lua push skill'.");
        return;
      }
      displayVersionsCore(selectedSkill, data.versions, data.activeVersionId);
      break;
    }
    case 'deploy': {
      if (!options.skillVersion) {
        console.error('❌ --skill-version is required for deploy action');
        console.log('\nUsage: lua skills deploy --skill-name mySkill --skill-version 1.0.3');
        console.log('       lua skills deploy -i mySkill -v latest');
        throw new Error('--skill-version is required for deploy action');
      }
      const data = await fetchVersionsCore(context, selectedSkill);
      if (!data) throw new Error('Failed to fetch skill versions');
      if (data.versions.length === 0) {
        console.error(`❌ No versions found for ${selectedSkill.name}.`);
        console.log("💡 Push a version first using 'lua push skill'.");
        throw new Error(`No versions found for ${selectedSkill.name}`);
      }
      const resolvedVersion = resolveVersion(data.versions, options.skillVersion);
      if (!resolvedVersion) throw new Error('Failed to resolve skill version');
      const success = await deployVersionCore(context, selectedSkill, resolvedVersion);
      if (!success) throw new Error('Failed to deploy skill version');
      break;
    }
    case 'delete': {
      const success = await deleteSkillCore(context, selectedSkill);
      if (!success) throw new Error('Failed to delete skill');
      break;
    }
  }
}

// ─────────────────────────────────────────────────────────────────────────────
// Interactive Mode
// ─────────────────────────────────────────────────────────────────────────────

async function manageSandboxSkillsInteractive(context: SkillsCommandContext, config: YamlConfig): Promise<void> {
  let continueManaging = true;

  while (continueManaging) {
    console.log('\n' + '='.repeat(60));
    console.log('🔧 Sandbox Skills');
    console.log('='.repeat(60) + '\n');

    const skills = config.skills || [];

    if (skills.length === 0) {
      console.log('ℹ️  No skills found in configuration.');
      console.log("💡 Run 'lua compile' to add skills to your configuration.\n");
    } else {
      console.log('Local skills in lua.skill.yaml:\n');
      skills.forEach((skill: any, index: number) => {
        console.log(`${index + 1}. 📦 ${skill.name}`);
        console.log(`   Version: ${skill.version}`);
        console.log(`   Skill ID: ${skill.skillId}`);
        console.log();
      });
    }

    const actionAnswer = await safePrompt<{ action: string }>([
      {
        type: 'list',
        name: 'action',
        message: 'What would you like to do?',
        choices: [
          { name: '🔄 Refresh list', value: 'refresh' },
          { name: '📦 Compile skills', value: 'compile' },
          { name: '☁️  Push a skill', value: 'push' },
          { name: '❌ Exit', value: 'exit' },
        ],
      },
    ]);

    if (!actionAnswer) return;
    const { action } = actionAnswer;

    switch (action) {
      case 'refresh':
        const newConfig = readYamlConfig();
        if (newConfig) {
          config.skills = newConfig.skills;
        }
        break;
      case 'compile':
        console.log("\n💡 Run 'lua compile' in your terminal to compile your skills.\n");
        await safePrompt([{ type: 'input', name: 'continue', message: 'Press Enter to continue...' }]);
        break;
      case 'push':
        console.log("\n💡 Run 'lua push skill' in your terminal to push a skill.\n");
        await safePrompt([{ type: 'input', name: 'continue', message: 'Press Enter to continue...' }]);
        break;
      case 'exit':
        continueManaging = false;
        console.log('\n👋 Goodbye!\n');
        break;
    }
  }
}

async function manageProductionSkillsInteractive(context: SkillsCommandContext, config: YamlConfig): Promise<void> {
  let continueManaging = true;

  while (continueManaging) {
    console.log('\n' + '='.repeat(60));
    console.log('🚀 Production Skills');
    console.log('='.repeat(60) + '\n');

    const actionAnswer = await safePrompt<{ action: string }>([
      {
        type: 'list',
        name: 'action',
        message: 'What would you like to do?',
        choices: [
          { name: '👁️  View deployed skills', value: 'view' },
          { name: '📜 View skill versions', value: 'versions' },
          { name: '🚀 Deploy a version', value: 'deploy' },
          { name: '🗑️  Delete a skill', value: 'delete' },
          { name: '❌ Exit', value: 'exit' },
        ],
      },
    ]);

    if (!actionAnswer) return;
    const { action } = actionAnswer;

    switch (action) {
      case 'view':
        await viewSkillsInteractive(context, config);
        break;
      case 'versions':
        await viewVersionsInteractive(context, config);
        break;
      case 'deploy':
        await deployVersionInteractive(context, config);
        break;
      case 'delete':
        await deleteSkillInteractive(context, config);
        break;
      case 'exit':
        continueManaging = false;
        console.log('\n👋 Goodbye!\n');
        break;
    }
  }
}

async function viewSkillsInteractive(context: SkillsCommandContext, config: YamlConfig): Promise<void> {
  writeProgress('🔄 Loading skill information...');
  const skills = config.skills || [];

  if (skills.length === 0) {
    console.log('\nℹ️  No skills found in configuration.\n');
  } else {
    await displaySkillsCore(context, skills);
    console.log();
  }

  await safePrompt([{ type: 'input', name: 'continue', message: 'Press Enter to continue...' }]);
}

async function viewVersionsInteractive(context: SkillsCommandContext, config: YamlConfig): Promise<void> {
  const skills = config.skills || [];

  if (skills.length === 0) {
    console.log('\nℹ️  No skills found in configuration.\n');
    await safePrompt([{ type: 'input', name: 'continue', message: 'Press Enter to continue...' }]);
    return;
  }

  const selectedSkill = await promptSkillSelection(skills, 'Select a skill to view versions:');
  if (!selectedSkill) return;

  writeProgress(`🔄 Loading versions for ${selectedSkill.name}...`);
  const data = await fetchVersionsCore(context, selectedSkill);

  if (!data) {
    await safePrompt([{ type: 'input', name: 'continue', message: 'Press Enter to continue...' }]);
    return;
  }

  if (data.versions.length === 0) {
    console.log(`\nℹ️  No versions found for ${selectedSkill.name}.\n`);
    console.log("💡 Push a version first using 'lua push skill'.\n");
  } else {
    displayVersionsCore(selectedSkill, data.versions, data.activeVersionId);
    console.log();
  }

  await safePrompt([{ type: 'input', name: 'continue', message: 'Press Enter to continue...' }]);
}

async function deployVersionInteractive(context: SkillsCommandContext, config: YamlConfig): Promise<void> {
  const skills = config.skills || [];

  if (skills.length === 0) {
    console.log('\nℹ️  No skills found in configuration.\n');
    await safePrompt([{ type: 'input', name: 'continue', message: 'Press Enter to continue...' }]);
    return;
  }

  const selectedSkill = await promptSkillSelection(skills, 'Select a skill to deploy:');
  if (!selectedSkill) return;

  writeProgress(`🔄 Loading versions for ${selectedSkill.name}...`);
  const data = await fetchVersionsCore(context, selectedSkill);

  if (!data) {
    await safePrompt([{ type: 'input', name: 'continue', message: 'Press Enter to continue...' }]);
    return;
  }

  if (data.versions.length === 0) {
    console.log(`\nℹ️  No versions found for ${selectedSkill.name}.\n`);
    console.log("💡 Push a version first using 'lua push skill'.\n");
    await safePrompt([{ type: 'input', name: 'continue', message: 'Press Enter to continue...' }]);
    return;
  }

  const selectedVersion = await promptVersionSelection(data.versions, data.activeVersionId);
  if (!selectedVersion) return;

  // Show warning and confirm
  console.log('\n⚠️  WARNING: You are about to deploy to PRODUCTION!');
  console.log('⚠️  This will affect ALL users immediately.\n');
  console.log(`Skill: ${selectedSkill.name}`);
  console.log(`Version: ${selectedVersion.version}\n`);

  const confirmAnswer = await safePrompt<{ confirm: boolean }>([
    {
      type: 'confirm',
      name: 'confirm',
      message: 'Are you absolutely sure you want to deploy this version?',
      default: false,
    },
  ]);

  if (!confirmAnswer || !confirmAnswer.confirm) {
    console.log('\n❌ Deployment cancelled.\n');
    return;
  }

  await deployVersionCore(context, selectedSkill, selectedVersion.version);
  await safePrompt([{ type: 'input', name: 'continue', message: 'Press Enter to continue...' }]);
}

async function deleteSkillInteractive(context: SkillsCommandContext, config: YamlConfig): Promise<void> {
  const { merged, orphanIds, serverFailed } = await skillHandler.fetchMergedForInteraction(
    context.apiKey,
    context.agentId,
    config
  );
  if (serverFailed) {
    console.log('\n⚠️  Could not reach server. Showing local items only.\n');
  }

  if (merged.length === 0) {
    console.log('\nℹ️  No skills found in configuration.\n');
    await safePrompt([{ type: 'input', name: 'continue', message: 'Press Enter to continue...' }]);
    return;
  }

  const answer = await safePrompt<{ selected: (typeof merged)[number] }>([
    {
      type: 'list',
      name: 'selected',
      message: 'Select a skill to delete:',
      choices: merged.map((item) => ({
        name: orphanIds.has(item.skillId)
          ? `${item.name} (${item.skillId}) [server only]`
          : `${item.name} (${item.skillId})`,
        value: item,
      })),
    },
  ]);
  const selectedSkill = answer?.selected ?? null;
  if (!selectedSkill) return;

  // Show warning and confirm
  console.log('\n⚠️  WARNING: You are about to delete a skill!');
  console.log('⚠️  If the skill has versions, it will be deactivated instead.\n');
  console.log(`Skill: ${selectedSkill.name}`);
  console.log(`Skill ID: ${selectedSkill.skillId}\n`);

  const confirmAnswer = await safePrompt<{ confirm: boolean }>([
    {
      type: 'confirm',
      name: 'confirm',
      message: 'Are you sure you want to delete this skill?',
      default: false,
    },
  ]);

  if (!confirmAnswer || !confirmAnswer.confirm) {
    console.log('\n❌ Deletion cancelled.\n');
    return;
  }

  await deleteSkillCore(context, selectedSkill);
  await safePrompt([{ type: 'input', name: 'continue', message: 'Press Enter to continue...' }]);
}
