/**
 * Primitive Handlers Registry
 *
 * Central export point for all primitive handlers.
 * Provides type-safe access to handlers by primitive kind.
 */

import { PrimitiveKind } from '../compiler/types.js';
import { isVersionedHandler, type PrimitiveHandler, type VersionedPrimitiveHandler, type SyncResult } from './types.js';

// Import all handlers
import { skillHandler, SkillHandler } from './skill.handler.js';
import { webhookHandler, WebhookHandler } from './webhook.handler.js';
import { jobHandler, JobHandler } from './job.handler.js';
import { preprocessorHandler, PreprocessorHandler } from './preprocessor.handler.js';
import { postprocessorHandler, PostprocessorHandler } from './postprocessor.handler.js';
import { mcpServerHandler, MCPServerHandler } from './mcp-server.handler.js';
import { deviceHandler, DeviceHandler } from './device.handler.js';
import { deviceTriggerHandler, DeviceTriggerHandler } from './device-trigger.handler.js';
import { voiceHandler, VoiceHandler } from './voice.handler.js';

// Re-export types and helpers
export {
  isVersionedHandler,
  type PrimitiveHandler,
  type VersionedPrimitiveHandler,
  type SyncResult,
  type YamlPrimitiveConfig,
} from './types.js';

// Re-export handler classes (for testing/extension)
export { SkillHandler } from './skill.handler.js';
export { WebhookHandler } from './webhook.handler.js';
export { JobHandler } from './job.handler.js';
export { PreprocessorHandler } from './preprocessor.handler.js';
export { PostprocessorHandler } from './postprocessor.handler.js';
export { MCPServerHandler } from './mcp-server.handler.js';
export { DeviceHandler } from './device.handler.js';
export { DeviceTriggerHandler } from './device-trigger.handler.js';
export { VoiceHandler } from './voice.handler.js';

// Re-export singleton instances
export { skillHandler } from './skill.handler.js';
export { webhookHandler } from './webhook.handler.js';
export { jobHandler } from './job.handler.js';
export { preprocessorHandler } from './preprocessor.handler.js';
export { postprocessorHandler } from './postprocessor.handler.js';
export { mcpServerHandler } from './mcp-server.handler.js';
export { deviceHandler } from './device.handler.js';
export { deviceTriggerHandler } from './device-trigger.handler.js';
export { voiceHandler } from './voice.handler.js';

/**
 * Map of primitive handlers by kind.
 * Note: TOOL kind has no handler — tools are managed as part of skills.
 */
export const primitiveHandlers: Partial<Record<PrimitiveKind, PrimitiveHandler>> = {
  [PrimitiveKind.SKILL]: skillHandler,
  [PrimitiveKind.WEBHOOK]: webhookHandler,
  [PrimitiveKind.JOB]: jobHandler,
  [PrimitiveKind.PREPROCESSOR]: preprocessorHandler,
  [PrimitiveKind.POSTPROCESSOR]: postprocessorHandler,
  [PrimitiveKind.MCP_SERVER]: mcpServerHandler,
  [PrimitiveKind.DEVICE]: deviceHandler,
  [PrimitiveKind.DEVICE_TRIGGER]: deviceTriggerHandler,
  [PrimitiveKind.VOICE]: voiceHandler,
};

/**
 * Get a primitive handler by kind.
 *
 * @param kind - Primitive kind
 * @returns Handler or undefined if not found (e.g., TOOL has no handler)
 */
export function getHandler(kind: PrimitiveKind): PrimitiveHandler | undefined {
  return primitiveHandlers[kind];
}

/**
 * Get the skill handler (typed for manifest sync support)
 */
export function getSkillHandler(): SkillHandler {
  return skillHandler;
}

/**
 * All versioned primitive handlers (derived from primitiveHandlers map).
 */
export const versionedHandlers: VersionedPrimitiveHandler[] = Object.values(primitiveHandlers).filter(
  (h): h is VersionedPrimitiveHandler => isVersionedHandler(h!)
);

/**
 * All primitive handlers that support sync (derived from primitiveHandlers map).
 */
export const syncableHandlers: PrimitiveHandler[] = Object.values(primitiveHandlers) as PrimitiveHandler[];
