// ============================================================================
// Shared Push Options Type
// ============================================================================

interface PushOptions {
  force?: boolean;
  autoDeploy?: boolean;
  entityName?: string | null;
  version?: string | null;
  /**
   * `lua push backup --fresh`: build the backup manifest by walking disk
   * instead of trusting the compiled dist-v2/manifest.json. Ignored for
   * non-backup push types.
   */
  fresh?: boolean;
  /**
   * After the per-agent backup succeeds, also attach the workspace archive
   * to each pushed skill version on the canonical per-skill source store so
   * the admin Builder UI's source panel reflects this CLI edit.
   *
   * **Default: `true`** (the attach runs automatically). Pass
   * `--no-include-source` to skip the attach — useful for fast publish
   * loops or CI environments where the admin Builder UI is irrelevant.
   *
   * The attach is non-fatal: a failure here logs a warning but doesn't
   * fail the push, because the primitive is already deployed and the
   * per-agent backup already succeeded. The per-skill source store is a
   * denormalized UI projection, not the canonical store.
   */
  includeSource?: boolean;
}

