/**
 * Logs API Service
 * Handles log retrieval for agents and skills
 */

import { HttpClient } from './http.client.js';
import { ApiResponse } from '../interfaces/common.js';
import { LogsResponse } from '../interfaces/logs.js';
import { AGENT_LOG_SOURCES } from '@lua/shared-types';
import type { AgentLogSource } from '@lua/shared-types';

export { AGENT_LOG_SOURCES };
export type { AgentLogSource };

export default class LogsApi extends HttpClient {
  private apiKey: string;

  /**
   * Creates an instance of LogsApi
   * @param baseUrl - The base URL for the API
   * @param apiKey - The API key for authentication
   */
  constructor(baseUrl: string, apiKey: string) {
    super(baseUrl);
    this.apiKey = apiKey;
  }

  /**
   * Retrieves logs for an agent
   * @param agentId - The ID of the agent
   * @param limit - Number of logs per page (default: 20)
   * @param page - Page number (default: 1)
   * @param filters - Optional filters to narrow log results
   * @returns Promise resolving to an ApiResponse containing logs and pagination
   */
  async getAgentLogs(
    agentId: string,
    limit: number,
    page: number,
    filters: {
      logSource?: AgentLogSource;
      primitiveId?: string;
      primitiveName?: string;
      toolId?: string;
      toolName?: string;
      logType?: string;
      userId?: string;
    } = {}
  ): Promise<ApiResponse<LogsResponse>> {
    const queryParams = new URLSearchParams({
      limit: limit.toString(),
      page: page.toString(),
    });

    if (filters.logSource) queryParams.append('logSource', filters.logSource);
    if (filters.primitiveId) queryParams.append('primitiveId', filters.primitiveId);
    if (filters.primitiveName) queryParams.append('primitiveName', filters.primitiveName);
    if (filters.toolId) queryParams.append('toolId', filters.toolId);
    if (filters.toolName) queryParams.append('toolName', filters.toolName);
    if (filters.logType) queryParams.append('logType', filters.logType);
    if (filters.userId) queryParams.append('userId', filters.userId);

    return this.httpGet<LogsResponse>(`/developer/agents/${agentId}/logs?${queryParams.toString()}`, {
      Authorization: `Bearer ${this.apiKey}`,
    });
  }
}
