/**
 * Browser try-page for `lua voice`. Spins up a local HTTP server,
 * serves a Lua-branded HTML page that uses the LiveKit JS SDK to
 * attach to the dispatched room, and opens it via `open`. The wss URL
 * + token are injected server-side into the page (not in the query
 * string) so the browser's URL bar stays clean.
 *
 * Lifecycle: server stays up until either the page POSTs /end (user
 * clicked the End-call button) or the 1h safety timeout fires. Both
 * paths close the server cleanly so the CLI exits.
 */

import http from 'http';
import { AddressInfo } from 'net';
import open from 'open';
import { writeSuccess } from '../utils/cli.js';
import { parseJoinUrl } from './voice-shared.js';

const SAFETY_TIMEOUT_MS = 60 * 60 * 1000;

export async function runBrowserMode(joinUrl: string): Promise<void> {
  const { wsUrl, token } = parseJoinUrl(joinUrl);
  const html = renderTryPage(wsUrl, token);

  const server = http.createServer((req, res) => {
    const url = req.url ?? '/';
    if (url === '/' || url.startsWith('/?')) {
      res.writeHead(200, {
        'Content-Type': 'text/html; charset=utf-8',
        'Cache-Control': 'no-store',
      });
      res.end(html);
      return;
    }
    if (url === '/end' && req.method === 'POST') {
      res.writeHead(204);
      res.end();
      // Defer close so the response actually flushes before the socket dies.
      setTimeout(() => server.close(), 50);
      return;
    }
    res.writeHead(404);
    res.end();
  });

  await new Promise<void>((resolve, reject) => {
    server.once('error', reject);
    server.listen(0, '127.0.0.1', () => resolve());
  });

  const { port } = server.address() as AddressInfo;
  const localUrl = `http://localhost:${port}/`;

  writeSuccess(`Voice room ready (opening browser)`);
  console.log(`   ${localUrl}`);
  await open(localUrl);

  await new Promise<void>((resolve) => {
    const safety = setTimeout(() => {
      try {
        server.close();
      } catch {
        /* already closed */
      }
    }, SAFETY_TIMEOUT_MS);
    safety.unref();
    server.on('close', () => resolve());
  });
}

function renderTryPage(wsUrl: string, token: string): string {
  // JSON.stringify escapes both for safe embedding inside a <script> body.
  // The LiveKit JS SDK is loaded from jsDelivr — localhost page so no
  // offline concerns, and bundling it would inflate the CLI tarball ~600 KB.
  const wsLiteral = JSON.stringify(wsUrl);
  const tokenLiteral = JSON.stringify(token);
  return `<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <title>Lua Voice — Try</title>
  <meta name="viewport" content="width=device-width, initial-scale=1" />
  <style>
    *, *::before, *::after { box-sizing: border-box; }
    html, body { height: 100%; margin: 0; }
    body {
      font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', system-ui, sans-serif;
      background: radial-gradient(circle at 30% 20%, #1a1830 0%, #0a0a14 60%);
      color: #eaeaea;
      display: flex;
      align-items: center;
      justify-content: center;
      padding: 24px;
    }
    .card {
      background: rgba(22, 22, 30, 0.85);
      border: 1px solid #2a2a35;
      border-radius: 16px;
      padding: 36px 32px;
      max-width: 460px;
      width: 100%;
      box-shadow: 0 24px 60px rgba(0, 0, 0, 0.45);
      backdrop-filter: blur(18px);
    }
    .brand { font-size: 12px; letter-spacing: 0.18em; color: #9696a8; text-transform: uppercase; margin-bottom: 6px; }
    h1 { margin: 0 0 6px 0; font-size: 24px; font-weight: 600; }
    p { color: #a0a0b0; margin: 0 0 20px 0; font-size: 14px; line-height: 1.55; }
    .status {
      display: flex; align-items: center; gap: 10px;
      padding: 14px 16px;
      background: #10101a;
      border: 1px solid #2a2a35;
      border-radius: 10px;
      font-size: 14px;
      font-variant-numeric: tabular-nums;
      margin-bottom: 18px;
    }
    .dot { width: 9px; height: 9px; border-radius: 50%; background: #555560; transition: background 200ms, box-shadow 200ms; flex-shrink: 0; }
    .dot.live { background: #4ade80; box-shadow: 0 0 12px rgba(74, 222, 128, 0.55); }
    .dot.error { background: #f87171; box-shadow: 0 0 12px rgba(248, 113, 113, 0.55); }
    button {
      width: 100%;
      background: linear-gradient(180deg, #d63b3b, #b62a2a);
      color: white;
      border: 0;
      padding: 14px 24px;
      border-radius: 10px;
      font-size: 15px;
      font-weight: 600;
      cursor: pointer;
      transition: opacity 120ms, transform 80ms;
    }
    button:hover { opacity: 0.92; }
    button:active { transform: translateY(1px); }
    button:disabled { background: #2a2a35; color: #6c6c80; cursor: not-allowed; }
  </style>
</head>
<body>
  <div class="card">
    <div class="brand">Lua Voice</div>
    <h1>Try your voice agent</h1>
    <p>Allow microphone access when prompted. The agent will hear you when you speak.</p>
    <div class="status"><span class="dot" id="dot"></span><span id="msg">Connecting…</span></div>
    <button id="end" disabled>End call</button>
  </div>
  <script src="https://cdn.jsdelivr.net/npm/livekit-client@2/dist/livekit-client.umd.min.js"></script>
  <script>
    (function () {
      var wsUrl = ${wsLiteral};
      var token = ${tokenLiteral};
      var dot = document.getElementById('dot');
      var msg = document.getElementById('msg');
      var endBtn = document.getElementById('end');

      function setStatus(text, kind) {
        msg.textContent = text;
        dot.className = 'dot' + (kind ? ' ' + kind : '');
      }

      if (!window.LivekitClient) {
        setStatus('Failed to load LiveKit JS SDK from CDN.', 'error');
        return;
      }

      var room = new window.LivekitClient.Room({ adaptiveStream: true, dynacast: true });
      var ended = false;

      room.on(window.LivekitClient.RoomEvent.Connected, function () { setStatus('Connected — speak now', 'live'); });
      room.on(window.LivekitClient.RoomEvent.Disconnected, function () { if (!ended) setStatus('Disconnected', null); endBtn.disabled = true; });
      room.on(window.LivekitClient.RoomEvent.TrackSubscribed, function (track) {
        if (track.kind === 'audio') {
          var el = track.attach();
          el.style.display = 'none';
          document.body.appendChild(el);
        }
      });

      endBtn.addEventListener('click', function () {
        ended = true;
        setStatus('Call ended.', null);
        endBtn.disabled = true;
        room.disconnect().catch(function () { /* ignore */ }).then(function () {
          fetch('/end', { method: 'POST', keepalive: true }).catch(function () { /* ignore */ });
          setTimeout(function () { window.close(); }, 200);
        });
      });

      window.addEventListener('beforeunload', function () {
        try { fetch('/end', { method: 'POST', keepalive: true }); } catch (e) { /* ignore */ }
      });

      room.connect(wsUrl, token)
        .then(function () { return room.localParticipant.setMicrophoneEnabled(true); })
        .then(function () { endBtn.disabled = false; })
        .catch(function (e) { setStatus('Connect failed: ' + (e && e.message ? e.message : String(e)), 'error'); });
    })();
  </script>
</body>
</html>`;
}
