/**
 * Prompt Handler Utility
 * Gracefully handles user interruptions (Ctrl+C) in inquirer prompts
 */

import inquirer from 'inquirer';
import { isCiModeEnabled } from './cli.js';

/**
 * Wraps inquirer.prompt to gracefully handle Ctrl+C interruptions
 * Also ensures clean terminal state before showing prompts
 *
 * In CI mode (--ci flag), throws an error instead of prompting
 * In non-TTY environments without --ci, logs a warning
 */
export async function safePrompt<T = any>(questions: any): Promise<T | null> {
  // Check if CI mode is enabled
  if (isCiModeEnabled()) {
    throw new Error('Interactive prompt required but --ci flag is set. Provide all required flags or arguments.');
  }

  // Auto-detect non-TTY environment and warn (but don't fail)
  if (!process.stdin.isTTY && !isCiModeEnabled()) {
    console.warn('⚠️  Warning: stdin is not a TTY. Interactive prompts may not work correctly.');
    console.warn('💡 Tip: Use --ci flag in CI/CD environments to fail loudly on missing required flags.');
  }

  try {
    // Ensure any previous output is fully flushed before showing prompt
    // Small delay to let terminal render previous messages
    await new Promise((resolve) => setTimeout(resolve, 10));

    const answers = await inquirer.prompt(questions);
    return answers as T;
  } catch (error: any) {
    // Handle Ctrl+C gracefully
    if (error.name === 'ExitPromptError' || error.message?.includes('SIGINT')) {
      // console.log('\n\n👋 Operation cancelled. Goodbye!\n');
      process.exit(0);
    }
    throw error;
  }
}

/**
 * Setup global SIGINT handler for graceful exits
 */
export function setupGlobalInterruptHandler(): void {
  process.on('SIGINT', () => {
    // console.log('\n\n👋 Operation cancelled. Goodbye!\n');
    process.exit(0);
  });
}
