/**
 * Source Commands
 *
 * User-facing commands for inspecting and rolling back to historical
 * source backup versions. Backed by the Phase 1 versioned-manifest
 * endpoints on the server.
 *
 * - `lua source list`            — list backup versions for the agent
 * - `lua source rollback --version N` — restore version N's files locally
 *                                       and append them as a new version
 *
 * The rollback command intentionally does NOT mutate the historical
 * record. It downloads v<N>'s files, overwrites the local working copy,
 * and then runs a fresh push that creates v<latest+1>. Append-only
 * history means rolling back is always safe and auditable.
 */

import inquirer from 'inquirer';
import { requireAuthOrExit } from '../utils/command-utils.js';
import { readYamlConfig } from '../utils/files.js';
import { writeError } from '../utils/cli.js';
import { BASE_URLS } from '../config/constants.js';
import { downloadBlobsParallel, restoreProjectFromBackup } from '../utils/backup-helpers.js';
import { runBackupPush } from './pushBackup.js';
import type { BackupManifest } from '../interfaces/backup.js';

interface ManifestVersionSummary {
  version: number;
  createdAt: string;
  createdBy: string;
  triggeredBy?: string;
  projectHash: string;
}

interface ListResponse {
  versions: ManifestVersionSummary[];
}

export interface SourceListOptions {
  all: boolean;
  limit: number;
  /** Test seam — bypasses HTTP. */
  fetchVersions?: (apiKey: string, agentId: string, all: boolean) => Promise<ListResponse>;
}

/**
 * List historical backup versions for the current agent. Active version
 * is marked with a `*` next to its number. Default cap 50; pass --all
 * to show full history.
 */
export async function sourceListCommand(opts: SourceListOptions): Promise<void> {
  const apiKey = requireAuthOrExit(true);
  const config = readYamlConfig();
  const agentId = config?.agent?.agentId;
  const activeVersion = config?.backup?.activeVersion;
  if (!agentId) {
    writeError('No agentId in lua.skill.yaml. Run `lua init` first.');
    return;
  }

  const fetcher = opts.fetchVersions ?? defaultFetchVersions;
  const { versions } = await fetcher(apiKey, agentId, opts.all);
  if (versions.length === 0) {
    console.log('(no source versions yet — push to create one)');
    return;
  }

  // `--all` controls server-side fetch (lifts the default 50-cap on the
  // /versions endpoint). `--limit` always applies as a display cap on top
  // of whatever the server returned. `--all --limit 100` = "fetch full
  // history, show me up to 100"; `--limit 30` (no --all) = "fetch the
  // server default, show me up to 30 of those".
  const slice = versions.slice(0, opts.limit);

  console.log('VERSION   CREATED            BY        TRIGGERED BY                   HASH');
  for (const v of slice) {
    const active = v.version === activeVersion ? ' *' : '';
    const date = new Date(v.createdAt).toISOString().slice(0, 16).replace('T', ' ');
    const trig = (v.triggeredBy ?? '').slice(0, 30).padEnd(30, ' ');
    const hash = v.projectHash.slice(0, 8) + '...';
    console.log(`v${v.version}${active}\t${date}\t${v.createdBy}\t${trig}\t${hash}`);
  }
}

async function defaultFetchVersions(apiKey: string, agentId: string, all: boolean): Promise<ListResponse> {
  return requestJson<ListResponse>(
    'GET',
    `${BASE_URLS.API}/developer/agents/${encodeURIComponent(agentId)}/backup/versions${all ? '?all=true' : ''}`,
    apiKey
  );
}

// =============================================================================
// ROLLBACK
// =============================================================================

interface RollbackManifestResponse {
  files: BackupManifest['files'];
  activeVersion?: number;
  // Other BackupMetadata fields may be present but we only consume what the
  // restore step needs.
  [key: string]: unknown;
}

export interface SourceRollbackOptions {
  version: number;
  force: boolean;
  /** Test seam — bypasses HTTP. */
  fetchManifest?: (apiKey: string, agentId: string, version: number) => Promise<RollbackManifestResponse>;
  /** Test seam — bypasses HTTP. */
  fetchUrls?: (apiKey: string, agentId: string, hashes: string[]) => Promise<{ urls: Record<string, string> }>;
  /** Test seam — bypasses S3 download. */
  downloadBlobs?: (urls: Record<string, string>) => Promise<Map<string, Buffer>>;
  /** Test seam — bypasses disk writes. */
  restoreFiles?: (manifest: RollbackManifestResponse, blobs: Map<string, Buffer>, targetDir: string) => void;
}

/**
 * Roll back to a historical backup version.
 *
 * Append-only history: this does NOT mutate v<N>. It downloads v<N>'s
 * files, overwrites the local working copy, then runs `runBackupPush`
 * with `fresh=true` so the server creates v<latest+1> with v<N>'s
 * contents. Blobs already exist on S3 (content-addressed dedup), so
 * the only new write is the manifest itself.
 */
export async function sourceRollbackCommand(opts: SourceRollbackOptions): Promise<{ newActiveVersion: number }> {
  const apiKey = requireAuthOrExit(true);
  const config = readYamlConfig();
  const agentId = config?.agent?.agentId;
  if (!agentId) throw new Error('No agentId in lua.skill.yaml. Run `lua init` first.');

  const fetchM = opts.fetchManifest ?? defaultFetchManifest;
  const fetchU = opts.fetchUrls ?? defaultFetchUrls;
  const dlBlobs = opts.downloadBlobs ?? downloadBlobsParallel;
  const restore = opts.restoreFiles ?? defaultRestore;

  if (!opts.force) {
    const { confirm } = await inquirer.prompt([
      {
        type: 'confirm',
        name: 'confirm',
        message: `Rolling back to v${opts.version} will overwrite local files and create a new version. Continue?`,
        default: false,
      },
    ]);
    if (!confirm) return { newActiveVersion: config?.backup?.activeVersion ?? 0 };
  }

  const manifest = await fetchM(apiKey, agentId, opts.version);
  const urlsResponse = await fetchU(
    apiKey,
    agentId,
    manifest.files.map((f) => f.hash)
  );
  const blobs = await dlBlobs(urlsResponse.urls);
  restore(manifest, blobs, process.cwd());

  // Append the rolled-back state as a new version. Server creates
  // v<latest+1> referencing v<N>'s blobs (already on S3) — no re-upload.
  const result = await runBackupPush({
    apiKey,
    agentId,
    force: true,
    fresh: true,
    triggeredBy: `rollback to v${opts.version}`,
  });

  return { newActiveVersion: result.activeVersion };
}

async function defaultFetchManifest(
  apiKey: string,
  agentId: string,
  version: number
): Promise<RollbackManifestResponse> {
  return requestJson<RollbackManifestResponse>(
    'GET',
    `${BASE_URLS.API}/developer/agents/${encodeURIComponent(agentId)}/backup/manifest?version=${version}`,
    apiKey
  );
}

async function defaultFetchUrls(
  apiKey: string,
  agentId: string,
  hashes: string[]
): Promise<{ urls: Record<string, string> }> {
  return requestJson<{ urls: Record<string, string> }>(
    'POST',
    `${BASE_URLS.API}/developer/agents/${encodeURIComponent(agentId)}/backup/blob-urls`,
    apiKey,
    { hashes }
  );
}

async function requestJson<T>(method: 'GET' | 'POST', url: string, apiKey: string, body?: unknown): Promise<T> {
  const headers: Record<string, string> = { Authorization: `Bearer ${apiKey}` };
  const init: RequestInit = { method, headers };
  if (body !== undefined) {
    headers['Content-Type'] = 'application/json';
    init.body = JSON.stringify(body);
  }
  const response = await fetch(url, init);
  if (!response.ok) {
    const text = await response.text().catch(() => '');
    throw new Error(`HTTP ${response.status} ${method} ${url}${text ? `: ${text}` : ''}`);
  }
  return (await response.json()) as T;
}

function defaultRestore(manifest: RollbackManifestResponse, blobs: Map<string, Buffer>, targetDir: string): void {
  // restoreProjectFromBackup expects a BackupManifest. The rollback
  // response has the same `files` shape; cast through unknown because
  // the metadata fields we don't consume aren't worth round-tripping.
  restoreProjectFromBackup(manifest as unknown as BackupManifest, blobs, targetDir, { overwrite: true });
}
