/**
 * PostProcessors Command
 * Manages agent postprocessors for production environment
 */

import { withErrorHandling, writeProgress, writeSuccess, writeInfo, writeHintBlock } from '../utils/cli.js';
import { BASE_URLS } from '../config/constants.js';
import { safePrompt } from '../utils/prompt-handler.js';
import { initializeCommand } from '../utils/command-utils.js';
import PostProcessorApi from '../api/postprocessor.api.service.js';
import { postprocessorHandler } from '../primitives/postprocessor.handler.js';
import { YamlConfig } from '../types/yaml.types.js';
import { trackEvent } from '../services/analytics.js';
import { validateOrSuggest } from '../utils/aliases.js';

interface PostProcessorsCommandContext {
  agentId: string;
  apiKey: string;
}

interface PostProcessorsOptions {
  postprocessorName?: string;
  postprocessorVersion?: string;
}

type PostProcessorAction = 'view' | 'versions' | 'deploy' | 'activate' | 'deactivate' | 'delete';

// ─────────────────────────────────────────────────────────────────────────────
// Main Command Entry
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Main postprocessors command - manages agent postprocessors.
 *
 * Supports both interactive and non-interactive modes:
 * - Interactive: prompts for action and postprocessor selection
 * - Non-interactive: use action argument with -i and -v flags
 */
export async function postprocessorsCommand(action?: string, cmdObj?: any): Promise<void> {
  return withErrorHandling(async () => {
    const options: PostProcessorsOptions = {
      postprocessorName: cmdObj?.postprocessorName || null,
      postprocessorVersion: cmdObj?.postprocessorVersion || null,
    };

    // Initialize command (validates config + auth)
    const { config, agentId, apiKey } = await initializeCommand();

    const context: PostProcessorsCommandContext = {
      agentId,
      apiKey,
    };

    // Determine mode
    if (action) {
      await executeNonInteractive(context, config, action, options);
    } else {
      await managePostProcessorsInteractive(context, config);
    }
    trackEvent('cli_postprocessors_action', {
      action: action || 'interactive',
      postprocessor_name: options.postprocessorName || null,
      non_interactive: !!action,
    });
  }, 'postprocessors');
}

// ─────────────────────────────────────────────────────────────────────────────
// Shared Core Functions
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Displays all postprocessors with their current status.
 */
async function displayPostProcessorsCore(context: PostProcessorsCommandContext, postprocessors: any[]): Promise<void> {
  console.log('\n' + '='.repeat(60));
  console.log('⚙️  Production PostProcessors');
  console.log('='.repeat(60) + '\n');

  const api = new PostProcessorApi(BASE_URLS.API, context.apiKey, context.agentId);

  for (const postprocessor of postprocessors) {
    try {
      const response = await api.getPostProcessorVersions(postprocessor.postprocessorId);

      if (response.success && response.data) {
        const versions = response.data.versions || [];
        const activeVersionId = response.data.activeVersionId;
        const activeVersion = versions.find((v: any) => v.versionId === activeVersionId);

        console.log(`📤 ${postprocessor.name}`);
        console.log(`   PostProcessor ID: ${postprocessor.postprocessorId}`);

        if (activeVersion) {
          console.log(`   Deployed Version: ${activeVersion.version} ⭐`);
          console.log(`   Deployed: ${new Date(activeVersion.createdAt).toLocaleString()}`);
        } else {
          console.log(`   Deployed Version: Not deployed`);
        }

        console.log(`   Total Versions: ${versions.length}`);
        console.log();
      } else {
        displayPostProcessorError(postprocessor, 'Unable to fetch version info');
      }
    } catch {
      displayPostProcessorError(postprocessor, 'Error loading versions');
    }
  }

  console.log('='.repeat(60));
}

function displayPostProcessorError(postprocessor: any, status: string): void {
  console.log(`📤 ${postprocessor.name}`);
  console.log(`   PostProcessor ID: ${postprocessor.postprocessorId}`);
  console.log(`   Status: ${status}`);
  console.log();
}

/**
 * Fetches and returns sorted postprocessor versions.
 */
async function fetchVersionsCore(
  context: PostProcessorsCommandContext,
  postprocessor: any
): Promise<{ versions: any[]; activeVersionId: string | undefined } | null> {
  const api = new PostProcessorApi(BASE_URLS.API, context.apiKey, context.agentId);
  const response = await api.getPostProcessorVersions(postprocessor.postprocessorId);

  if (!response.success || !response.data) {
    console.error(`❌ Failed to fetch versions: ${response.error?.message || 'Unknown error'}`);
    return null;
  }

  const versions = (response.data.versions || []).sort(
    (a: any, b: any) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime()
  );

  return { versions, activeVersionId: response.data.activeVersionId };
}

/**
 * Displays versions for a postprocessor.
 */
function displayVersionsCore(postprocessor: any, versions: any[], activeVersionId: string | undefined): void {
  console.log('\n' + '='.repeat(60));
  console.log(`📜 Versions for ${postprocessor.name}`);
  console.log('='.repeat(60) + '\n');

  versions.forEach((version: any, index: number) => {
    const isActive = version.versionId === activeVersionId;
    console.log(`${index + 1}. Version ${version.version}${isActive ? ' ⭐ DEPLOYED' : ''}`);
    console.log(`   Created: ${new Date(version.createdAt).toLocaleString()}`);
    console.log();
  });

  console.log('='.repeat(60));
}

/**
 * Deploys a specific version of a postprocessor.
 */
async function deployVersionCore(
  context: PostProcessorsCommandContext,
  postprocessor: any,
  version: string
): Promise<boolean> {
  writeProgress(`🔄 Deploying version ${version} of "${postprocessor.name}"...`);

  const api = new PostProcessorApi(BASE_URLS.API, context.apiKey, context.agentId);
  const deployResponse = await api.publishPostProcessorVersion(postprocessor.postprocessorId, version);

  if (!deployResponse.success) {
    console.error(`❌ Deploy Error: ${deployResponse.error?.message || 'Unknown error'}`);
    return false;
  }

  writeSuccess(`✅ Version ${version} of "${postprocessor.name}" deployed successfully`);
  writeHintBlock({
    headline: 'Postprocessor is live. Send a test message to trigger it:',
    lines: [
      { label: 'Test:', command: 'lua chat -e production -m "test"' },
      { label: 'Inspect:', command: `lua logs --type postprocessor --name ${postprocessor.name} --limit 10` },
    ],
    when: 'success',
  });
  return true;
}

/**
 * Activates a postprocessor.
 */
async function activatePostProcessorCore(context: PostProcessorsCommandContext, postprocessor: any): Promise<boolean> {
  writeProgress(`🔄 Activating postprocessor "${postprocessor.name}"...`);

  const api = new PostProcessorApi(BASE_URLS.API, context.apiKey, context.agentId);
  const response = await api.activatePostProcessor(postprocessor.postprocessorId);

  if (response.success) {
    writeSuccess(`✅ PostProcessor "${postprocessor.name}" activated successfully`);
    writeInfo('💡 The postprocessor is now enabled and will process all outgoing responses.');
    return true;
  } else {
    console.error(`❌ Failed to activate postprocessor: ${response.error?.message || 'Unknown error'}`);
    return false;
  }
}

/**
 * Deactivates a postprocessor.
 */
async function deactivatePostProcessorCore(
  context: PostProcessorsCommandContext,
  postprocessor: any
): Promise<boolean> {
  writeProgress(`🔄 Deactivating postprocessor "${postprocessor.name}"...`);

  const api = new PostProcessorApi(BASE_URLS.API, context.apiKey, context.agentId);
  const response = await api.deactivatePostProcessor(postprocessor.postprocessorId);

  if (response.success) {
    writeSuccess(`✅ PostProcessor "${postprocessor.name}" deactivated successfully`);
    writeInfo('💡 The postprocessor is now disabled.');
    return true;
  } else {
    console.error(`❌ Failed to deactivate postprocessor: ${response.error?.message || 'Unknown error'}`);
    return false;
  }
}

/**
 * Deletes a postprocessor.
 */
async function deletePostProcessorCore(context: PostProcessorsCommandContext, postprocessor: any): Promise<boolean> {
  writeProgress(`🔄 Deleting postprocessor "${postprocessor.name}"...`);

  const api = new PostProcessorApi(BASE_URLS.API, context.apiKey, context.agentId);
  const response = await api.deletePostProcessor(postprocessor.postprocessorId);

  if (response.success) {
    if (response.data?.deleted) {
      writeSuccess(`✅ PostProcessor "${postprocessor.name}" deleted successfully`);
    } else if (response.data?.deactivated) {
      writeInfo(
        `⚠️  PostProcessor "${postprocessor.name}" has versions and cannot be deleted. It has been deactivated instead.`
      );
    }
    return true;
  } else {
    console.error(`❌ Failed to delete postprocessor: ${response.error?.message || 'Unknown error'}`);
    return false;
  }
}

/**
 * Resolves a version string to an actual version, supporting "latest".
 */
function resolveVersion(versions: any[], versionArg: string): string | null {
  if (versionArg.toLowerCase() === 'latest') {
    return versions[0].version;
  }

  const exists = versions.some((v: any) => v.version === versionArg);
  if (!exists) {
    console.error(`❌ Version "${versionArg}" not found`);
    console.log('\nAvailable versions:');
    versions.slice(0, 5).forEach((v: any) => console.log(`  - ${v.version}`));
    return null;
  }
  return versionArg;
}

/**
 * Prompts user to select a postprocessor from a list.
 */
async function promptPostProcessorSelection(postprocessors: any[], message: string): Promise<any | null> {
  const answer = await safePrompt<{ selected: any }>([
    {
      type: 'list',
      name: 'selected',
      message,
      choices: postprocessors.map((p: any) => ({
        name: `${p.name} (${p.postprocessorId})`,
        value: p,
      })),
    },
  ]);
  return answer?.selected || null;
}

/**
 * Prompts user to select a version from a list.
 */
async function promptVersionSelection(versions: any[], activeVersionId: string | undefined): Promise<any | null> {
  const answer = await safePrompt<{ selectedVersion: any }>([
    {
      type: 'list',
      name: 'selectedVersion',
      message: 'Select a version to deploy:',
      choices: versions.map((version: any) => {
        const isActive = version.versionId === activeVersionId;
        return {
          name: `Version ${version.version} (${new Date(version.createdAt).toLocaleDateString()})${isActive ? ' ⭐ CURRENT' : ''}`,
          value: version,
        };
      }),
    },
  ]);
  return answer?.selectedVersion || null;
}

// ─────────────────────────────────────────────────────────────────────────────
// Non-Interactive Mode
// ─────────────────────────────────────────────────────────────────────────────

async function executeNonInteractive(
  context: PostProcessorsCommandContext,
  config: YamlConfig,
  action: string,
  options: PostProcessorsOptions
): Promise<void> {
  const normalizedAction = validateOrSuggest('postprocessors.action', action);

  const postprocessors = config.postprocessors || [];

  // View action doesn't require postprocessor selection
  if (normalizedAction === 'view') {
    if (postprocessors.length === 0) {
      console.log('ℹ️  No postprocessors found in configuration.');
      return;
    }
    await displayPostProcessorsCore(context, postprocessors);
    return;
  }

  // All other actions require postprocessor selection
  if (!options.postprocessorName) {
    console.error(`❌ --postprocessor-name is required for action "${normalizedAction}"`);
    console.log(`\nUsage: lua postprocessors ${normalizedAction} --postprocessor-name <name>`);
    throw new Error(`--postprocessor-name is required for action "${normalizedAction}"`);
  }

  let selected = postprocessors.find(
    (p) => p.postprocessorId === options.postprocessorName || p.name === options.postprocessorName
  );

  if (!selected && normalizedAction === 'delete') {
    const api = new PostProcessorApi(BASE_URLS.API, context.apiKey, context.agentId);
    const serverResponse = await api.getPostProcessors();
    if (serverResponse.success && serverResponse.data?.postprocessors) {
      const serverPost = serverResponse.data.postprocessors.find(
        (p) => p.id === options.postprocessorName || p.name === options.postprocessorName
      );
      if (serverPost) {
        const activeVersion = serverPost.versions.find((v) => v.isActive) ?? serverPost.versions[0];
        selected = { name: serverPost.name, postprocessorId: serverPost.id, version: activeVersion?.version ?? '' };
      }
    }
  }

  if (!selected) {
    console.error(`❌ PostProcessor "${options.postprocessorName}" not found`);
    console.log('\nAvailable postprocessors:');
    postprocessors.forEach((p) => console.log(`  - ${p.name} (${p.postprocessorId})`));
    throw new Error(`PostProcessor "${options.postprocessorName}" not found`);
  }

  switch (normalizedAction as PostProcessorAction) {
    case 'versions': {
      const data = await fetchVersionsCore(context, selected);
      if (!data) throw new Error('Failed to fetch postprocessor versions');
      if (data.versions.length === 0) {
        console.log(`ℹ️  No versions found for ${selected.name}.`);
        console.log("💡 Push a version first using 'lua push postprocessor'.");
        return;
      }
      displayVersionsCore(selected, data.versions, data.activeVersionId);
      break;
    }
    case 'deploy': {
      if (!options.postprocessorVersion) {
        console.error('❌ --postprocessor-version is required for deploy action');
        console.log('\nUsage: lua postprocessors deploy --postprocessor-name myPost --postprocessor-version 1.0.3');
        console.log('       lua postprocessors deploy -i myPost -v latest');
        throw new Error('--postprocessor-version is required for deploy action');
      }
      const data = await fetchVersionsCore(context, selected);
      if (!data) throw new Error('Failed to fetch postprocessor versions');
      if (data.versions.length === 0) {
        console.error(`❌ No versions found for ${selected.name}.`);
        console.log("💡 Push a version first using 'lua push postprocessor'.");
        throw new Error(`No versions found for ${selected.name}`);
      }
      const resolvedVersion = resolveVersion(data.versions, options.postprocessorVersion);
      if (!resolvedVersion) throw new Error('Failed to resolve postprocessor version');
      const success = await deployVersionCore(context, selected, resolvedVersion);
      if (!success) throw new Error('Failed to deploy postprocessor version');
      break;
    }
    case 'activate': {
      const success = await activatePostProcessorCore(context, selected);
      if (!success) throw new Error('Failed to activate postprocessor');
      break;
    }
    case 'deactivate': {
      const success = await deactivatePostProcessorCore(context, selected);
      if (!success) throw new Error('Failed to deactivate postprocessor');
      break;
    }
    case 'delete': {
      const success = await deletePostProcessorCore(context, selected);
      if (!success) throw new Error('Failed to delete postprocessor');
      break;
    }
  }
}

// ─────────────────────────────────────────────────────────────────────────────
// Interactive Mode
// ─────────────────────────────────────────────────────────────────────────────

async function managePostProcessorsInteractive(
  context: PostProcessorsCommandContext,
  config: YamlConfig
): Promise<void> {
  let continueManaging = true;

  while (continueManaging) {
    console.log('\n' + '='.repeat(60));
    console.log('🚀 Production PostProcessors');
    console.log('='.repeat(60) + '\n');

    const actionAnswer = await safePrompt<{ action: string }>([
      {
        type: 'list',
        name: 'action',
        message: 'What would you like to do?',
        choices: [
          { name: '👁️  View deployed postprocessors', value: 'view' },
          { name: '📜 View postprocessor versions', value: 'versions' },
          { name: '🚀 Deploy a version', value: 'deploy' },
          { name: '✅ Activate a postprocessor', value: 'activate' },
          { name: '🚫 Deactivate a postprocessor', value: 'deactivate' },
          { name: '🗑️  Delete a postprocessor', value: 'delete' },
          { name: '❌ Exit', value: 'exit' },
        ],
      },
    ]);

    if (!actionAnswer) return;
    const { action } = actionAnswer;

    switch (action) {
      case 'view':
        await viewPostProcessorsInteractive(context, config);
        break;
      case 'versions':
        await viewVersionsInteractive(context, config);
        break;
      case 'deploy':
        await deployVersionInteractive(context, config);
        break;
      case 'activate':
        await activatePostProcessorInteractive(context, config);
        break;
      case 'deactivate':
        await deactivatePostProcessorInteractive(context, config);
        break;
      case 'delete':
        await deletePostProcessorInteractive(context, config);
        break;
      case 'exit':
        continueManaging = false;
        console.log('\n👋 Goodbye!\n');
        break;
    }
  }
}

async function viewPostProcessorsInteractive(context: PostProcessorsCommandContext, config: YamlConfig): Promise<void> {
  writeProgress('🔄 Loading postprocessor information...');
  const postprocessors = config.postprocessors || [];

  if (postprocessors.length === 0) {
    console.log('\nℹ️  No postprocessors found in configuration.\n');
  } else {
    await displayPostProcessorsCore(context, postprocessors);
    console.log();
  }

  await safePrompt([{ type: 'input', name: 'continue', message: 'Press Enter to continue...' }]);
}

async function viewVersionsInteractive(context: PostProcessorsCommandContext, config: YamlConfig): Promise<void> {
  const postprocessors = config.postprocessors || [];

  if (postprocessors.length === 0) {
    console.log('\nℹ️  No postprocessors found in configuration.\n');
    await safePrompt([{ type: 'input', name: 'continue', message: 'Press Enter to continue...' }]);
    return;
  }

  const selected = await promptPostProcessorSelection(postprocessors, 'Select a postprocessor to view versions:');
  if (!selected) return;

  writeProgress(`🔄 Loading versions for ${selected.name}...`);
  const data = await fetchVersionsCore(context, selected);

  if (!data) {
    await safePrompt([{ type: 'input', name: 'continue', message: 'Press Enter to continue...' }]);
    return;
  }

  if (data.versions.length === 0) {
    console.log(`\nℹ️  No versions found for ${selected.name}.\n`);
    console.log("💡 Push a version first using 'lua push postprocessor'.\n");
  } else {
    displayVersionsCore(selected, data.versions, data.activeVersionId);
    console.log();
  }

  await safePrompt([{ type: 'input', name: 'continue', message: 'Press Enter to continue...' }]);
}

async function deployVersionInteractive(context: PostProcessorsCommandContext, config: YamlConfig): Promise<void> {
  const postprocessors = config.postprocessors || [];

  if (postprocessors.length === 0) {
    console.log('\nℹ️  No postprocessors found in configuration.\n');
    await safePrompt([{ type: 'input', name: 'continue', message: 'Press Enter to continue...' }]);
    return;
  }

  const selected = await promptPostProcessorSelection(postprocessors, 'Select a postprocessor to deploy:');
  if (!selected) return;

  writeProgress(`🔄 Loading versions for ${selected.name}...`);
  const data = await fetchVersionsCore(context, selected);

  if (!data) {
    await safePrompt([{ type: 'input', name: 'continue', message: 'Press Enter to continue...' }]);
    return;
  }

  if (data.versions.length === 0) {
    console.log(`\nℹ️  No versions found for ${selected.name}.\n`);
    console.log("💡 Push a version first using 'lua push postprocessor'.\n");
    await safePrompt([{ type: 'input', name: 'continue', message: 'Press Enter to continue...' }]);
    return;
  }

  const selectedVersion = await promptVersionSelection(data.versions, data.activeVersionId);
  if (!selectedVersion) return;

  // Show warning and confirm
  console.log('\n⚠️  WARNING: You are about to deploy to PRODUCTION!');
  console.log('⚠️  This will affect ALL users immediately.\n');
  console.log(`PostProcessor: ${selected.name}`);
  console.log(`Version: ${selectedVersion.version}\n`);

  const confirmAnswer = await safePrompt<{ confirm: boolean }>([
    {
      type: 'confirm',
      name: 'confirm',
      message: 'Are you absolutely sure you want to deploy this version?',
      default: false,
    },
  ]);

  if (!confirmAnswer || !confirmAnswer.confirm) {
    console.log('\n❌ Deployment cancelled.\n');
    return;
  }

  await deployVersionCore(context, selected, selectedVersion.version);
  await safePrompt([{ type: 'input', name: 'continue', message: 'Press Enter to continue...' }]);
}

async function activatePostProcessorInteractive(
  context: PostProcessorsCommandContext,
  config: YamlConfig
): Promise<void> {
  const postprocessors = config.postprocessors || [];

  if (postprocessors.length === 0) {
    console.log('\nℹ️  No postprocessors found.\n');
    return;
  }

  const selected = await promptPostProcessorSelection(postprocessors, 'Select a postprocessor to activate:');
  if (!selected) return;

  await activatePostProcessorCore(context, selected);
}

async function deactivatePostProcessorInteractive(
  context: PostProcessorsCommandContext,
  config: YamlConfig
): Promise<void> {
  const postprocessors = config.postprocessors || [];

  if (postprocessors.length === 0) {
    console.log('\nℹ️  No postprocessors found.\n');
    return;
  }

  const selected = await promptPostProcessorSelection(postprocessors, 'Select a postprocessor to deactivate:');
  if (!selected) return;

  const confirmAnswer = await safePrompt<{ confirm: boolean }>([
    {
      type: 'confirm',
      name: 'confirm',
      message: `Are you sure you want to deactivate "${selected.name}"? Responses will not be postprocessed.`,
      default: false,
    },
  ]);

  if (!confirmAnswer || !confirmAnswer.confirm) {
    console.log('\n❌ Deactivation cancelled.\n');
    return;
  }

  await deactivatePostProcessorCore(context, selected);
}

async function deletePostProcessorInteractive(
  context: PostProcessorsCommandContext,
  config: YamlConfig
): Promise<void> {
  const { merged, orphanIds, serverFailed } = await postprocessorHandler.fetchMergedForInteraction(
    context.apiKey,
    context.agentId,
    config
  );
  if (serverFailed) {
    console.log('\n⚠️  Could not reach server. Showing local items only.\n');
  }

  if (merged.length === 0) {
    console.log('\nℹ️  No postprocessors found.\n');
    return;
  }

  const answer = await safePrompt<{ selected: (typeof merged)[number] }>([
    {
      type: 'list',
      name: 'selected',
      message: 'Select a postprocessor to delete:',
      choices: merged.map((item) => ({
        name: orphanIds.has(item.postprocessorId)
          ? `${item.name} (${item.postprocessorId}) [server only]`
          : `${item.name} (${item.postprocessorId})`,
        value: item,
      })),
    },
  ]);
  const selected = answer?.selected ?? null;
  if (!selected) return;

  const confirmAnswer = await safePrompt<{ confirm: boolean }>([
    {
      type: 'confirm',
      name: 'confirm',
      message: `⚠️  Are you sure you want to DELETE "${selected.name}"? This cannot be undone.`,
      default: false,
    },
  ]);

  if (!confirmAnswer || !confirmAnswer.confirm) {
    console.log('\n❌ Deletion cancelled.\n');
    return;
  }

  await deletePostProcessorCore(context, selected);
}
