/**
 * Handle primitive drift interactively.
 * Displays all drifted primitives, then prompts for each one.
 * If the user chooses "pull" for any primitive, the entire project
 * is restored from backup (once).
 */
async function handlePrimitiveDriftInteractive(context: SyncContext, primitiveDrift: PrimitiveDrift): Promise<void> {
  showPrimitiveDrift(primitiveDrift.items, primitiveDrift.backupAvailable);

  let hasRestoredFromBackup = false;
  let hasSyncedMcp = false;

  for (const item of primitiveDrift.items) {
    const choices: Array<{ name: string; value: string }> = [];
    const isMcp = item.type === 'mcpServer';

    if (item.status !== 'missing-locally') {
      choices.push({ name: '📤 Push local to server', value: 'push' });
    }

    if (item.status !== 'missing-on-server') {
      if (isMcp) {
        // MCP servers pull live from the server, not from backup.
        choices.push({ name: '📥 Pull from server', value: 'pull-mcp' });
      } else if (primitiveDrift.backupAvailable) {
        choices.push({ name: '📥 Pull from backup', value: 'pull' });
      } else {
        choices.push({ name: '📥 Pull from backup (unavailable)', value: 'pull-unavailable' });
      }
    }

    choices.push({ name: '⏭️  Skip', value: 'skip' });

    const answer = await safePrompt<{ action: string }>([
      {
        type: 'list',
        name: 'action',
        message: `${item.type}: ${item.name} — What would you like to do?`,
        choices,
      },
    ]);

    if (!answer || answer.action === 'skip') {
      writeInfo(`Skipped ${item.type}: ${item.name}`);
      continue;
    }

    if (answer.action === 'push') {
      // The internal drift type 'mcpServer' maps to CLI arg 'mcp' (see validTypes in push.ts).
      const pushArg = item.type === 'mcpServer' ? 'mcp' : item.type;
      writeInfo(`💡 To push this ${item.type}, run: lua push ${pushArg} --name "${item.name}"`);
    } else if (answer.action === 'pull-mcp') {
      // mcpServerHandler.syncWithServer does a bulk sync of all MCP servers,
      // so only call it once per session.
      if (hasSyncedMcp) {
        writeInfo(`✅ Already synced MCP servers (includes ${item.name})`);
      } else {
        writeProgress('📥 Syncing MCP servers from server...');
        try {
          const yamlConfig = readYamlConfig();
          const result = await mcpServerHandler.syncWithServer(context.apiKey, context.agentId, yamlConfig);
          writeSuccess(result.yamlUpdated ? '✅ MCP servers synced from server' : '✅ MCP servers already in sync');
          hasSyncedMcp = true;
        } catch (error: any) {
          console.error(`❌ Failed to sync MCP servers: ${error.message}`);
        }
      }
    } else if (answer.action === 'pull') {
      if (hasRestoredFromBackup) {
        writeInfo(`✅ Already restored from backup (includes ${item.name})`);
      } else {
        const pullableSource = primitiveDrift.items.filter(
          (i) => i.type !== 'mcpServer' && i.status !== 'missing-on-server'
        );

        writeProgress('📥 Restoring project files from backup...');
        const result = await restoreFromBackupForSync(
          context.apiKey,
          context.agentId,
          pullableSource.map((i) => i.name)
        );

        if (result.success) {
          hasRestoredFromBackup = true;
          reportRestoreResult(result, pullableSource, { verbose: false });
        } else {
          console.error(`❌ Failed to restore from backup: ${result.error}`);
        }
      }
    } else if (answer.action === 'pull-unavailable') {
      writeInfo('⚠️  No backup available. Run "lua push backup" first to enable pulling from server.');
    }
  }
}

