/**
 * Job Handler
 *
 * Handles CLI operations for job primitives.
 *
 * Jobs:
 * - Use 'status' field on entity (not 'active')
 * - Use 'isActive' field on versions
 * - buildPushData includes schedule field
 */

import { PrimitiveKind, ManifestPrimitive, ManifestJob } from '../compiler/types.js';
import { BASE_URLS } from '../config/constants.js';
import JobApi from '../api/job.api.service.js';
import type { PushJobVersionDTO } from '../interfaces/jobs.js';
import { BaseVersionedHandler } from './base.handler.js';
import type { YamlPrimitiveConfig } from './types.js';
import type { YamlConfigJob } from '../types/yaml.types.js';

/**
 * Job primitive handler
 */
export class JobHandler extends BaseVersionedHandler<YamlConfigJob, PushJobVersionDTO> {
  readonly kind = PrimitiveKind.JOB;
  readonly displayName = 'job';
  readonly displayNamePlural = 'jobs';
  readonly deleteCommand = 'lua jobs delete';
  readonly yamlConfig: YamlPrimitiveConfig = {
    yamlKey: 'jobs',
    idField: 'jobId',
  };

  protected getApi(apiKey: string, agentId: string): JobApi {
    return new JobApi(BASE_URLS.API, apiKey, agentId);
  }

  protected async fetchFromServer(api: JobApi): Promise<any[] | null> {
    const response = await api.getJobs();
    if (!response.success || !response.data?.jobs) {
      return null;
    }
    return response.data.jobs;
  }

  /**
   * Jobs expose an `activeVersion` shortcut on the entity, and use `v.active`
   * on version objects (not `v.isActive` as the base class expects).
   */
  getActiveVersion(serverItem: any): string | null {
    return (
      serverItem.activeVersion?.version ?? serverItem.versions?.find((v: any) => v.active === true)?.version ?? null
    );
  }

  protected async createOnServer(api: JobApi, primitive: ManifestPrimitive): Promise<string | null> {
    const job = primitive as ManifestJob;

    // Build complete schedule - fill in missing fields based on type
    // Use any for the schedule since the manifest type doesn't include all API fields
    let schedule: any = job.schedule;
    if (!schedule || !schedule.type) {
      schedule = { type: 'cron', expression: '0 0 * * *' };
    } else if (schedule.type === 'cron' && !schedule.expression) {
      schedule = { ...schedule, expression: '0 0 * * *' }; // Default: daily at midnight
    } else if (schedule.type === 'interval' && !schedule.seconds) {
      schedule = { ...schedule, seconds: 3600 }; // Default: every hour
    } else if (schedule.type === 'once' && !schedule.executeAt) {
      // For "once" jobs, set to 1 hour from now as a reasonable default
      const oneHourFromNow = new Date(Date.now() + 60 * 60 * 1000).toISOString();
      schedule = { ...schedule, executeAt: oneHourFromNow };
    }

    const response = await api.createJob({
      name: job.name,
      description: job.description || `A Lua job for ${job.name}`,
      schedule,
    });
    if (!response.success || !response.data?.id) return null;
    return response.data.id;
  }

  /**
   * Jobs use 'status' field (not 'active').
   * Active if status is not 'inactive'.
   */
  isActive(serverItem: any): boolean {
    return serverItem.status !== 'inactive';
  }

  async pushToServer(apiKey: string, agentId: string, entityId: string, pushData: PushJobVersionDTO) {
    const api = this.getApi(apiKey, agentId);
    const response = await api.pushJob(entityId, { ...pushData, jobId: entityId });
    return { success: response.success, error: response.error?.message };
  }

  async publishVersion(apiKey: string, agentId: string, entityId: string, version: string) {
    const api = this.getApi(apiKey, agentId);
    const response = await api.publishJobVersion(entityId, version);
    return { success: response.success, error: response.error?.message };
  }

  /**
   * Override to include schedule, timeout, retry fields in push data.
   */
  protected buildPushData(
    primitive: ManifestPrimitive,
    compressedCode: string | undefined,
    codeS3Hash?: string
  ): Record<string, unknown> {
    const job = primitive as ManifestJob;
    return {
      name: job.name,
      description: job.description,
      ...(codeS3Hash ? { codeS3Hash } : { code: compressedCode }),
      schedule: job.schedule,
      timeout: job.timeout,
      retry: job.retry,
      metadata: job.metadata,
    };
  }
}

// Export singleton instance
export const jobHandler = new JobHandler();
