const BOLD = '\x1b[1m';
const DIM = '\x1b[2m';
const BRIGHT = '\x1b[97m';
const RESET = '\x1b[0m';

interface PrintBannerOptions {
  version: string;
}

function visibleLength(s: string): number {
  return s.replace(/\x1b\[[0-9;]*m/g, '').length;
}

export function printBanner(opts: PrintBannerOptions): void {
  if (process.env.LUA_NO_BANNER) return;
  if (!process.stdout.isTTY && !process.env.LUA_FORCE_BANNER) return;

  if (process.env.NO_COLOR) {
    process.stdout.write(`\nlua-cli v${opts.version}  ·  Build and deploy AI agents with superpowers\n\n`);
    return;
  }

  const header = `${BOLD}${BRIGHT}lua-cli${RESET}  ${DIM}v${opts.version}${RESET}`;
  const tagline = `${DIM}Build and deploy AI agents with superpowers${RESET}`;
  const ruleWidth = Math.max(visibleLength(header), visibleLength(tagline));
  const rule = `${DIM}${'='.repeat(ruleWidth)}${RESET}`;

  process.stdout.write('\n');
  process.stdout.write(rule + '\n');
  process.stdout.write(header + '\n');
  process.stdout.write(tagline + '\n');
  process.stdout.write(rule + '\n');
  process.stdout.write('\n');
}
