/**
 * Result of running the interactive duplicate-agent prompts.
 */
export interface DuplicatePromptResult {
  targetOrg: SelectedOrg;
  newName: string;
  include: DuplicateAgentIncludeOptions;
  confirmed: boolean;
}

/**
 * Sequential prompts for the interactive `lua init` duplicate flow:
 * target org (skipped if user has only one org), new agent name,
 * include-bucket checkboxes, and a final confirmation summary.
 *
 * @param sourceOrg - The org the source agent lives in (default target)
 * @param allOrgs - All orgs the user is admin of
 * @param sourceAgentName - Name of the source agent (used for default new name + summary)
 */
export async function promptDuplicateOptions(
  sourceOrg: SelectedOrg,
  allOrgs: OrganizationData[],
  sourceAgentName: string
): Promise<DuplicatePromptResult> {
  // Target org: only ask when the user has more than one org
  let targetOrg: SelectedOrg = sourceOrg;
  if (allOrgs.length > 1) {
    const { sameOrg } = await inquirer.prompt([
      {
        type: 'list',
        name: 'sameOrg',
        message: 'Where should the duplicate live?',
        choices: [
          { name: `Same org (${sourceOrg.registeredName || sourceOrg.name})`, value: true },
          { name: 'A different org', value: false },
        ],
        default: true,
      },
    ]);

    if (!sameOrg) {
      const otherOrgs = allOrgs.filter((o) => o.id !== sourceOrg.id);
      targetOrg = await promptOrganizationSelection(otherOrgs);
    }
  }

  // New name (default: "<source name> (Copy)")
  const defaultName = `${sourceAgentName} (Copy)`;
  const { newName } = await inquirer.prompt([
    {
      type: 'input',
      name: 'newName',
      message: 'Name for the new agent:',
      default: defaultName,
      validate: (input: string) => input.trim().length > 0 || 'Name is required',
    },
  ]);

  // Include-bucket checkboxes
  const { includedBuckets } = await inquirer.prompt([
    {
      type: 'checkbox',
      name: 'includedBuckets',
      message: 'Optional buckets to copy (default: just the core agent definition):',
      choices: [
        { name: 'Resources + RAG (knowledge base)', value: 'resources' },
        { name: 'Custom data', value: 'customData' },
        { name: 'Inquiry forms', value: 'inquiryForm' },
        { name: 'Device + trigger definitions', value: 'devices' },
        { name: 'Ecommerce catalog (products, branches, recommendations, events)', value: 'ecommerceCatalog' },
      ],
    },
  ]);

  const include: DuplicateAgentIncludeOptions = {
    resources: includedBuckets.includes('resources'),
    customData: includedBuckets.includes('customData'),
    inquiryForm: includedBuckets.includes('inquiryForm'),
    devices: includedBuckets.includes('devices'),
    ecommerceCatalog: includedBuckets.includes('ecommerceCatalog'),
  };

  // Summary + confirmation
  console.log('');
  console.log(chalk.cyan('━━━ Duplicate summary ━━━'));
  console.log(chalk.white(`  Source agent:  ${sourceAgentName}`));
  console.log(chalk.white(`  Target org:    ${targetOrg.registeredName || targetOrg.name}`));
  console.log(chalk.white(`  New name:      ${newName.trim()}`));
  console.log(
    chalk.white(
      `  Including:     ${includedBuckets.length > 0 ? includedBuckets.join(', ') : 'core agent definition only'}`
    )
  );
  console.log(chalk.cyan('━━━━━━━━━━━━━━━━━━━━━━━━━'));
  console.log('');

  const { confirmed } = await inquirer.prompt([
    {
      type: 'confirm',
      name: 'confirmed',
      message: 'Proceed with duplication?',
      default: true,
    },
  ]);

  return {
    targetOrg,
    newName: newName.trim(),
    include,
    confirmed,
  };
}
