/**
 * Pure helpers extracted from `push.ts` (LUA-180).
 *
 * Lives in its own module so unit tests can import without dragging in
 * `push.ts`'s transitive dependency on `utils/cli.ts` (which uses
 * `import.meta.url` and breaks ts-jest). Mirrors the same extraction
 * pattern used by `test-output.helpers.ts` and `log-tip.ts`.
 */

import { buildLogsCommand } from './log-tip.js';

/**
 * Per-item failure record collected by `pushAllCommand` so we can render an
 * aggregate failure block (with a contextual `lua logs` diagnose hint per
 * item) and pick the correct writeNextStep variant at the end of the run.
 */
export interface PushFailedItem {
  kind: string;
  name: string;
  error: string;
}

/**
 * Decide which writeNextStep `when` variant `pushAllCommand` should emit at
 * the end of a run. Exposed for unit tests so the success/partial/error
 * branching is verifiable without driving the full push pipeline.
 *
 *   pushedSomething=true,  failedCount=0  → 'success'
 *   pushedSomething=true,  failedCount>0  → 'partial'
 *   pushedSomething=false, failedCount>0  → 'error'
 *   pushedSomething=false, failedCount=0  → null   (no-op, nothing happened)
 */
export function pickPushAllNextStepVariant(opts: {
  pushedSomething: boolean;
  failedCount: number;
}): 'success' | 'partial' | 'error' | null {
  if (opts.pushedSomething && opts.failedCount === 0) return 'success';
  if (opts.pushedSomething && opts.failedCount > 0) return 'partial';
  if (!opts.pushedSomething && opts.failedCount > 0) return 'error';
  return null;
}

/**
 * Render an aggregate failure block for `pushAllCommand`. Returns the full
 * multi-line string ready for `console.error`, with an inline
 * `💡 Diagnose: <lua logs ...>` hint per item so users can jump straight to
 * the failing component's logs.
 *
 * Pure function — exported for testability.
 */
export function formatPushFailureSummary(failedItems: readonly PushFailedItem[]): string {
  if (failedItems.length === 0) return '';
  const lines: string[] = [];
  lines.push(`\n⚠️  ${failedItems.length} component(s) failed to push:`);
  for (const item of failedItems) {
    lines.push(`   ${item.kind} "${item.name}": ${item.error}`);
    lines.push(`   💡 Diagnose: ${buildLogsCommand({ primitiveType: item.kind, name: item.name })}`);
  }
  return lines.join('\n');
}
