/**
 * Webhook compilation plugin.
 *
 * Detects three authoring shapes:
 *   1. `defineWebhook({...})`             — function-based
 *   2. `new LuaWebhook({...})`            — class config
 *   3. `class MyWebhook extends LuaWebhook { ... }` — class definition (incl. transitive bases)
 */

import { Project, SourceFile, Node, ObjectLiteralExpression, ClassDeclaration } from 'ts-morph';
import {
  type WebhookMetadata,
  type WebhookMetadataFields,
  type ValidationResult,
  type SchemaSet,
  type CompiledPrimitive,
  type ManifestPrimitive,
  type ManifestWebhook,
} from '../types.js';
import {
  BasePlugin,
  readStringMember,
  deriveNameFromClassName,
  locateClassDefinition,
  validationError,
  validationWarning,
} from './base.js';
import { extractSchemaProperty } from '../utils/ast-helpers.js';
import { findClassMember } from '../utils/class-hierarchy.js';
import { zodToJsonSchema } from '../utils/schema-converter.js';

/**
 * Plugin for compiling webhook primitives.
 * Extends BasePlugin for common detection/entry point/postProcess logic.
 */
export class WebhookPlugin extends BasePlugin<WebhookMetadataFields> {
  readonly kind = 'webhook';
  readonly displayName = 'Webhook';
  readonly defineFunction = 'defineWebhook';
  readonly legacyClassNames = ['LuaWebhook'];

  protected readonly supportsClassDefinition = true;

  /**
   * Class-definition shape: read fields off the inheritance chain
   * (most-derived wins). Mirrors `extractFromConfig` field-for-field so
   * the rest of the pipeline is unaware of the authoring style.
   */
  protected extractFromClassDefinition(classDecl: ClassDeclaration, sourceFile: SourceFile): WebhookMetadata | null {
    const className = classDecl.getName();
    if (!className) return null;

    const isDefaultExport = classDecl.isDefaultExport();
    const exportName = isDefaultExport ? 'default' : className;

    const name = readStringMember(classDecl, 'name') ?? deriveNameFromClassName(className);
    const description = readStringMember(classDecl, 'description') ?? '';

    return {
      kind: this.kind,
      name,
      description,
      sourcePath: sourceFile.getFilePath(),
      exportName,
      isDefaultExport,
      line: classDecl.getStartLineNumber(),
      column: 1,
      metadata: {
        pattern: 'class-definition',
        hasExecute: findClassMember(classDecl, 'execute', 'either') !== undefined,
        hasQuerySchema: findClassMember(classDecl, 'querySchema', 'property') !== undefined,
        hasHeaderSchema: findClassMember(classDecl, 'headerSchema', 'property') !== undefined,
        hasBodySchema: findClassMember(classDecl, 'bodySchema', 'property') !== undefined,
      },
    };
  }

  /**
   * Project the webhook class instance onto the standard primitive
   * shape. Schemas are read off the instance so subclass overrides
   * win at runtime.
   */
  protected getClassDefinitionPrimitiveShape(metadata: WebhookMetadata): string {
    return `{
    kind: 'webhook',
    name: __lua_instance__.name ?? ${JSON.stringify(metadata.name)},
    description: __lua_instance__.description ?? ${JSON.stringify(metadata.description)},
    querySchema: __lua_instance__.querySchema,
    headerSchema: __lua_instance__.headerSchema,
    bodySchema: __lua_instance__.bodySchema,
    execute: typeof __lua_instance__.execute === 'function' ? __lua_instance__.execute.bind(__lua_instance__) : undefined,
  }`;
  }

  /**
   * Extract metadata from webhook config object.
   */
  protected extractFromConfig(
    config: ObjectLiteralExpression,
    exportName: string,
    sourcePath: string,
    position: { line: number; column: number },
    pattern: 'function' | 'class'
  ): WebhookMetadata | null {
    const common = this.extractCommonFields(config, exportName, sourcePath, position);
    if (!common) return null;

    return {
      kind: this.kind,
      ...common,
      metadata: {
        pattern,
        hasExecute: config.getProperty('execute') !== undefined,
        hasQuerySchema: config.getProperty('querySchema') !== undefined,
        hasHeaderSchema: config.getProperty('headerSchema') !== undefined,
        hasBodySchema: config.getProperty('bodySchema') !== undefined,
      },
    };
  }

  validate(metadata: WebhookMetadata): ValidationResult {
    const { errors, warnings } = this.baseValidation(metadata);

    if (!metadata.metadata.hasExecute) {
      errors.push(validationError('Webhook must have an execute function', { line: metadata.line }));
    }

    if (metadata.name && !/^[a-z][a-z0-9-]*$/.test(metadata.name)) {
      warnings.push(
        validationWarning('Webhook name should be URL-safe (lowercase, hyphens only)', { line: metadata.line })
      );
    }

    return { valid: errors.length === 0, errors, warnings };
  }

  /**
   * Add runtime validation for execute function.
   */
  protected getRuntimeValidation(): string {
    return `
  if (typeof primitive.primitive?.execute !== 'function') {
    throw new Error('[Lua] Invalid webhook artifact: execute is not a function');
  }`;
  }

  /**
   * Extract query, header, and body schemas from webhook.
   */
  async extractSchemas(metadata: WebhookMetadata, project: Project): Promise<SchemaSet | undefined> {
    const sourceFile = project.getSourceFile(metadata.sourcePath);
    if (!sourceFile) return undefined;

    const schemas: SchemaSet = {};

    // Schema names → manifest key → metadata flag, used for both
    // config-literal and class-property extraction paths.
    const schemaProps: { prop: string; key: string; metaFlag: keyof WebhookMetadataFields }[] = [
      { prop: 'querySchema', key: 'query', metaFlag: 'hasQuerySchema' },
      { prop: 'headerSchema', key: 'headers', metaFlag: 'hasHeaderSchema' },
      { prop: 'bodySchema', key: 'body', metaFlag: 'hasBodySchema' },
    ];

    if (metadata.metadata.pattern === 'class-definition') {
      // Read each schema off the class chain (most-derived wins) so a
      // leaf can override one schema while inheriting the others.
      const classDecl = locateClassDefinition(sourceFile, metadata.exportName);
      if (!classDecl) return undefined;

      for (const { prop: propName, key, metaFlag } of schemaProps) {
        if (!metadata.metadata[metaFlag]) continue;
        const hit = findClassMember(classDecl, propName, 'property');
        if (!hit || !Node.isPropertyDeclaration(hit.node)) continue;
        const schemaNode = hit.node.getInitializer();
        if (!schemaNode) continue;
        try {
          const jsonSchema = await zodToJsonSchema(schemaNode);
          schemas[key] = jsonSchema;
        } catch (error) {
          console.warn(`Warning: Could not convert ${propName} for ${metadata.name}:`, error);
        }
      }
      return Object.keys(schemas).length > 0 ? schemas : undefined;
    }

    const varDecl = sourceFile.getVariableDeclaration(metadata.exportName);
    if (!varDecl) return undefined;

    const initializer = varDecl.getInitializer();
    if (!initializer || !Node.isCallExpression(initializer)) return undefined;

    const args = initializer.getArguments();
    if (args.length === 0) return undefined;

    const config = args[0];
    if (!Node.isObjectLiteralExpression(config)) return undefined;

    for (const { prop: propName, key, metaFlag } of schemaProps) {
      if (metadata.metadata[metaFlag]) {
        const schemaNode = extractSchemaProperty(config, propName);
        if (schemaNode) {
          try {
            const jsonSchema = await zodToJsonSchema(schemaNode);
            schemas[key] = jsonSchema;
          } catch (error) {
            console.warn(`Warning: Could not convert ${propName} for ${metadata.name}:`, error);
          }
        }
      }
    }

    return Object.keys(schemas).length > 0 ? schemas : undefined;
  }

  toManifestEntry(compiled: CompiledPrimitive, _allPrimitives?: CompiledPrimitive[]): ManifestPrimitive {
    return {
      ...this.baseManifestFields(compiled),
      schemas: compiled.schemas
        ? {
            query: compiled.schemas.query,
            headers: compiled.schemas.headers,
            body: compiled.schemas.body,
          }
        : undefined,
    } as ManifestWebhook;
  }
}
