#!/usr/bin/env node
/**
 * Lua CLI - Main Entry Point
 *
 * Command-line interface for managing Lua AI skills.
 * Provides tools for authentication, project initialization, compilation,
 * testing, deployment, and development.
 *
 * For more information: https://docs.heylua.ai
 */

import { Command } from 'commander';
import { setupAuthCommands, setupSkillCommands, setupMarketplaceCommands } from './cli/command-definitions.js';
import { setCiMode } from './utils/cli.js';
import { printBanner } from './utils/banner.js';
import { getCliVersion } from './utils/package-root.js';

const CLI_VERSION = getCliVersion();

const args = process.argv.slice(2);
const isBareInvocation = args.length === 0;
const isHelpInvocation = args.includes('--help') || args.includes('-h');
if (isBareInvocation || isHelpInvocation) {
  printBanner({ version: CLI_VERSION });
}

// Create the main CLI program
const program = new Command();

// Configure program metadata
program
  .showSuggestionAfterError()
  .name('lua')
  .description('Lua AI - Build and deploy AI agents with superpowers')
  .version(CLI_VERSION)
  .option('--ci', 'CI/CD mode: fail loudly on missing required flags instead of prompting')
  .addHelpText(
    'after',
    `
Categories:
  🔐 Authentication    Manage API keys and authentication
  🚀 Project Setup     Initialize and configure projects
  📦 Development       Build and test your skills locally
  ☁️ Deployment        Push and deploy to production
  💬 Testing           Chat and test your agent
  ⚙️ Configuration     Manage environment and persona
  📡 Devices           Connect and manage IoT/external devices
  📖 Utilities         Quick access to admin and docs

Examples:
  $ lua auth configure     🔑 Set up your API key
  $ lua init               🚀 Initialize a new project
  $ lua compile            📦 Compile your skills
  $ lua test               🧪 Test tools interactively
  $ lua push               ☁️ Push to server (interactive)
  $ lua push skill         ☁️ Push skill directly
  $ lua push device        ☁️ Push device definition
  $ lua push device-trigger ☁️ Push device trigger
  $ lua push persona       ☁️ Push persona directly
  $ lua deploy             🚀 Deploy to production
  $ lua chat               💬 Start interactive chat
  $ lua env                ⚙️ Manage environment variables (interactive)
  $ lua env staging        ⚙️ Manage staging env vars directly
  $ lua env production     ⚙️ Manage production env vars directly
  $ lua persona            🤖 Manage agent persona (interactive)
  $ lua persona staging    🤖 Manage staging persona directly
  $ lua persona production 🤖 Manage production persona directly
  $ lua skills             ⚙️ Manage skills (interactive)
  $ lua skills staging     ⚙️ View staging skills directly
  $ lua skills production  ⚙️ Manage production skills directly
  $ lua devices            📡 Manage connected devices (interactive)
  $ lua devices list       📡 List all devices and their status
  $ lua devices status --device-name my-device   Check device status
  $ lua devices test --device-name my-device     Test a device command
  $ lua push device-trigger 📡 Push a device trigger to server
  $ lua features           🎯 Manage agent features
  $ lua admin              🔧 Open admin dashboard
  $ lua evals              📊 Open evaluations dashboard
  $ lua docs               📖 Open documentation
  $ lua completion         🎯 Enable shell autocomplete
  $ lua marketplace        🛍️ Interact with the Lua Marketplace
 
 🌙 Documentation: https://docs.heylua.ai
 🌙 Support: https://heylua.ai/support
`
  );

// Set CI mode before any command runs (must happen before parse, since actions are async)
program.hook('preAction', (thisCommand) => {
  const opts = thisCommand.opts();
  if (opts.ci) {
    setCiMode(true);
  }
});

// Set up all command groups
setupAuthCommands(program);
setupSkillCommands(program);
setupMarketplaceCommands(program);

// Parse command-line arguments
program.parse(process.argv);
