import { HttpClient } from './http.client.js';
import { ApiResponse } from '../interfaces/common.js';

/**
 * PreProcessor API Response Types
 */
export interface PreProcessorVersion {
  version: string;
  preprocessorId: string;
  createdAt: string | number;
  isActive?: boolean;
}

export interface GetPreProcessorsResponse {
  preprocessors: Array<{
    id: string;
    name: string;
    description?: string;
    versions: PreProcessorVersion[];
    activeVersionId?: string;
  }>;
}

export interface CreatePreProcessorResponse {
  id: string;
  name: string;
  description?: string;
  agentId: string;
}

export interface PreProcessorVersionResponse {
  versionId: string;
  preprocessorId: string;
  version: string;
  createdAt: string;
}

export interface DeletePreProcessorResponse {
  deleted: boolean;
  deactivated?: boolean;
  message: string;
}

/**
 * PreProcessor API Service
 * Handles all preprocessor-related API calls
 */
export default class PreProcessorApi extends HttpClient {
  private apiKey: string;
  private agentId: string;

  constructor(baseUrl: string, apiKey: string, agentId: string) {
    super(baseUrl);
    this.apiKey = apiKey;
    this.agentId = agentId;
  }

  /**
   * Retrieves all preprocessors for the agent
   */
  async getPreProcessors(): Promise<ApiResponse<GetPreProcessorsResponse>> {
    return this.httpGet<GetPreProcessorsResponse>(`/developer/preprocessors/${this.agentId}`, {
      Authorization: `Bearer ${this.apiKey}`,
    });
  }

  /**
   * Creates a new preprocessor for the agent
   */
  async createPreProcessor(data: {
    name: string;
    description?: string;
  }): Promise<ApiResponse<CreatePreProcessorResponse>> {
    return this.httpPost<CreatePreProcessorResponse>(`/developer/preprocessors/${this.agentId}`, data, {
      Authorization: `Bearer ${this.apiKey}`,
    });
  }

  /**
   * Pushes a new version of a preprocessor
   *
   * @param preprocessorId - The preprocessor ID
   * @param versionData - Version data including code, description, and async flag
   * @param versionData.version - Version number
   * @param versionData.code - Compressed execute function code
   * @param versionData.description - Preprocessor description
   * @param versionData.async - Async execution flag (true = background, false = blocking)
   * @param versionData.priority - Execution priority (lower runs first; default 100)
   */
  async pushPreProcessor(
    preprocessorId: string,
    versionData: {
      name: string;
      version: string;
      description?: string;
      preprocessorId: string;
      code?: string;
      codeS3Hash?: string;
      async?: boolean;
      priority?: number;
    }
  ): Promise<ApiResponse<PreProcessorVersionResponse>> {
    return this.httpPost<PreProcessorVersionResponse>(
      `/developer/preprocessors/${this.agentId}/${preprocessorId}/version`,
      versionData,
      {
        Authorization: `Bearer ${this.apiKey}`,
      }
    );
  }

  /**
   * Retrieves all versions of a specific preprocessor
   */
  async getPreProcessorVersions(
    preprocessorId: string
  ): Promise<ApiResponse<{ versions: PreProcessorVersion[]; activeVersionId?: string }>> {
    return this.httpGet<{ versions: PreProcessorVersion[]; activeVersionId?: string }>(
      `/developer/preprocessors/${this.agentId}/${preprocessorId}/versions`,
      {
        Authorization: `Bearer ${this.apiKey}`,
      }
    );
  }

  /**
   * Publishes a specific version of a preprocessor to production
   */
  async publishPreProcessorVersion(
    preprocessorId: string,
    version: string
  ): Promise<ApiResponse<{ message: string; preprocessorId: string; activeVersionId: string; publishedAt: string }>> {
    return this.httpPost<{ message: string; preprocessorId: string; activeVersionId: string; publishedAt: string }>(
      `/developer/preprocessors/${this.agentId}/${preprocessorId}/${version}/publish`,
      {},
      {
        Authorization: `Bearer ${this.apiKey}`,
      }
    );
  }

  /**
   * Activates a preprocessor
   */
  async activatePreProcessor(preprocessorId: string): Promise<ApiResponse<{ message: string; active: boolean }>> {
    return this.httpPost<{ message: string; active: boolean }>(
      `/developer/preprocessors/${this.agentId}/${preprocessorId}/activate`,
      {},
      {
        Authorization: `Bearer ${this.apiKey}`,
      }
    );
  }

  /**
   * Deactivates a preprocessor
   */
  async deactivatePreProcessor(preprocessorId: string): Promise<ApiResponse<{ message: string; active: boolean }>> {
    return this.httpPost<{ message: string; active: boolean }>(
      `/developer/preprocessors/${this.agentId}/${preprocessorId}/deactivate`,
      {},
      {
        Authorization: `Bearer ${this.apiKey}`,
      }
    );
  }

  /**
   * Deletes a preprocessor
   */
  async deletePreProcessor(preprocessorId: string): Promise<ApiResponse<DeletePreProcessorResponse>> {
    return this.httpDelete<DeletePreProcessorResponse>(`/developer/preprocessors/${this.agentId}/${preprocessorId}`, {
      Authorization: `Bearer ${this.apiKey}`,
    });
  }

  /**
   * Pushes a new sandbox (dev) version of a preprocessor
   * Creates a new sandbox version for testing without affecting production
   *
   * @param preprocessorId - The preprocessor ID
   * @param versionData - Version data including code and async flag
   * @returns Sandbox version response with sandboxId
   */
  async pushDevPreProcessor(
    preprocessorId: string,
    versionData: {
      name: string;
      version?: string;
      description?: string;
      code?: string;
      codeS3Hash?: string;
      async?: boolean;
      priority?: number;
    }
  ): Promise<ApiResponse<{ versionId: string; preprocessorId: string; version: string; createdAt: string }>> {
    return this.httpPost(`/developer/preprocessors/${this.agentId}/${preprocessorId}/version/sandbox`, versionData, {
      Authorization: `Bearer ${this.apiKey}`,
    });
  }

  /**
   * Updates an existing sandbox version of a preprocessor
   *
   * @param preprocessorId - The preprocessor ID
   * @param sandboxVersionId - The sandbox version ID to update
   * @param versionData - Updated version data
   * @returns Update response
   */
  async updateDevPreProcessor(
    preprocessorId: string,
    sandboxVersionId: string,
    versionData: {
      name: string;
      version?: string;
      description?: string;
      code?: string;
      codeS3Hash?: string;
      async?: boolean;
      priority?: number;
    }
  ): Promise<ApiResponse<{ message: string; versionId: string }>> {
    return this.httpPut(
      `/developer/preprocessors/${this.agentId}/${preprocessorId}/version/sandbox/${sandboxVersionId}`,
      versionData,
      {
        Authorization: `Bearer ${this.apiKey}`,
      }
    );
  }
}
