/**
 * Loads API key and agent ID, failing with clear error if not configured.
 */
async function loadAuthOrFail(): Promise<{ apiKey: string; agentId: string; config: any }> {
  const { config, agentId, apiKey } = await initializeCommand({ showProgress: false });
  return { apiKey, agentId, config };
}

/**
 * Prompts user to select a tool from the list.
 */
async function promptToolSelection(tools: ToolData[]): Promise<ToolData> {
  const toolChoices: ToolChoice[] = tools.map((tool: ToolData) => ({
    name: tool.skillName
      ? `${tool.name} (${tool.skillName}) - ${tool.description}`
      : `${tool.name} - ${tool.description}`,
    value: tool,
  }));

  const { selectedTool } = await inquirer.prompt([
    {
      type: 'list',
      name: 'selectedTool',
      message: '🔧 Select a tool to test:',
      choices: toolChoices,
      pageSize: 10,
    },
  ]);

  return selectedTool;
}

/**
 * Wraps execution with sandbox environment (env vars setup/teardown).
 */
async function withSandboxEnv<T>(fn: () => Promise<T>): Promise<T> {
  const envVars = loadEnvironmentVariables();
  const originalEnv = { ...process.env };

  for (const [key, value] of Object.entries(envVars)) {
    process.env[key] = value;
  }

  try {
    return await fn();
  } finally {
    process.env = originalEnv;
  }
}

/**
 * Parses JSON input, failing with formatted error message.
 */
function parseJsonInputOrFail<T>(inputJson: string, expectedFormat: string): T {
  try {
    return JSON.parse(inputJson);
  } catch (error) {
    console.error(`❌ Invalid JSON input: ${error instanceof Error ? error.message : 'Unknown error'}`);
    console.log(`Expected format: ${expectedFormat}`);
    throw new Error(`Invalid JSON input: ${error instanceof Error ? error.message : 'Unknown error'}`);
  }
}

interface SelectEntityOptions<T> {
  items: T[];
  entityName: string | null;
  entityType: string;
  idProperty: keyof T;
  nameProperty: keyof T;
  promptMessage: string;
  formatChoice?: (item: T) => string;
  asJson?: boolean;
}

/**
 * Selects an entity by name (non-interactive) or prompts user (interactive).
 */
async function selectEntityOrPrompt<T>(options: SelectEntityOptions<T>): Promise<T | null> {
  const { items, entityName, entityType, idProperty, nameProperty, promptMessage, formatChoice, asJson } = options;

  if (entityName) {
    const selected = items.find((item: T) => item[idProperty] === entityName || item[nameProperty] === entityName);
    if (!selected) {
      console.error(`❌ ${entityType} "${entityName}" not found`);
      throw new Error(`${entityType} "${entityName}" not found`);
    }
    progress(asJson ?? false, `✅ Selected ${entityType.toLowerCase()}: ${selected[nameProperty]}`);
    return selected;
  }

  const answer = await safePrompt<{ selected: T }>([
    {
      type: 'list',
      name: 'selected',
      message: promptMessage,
      choices: items.map((item: T) => ({
        name: formatChoice ? formatChoice(item) : `${item[nameProperty]}`,
        value: item,
      })),
    },
  ]);

  if (!answer) return null;
  return answer.selected;
}

/**
 * Writes a progress message. In `--json` mode, routes to stderr so stdout
 * stays clean for the final JSON payload (allowing `| jq` etc.).
 */
function progress(asJson: boolean, message: string): void {
  if (asJson) {
    process.stderr.write('\r\x1b[K' + message + '\n');
  } else {
    writeProgress(message);
  }
}

/**
 * Writes a success message. In `--json` mode, routes to stderr (see `progress`).
 */
function success(asJson: boolean, message: string): void {
  if (asJson) {
    process.stderr.write('\r\x1b[K' + message + '\n');
  } else {
    writeSuccess(message);
  }
}

/**
 * Runs `compileCommand` with stdout redirected to stderr when `asJson` is
 * true, so compile output (which uses `console.log` and direct stdout writes)
 * doesn't pollute the JSON stream piped from `lua test --json`.
 */
async function compileQuietly(asJson: boolean): Promise<void> {
  if (!asJson) {
    await compileCommand();
    return;
  }

  const originalLog = console.log;
  const originalInfo = console.info;
  const originalStdoutWrite = process.stdout.write.bind(process.stdout);

  // Re-route stdout writes to stderr for the duration of compile.
  console.log = console.error;
  console.info = console.error;
  process.stdout.write = process.stderr.write.bind(process.stderr) as typeof process.stdout.write;

  try {
    await compileCommand();
  } finally {
    console.log = originalLog;
    console.info = originalInfo;
    process.stdout.write = originalStdoutWrite;
  }
}

/**
 * Handles execution errors with consistent formatting.
 */
function handleExecutionError(error: any, entityType: string): void {
  console.error(`\n❌ ${entityType} execution failed:`);
  console.error(error.message);
  if (error.stack) {
    console.error(error.stack);
  }
}

/**
 * Extracts all tools from manifest (grouped by skill).
 */
function extractToolsFromManifest(manifest: CompilationManifest): any[] {
  const tools = getPrimitivesByKind<ManifestTool>(manifest, PrimitiveKind.TOOL);
  const skills = getPrimitivesByKind<ManifestSkill>(manifest, PrimitiveKind.SKILL);

  // Create a map of tool name to skill name
  const toolToSkill = new Map<string, string>();
  for (const skill of skills) {
    for (const toolName of skill.tools || []) {
      toolToSkill.set(toolName, skill.name);
    }
  }

  return tools.map((tool) => ({
    ...tool,
    id: tool.name,
    skillName: toolToSkill.get(tool.name) || 'unknown',
  }));
}

