import { HttpClient } from './http.client.js';
import { ApiResponse } from '../interfaces/common.js';

/**
 * PostProcessor API Response Types
 */
export interface PostProcessorVersion {
  version: string;
  postprocessorId: string;
  createdAt: string | number;
  isActive?: boolean;
}

export interface GetPostProcessorsResponse {
  postprocessors: Array<{
    id: string;
    name: string;
    description?: string;
    versions: PostProcessorVersion[];
    activeVersionId?: string;
  }>;
}

export interface CreatePostProcessorResponse {
  id: string;
  name: string;
  description?: string;
  priority: number;
  agentId: string;
}

export interface PostProcessorVersionResponse {
  versionId: string;
  postprocessorId: string;
  version: string;
  createdAt: string;
}

export interface DeletePostProcessorResponse {
  deleted: boolean;
  deactivated?: boolean;
  message: string;
}

/**
 * PostProcessor API Service
 * Handles all postprocessor-related API calls
 */
export default class PostProcessorApi extends HttpClient {
  private apiKey: string;
  private agentId: string;

  constructor(baseUrl: string, apiKey: string, agentId: string) {
    super(baseUrl);
    this.apiKey = apiKey;
    this.agentId = agentId;
  }

  /**
   * Retrieves all postprocessors for the agent
   */
  async getPostProcessors(): Promise<ApiResponse<GetPostProcessorsResponse>> {
    return this.httpGet<GetPostProcessorsResponse>(`/developer/postprocessors/${this.agentId}`, {
      Authorization: `Bearer ${this.apiKey}`,
    });
  }

  /**
   * Creates a new postprocessor for the agent
   */
  async createPostProcessor(data: {
    name: string;
    description?: string;
  }): Promise<ApiResponse<CreatePostProcessorResponse>> {
    return this.httpPost<CreatePostProcessorResponse>(`/developer/postprocessors/${this.agentId}`, data, {
      Authorization: `Bearer ${this.apiKey}`,
    });
  }

  /**
   * Pushes a new version of a postprocessor
   *
   * @param postprocessorId - The postprocessor ID
   * @param versionData - Version data including code and description
   * @param versionData.version - Version number
   * @param versionData.code - Compressed execute function code
   * @param versionData.description - Postprocessor description
   */
  async pushPostProcessor(
    postprocessorId: string,
    versionData: {
      name: string;
      version: string;
      description?: string;
      postprocessorId: string;
      priority?: number;
      code?: string;
      codeS3Hash?: string;
    }
  ): Promise<ApiResponse<PostProcessorVersionResponse>> {
    return this.httpPost<PostProcessorVersionResponse>(
      `/developer/postprocessors/${this.agentId}/${postprocessorId}/version`,
      versionData,
      {
        Authorization: `Bearer ${this.apiKey}`,
      }
    );
  }

  /**
   * Retrieves all versions of a specific postprocessor
   */
  async getPostProcessorVersions(
    postprocessorId: string
  ): Promise<ApiResponse<{ versions: PostProcessorVersion[]; activeVersionId?: string }>> {
    return this.httpGet<{ versions: PostProcessorVersion[]; activeVersionId?: string }>(
      `/developer/postprocessors/${this.agentId}/${postprocessorId}/versions`,
      {
        Authorization: `Bearer ${this.apiKey}`,
      }
    );
  }

  /**
   * Publishes a specific version of a postprocessor to production
   */
  async publishPostProcessorVersion(
    postprocessorId: string,
    version: string
  ): Promise<ApiResponse<{ message: string; postprocessorId: string; activeVersionId: string; publishedAt: string }>> {
    return this.httpPost<{ message: string; postprocessorId: string; activeVersionId: string; publishedAt: string }>(
      `/developer/postprocessors/${this.agentId}/${postprocessorId}/${version}/publish`,
      {},
      {
        Authorization: `Bearer ${this.apiKey}`,
      }
    );
  }

  /**
   * Activates a postprocessor
   */
  async activatePostProcessor(postprocessorId: string): Promise<ApiResponse<{ message: string; active: boolean }>> {
    return this.httpPost<{ message: string; active: boolean }>(
      `/developer/postprocessors/${this.agentId}/${postprocessorId}/activate`,
      {},
      {
        Authorization: `Bearer ${this.apiKey}`,
      }
    );
  }

  /**
   * Deactivates a postprocessor
   */
  async deactivatePostProcessor(postprocessorId: string): Promise<ApiResponse<{ message: string; active: boolean }>> {
    return this.httpPost<{ message: string; active: boolean }>(
      `/developer/postprocessors/${this.agentId}/${postprocessorId}/deactivate`,
      {},
      {
        Authorization: `Bearer ${this.apiKey}`,
      }
    );
  }

  /**
   * Deletes a postprocessor
   */
  async deletePostProcessor(postprocessorId: string): Promise<ApiResponse<DeletePostProcessorResponse>> {
    return this.httpDelete<DeletePostProcessorResponse>(
      `/developer/postprocessors/${this.agentId}/${postprocessorId}`,
      {
        Authorization: `Bearer ${this.apiKey}`,
      }
    );
  }

  /**
   * Pushes a new sandbox (dev) version of a postprocessor
   * Creates a new sandbox version for testing without affecting production
   *
   * @param postprocessorId - The postprocessor ID
   * @param versionData - Version data including code
   * @returns Sandbox version response with sandboxId
   */
  async pushDevPostProcessor(
    postprocessorId: string,
    versionData: {
      name: string;
      version?: string;
      description?: string;
      priority?: number;
      code?: string;
      codeS3Hash?: string;
    }
  ): Promise<ApiResponse<{ versionId: string; postprocessorId: string; version: string; createdAt: string }>> {
    return this.httpPost(`/developer/postprocessors/${this.agentId}/${postprocessorId}/version/sandbox`, versionData, {
      Authorization: `Bearer ${this.apiKey}`,
    });
  }

  /**
   * Updates an existing sandbox version of a postprocessor
   *
   * @param postprocessorId - The postprocessor ID
   * @param sandboxVersionId - The sandbox version ID to update
   * @param versionData - Updated version data
   * @returns Update response
   */
  async updateDevPostProcessor(
    postprocessorId: string,
    sandboxVersionId: string,
    versionData: {
      name: string;
      version?: string;
      description?: string;
      priority?: number;
      code?: string;
      codeS3Hash?: string;
    }
  ): Promise<ApiResponse<{ message: string; versionId: string }>> {
    return this.httpPut(
      `/developer/postprocessors/${this.agentId}/${postprocessorId}/version/sandbox/${sandboxVersionId}`,
      versionData,
      {
        Authorization: `Bearer ${this.apiKey}`,
      }
    );
  }
}
