/**
 * Primitive Handler Types
 *
 * Interfaces for the handler-based architecture that manages
 * CLI operations for primitives (skills, webhooks, jobs, etc.)
 *
 * IMPORTANT: YAML item types live in yaml.types.ts (YamlConfigSkill, etc.)
 * Server item types live in interfaces/ (Skill, Webhook, Job, etc.)
 * Do NOT duplicate them here.
 */

import { PrimitiveKind, CompilationManifest } from '../compiler/types.js';
import { YamlConfig } from '../types/yaml.types.js';

// =============================================================================
// SYNC TYPES
// =============================================================================

/**
 * Result of a server sync operation
 */
export interface SyncResult {
  messages: string[];
  yamlUpdated: boolean;
  orphanedCount: number;
}

/**
 * Data fetched from server during sync (before any YAML writes).
 * Used by the parallel sync pipeline: fetch all handlers in parallel,
 * then apply YAML changes sequentially.
 */
export interface ServerSyncData {
  serverItems: any[] | null;
  fetchError?: string;
}

/**
 * Configuration for how a primitive type is stored in YAML
 */
export interface YamlPrimitiveConfig {
  /** Key in YamlConfig (e.g., 'skills', 'webhooks') */
  yamlKey: keyof YamlConfig;
  /** Field name for server ID in yaml items (e.g., 'skillId', 'webhookId') */
  idField: string;
}

// =============================================================================
// HANDLER INTERFACES
// =============================================================================

/**
 * Base interface for all primitive handlers.
 *
 * T = the YAML item type from yaml.types.ts (e.g., YamlConfigSkill)
 */
// eslint-disable-next-line @typescript-eslint/no-explicit-any
export interface PrimitiveHandler<T = any> {
  readonly kind: PrimitiveKind;
  readonly displayName: string;
  readonly displayNamePlural: string;
  readonly deleteCommand: string;
  readonly yamlConfig: YamlPrimitiveConfig;

  syncWithServer(
    apiKey: string,
    agentId: string,
    config: YamlConfig | null,
    manifest?: CompilationManifest
  ): Promise<SyncResult>;
  updateYaml(items: T[], config: YamlConfig | null): void;
  getFromYaml(config: YamlConfig | null): T[];
  cleanItem(item: T): T;
  prepareForPush(
    manifest: CompilationManifest,
    name: string,
    projectPath?: string,
    bundleAccumulator?: Map<string, Buffer>
  ): Record<string, unknown> | null;

  /** Phase 1 of parallel sync: fetch server state (HTTP only, no YAML writes) */
  fetchServerState(apiKey: string, agentId: string): Promise<ServerSyncData>;
  /** Phase 2 of parallel sync: apply fetched data to YAML (no HTTP except optional create-on-server) */
  applySyncToYaml(
    serverData: ServerSyncData,
    config: YamlConfig | null,
    manifest?: CompilationManifest,
    apiCredentials?: { apiKey: string; agentId: string }
  ): Promise<SyncResult>;
}

/**
 * Extended handler for primitives that have versions.
 *
 * T = the YAML item type (must have name + version + idField)
 */
// eslint-disable-next-line @typescript-eslint/no-explicit-any
export interface VersionedPrimitiveHandler<T = any> extends PrimitiveHandler<T> {
  isActive(serverItem: Record<string, unknown>): boolean;
  getActiveVersion(serverItem: Record<string, unknown>): string | null;
  updateVersionInYaml(name: string, newVersion: string, options?: { silent?: boolean }): void;
  syncYamlWithManifest(manifest: CompilationManifest, config: YamlConfig | null): void;
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  pushToServer(
    apiKey: string,
    agentId: string,
    entityId: string,
    pushData: any
  ): Promise<{ success: boolean; error?: string }>;
  publishVersion(
    apiKey: string,
    agentId: string,
    entityId: string,
    version: string
  ): Promise<{ success: boolean; error?: string }>;
  getHighestServerVersion(apiKey: string, agentId: string, entityId: string): Promise<string | null>;
  /** Fetch all server items once, extract highest version for each entity ID */
  batchGetHighestVersions(apiKey: string, agentId: string, entityIds: string[]): Promise<Map<string, string | null>>;
}

/**
 * Type guard to check if a handler supports versioning
 */
export function isVersionedHandler(handler: PrimitiveHandler): handler is VersionedPrimitiveHandler {
  return 'isActive' in handler && 'getActiveVersion' in handler;
}
