/**
 * Zod schema to JSON Schema converter.
 *
 * Uses ts-evaluator to evaluate Zod schema AST nodes at compile time,
 * automatically resolving imports, variables, and expressions.
 *
 * Zod and `zod-to-json-schema` are loaded from a vendored ESM bundle that
 * ships inside lua-cli's own `dist` directory (built by
 * `scripts/build-vendor.mjs`). This avoids `node_modules/zod` resolution at
 * runtime, which is fragile against corrupt/partial installs and hoisting
 * conflicts in user environments. See `SchemaConverterUnavailableError` for
 * the failure mode the preflight surfaces if the vendored bundle is missing.
 */

import { Node } from 'ts-morph';
import { getZodRuntimeUrl } from '../../utils/package-root.js';
import ts from 'typescript';
import { evaluate } from 'ts-evaluator';
import type { JSONSchema } from '../types.js';

/**
 * Thrown when the bundled zod runtime cannot be loaded. Indicates a broken
 * lua-cli installation, not a problem with the user's code. Surfaced by
 * `ensureSchemaConverterReady()` so the compiler can abort with an
 * actionable message before iterating primitives.
 */
export class SchemaConverterUnavailableError extends Error {
  readonly suggestion: string;

  constructor(message: string, suggestion: string, options?: { cause?: unknown }) {
    super(message, options as ErrorOptions);
    this.name = 'SchemaConverterUnavailableError';
    this.suggestion = suggestion;
  }
}

interface ZodRuntime {
  z: any;
  zodToJsonSchema: (schema: any, opts?: any) => any;
}

let vendorPromise: Promise<ZodRuntime> | null = null;

function vendorBundleUrl(): URL {
  // Anchored to lua-cli's package root (located via package-root.ts) so the
  // URL stays stable whether this code runs from src/ during jest, or from a
  // bundled dist/<entry>.js after tsup flattens the module structure.
  return getZodRuntimeUrl();
}

async function loadVendor(): Promise<ZodRuntime> {
  if (vendorPromise) return vendorPromise;
  const url = vendorBundleUrl();
  vendorPromise = (async () => {
    const failures: string[] = [];

    // Primary path: the vendored bundle that ships inside lua-cli's own
    // `dist/`. This is what published installs use and is the resolution
    // anchor that survives broken `node_modules/zod` (the failure mode that
    // motivated vendoring in the first place).
    try {
      const mod = await import(url.href);
      if (mod && typeof mod.z !== 'undefined' && typeof mod.zodToJsonSchema === 'function') {
        return { z: mod.z, zodToJsonSchema: mod.zodToJsonSchema };
      }
      failures.push(`vendored bundle (${url.pathname}) loaded but did not export the expected { z, zodToJsonSchema }`);
    } catch (cause: any) {
      failures.push(`vendored bundle (${url.pathname}): ${cause?.message || cause}`);
    }

    // Fallback path: bare `'zod'` / `'zod-to-json-schema'` from
    // `node_modules`. Used during local development and tests in this
    // repo (where Jest runs `src/` and the vendor bundle only exists in
    // `dist/`) and as defence-in-depth if the vendored bundle is somehow
    // missing in a published install.
    try {
      const [zodMod, converterMod] = await Promise.all([import('zod'), import('zod-to-json-schema')]);
      if (zodMod?.z && typeof converterMod?.zodToJsonSchema === 'function') {
        return { z: zodMod.z, zodToJsonSchema: converterMod.zodToJsonSchema };
      }
      failures.push('node_modules zod / zod-to-json-schema imported but missing expected exports');
    } catch (cause: any) {
      failures.push(`node_modules fallback: ${cause?.message || cause}`);
    }

    vendorPromise = null;
    throw new SchemaConverterUnavailableError(
      `lua-cli could not load a working zod runtime. Tried: ${failures.join(' | ')}`,
      'Reinstall lua-cli: `npm cache clean --force && npm install -g lua-cli@latest`. ' +
        'If you installed via pnpm, run `pnpm store prune && pnpm install` in your project.'
    );
  })();
  return vendorPromise;
}

/**
 * Preflight check: load the vendored zod runtime once so the compiler can
 * fail loudly with an actionable message before iterating primitives. Safe
 * to call multiple times — the result is memoized.
 */
export async function ensureSchemaConverterReady(): Promise<void> {
  await loadVendor();
}

/**
 * Convert a Zod schema AST node to JSON Schema.
 *
 * Uses ts-evaluator for proper AST evaluation — resolves all variable
 * references, imports, and expressions automatically.
 *
 * @param schemaNode - The ts-morph node containing the Zod schema
 * @returns JSON Schema object
 */
export async function zodToJsonSchema(schemaNode: Node): Promise<JSONSchema> {
  // Vendor load failures are fatal — propagate so the compiler can stop.
  // User-code evaluation failures are degraded to `{ type: 'object' }` below.
  const { z, zodToJsonSchema: convertSchema } = await loadVendor();

  try {
    const sourceFile = schemaNode.getSourceFile();
    const project = sourceFile.getProject();

    const tsNode = schemaNode.compilerNode as ts.Expression;
    const typeChecker = project.getTypeChecker().compilerObject;

    const result = evaluate({
      node: tsNode,
      typeChecker,
      typescript: ts,
      environment: {
        preset: 'NODE',
        extra: { z },
      },
      policy: {
        deterministic: false,
        network: false,
        console: false,
        io: { read: true, write: false },
        process: { exit: false, spawnChild: false },
      },
    });

    if (!result.success) {
      throw new Error(result.reason?.message || 'Failed to evaluate schema');
    }

    const zodSchema = result.value;
    if (!zodSchema || typeof zodSchema !== 'object') {
      return { type: 'object' };
    }

    // zod-to-json-schema returns its own JsonSchema7 type, cast for compatibility
    const jsonSchema = convertSchema(zodSchema as any, { target: 'jsonSchema7' });
    return cleanJsonSchema(jsonSchema);
  } catch (error: any) {
    console.warn(`Warning: Could not convert Zod schema:`, error?.message || error);
    return { type: 'object' };
  }
}

/**
 * Clean up JSON Schema by removing unnecessary properties.
 */
function cleanJsonSchema(schema: any): JSONSchema {
  // Remove top-level metadata we don't need
  const { $schema, title, definitions, $ref, ...cleanSchema } = schema;

  // If there's a $ref to definitions, inline it
  if ($ref && definitions) {
    const refName = $ref.replace('#/definitions/', '');
    if (definitions[refName]) {
      return cleanJsonSchema(definitions[refName]);
    }
  }

  return cleanSchema;
}

/**
 * Convert a Zod schema string to JSON Schema.
 * Fallback for when only a string representation is available (no AST node).
 *
 * @param zodSchemaCode - String representation of Zod schema
 * @returns JSON Schema object
 */
export async function zodStringToJsonSchema(zodSchemaCode: string): Promise<JSONSchema> {
  const { z, zodToJsonSchema: convertSchema } = await loadVendor();
  try {
    const evalFunction = new Function('z', `return ${zodSchemaCode}`);
    const zodSchema = evalFunction(z);
    const jsonSchema = convertSchema(zodSchema, { target: 'jsonSchema7' });

    return cleanJsonSchema(jsonSchema);
  } catch (error: any) {
    console.warn(`Warning: Could not evaluate Zod schema string:`, error?.message || error);
    return { type: 'object' };
  }
}
