/**
 * PreProcessor Handler
 *
 * Handles CLI operations for preprocessor primitives.
 *
 * PreProcessors:
 * - Use 'activeVersionId' for active detection (no top-level 'active' field)
 * - Use 'isActive' field on versions
 */

import { PrimitiveKind, ManifestPrimitive, ManifestPreProcessor } from '../compiler/types.js';
import { BASE_URLS } from '../config/constants.js';
import PreProcessorApi from '../api/preprocessor.api.service.js';
import { BaseVersionedHandler } from './base.handler.js';
import type { YamlPrimitiveConfig } from './types.js';
import type { YamlConfigPreprocessor } from '../types/yaml.types.js';

/**
 * PreProcessor primitive handler
 */
type PreProcessorPushData = Parameters<PreProcessorApi['pushPreProcessor']>[1];

export class PreprocessorHandler extends BaseVersionedHandler<YamlConfigPreprocessor, PreProcessorPushData> {
  readonly kind = PrimitiveKind.PREPROCESSOR;
  readonly displayName = 'preprocessor';
  readonly displayNamePlural = 'preprocessors';
  readonly deleteCommand = 'lua preprocessors delete';
  readonly yamlConfig: YamlPrimitiveConfig = {
    yamlKey: 'preprocessors',
    idField: 'preprocessorId',
  };

  protected getApi(apiKey: string, agentId: string): PreProcessorApi {
    return new PreProcessorApi(BASE_URLS.API, apiKey, agentId);
  }

  protected async fetchFromServer(api: PreProcessorApi): Promise<any[] | null> {
    const response = await api.getPreProcessors();
    if (!response.success || !response.data?.preprocessors) {
      return null;
    }
    return response.data.preprocessors;
  }

  protected async createOnServer(api: PreProcessorApi, primitive: ManifestPrimitive): Promise<string | null> {
    const response = await api.createPreProcessor({
      name: primitive.name,
      description: primitive.description || `A Lua preprocessor for ${primitive.name}`,
    });
    if (!response.success || !response.data?.id) return null;
    return response.data.id;
  }

  async pushToServer(apiKey: string, agentId: string, entityId: string, pushData: PreProcessorPushData) {
    const api = this.getApi(apiKey, agentId);
    const response = await api.pushPreProcessor(entityId, { ...pushData, preprocessorId: entityId });
    return { success: response.success, error: response.error?.message };
  }

  async publishVersion(apiKey: string, agentId: string, entityId: string, version: string) {
    const api = this.getApi(apiKey, agentId);
    const response = await api.publishPreProcessorVersion(entityId, version);
    return { success: response.success, error: response.error?.message };
  }

  /**
   * Override to include async flag and priority in push data.
   * Reads values extracted from source during compilation.
   */
  protected buildPushData(
    primitive: ManifestPrimitive,
    compressedCode: string | undefined,
    codeS3Hash?: string
  ): Record<string, unknown> {
    const preProcessor = primitive as ManifestPreProcessor;
    return {
      name: primitive.name,
      description: primitive.description,
      ...(codeS3Hash ? { codeS3Hash } : { code: compressedCode }),
      async: Boolean(preProcessor.isAsync ?? false),
      ...(preProcessor.priority !== undefined ? { priority: preProcessor.priority } : {}),
    };
  }
}

// Export singleton instance
export const preprocessorHandler = new PreprocessorHandler();
