/**
 * Agent Handler
 *
 * Consolidates all agent-level push/pull/drift operations.
 * Unlike other handlers, does NOT extend BaseVersionedHandler or BaseNonVersionedHandler —
 * the agent isn't a versioned primitive and doesn't use YAML for state tracking.
 *
 * Owns:
 * - Push: name, persona (versioned), model, modelResolver → server
 * - Pull: name, persona, model ← server → local source code
 * - Drift: detect differences between local and server state
 * - Unified push: push all agent config from manifest in one call
 */

import { hasPersonaTextContent } from '@lua/shared-types';
import { AuthenticationError } from '../errors/auth.error.js';
import { writeProgress, writeSuccess } from '../utils/cli.js';
import { setAgentName, setAgentPersona, setAgentModel } from '../compiler/index.js';
import {
  fetchServerAgent,
  checkPersonaDrift,
  checkNameDrift,
  checkModelDrift,
  checkGovernanceDrift,
} from '../utils/sync-fetch.js';
import type { PersonaDrift, NameDrift, ModelDrift, GovernanceDrift } from '../utils/sync-fetch.js';
import type { CompilationManifest, ManifestAgent } from '../compiler/types.js';
import { PrimitiveKind } from '../compiler/types.js';
import { getPrimitivesByKind, loadArtifact, compressForPush } from '../utils/artifact-loader.js';
import PersonaApi from '../api/persona.api.service.js';
import AgentApi from '../api/agent.api.service.js';
import { BASE_URLS } from '../config/constants.js';
import { readYamlConfig } from '../utils/files.js';
import type { BatchingConfig, PersonaText } from '@lua/shared-types';

// =============================================================================
// TYPES
// =============================================================================

export interface AgentDrift {
  name: NameDrift | null;
  persona: PersonaDrift | null;
  model: ModelDrift | null;
  governance: GovernanceDrift | null;
}

export interface AgentPushResult {
  persona?: { success: boolean; version?: number };
  model?: { success: boolean };
  batching?: { success: boolean };
  governance?: { success: boolean };
  voices?: { success: boolean; cleared?: boolean };
}

interface SyncContext {
  apiKey: string;
  agentId: string;
}

// =============================================================================
// AGENT HANDLER
// =============================================================================

function stripApiKey<T extends { apiKey?: unknown }>(governance: T): Omit<T, 'apiKey'> {
  const { apiKey: _stripped, ...rest } = governance;
  return rest;
}

export class AgentHandler {
  // ===========================================================================
  // UNIFIED PUSH (from manifest — used by "lua push all" and "lua push agent")
  // ===========================================================================

  /**
   * Push all agent-level config from the compilation manifest to the server.
   * Pushes persona (creates version) + model/modelResolver (updates agent).
   */
  async pushAgentConfig(apiKey: string, agentId: string, manifest: CompilationManifest): Promise<AgentPushResult> {
    const result: AgentPushResult = {};

    const agent = getPrimitivesByKind<ManifestAgent>(manifest, PrimitiveKind.AGENT)[0];

    // Push persona (creates a new version)
    const persona = agent?.persona;
    if (hasPersonaTextContent(persona)) {
      writeProgress('\n🌙 Pushing persona...');
      try {
        const personaResult = await this.pushPersona({ apiKey, agentId }, persona);
        result.persona = personaResult;
        if (personaResult.success) {
          writeSuccess(`  ✅ Persona version ${personaResult.version} created`);
        } else {
          console.error('  ❌ Failed to push persona');
        }
      } catch (error: any) {
        // Auth/access errors are fatal — the same problem will recur on
        // model, batching, and governance pushes below, and the user needs
        // the BAC-202 remediation hint from withErrorHandling, not a
        // truncated "Failed to push persona" line.
        if (AuthenticationError.isAuthenticationError(error)) throw error;
        console.error(`  ❌ Failed to push persona: ${error.message}`);
        result.persona = { success: false };
      }
    }

    // Push model configuration — always runs so that removing a model sends an
    // explicit null to clear the stale value on the server (BAC-87).
    const model = agent?.model;
    const hasModelResolver = agent?.hasModelResolver;

    writeProgress('\n🤖 Pushing model configuration...');
    try {
      let modelToSend: string | null | undefined = model;
      let modelResolver: string | null | undefined;

      if (hasModelResolver && agent?.path) {
        const artifactCode = loadArtifact(agent);
        modelResolver = compressForPush(artifactCode);
      } else if (!model && !hasModelResolver) {
        modelToSend = null;
        modelResolver = null;
      }

      const success = await this.pushModel({ apiKey, agentId }, modelToSend, modelResolver);
      result.model = { success };
      if (success) {
        if (model || hasModelResolver) {
          writeSuccess(`  ✅ Model ${hasModelResolver ? 'resolver' : `"${model}"`} pushed`);
        } else {
          writeSuccess('  ✅ Model configuration cleared');
        }
      } else {
        console.error('  ❌ Failed to push model');
      }
    } catch (error: any) {
      if (AuthenticationError.isAuthenticationError(error)) throw error;
      console.error(`  ❌ Failed to push model: ${error.message}`);
      result.model = { success: false };
    }

    // Push batching config — always runs so that removing batching sends an
    // explicit null to clear the stale value on the server.
    const batching = agent?.batching ?? null;

    writeProgress('\n⏱  Pushing batching configuration...');
    try {
      const success = await this.pushBatching({ apiKey, agentId }, batching);
      result.batching = { success };
      if (success) {
        if (batching) {
          writeSuccess('  ✅ Batching config pushed');
        } else {
          writeSuccess('  ✅ Batching config cleared (using platform defaults)');
        }
      } else {
        console.error('  ❌ Failed to push batching config');
      }
    } catch (error: any) {
      if (AuthenticationError.isAuthenticationError(error)) throw error;
      console.error(`  ❌ Failed to push batching config: ${error.message}`);
      result.batching = { success: false };
    }

    // Push the voices list so the runtime resolver knows which voices
    // belong to this agent. Always runs so that removing the voices entry
    // sends an explicit empty array, clearing stale refs (mirrors the
    // model-push pattern from BAC-87 — the alternative leaves dangling
    // voiceIds pointing at deleted voice agents on every rename).
    //
    // The one exception: when the manifest has voices but the YAML doesn't
    // yet have matching voiceIds (typical first-time push), skip rather
    // than nullify — the user expects voices to land on the next push,
    // not get their links cleared.
    const voiceRefNames = agent?.voiceRefs?.map((v) => v.name) ?? [];
    let voicesLinkPayload: { voiceId: string }[] | null = [];
    let skipVoicesPush = false;

    if (voiceRefNames.length > 0) {
      const yamlConfig = readYamlConfig();
      const resolved: { voiceId: string }[] = [];
      const missing: string[] = [];
      for (const refName of voiceRefNames) {
        // `filter` rather than `find` so YAML duplicate-name entries (which
        // read-your-writes uniqueness gaps in lua-agents can produce —
        // see the partial unique index fix in BAC-214) surface as a warn
        // instead of silently picking the first match.
        const matches = yamlConfig?.voices?.filter((v) => v.name === refName) ?? [];
        if (matches.length > 1) {
          console.warn(
            `  ⚠️  YAML has ${matches.length} voices with name "${refName}" — using the first match (voiceId=${matches[0].voiceId}). Resolve the duplicate.`
          );
        }
        const yamlVoice = matches[0];
        if (yamlVoice?.voiceId) {
          resolved.push({ voiceId: yamlVoice.voiceId });
        } else {
          missing.push(refName);
        }
      }

      if (missing.length > 0) {
        console.warn(
          `  ⚠️  Agent declares voices [${missing.join(', ')}] but YAML has no matching entries — skip; push the voices first.`
        );
        skipVoicesPush = true;
      } else {
        voicesLinkPayload = resolved;
      }
    }

    if (!skipVoicesPush) {
      writeProgress(voicesLinkPayload?.length ? '\n🎙️  Pushing voices...' : '\n🎙️  Clearing voices...');
      try {
        const success = await this.pushVoices({ apiKey, agentId }, voicesLinkPayload);
        result.voices = { success };
        if (success) {
          if (voicesLinkPayload?.length) {
            writeSuccess(`  ✅ Voices linked: ${voiceRefNames.join(', ')} (${voicesLinkPayload.length} voice(s))`);
          } else {
            writeSuccess('  ✅ Voices cleared');
          }
        } else {
          console.error('  ❌ Failed to push voices');
        }
      } catch (error: any) {
        if (AuthenticationError.isAuthenticationError(error)) throw error;
        console.error(`  ❌ Failed to push voices: ${error.message}`);
        result.voices = { success: false };
      }
    }

    // Push governance config only when the manifest actually defines it.
    // Agents that never configured governance don't trigger an unrelated
    // server write on every push. To explicitly clear a previously-set
    // config, use `lua governance remove`, which sends null via the same
    // pushGovernance path.
    const governance = agent?.governance;
    if (governance) {
      writeProgress('\n🛡️  Pushing governance configuration...');
      try {
        const success = await this.pushGovernance({ apiKey, agentId }, governance);
        result.governance = { success };
        if (success) {
          writeSuccess(`  ✅ Governance config pushed (${governance.mode} mode)`);
        } else {
          console.error('  ❌ Failed to push governance config');
        }
      } catch (error: any) {
        if (AuthenticationError.isAuthenticationError(error)) throw error;
        console.error(`  ❌ Failed to push governance config: ${error.message}`);
        result.governance = { success: false };
      }
    }

    return result;
  }

  // ===========================================================================
  // INDIVIDUAL PUSH (used by sync command)
  // ===========================================================================

  async pushName(ctx: SyncContext, name: string): Promise<boolean> {
    const agentApi = new AgentApi(BASE_URLS.API, ctx.apiKey);
    const result = await agentApi.updateAgent(ctx.agentId, { name });
    return result.success;
  }

  async pushPersona(ctx: SyncContext, persona: PersonaText): Promise<{ success: boolean; version?: number }> {
    const personaApi = new PersonaApi(BASE_URLS.API, ctx.apiKey, ctx.agentId);
    const result = await personaApi.createVersion(persona);
    return {
      success: result.success,
      version: result.data?.version,
    };
  }

  async pushModel(ctx: SyncContext, model?: string | null, modelResolver?: string | null): Promise<boolean> {
    const agentApi = new AgentApi(BASE_URLS.API, ctx.apiKey);
    const result = await agentApi.updateAgent(ctx.agentId, { model, modelResolver });
    return result.success;
  }

  async pushBatching(ctx: SyncContext, batchingConfig: BatchingConfig | null): Promise<boolean> {
    const agentApi = new AgentApi(BASE_URLS.API, ctx.apiKey);
    const result = await agentApi.updateAgent(ctx.agentId, { batchingConfig });
    return result.success;
  }

  async pushVoices(ctx: SyncContext, voices: { voiceId: string }[] | null): Promise<boolean> {
    const agentApi = new AgentApi(BASE_URLS.API, ctx.apiKey);
    const result = await agentApi.updateAgent(ctx.agentId, { voices });
    return result.success;
  }

  async pushGovernance(ctx: SyncContext, governance: any | null): Promise<boolean> {
    const agentApi = new AgentApi(BASE_URLS.API, ctx.apiKey);
    // Defence-in-depth: strip any raw apiKey before hitting the wire, even
    // if an older governance.ts still has one. Only apiKeyEnvVar is allowed.
    const safeGovernance = governance ? stripApiKey(governance) : governance;
    const result = await agentApi.updateAgent(ctx.agentId, { governance: safeGovernance });
    return result.success;
  }

  // ===========================================================================
  // PULL (server → local source code, used by sync command)
  // ===========================================================================

  pullName(serverName: string): boolean {
    return setAgentName(serverName);
  }

  pullPersona(serverPersona: PersonaText): boolean {
    return setAgentPersona(serverPersona);
  }

  pullModel(serverModel: string): boolean {
    return setAgentModel(serverModel);
  }

  // ===========================================================================
  // DRIFT DETECTION
  // ===========================================================================

  /**
   * Check all agent fields for drift between local and server.
   * Runs all checks in parallel.
   */
  async checkDrift(apiKey: string, agentId: string): Promise<AgentDrift> {
    const agent = await fetchServerAgent(apiKey, agentId);
    const [name, persona, model, governance] = await Promise.all([
      checkNameDrift(apiKey, agentId, agent),
      checkPersonaDrift(apiKey, agentId),
      checkModelDrift(apiKey, agentId, agent),
      checkGovernanceDrift(apiKey, agentId, agent),
    ]);
    return { name, persona, model, governance };
  }

  /**
   * Returns true if any agent field has drifted.
   */
  hasDrift(drift: AgentDrift): boolean {
    return !!(drift.name || drift.persona || drift.model || drift.governance);
  }
}

export const agentHandler = new AgentHandler();
