// Sandbox surface lives in @lua/shared-sandbox. Do not add globals here —
// add them in shared-sandbox so lua-core and lua-cli stay in lockstep, and
// so the contract stays under a single test suite. See WARNING in
// @lua/shared-sandbox/src/index.ts about the security limits of node:vm.

function resolveRequireMode(): RequireMode {
  return process.env.LUA_SANDBOX_REQUIRE_MODE === 'enforce' ? 'enforce' : 'log';
}

function resolveEgressMode(): EgressMode {
  const v = process.env.LUA_SANDBOX_EGRESS_FILTER;
  if (v === 'enforce') return 'enforce';
  if (v === 'log') return 'log';
  return 'off';
}

/**
 * Egress allowlist override. Read from the host `process.env`, NOT from the
 * per-skill envVars exposed to user code — that channel is conceptually
 * customer-editable and a malicious skill could set
 * `LUA_ALLOWED_EGRESS_CIDRS=0.0.0.0/0,::/0` to bypass the filter. In
 * `lua test` the developer IS the operator, so `process.env` is the right
 * source either way; this keeps lua-cli and lua-core symmetrical.
 */
function resolveExtraAllowedCidrs(): string[] {
  const csv = process.env.LUA_ALLOWED_EGRESS_CIDRS;
  if (!csv) return [];
  return csv
    .split(',')
    .map((s) => s.trim())
    .filter(Boolean);
}

function defaultSecurityEventLogger(evt: SandboxSecurityEvent): void {
  // Local dev — surface the warning via stderr so the developer sees it.
  // Production lua-core wires this to VmExecutionLogger; lua-cli has no
  // central logger, so console is the right destination.
  // eslint-disable-next-line no-console
  console.warn('[sandbox]', JSON.stringify(evt));
}

