/**
 * Plugin Base
 *
 * Contains:
 * - CompilationPlugin interface (contract)
 * - BasePlugin abstract class (common implementation)
 * - Helper functions
 *
 * Data types are in ../types.ts
 */

import { SourceFile, Project, Node, ObjectLiteralExpression, ClassDeclaration } from 'ts-morph';
import {
  COMPILER_VERSION,
  PrimitiveKind,
  type PrimitiveMetadata,
  type CommonExtractedFields,
  type ValidationResult,
  type ValidationMessage,
  type SchemaSet,
  type BundledArtifact,
  type CompiledPrimitive,
  type ManifestPrimitive,
  type BaseMetadataFields,
} from '../types.js';
import { extractStringProperty, evaluateNodeAsString } from '../utils/ast-helpers.js';
import { extendsAny, findClassMember } from '../utils/class-hierarchy.js';

// =============================================================================
// REFERENCE RESOLUTION CONTEXT
// =============================================================================

/**
 * Context for resolving references between primitives.
 * Passed to plugins when they need to resolve dependencies.
 */
export interface ReferenceResolverContext {
  /** The ts-morph project for AST analysis */
  project: Project;
  /** Resolve an import specifier to absolute path */
  resolveImportPath: (specifier: string, fromFile: string) => string | null;
  /** Get a plugin by kind */
  getPlugin: (kind: string) => CompilationPlugin | undefined;
  /** Debug logging */
  log: (message: string) => void;
}

// =============================================================================
// COMPILATION PLUGIN INTERFACE (class contract)
// =============================================================================

/**
 * Plugin for compiling a specific primitive type.
 *
 * Implement this interface to add support for a new primitive.
 * Each method has a single responsibility:
 *
 * - detect: Find primitives in source files
 * - validate: Check for errors/warnings
 * - generateEntryPoint: Create the bundler entry point
 * - extractSchemas: Convert Zod → JSON Schema
 * - postProcess: Transform the bundled output
 */
export interface CompilationPlugin {
  /**
   * Unique identifier matching the primitive's 'kind' property.
   * Must match exactly what users write in their code.
   */
  readonly kind: string;

  /**
   * Human-readable name for CLI output and error messages.
   */
  readonly displayName: string;

  /**
   * The function name that creates this primitive (e.g., 'defineTool').
   * Used for detection in source files.
   */
  readonly defineFunction: string;

  /**
   * Detect primitives of this type in a source file.
   *
   * Called once per source file during the scanning phase.
   * Should be fast - don't do heavy processing here.
   *
   * @param sourceFile - The ts-morph source file to scan
   * @returns Array of detected primitives
   */
  detect(sourceFile: SourceFile): PrimitiveMetadata[];

  /**
   * Validate extracted metadata.
   *
   * Called after detection. Return errors for things that prevent
   * compilation, warnings for things that might be problems.
   *
   * @param metadata - The primitive metadata to validate
   * @returns Validation result with errors and warnings
   */
  validate(metadata: PrimitiveMetadata): ValidationResult;

  /**
   * Generate the entry point code for bundling.
   *
   * This creates a wrapper that:
   * 1. Imports the user's primitive
   * 2. Re-exports it in a standard format
   * 3. Includes runtime metadata
   *
   * @param metadata - The primitive metadata
   * @returns TypeScript code for the entry point
   */
  generateEntryPoint(metadata: PrimitiveMetadata): string;

  /**
   * Extract schemas and convert to JSON Schema format.
   *
   * Called after detection. Uses ts-morph to evaluate Zod
   * schemas in the source code.
   *
   * @param metadata - The primitive metadata
   * @param project - The ts-morph project
   * @returns Schema set or undefined if no schemas
   */
  extractSchemas?(metadata: PrimitiveMetadata, project: Project): Promise<SchemaSet | undefined>;

  /**
   * Post-process the bundled artifact.
   *
   * Called after esbuild bundling. Can add runtime wrappers,
   * validation code, or other transformations.
   *
   * @param artifact - The bundled artifact
   * @param metadata - The primitive metadata
   * @returns Transformed artifact
   */
  postProcess?(artifact: BundledArtifact, metadata: PrimitiveMetadata): BundledArtifact;

  /**
   * Optional: produce the artifact directly, bypassing esbuild.
   *
   * For primitives whose artifact is never loaded at runtime for a given
   * metadata shape. When this returns an artifact, the compiler skips
   * `generateEntryPoint → bundler.bundle → postProcess → extractSchemas`
   * for that primitive and uses the returned artifact as-is. Return
   * `undefined` (or omit the method) to fall back to the default esbuild
   * path — useful for conditional opt-outs.
   *
   * Current implementers:
   * - `SkillPlugin` — unconditional; skills have no executable code and
   *   `SkillHandler.prepareForPush()` only loads tool artifacts, never the
   *   skill's own.
   *
   * Candidate extensions (implement conditionally):
   * - `AgentPlugin` — when `!hasModelResolver` (static `model: 'gpt-4o'`).
   *   `AgentHandler` skips `loadArtifact` in that case
   *   (`agent.handler.ts:95-107`).
   * - `MCPServerPlugin` — when `!hasUrlResolver && !hasHeadersResolver`
   *   (static URL + static headers). `MCPServerHandler.loadBundledServers`
   *   skips `loadArtifact` in that case (`mcp-server.handler.ts:67-68`).
   *
   * @param metadata - The primitive metadata
   * @returns Artifact to use, `undefined` to fall back to esbuild, or a
   *   Promise of either
   */
  buildArtifact?(metadata: PrimitiveMetadata): BundledArtifact | undefined | Promise<BundledArtifact | undefined>;

  /**
   * Create the manifest entry for this primitive.
   *
   * Each plugin knows what fields its manifest entry needs.
   * This keeps primitive-specific logic in the plugins.
   * May be async for plugins that need additional processing (e.g., bundling resolvers).
   *
   * @param compiled - The compiled primitive data
   * @param allPrimitives - All compiled primitives (for cross-referencing, e.g., skill → tool name resolution)
   * @returns The typed manifest entry for this primitive
   */
  toManifestEntry(
    compiled: CompiledPrimitive,
    allPrimitives?: CompiledPrimitive[]
  ): ManifestPrimitive | Promise<ManifestPrimitive>;

  /**
   * Resolve references to other primitives.
   *
   * Some primitives reference others (e.g., Skills reference Tools).
   * This method allows plugins to resolve those references and return
   * the additional primitives that should be compiled.
   *
   * @param metadata - The primitive that may have references
   * @param sourceFile - The source file containing the primitive
   * @param context - Context for resolving imports and getting plugins
   * @returns Array of referenced primitives, empty if none
   */
  resolveReferences?(
    metadata: PrimitiveMetadata,
    sourceFile: SourceFile,
    context: ReferenceResolverContext
  ): PrimitiveMetadata[];

  /**
   * Sanitize the primitive's `metadata` payload before it is written to
   * disk (artifact code, sidecar JSON, or anywhere else that ends up
   * committed or uploaded). Defaults to a passthrough.
   *
   * Used to strip build-machine-specific fields that shouldn't leak
   * into deliverables — e.g. `SkillPlugin` strips `toolRefSourcePaths`
   * because those are absolute paths that break hash reproducibility
   * and expose the developer's filesystem layout.
   *
   * Implementations MUST NOT mutate the input; return a new object.
   */
  sanitizeForPersistence?(metadata: PrimitiveMetadata['metadata']): PrimitiveMetadata['metadata'];
}

// =============================================================================
// BASE PLUGIN ABSTRACT CLASS
// =============================================================================

/**
 * Abstract base class for plugins with common implementation.
 *
 * Provides default implementations for:
 * - detect() - Function-based and class-based detection
 * - generateEntryPoint() - Universal import pattern
 * - postProcess() - Runtime validation wrapper
 * - extractSchemas() - Returns undefined (override for tools/webhooks)
 *
 * Subclasses must implement:
 * - kind, displayName, defineFunction, legacyClassNames
 * - extractFromConfig() - Extract primitive-specific fields
 * - validate() - Validation rules
 * - toManifestEntry() - Manifest entry creation
 *
 * Subclasses can optionally override:
 * - getEntryPointFields() - Add extra fields to __lua_primitive__
 * - getRuntimeValidation() - Add runtime checks in postProcess
 * - resolveReferences() - Resolve dependencies (skills → tools)
 */
export abstract class BasePlugin<T extends BaseMetadataFields = BaseMetadataFields> implements CompilationPlugin {
  /** Unique identifier for this primitive type */
  abstract readonly kind: string;

  /** Human-readable name for CLI output */
  abstract readonly displayName: string;

  /** Function name for detection (e.g., 'defineTool') */
  abstract readonly defineFunction: string;

  /** Legacy class names for constructor-based detection (e.g., ['LuaJob']) */
  abstract readonly legacyClassNames: string[];

  // ===========================================================================
  // DETECTION (common implementation)
  // ===========================================================================

  /**
   * Opt-in to class-definition detection (`class X extends LuaY { ... }`).
   * Plugins flip this to true when subclass-with-field-override is a
   * supported authoring shape for their primitive type.
   */
  protected readonly supportsClassDefinition: boolean = false;

  /**
   * Detect primitives in a source file.
   * Three passes, in source-precedence order:
   *   1. function-based   — `defineX({...})`
   *   2. class config     — `new LuaX({...})`
   *   3. class definition — `class MyX extends LuaX {...}` (opt-in)
   */
  detect(sourceFile: SourceFile): PrimitiveMetadata<T>[] {
    const primitives: PrimitiveMetadata<T>[] = [];

    this.detectFunctionBased(sourceFile, primitives);
    this.detectClassBased(sourceFile, primitives);
    if (this.supportsClassDefinition) {
      this.detectClassDefinitions(sourceFile, primitives);
    }

    return primitives;
  }

  /**
   * Detect function-based definitions (defineX pattern):
   *
   * Supported patterns:
   * - const/let/var x = defineX({ ... })
   * - export const/let/var x = defineX({ ... })
   * - export default defineX({ ... })
   */
  protected detectFunctionBased(sourceFile: SourceFile, primitives: PrimitiveMetadata<T>[]): void {
    // Pattern 1: Variable declarations - const/let/var x = defineX({ ... })
    // Also covers: export const/let/var x = defineX({ ... })
    sourceFile.getVariableDeclarations().forEach((varDecl) => {
      const initializer = varDecl.getInitializer();
      if (!initializer || !Node.isCallExpression(initializer)) return;

      const callee = initializer.getExpression();
      if (callee.getText() !== this.defineFunction) return;

      const args = initializer.getArguments();
      if (args.length === 0) return;

      const configArg = args[0];
      if (!Node.isObjectLiteralExpression(configArg)) return;

      const pos = sourceFile.getLineAndColumnAtPos(varDecl.getStart());
      const metadata = this.extractFromConfig(configArg, varDecl.getName(), sourceFile.getFilePath(), pos, 'function');

      if (metadata) primitives.push(metadata);
    });

    // Pattern 2: Export default - export default defineX({ ... })
    this.detectDefaultExport(sourceFile, primitives, 'function', (expr) => {
      if (!Node.isCallExpression(expr)) return null;
      const callee = expr.getExpression();
      if (callee.getText() !== this.defineFunction) return null;
      const args = expr.getArguments();
      if (args.length === 0 || !Node.isObjectLiteralExpression(args[0])) return null;
      return args[0];
    });
  }

  /**
   * Detect class-based definitions (new LuaX pattern):
   *
   * Supported patterns:
   * - const/let/var x = new LuaX({ ... })
   * - export const/let/var x = new LuaX({ ... })
   * - export default new LuaX({ ... })
   */
  protected detectClassBased(sourceFile: SourceFile, primitives: PrimitiveMetadata<T>[]): void {
    // Track which nodes we've already processed to avoid duplicates
    const processedNodes = new Set<number>();

    // Pattern 1: Variable declarations - const/let/var x = new LuaX({ ... })
    // Also covers: export const/let/var x = new LuaX({ ... })
    sourceFile.getVariableDeclarations().forEach((varDecl) => {
      const initializer = varDecl.getInitializer();
      if (!initializer || !Node.isNewExpression(initializer)) return;

      const expression = initializer.getExpression();
      const className = expression.getText();
      if (!this.legacyClassNames.includes(className)) return;

      const args = initializer.getArguments();
      if (args.length === 0) return;

      const configArg = args[0];
      if (!Node.isObjectLiteralExpression(configArg)) return;

      processedNodes.add(initializer.getStart());

      const pos = sourceFile.getLineAndColumnAtPos(varDecl.getStart());
      const metadata = this.extractFromConfig(configArg, varDecl.getName(), sourceFile.getFilePath(), pos, 'class');

      if (metadata) primitives.push(metadata);
    });

    // Pattern 2: Export default - export default new LuaX({ ... })
    this.detectDefaultExport(sourceFile, primitives, 'class', (expr) => {
      if (!Node.isNewExpression(expr)) return null;
      // Skip if already processed as variable declaration
      if (processedNodes.has(expr.getStart())) return null;
      const expression = expr.getExpression();
      const className = expression.getText();
      if (!this.legacyClassNames.includes(className)) return null;
      const args = expr.getArguments();
      if (args.length === 0 || !Node.isObjectLiteralExpression(args[0])) return null;
      return args[0];
    });
  }

  /**
   * Detect class-DEFINITION primitives:
   *   class MyX extends LuaY { ... }
   *   class MyX extends SharedY { ... }   // where SharedY extends LuaY
   *   class MyX implements LuaY { ... }   // (kept for symmetry with old tool path)
   *
   * Walks the full inheritance chain via `extendsAny`, so a leaf class
   * is detected even when the direct parent isn't a `legacyClassName`.
   * Subclasses extending shared bases in a workspace package fall out
   * of this naturally.
   *
   * Default-export and named-export shapes are both handled here; the
   * leaf class's own export status is read off the declaration.
   */
  protected detectClassDefinitions(sourceFile: SourceFile, primitives: PrimitiveMetadata<T>[]): void {
    for (const classDecl of sourceFile.getClasses()) {
      if (!extendsAny(classDecl, this.legacyClassNames)) continue;

      const className = classDecl.getName();
      if (!className) continue;

      const metadata = this.extractFromClassDefinition(classDecl, sourceFile);
      if (metadata) primitives.push(metadata);
    }
  }

  /**
   * Default class-definition extractor: reads `name` and `description`
   * off the inheritance chain (most-derived wins), defers everything
   * else to plugin overrides.
   *
   * Subclasses extend this to read type-specific metadata (e.g. tool
   * `hasInputSchema`/`hasExecute`, job schedule, agent persona, etc.)
   * — typically by chaining `super.extractFromClassDefinition()` and
   * merging additional fields into `metadata.metadata`.
   */
  protected extractFromClassDefinition(
    classDecl: ClassDeclaration,
    sourceFile: SourceFile
  ): PrimitiveMetadata<T> | null {
    const className = classDecl.getName();
    if (!className) return null;

    const isDefaultExport = classDecl.isDefaultExport();
    const exportName = isDefaultExport ? 'default' : className;

    const nameFromMember = readStringMember(classDecl, 'name');
    const name = nameFromMember ?? deriveNameFromClassName(className);

    const description = readStringMember(classDecl, 'description') ?? '';

    const startPos = classDecl.getStartLineNumber();

    return {
      kind: this.kind as PrimitiveKind,
      name,
      description,
      sourcePath: sourceFile.getFilePath(),
      exportName,
      isDefaultExport,
      line: startPos,
      column: 1,
      metadata: {
        pattern: 'class-definition',
        className,
      } as unknown as T,
    };
  }

  /**
   * Generate entry-point code for class-definition primitives.
   *
   * Imports the user's class, instantiates it with zero args, and
   * re-exports the standard `{ kind, name, description, ... }` shape.
   * Field initializers on the subclass (`ragSearchPath = "/blk/search"`)
   * run during construction, so override-via-field-initializer works
   * natively — no constructor-arg threading required.
   *
   * Subclasses override `getClassDefinitionPrimitiveShape` to project
   * specific instance members onto the `primitive: {...}` literal
   * (e.g. tools bind `execute`/`condition`/`inputSchema`).
   */
  protected generateClassDefinitionEntryPoint(metadata: PrimitiveMetadata<T>): string {
    const importStatement = metadata.isDefaultExport
      ? `import __PrimitiveClass__ from '${metadata.sourcePath}';`
      : `import { __lua_target__ as __PrimitiveClass__ } from '${metadata.sourcePath}';`;

    const exportStatement = metadata.isDefaultExport ? '' : `export { __PrimitiveClass__ as ${metadata.exportName} };`;

    const primitiveShape = this.getClassDefinitionPrimitiveShape(metadata);

    return `
// =============================================================================
// AUTO-GENERATED ENTRY POINT (Class-definition)
// ${this.displayName}: ${metadata.name}
// Source: ${metadata.sourcePath}
// =============================================================================

${importStatement}

const __lua_instance__ = new __PrimitiveClass__();

const __lua_primitive__ = {
  version: '${COMPILER_VERSION}',
  kind: '${this.kind}',
  name: ${JSON.stringify(metadata.name)},
  description: ${JSON.stringify(metadata.description)},
  exportName: ${JSON.stringify(metadata.exportName)},
  pattern: 'class-definition',
};

export default {
  __lua_primitive__,
  primitive: ${primitiveShape},
};

${exportStatement}
`;
  }

  /**
   * Object-literal source for the `primitive: {...}` body in a
   * class-definition entry point. Subclasses override to bind their
   * specific instance members (inputSchema, condition, schedule, etc.).
   *
   * Default: `{ kind, name, description, execute }` — covers the
   * common "primitive has an execute method" shape.
   */
  protected getClassDefinitionPrimitiveShape(_metadata: PrimitiveMetadata<T>): string {
    return `{
    kind: '${this.kind}',
    name: __lua_instance__.name ?? ${JSON.stringify(_metadata.name)},
    description: __lua_instance__.description ?? ${JSON.stringify(_metadata.description)},
    execute: typeof __lua_instance__.execute === 'function' ? __lua_instance__.execute.bind(__lua_instance__) : undefined,
  }`;
  }

  /**
   * Helper to detect export default patterns.
   * Works for both function-based (defineX) and class-based (new LuaX) patterns.
   *
   * Sets exportName='default' which causes extractCommonFields to set isDefaultExport=true.
   */
  private detectDefaultExport(
    sourceFile: SourceFile,
    primitives: PrimitiveMetadata<T>[],
    pattern: 'function' | 'class',
    extractConfig: (expr: Node) => ObjectLiteralExpression | null
  ): void {
    sourceFile.forEachDescendant((node) => {
      if (!Node.isExportAssignment(node)) return;

      const expr = node.getExpression();
      const configArg = extractConfig(expr);
      if (!configArg) return;

      const pos = sourceFile.getLineAndColumnAtPos(node.getStart());
      const metadata = this.extractFromConfig(
        configArg,
        'default', // Triggers isDefaultExport=true in extractCommonFields
        sourceFile.getFilePath(),
        pos,
        pattern
      );

      if (metadata) primitives.push(metadata);
    });
  }

  /**
   * Extract metadata from config object literal.
   * Subclasses implement this to extract primitive-specific fields.
   *
   * Common fields (name, description) can use extractCommonFields().
   */
  protected abstract extractFromConfig(
    config: ObjectLiteralExpression,
    exportName: string,
    sourcePath: string,
    position: { line: number; column: number },
    pattern: 'function' | 'class'
  ): PrimitiveMetadata<T> | null;

  /**
   * Helper to extract common fields (name, description) from config.
   * Returns null if name is missing.
   *
   * Automatically sets `isDefaultExport: true` when `exportName === 'default'`.
   */
  protected extractCommonFields(
    config: ObjectLiteralExpression,
    exportName: string,
    sourcePath: string,
    position: { line: number; column: number }
  ): CommonExtractedFields | null {
    const name = extractStringProperty(config, 'name');
    if (!name) return null;

    return {
      name,
      description: extractStringProperty(config, 'description') || '',
      exportName,
      isDefaultExport: exportName === 'default',
      sourcePath,
      line: position.line,
      column: position.column,
    };
  }

  // ===========================================================================
  // VALIDATION (must be implemented by subclass)
  // ===========================================================================

  /**
   * Common validation: name required (error), description recommended (warning).
   * Subclasses call this first, then add type-specific checks to the returned arrays.
   */
  protected baseValidation(metadata: PrimitiveMetadata<T>): {
    errors: ValidationMessage[];
    warnings: ValidationMessage[];
  } {
    const errors: ValidationMessage[] = [];
    const warnings: ValidationMessage[] = [];
    if (!metadata.name) {
      errors.push(validationError(`${this.displayName} must have a name`, { line: metadata.line }));
    }
    if (!metadata.description) {
      warnings.push(validationWarning(`${this.displayName} should have a description`, { line: metadata.line }));
    }
    return { errors, warnings };
  }

  abstract validate(metadata: PrimitiveMetadata<T>): ValidationResult;

  // ===========================================================================
  // ENTRY POINT GENERATION (common implementation)
  // ===========================================================================

  /**
   * Generate entry point code for bundling.
   *
   * Uses `import { __lua_target__ as X }` which is provided by the compiler's
   * virtual source plugin. This works uniformly regardless of how the primitive
   * is exported (default, named, or not exported at all).
   */
  generateEntryPoint(metadata: PrimitiveMetadata<T>): string {
    if ((metadata.metadata as { pattern?: string } | undefined)?.pattern === 'class-definition') {
      return this.generateClassDefinitionEntryPoint(metadata);
    }

    const extraFields = this.getEntryPointFields(metadata);
    const extraFieldsStr = extraFields ? `\n  ${extraFields}` : '';

    // Default exports use `import X from` syntax directly.
    // Named exports use the __lua_target__ alias injected by the virtual source plugin.
    const importStatement = metadata.isDefaultExport
      ? `import __primitive__ from '${metadata.sourcePath}';`
      : `import { __lua_target__ as __primitive__ } from '${metadata.sourcePath}';`;

    return `
// =============================================================================
// AUTO-GENERATED ENTRY POINT
// ${this.displayName}: ${metadata.name}
// Source: ${metadata.sourcePath}
// =============================================================================

${importStatement}

const __lua_primitive__ = {
  version: '${COMPILER_VERSION}',
  kind: '${this.kind}',
  name: ${JSON.stringify(metadata.name)},
  description: ${JSON.stringify(metadata.description)},
  exportName: ${JSON.stringify(metadata.exportName)},${extraFieldsStr}
};

export default {
  __lua_primitive__,
  primitive: __primitive__,
};
`;
  }

  /**
   * Override to add extra fields to __lua_primitive__ object.
   * Return a string like: `context: "some value",\n  tools: ["tool1"]`
   */
  protected getEntryPointFields(_metadata: PrimitiveMetadata<T>): string {
    return '';
  }

  // ===========================================================================
  // SCHEMA EXTRACTION (default: no schemas)
  // ===========================================================================

  /**
   * Extract schemas from the primitive.
   * Override for primitives that have schemas (tools, webhooks).
   */
  async extractSchemas(_metadata: PrimitiveMetadata<T>, _project: Project): Promise<SchemaSet | undefined> {
    return undefined;
  }

  // ===========================================================================
  // POST PROCESSING (common implementation)
  // ===========================================================================

  /**
   * Default: return the metadata unchanged. Subclasses override to
   * strip build-machine-specific fields (absolute paths, local-only
   * lookup tables) that shouldn't appear in artifacts or sidecars.
   *
   * MUST be pure — no mutation of the input.
   */
  sanitizeForPersistence(metadata: PrimitiveMetadata['metadata']): PrimitiveMetadata['metadata'] {
    return metadata;
  }

  /**
   * Post-process bundled artifact with runtime validation wrapper.
   */
  postProcess(artifact: BundledArtifact, metadata: PrimitiveMetadata<T>): BundledArtifact {
    const extraValidation = this.getRuntimeValidation(metadata);
    const extraValidationStr = extraValidation ? `\n  ${extraValidation}` : '';

    const wrappedCode = `
// =============================================================================
// LUA RUNTIME WRAPPER - ${this.displayName}: ${metadata.name}
// =============================================================================

${artifact.code}

(function() {
  const mod = typeof module !== 'undefined' ? module.exports : {};
  const primitive = mod.default;
  
  if (!primitive || !primitive.__lua_primitive__) {
    throw new Error('[Lua] Invalid ${this.kind} artifact: missing __lua_primitive__ marker');
  }
  
  if (primitive.__lua_primitive__.kind !== '${this.kind}') {
    throw new Error('[Lua] Invalid ${this.kind} artifact: expected kind "${this.kind}"');
  }${extraValidationStr}
})();
`;

    return {
      ...artifact,
      code: wrappedCode,
      size: Buffer.byteLength(wrappedCode, 'utf8'),
    };
  }

  /**
   * Override to add extra runtime validation in postProcess.
   * Return JavaScript code to add to the validation IIFE.
   */
  protected getRuntimeValidation(_metadata: PrimitiveMetadata<T>): string {
    return '';
  }

  // ===========================================================================
  // MANIFEST ENTRY
  // ===========================================================================

  /**
   * Common manifest fields shared by ALL primitive types.
   * Subclasses spread this and add type-specific fields.
   */
  protected baseManifestFields(compiled: CompiledPrimitive) {
    return {
      kind: this.kind as PrimitiveKind,
      name: compiled.name,
      description: compiled.description,
      path: `artifacts/${compiled.kind}/${compiled.name}.js`,
      sourcePath: compiled.sourcePath,
      hash: compiled.artifact.hash,
    };
  }

  abstract toManifestEntry(
    compiled: CompiledPrimitive,
    allPrimitives?: CompiledPrimitive[]
  ): ManifestPrimitive | Promise<ManifestPrimitive>;
}

// =============================================================================
// HELPER FUNCTIONS
// =============================================================================

/**
 * Locate a class declaration in a source file by export name, where
 * `exportName === 'default'` means "the class that's exported as
 * default". Used by plugins that need to re-read AST nodes off the
 * class during schema extraction etc.
 */
export function locateClassDefinition(sourceFile: SourceFile, exportName: string): ClassDeclaration | undefined {
  if (exportName !== 'default') return sourceFile.getClass(exportName);
  return sourceFile.getClasses().find((c) => c.isDefaultExport());
}

/**
 * Read a string-valued property from a class declaration, walking the
 * inheritance chain (most-derived wins). Returns undefined if the
 * member isn't a string or doesn't exist.
 *
 * Used by class-definition extractors to resolve `name` / `description`
 * (and any other string fields) across `class Leaf extends SharedBase`.
 */
export function readStringMember(classDecl: ClassDeclaration, memberName: string): string | undefined {
  const hit = findClassMember(classDecl, memberName, 'property');
  if (!hit || !Node.isPropertyDeclaration(hit.node)) return undefined;
  return evaluateNodeAsString(hit.node.getInitializer());
}

/**
 * Derive a kebab-case primitive name from a PascalCase class name when
 * the class doesn't declare an explicit `name` field. Strips trailing
 * `Tool`, inserts hyphens before remaining capitals, then lowercases.
 *
 *   `SearchKnowledgeBaseTool` → `search-knowledge-base`
 *   `MyCustomJob`             → `my-custom-job`
 */
export function deriveNameFromClassName(className: string): string {
  return className
    .replace(/Tool$/, '')
    .replace(/([A-Z])/g, '-$1')
    .toLowerCase()
    .replace(/^-/, '');
}

/**
 * Creates a validation result with no errors or warnings.
 */
export function validResult(): ValidationResult {
  return { valid: true, errors: [], warnings: [] };
}

/**
 * Creates a validation error.
 */
export function validationError(
  message: string,
  options?: { line?: number; column?: number; suggestion?: string; docsUrl?: string }
): ValidationMessage {
  return { message, ...options };
}

/**
 * Creates a validation warning.
 */
export function validationWarning(
  message: string,
  options?: { line?: number; column?: number; suggestion?: string; docsUrl?: string }
): ValidationMessage {
  return { message, ...options };
}
