/**
 * Production Command
 * Overview and management of production environment
 */

import { withErrorHandling, writeProgress, writeSuccess, writeInfo } from '../utils/cli.js';
import { BASE_URLS } from '../config/constants.js';
import { safePrompt } from '../utils/prompt-handler.js';
import { initializeCommand } from '../utils/command-utils.js';
import PersonaApi from '../api/persona.api.service.js';
import SkillApi from '../api/skills.api.service.js';
import DeveloperApi from '../api/developer.api.service.js';
import { trackEvent } from '../services/analytics.js';
import { validateOrSuggest } from '../utils/aliases.js';
import { flattenPersonaTextAll, type PersonaText } from '@lua/shared-types';

interface ProductionContext {
  agentId: string;
  apiKey: string;
}

interface PersonaVersion {
  version: number;
  persona: PersonaText;
  createdDate: number;
  createdBy?: string;
  isCurrent: boolean;
}

interface EnvVariable {
  key: string;
  value: string;
}

type ProductionAction = 'overview' | 'persona' | 'skills' | 'env';

// ─────────────────────────────────────────────────────────────────────────────
// Main Command Entry
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Main production command - overview of production environment.
 *
 * Supports both interactive and non-interactive modes:
 * - Interactive: menu-driven management
 * - Non-interactive: use action argument to display specific section
 */
export async function productionCommand(action?: string): Promise<void> {
  return withErrorHandling(async () => {
    // Initialize command (validates config + auth)
    const { config, agentId, apiKey } = await initializeCommand();

    const context: ProductionContext = {
      agentId,
      apiKey,
    };

    // Determine mode
    if (action) {
      await executeNonInteractive(context, config, action);
    } else {
      await manageProductionInteractive(context, config);
    }
    trackEvent('cli_production_action', {
      action: action || 'interactive',
      non_interactive: !!action,
    });
  }, 'production');
}

// ─────────────────────────────────────────────────────────────────────────────
// Shared Core Functions
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Fetches persona versions from the API.
 */
async function fetchPersonaVersionsCore(context: ProductionContext): Promise<PersonaVersion[] | null> {
  try {
    const personaApi = new PersonaApi(BASE_URLS.API, context.apiKey, context.agentId);
    const response = await personaApi.getVersions();

    if (!response.success || !response.data) {
      console.error(`❌ API Error: ${response.error?.message || 'Unknown error'}`);
      return null;
    }

    const data = response.data;

    let versions: PersonaVersion[] = [];
    if (Array.isArray(data)) {
      versions = data;
    } else if (data && typeof data === 'object' && 'data' in data && Array.isArray((data as any).data)) {
      versions = (data as any).data;
    } else if (data && typeof data === 'object' && 'versions' in data && Array.isArray((data as any).versions)) {
      versions = (data as any).versions;
    }

    return versions;
  } catch (error) {
    console.error('❌ Error loading persona information:', error);
    return null;
  }
}

/**
 * Displays current persona information.
 */
function displayPersonaCore(versions: PersonaVersion[]): void {
  const currentVersion = versions.find((v) => v.isCurrent);

  console.log('\n' + '='.repeat(60));
  console.log('🤖 Current Production Persona');
  console.log('='.repeat(60) + '\n');

  if (currentVersion) {
    const date = new Date(currentVersion.createdDate);
    console.log(`Version: ${currentVersion.version} ⭐`);
    console.log(`Deployed: ${date.toLocaleString()}`);
    if (currentVersion.createdBy) {
      console.log(`Created by: ${currentVersion.createdBy}`);
    }
    console.log('\n' + '-'.repeat(60) + '\n');
    // Flatten polymorphic persona for terminal display — channel-agnostic
    // because there's no channel context in CLI output.
    console.log(flattenPersonaTextAll(currentVersion.persona));
    console.log('\n' + '='.repeat(60));
  } else {
    console.log('⚠️  No persona currently deployed.');
    console.log('💡 Deploy a version using: lua persona production deploy -v <version>\n');
    if (versions.length > 0) {
      console.log('Available versions:\n');
      versions.forEach((v, i) => {
        const date = new Date(v.createdDate);
        console.log(`  ${i + 1}. Version ${v.version} - ${date.toLocaleDateString()}`);
      });
    }
    console.log('\n' + '='.repeat(60));
  }

  console.log(`\nTotal versions available: ${versions.length}`);
}

/**
 * Displays deployed skills information.
 */
async function displaySkillsCore(context: ProductionContext, config: any): Promise<void> {
  const skills = config.skills || [];

  console.log('\n' + '='.repeat(60));
  console.log('⚙️  Production Skills');
  console.log('='.repeat(60) + '\n');

  if (skills.length === 0) {
    console.log('ℹ️  No skills found in configuration.\n');
    console.log('='.repeat(60));
    return;
  }

  const skillApi = new SkillApi(BASE_URLS.API, context.apiKey, context.agentId);

  for (const skill of skills) {
    try {
      const response = await skillApi.getSkillVersions(skill.skillId);

      if (response.success && response.data) {
        const data = response.data as any;
        const versions = data.versions || [];
        const activeVersionId = data.data?.activeVersionId || data.activeVersionId;

        const activeVersion = versions.find((v: any) => v.id === activeVersionId || v.skillId === activeVersionId);

        console.log(`📦 ${skill.name}`);
        console.log(`   Skill ID: ${skill.skillId}`);

        if (activeVersion) {
          console.log(`   Deployed Version: ${activeVersion.version} ⭐`);
          const date = new Date(activeVersion.createdDate);
          console.log(`   Deployed: ${date.toLocaleString()}`);
        } else {
          console.log(`   Deployed Version: Not deployed`);
        }

        console.log(`   Total Versions: ${versions.length}`);
        console.log();
      } else {
        console.log(`📦 ${skill.name}`);
        console.log(`   Skill ID: ${skill.skillId}`);
        console.log(`   Status: Unable to fetch version info`);
        console.log();
      }
    } catch {
      console.log(`📦 ${skill.name}`);
      console.log(`   Skill ID: ${skill.skillId}`);
      console.log(`   Status: Error loading versions`);
      console.log();
    }
  }

  console.log('='.repeat(60));
}

/**
 * Fetches environment variables from the API.
 */
async function fetchEnvVariablesCore(context: ProductionContext): Promise<EnvVariable[]> {
  try {
    const developerApi = new DeveloperApi(BASE_URLS.API, context.apiKey, context.agentId);
    const response = await developerApi.getEnvironmentVariables();

    if (!response.success || !response.data) {
      return [];
    }

    const data = response.data as any;

    if (data.data && typeof data.data === 'object') {
      return Object.entries(data.data).map(([key, value]) => ({
        key,
        value: String(value),
      }));
    }

    return [];
  } catch {
    console.error('⚠️  Error loading environment variables');
    return [];
  }
}

/**
 * Displays environment variables (masked).
 */
function displayEnvVariablesCore(variables: EnvVariable[]): void {
  console.log('\n' + '='.repeat(60));
  console.log('🔐 Production Environment Variables');
  console.log('='.repeat(60) + '\n');

  if (variables.length === 0) {
    console.log('ℹ️  No environment variables configured.\n');
    console.log('='.repeat(60));
    return;
  }

  variables.forEach((v, index) => {
    const maskedValue =
      v.value.length > 4
        ? v.value.substring(0, 4) + '*'.repeat(Math.min(v.value.length - 4, 20))
        : '*'.repeat(v.value.length);
    console.log(`${index + 1}. ${v.key} = ${maskedValue}`);
  });

  console.log('\n' + '='.repeat(60));
  console.log(`Total: ${variables.length} variable(s)`);
}

/**
 * Displays production overview (summary of all sections).
 */
async function displayOverviewCore(context: ProductionContext, config: any): Promise<void> {
  console.log('\n' + '='.repeat(60));
  console.log('🌙 Production Environment Overview');
  console.log('='.repeat(60) + '\n');

  // Persona summary
  writeProgress('Loading persona...');
  const versions = await fetchPersonaVersionsCore(context);
  const currentPersona = versions?.find((v) => v.isCurrent);
  console.log('🤖 Persona:');
  if (currentPersona) {
    // Flatten before previewing — .length / .substring() would fail on
    // an object-form persona returned from the server.
    const flatPersona = flattenPersonaTextAll(currentPersona.persona);
    const preview = flatPersona.length > 80 ? flatPersona.substring(0, 80) + '...' : flatPersona;
    console.log(`   Version ${currentPersona.version} ⭐ deployed`);
    console.log(`   Preview: ${preview}`);
  } else if (versions && versions.length > 0) {
    console.log(`   ⚠️  Not deployed (${versions.length} version(s) available)`);
  } else {
    console.log(`   ℹ️  No versions found`);
  }
  console.log();

  // Skills summary
  writeProgress('Loading skills...');
  const skills = config.skills || [];
  console.log('⚙️  Skills:');
  if (skills.length === 0) {
    console.log('   ℹ️  No skills configured');
  } else {
    console.log(`   ${skills.length} skill(s) configured`);
    for (const skill of skills.slice(0, 3)) {
      console.log(`   - ${skill.name}`);
    }
    if (skills.length > 3) {
      console.log(`   ... and ${skills.length - 3} more`);
    }
  }
  console.log();

  // Env variables summary
  writeProgress('Loading environment variables...');
  const envVars = await fetchEnvVariablesCore(context);
  console.log('🔐 Environment Variables:');
  if (envVars.length === 0) {
    console.log('   ℹ️  No variables configured');
  } else {
    console.log(`   ${envVars.length} variable(s) configured`);
    envVars.slice(0, 3).forEach((v) => {
      console.log(`   - ${v.key}`);
    });
    if (envVars.length > 3) {
      console.log(`   ... and ${envVars.length - 3} more`);
    }
  }

  console.log('\n' + '='.repeat(60));
}

// ─────────────────────────────────────────────────────────────────────────────
// Non-Interactive Mode
// ─────────────────────────────────────────────────────────────────────────────

async function executeNonInteractive(context: ProductionContext, config: any, action: string): Promise<void> {
  const normalizedAction = validateOrSuggest('production.action', action);

  switch (normalizedAction as ProductionAction) {
    case 'overview':
      await displayOverviewCore(context, config);
      break;

    case 'persona': {
      writeProgress('🔄 Loading persona information...');
      const versions = await fetchPersonaVersionsCore(context);
      if (!versions) throw new Error('Operation failed');
      displayPersonaCore(versions);
      break;
    }

    case 'skills':
      writeProgress('🔄 Loading skill information...');
      await displaySkillsCore(context, config);
      break;

    case 'env': {
      writeProgress('🔄 Loading environment variables...');
      const envVars = await fetchEnvVariablesCore(context);
      displayEnvVariablesCore(envVars);
      break;
    }
  }
}

// ─────────────────────────────────────────────────────────────────────────────
// Interactive Mode
// ─────────────────────────────────────────────────────────────────────────────

async function manageProductionInteractive(context: ProductionContext, config: any): Promise<void> {
  let continueManaging = true;

  while (continueManaging) {
    console.log('\n' + '='.repeat(60));
    console.log('🌙 Production Environment');
    console.log('='.repeat(60) + '\n');

    const actionAnswer = await safePrompt<{ action: string }>([
      {
        type: 'list',
        name: 'action',
        message: 'What would you like to view?',
        choices: [
          { name: '🤖 Persona - View current persona and versions', value: 'persona' },
          { name: '⚙️  Skills - View deployed skills and versions', value: 'skills' },
          { name: '🔐 Environment Variables - Manage production env', value: 'env' },
          { name: '❌ Exit', value: 'exit' },
        ],
      },
    ]);

    if (!actionAnswer) return;
    const { action } = actionAnswer;

    switch (action) {
      case 'persona':
        await viewProductionPersonaInteractive(context);
        break;
      case 'skills':
        await viewProductionSkillsInteractive(context, config);
        break;
      case 'env':
        await manageProductionEnvInteractive(context);
        break;
      case 'exit':
        continueManaging = false;
        console.log('\n👋 Goodbye!\n');
        break;
    }
  }
}

async function viewProductionPersonaInteractive(context: ProductionContext): Promise<void> {
  writeProgress('🔄 Loading persona information...');
  const versions = await fetchPersonaVersionsCore(context);

  if (!versions) {
    await safePrompt([{ type: 'input', name: 'continue', message: 'Press Enter to continue...' }]);
    return;
  }

  if (versions.length === 0) {
    console.log('\nℹ️  No persona versions found.');
    console.log('💡 Create a persona version first using: lua persona\n');
    await safePrompt([{ type: 'input', name: 'continue', message: 'Press Enter to continue...' }]);
    return;
  }

  displayPersonaCore(versions);
  console.log();
  await safePrompt([{ type: 'input', name: 'continue', message: 'Press Enter to continue...' }]);
}

async function viewProductionSkillsInteractive(context: ProductionContext, config: any): Promise<void> {
  writeProgress('🔄 Loading skill information...');
  await displaySkillsCore(context, config);
  console.log();
  await safePrompt([{ type: 'input', name: 'continue', message: 'Press Enter to continue...' }]);
}

async function manageProductionEnvInteractive(context: ProductionContext): Promise<void> {
  let continueManaging = true;

  while (continueManaging) {
    const variables = await fetchEnvVariablesCore(context);

    console.log('\n' + '='.repeat(60));
    console.log('🔐 Production Environment Variables');
    console.log('='.repeat(60) + '\n');

    if (variables.length === 0) {
      console.log('ℹ️  No environment variables configured.\n');
    } else {
      variables.forEach((v, index) => {
        const maskedValue =
          v.value.length > 4
            ? v.value.substring(0, 4) + '*'.repeat(Math.min(v.value.length - 4, 20))
            : '*'.repeat(v.value.length);
        console.log(`${index + 1}. ${v.key} = ${maskedValue}`);
      });
      console.log();
    }

    const actionAnswer = await safePrompt<{ action: string }>([
      {
        type: 'list',
        name: 'action',
        message: 'What would you like to do?',
        choices: [
          { name: '➕ Add new variable', value: 'add' },
          { name: '✏️  Update existing variable', value: 'update' },
          { name: '🗑️  Delete variable', value: 'delete' },
          { name: '👁️  View variable value', value: 'view' },
          { name: '🔄 Refresh list', value: 'refresh' },
          { name: '⬅️  Back to main menu', value: 'back' },
        ],
      },
    ]);

    if (!actionAnswer) return;
    const { action } = actionAnswer;

    switch (action) {
      case 'add':
        await addProductionVariableInteractive(context, variables);
        break;
      case 'update':
        await updateProductionVariableInteractive(context, variables);
        break;
      case 'delete':
        await deleteProductionVariableInteractive(context, variables);
        break;
      case 'view':
        await viewProductionVariableInteractive(variables);
        break;
      case 'refresh':
        break;
      case 'back':
        continueManaging = false;
        break;
    }
  }
}

async function saveProductionEnvVariables(context: ProductionContext, variables: EnvVariable[]): Promise<boolean> {
  try {
    const envData: Record<string, string> = {};
    variables.forEach((v) => {
      if (v.key.trim()) {
        envData[v.key.trim()] = v.value;
      }
    });

    const developerApi = new DeveloperApi(BASE_URLS.API, context.apiKey, context.agentId);
    const response = await developerApi.updateEnvironmentVariables(envData);

    if (!response.success) {
      throw new Error(response.error?.message || 'Failed to update environment variables');
    }

    return true;
  } catch (error) {
    console.error('❌ Error saving environment variables:', error);
    return false;
  }
}

async function addProductionVariableInteractive(
  context: ProductionContext,
  currentVariables: EnvVariable[]
): Promise<void> {
  const answers = await safePrompt<{ key: string; value: string }>([
    {
      type: 'input',
      name: 'key',
      message: 'Variable name:',
      validate: (input: string) => {
        if (!input.trim()) return 'Variable name is required';
        if (!/^[A-Z_][A-Z0-9_]*$/i.test(input.trim())) {
          return 'Variable name must start with a letter or underscore and contain only letters, numbers, and underscores';
        }
        if (currentVariables.some((v) => v.key === input.trim())) {
          return 'Variable already exists. Use update to modify it.';
        }
        return true;
      },
    },
    {
      type: 'input',
      name: 'value',
      message: 'Variable value:',
    },
  ]);

  if (!answers) return;

  const newVariable: EnvVariable = {
    key: answers.key.trim(),
    value: answers.value,
  };

  const updatedVariables = [...currentVariables, newVariable];

  writeProgress('🔄 Saving...');
  const success = await saveProductionEnvVariables(context, updatedVariables);

  if (success) {
    writeSuccess(`✅ Variable "${newVariable.key}" added successfully`);
  } else {
    console.error('❌ Failed to save variable');
  }
}

async function updateProductionVariableInteractive(
  context: ProductionContext,
  currentVariables: EnvVariable[]
): Promise<void> {
  if (currentVariables.length === 0) {
    console.log('\nℹ️  No variables to update.\n');
    return;
  }

  const selectAnswer = await safePrompt<{ selectedKey: string }>([
    {
      type: 'list',
      name: 'selectedKey',
      message: 'Select variable to update:',
      choices: currentVariables.map((v) => ({
        name: v.key,
        value: v.key,
      })),
    },
  ]);

  if (!selectAnswer) return;

  const currentVariable = currentVariables.find((v) => v.key === selectAnswer.selectedKey)!;

  const valueAnswer = await safePrompt<{ newValue: string }>([
    {
      type: 'input',
      name: 'newValue',
      message: `New value for ${selectAnswer.selectedKey}:`,
      default: currentVariable.value,
    },
  ]);

  if (!valueAnswer) return;

  const updatedVariables = currentVariables.map((v) =>
    v.key === selectAnswer.selectedKey ? { ...v, value: valueAnswer.newValue } : v
  );

  writeProgress('🔄 Saving...');
  const success = await saveProductionEnvVariables(context, updatedVariables);

  if (success) {
    writeSuccess(`✅ Variable "${selectAnswer.selectedKey}" updated successfully`);
  } else {
    console.error('❌ Failed to update variable');
  }
}

async function deleteProductionVariableInteractive(
  context: ProductionContext,
  currentVariables: EnvVariable[]
): Promise<void> {
  if (currentVariables.length === 0) {
    console.log('\nℹ️  No variables to delete.\n');
    return;
  }

  const selectAnswer = await safePrompt<{ selectedKey: string }>([
    {
      type: 'list',
      name: 'selectedKey',
      message: 'Select variable to delete:',
      choices: currentVariables.map((v) => ({
        name: v.key,
        value: v.key,
      })),
    },
  ]);

  if (!selectAnswer) return;

  const confirmAnswer = await safePrompt<{ confirm: boolean }>([
    {
      type: 'confirm',
      name: 'confirm',
      message: `Are you sure you want to delete "${selectAnswer.selectedKey}" from production?`,
      default: false,
    },
  ]);

  if (!confirmAnswer || !confirmAnswer.confirm) {
    console.log('\nℹ️  Deletion cancelled.\n');
    return;
  }

  const updatedVariables = currentVariables.filter((v) => v.key !== selectAnswer.selectedKey);

  writeProgress('🔄 Saving...');
  const success = await saveProductionEnvVariables(context, updatedVariables);

  if (success) {
    writeSuccess(`✅ Variable "${selectAnswer.selectedKey}" deleted successfully`);
  } else {
    console.error('❌ Failed to delete variable');
  }
}

async function viewProductionVariableInteractive(currentVariables: EnvVariable[]): Promise<void> {
  if (currentVariables.length === 0) {
    console.log('\nℹ️  No variables to view.\n');
    return;
  }

  const selectAnswer = await safePrompt<{ selectedKey: string }>([
    {
      type: 'list',
      name: 'selectedKey',
      message: 'Select variable to view:',
      choices: currentVariables.map((v) => ({
        name: v.key,
        value: v.key,
      })),
    },
  ]);

  if (!selectAnswer) return;

  const variable = currentVariables.find((v) => v.key === selectAnswer.selectedKey)!;

  console.log('\n' + '='.repeat(60));
  console.log(`Variable: ${variable.key}`);
  console.log('='.repeat(60));
  console.log(variable.value);
  console.log('='.repeat(60) + '\n');

  await safePrompt([{ type: 'input', name: 'continue', message: 'Press Enter to continue...' }]);
}
