/**
 * Sync Fetch — Data fetching layer for drift detection.
 * Fetches server state (persona, name) and compares with local code.
 */

import { canonify } from '@truestamp/canonify';
import type { PersonaText, SkillContextText } from '@lua/shared-types';
import { BASE_URLS } from '../config/constants.js';
import { getAgentName, getAgentPersona, getAgentModel, getAgentGovernance } from './artifact-loader.js';
import PersonaApi from '../api/persona.api.service.js';
import AgentApi from '../api/agent.api.service.js';
import SkillApi from '../api/skills.api.service.js';
import WebhookApi from '../api/webhook.api.service.js';
import JobApi from '../api/job.api.service.js';
import PreProcessorApi from '../api/preprocessor.api.service.js';
import PostProcessorApi from '../api/postprocessor.api.service.js';
import DeveloperApi from '../api/developer.api.service.js';
import { mcpServerHandler } from '../primitives/mcp-server.handler.js';
import type { YamlConfig } from '../types/yaml.types.js';

export interface PersonaDrift {
  hasDrift: boolean;
  serverPersona: PersonaText | null;
  localPersona: PersonaText;
  serverVersion?: number;
}

export interface NameDrift {
  hasDrift: boolean;
  serverName: string | null;
  localName: string;
}

function normalizeForComparison(str: string): string {
  return str
    .trim()
    .replace(/\\'/g, "'")
    .replace(/\\"/g, '"')
    .replace(/\\\\/g, '\\')
    .replace(/\r\n/g, '\n')
    .replace(/\r/g, '\n');
}

function canonicalizeForm(value: PersonaText | SkillContextText | null): string {
  if (value === null) return 'null';
  // Normalize strings the same way on both branches so the canonical form
  // stays internally consistent — a server string with CRLF endings vs. a
  // local string with LF endings should canonicalize identically.
  if (typeof value === 'string') return normalizeForComparison(value);
  const keys = Object.keys(value).sort();
  return JSON.stringify(
    keys.reduce((obj: Record<string, any>, key) => {
      const k = key as keyof typeof value;
      obj[k] = typeof value[k] === 'string' ? normalizeForComparison(value[k]) : value[k];
      return obj;
    }, {})
  );
}

export function comparePersona(serverPersona: PersonaText | null, localPersona: PersonaText): boolean {
  if (serverPersona === null) return false;
  const serverCanonical = canonicalizeForm(serverPersona);
  const localCanonical = canonicalizeForm(localPersona);
  if (typeof serverPersona === 'string' && typeof localPersona === 'string') {
    return normalizeForComparison(serverPersona) !== normalizeForComparison(localPersona);
  }
  return serverCanonical !== localCanonical;
}

export function compareSkillContext(serverContext: SkillContextText | null, localContext: SkillContextText): boolean {
  if (serverContext === null) return false;
  const serverCanonical = canonicalizeForm(serverContext);
  const localCanonical = canonicalizeForm(localContext);
  if (typeof serverContext === 'string' && typeof localContext === 'string') {
    return normalizeForComparison(serverContext) !== normalizeForComparison(localContext);
  }
  return serverCanonical !== localCanonical;
}

export async function fetchServerPersona(
  apiKey: string,
  agentId: string
): Promise<{ persona: PersonaText; version: number } | null> {
  try {
    const personaApi = new PersonaApi(BASE_URLS.API, apiKey, agentId);
    const latestPublished = await personaApi.getLatestPublishedVersion();
    if (latestPublished?.persona) {
      return { persona: latestPublished.persona, version: latestPublished.version };
    }
    return null;
  } catch {
    return null;
  }
}

export async function checkPersonaDrift(apiKey: string, agentId: string): Promise<PersonaDrift | null> {
  const localPersona = getAgentPersona() ?? '';
  const serverData = await fetchServerPersona(apiKey, agentId);
  const hasDrift = comparePersona(serverData?.persona || null, localPersona);
  if (!hasDrift) return null;
  return {
    hasDrift: true,
    serverPersona: serverData?.persona || null,
    localPersona,
    serverVersion: serverData?.version,
  };
}

export async function fetchServerAgent(apiKey: string, agentId: string): Promise<Record<string, any> | null> {
  try {
    const agentApi = new AgentApi(BASE_URLS.API, apiKey);
    const response = await agentApi.getAgent(agentId);
    return response.success && response.data ? response.data : null;
  } catch {
    return null;
  }
}

export async function fetchServerName(apiKey: string, agentId: string): Promise<string | null> {
  const agent = await fetchServerAgent(apiKey, agentId);
  return agent?.name ?? null;
}

export async function checkNameDrift(
  apiKey: string,
  agentId: string,
  prefetchedAgent?: Record<string, any> | null
): Promise<NameDrift | null> {
  const localName = getAgentName() ?? '';
  const agent = prefetchedAgent !== undefined ? prefetchedAgent : await fetchServerAgent(apiKey, agentId);
  const serverName = agent?.name ?? null;
  if (serverName === null) return null;
  const hasDrift = normalizeForComparison(serverName) !== normalizeForComparison(localName);
  if (!hasDrift) return null;
  return { hasDrift: true, serverName, localName };
}

export interface ModelDrift {
  hasDrift: boolean;
  serverModel: string | null;
  localModel: string;
}

export async function fetchServerModel(apiKey: string, agentId: string): Promise<string | null> {
  const agent = await fetchServerAgent(apiKey, agentId);
  if (agent === null) return null; // API failure — can't determine drift
  return agent.model ?? ''; // Agent exists but has no model → empty string
}

export async function checkModelDrift(
  apiKey: string,
  agentId: string,
  prefetchedAgent?: Record<string, any> | null
): Promise<ModelDrift | null> {
  const localModel = getAgentModel() ?? '';
  const agent = prefetchedAgent !== undefined ? prefetchedAgent : await fetchServerAgent(apiKey, agentId);
  if (agent === null) return null; // API failure only
  const serverModel = agent.model ?? '';

  const hasDrift = normalizeForComparison(serverModel) !== normalizeForComparison(localModel);
  if (!hasDrift) return null;

  return { hasDrift: true, serverModel: serverModel || null, localModel };
}

// ============================================================================
// Primitive Drift Types
// ============================================================================

/** Describes how a primitive differs between local config and the server. */
export type PrimitiveDriftStatus = 'version-mismatch' | 'missing-locally' | 'missing-on-server';

/** A single primitive that has drifted between local config and the server. */
export interface PrimitiveDriftItem {
  /** The name of the primitive as it appears in the YAML config or on the server. */
  name: string;
  /** The primitive type. */
  type: 'skill' | 'webhook' | 'job' | 'preprocessor' | 'postprocessor' | 'mcpServer';
  /** How the local config and server differ for this primitive. */
  status: PrimitiveDriftStatus;
  /** The version recorded in the local YAML config, or null when not present locally. */
  localVersion: string | null;
  /** The active version on the server, or null when not present on the server. */
  serverVersion: string | null;
  /** The server-assigned entity ID, if known. */
  entityId: string | null;
}

/** Aggregate result of comparing all primitives between local config and the server. */
export interface PrimitiveDrift {
  items: PrimitiveDriftItem[];
  hasDrift: boolean;
  /** Whether a backup exists for this agent (per-agent, not per-primitive). */
  backupAvailable?: boolean;
}

// ============================================================================
// Server Primitive Shapes (normalised for comparison)
// ============================================================================

interface ServerPrimitive {
  id: string;
  name: string;
  /** Active version string, or null when none exists. */
  activeVersion: string | null;
}

interface ServerPrimitives {
  skills: ServerPrimitive[];
  webhooks: ServerPrimitive[];
  jobs: ServerPrimitive[];
  preprocessors: ServerPrimitive[];
  postprocessors: ServerPrimitive[];
  mcpServers: ServerPrimitive[];
}

interface ServerVersionEntry {
  id?: string;
  versionId?: string;
  version?: string;
  active?: boolean;
}

/** Resolves the active version string from a list of version entries. */
function resolveActiveVersion(versions: ServerVersionEntry[], activeVersionId?: string | null): string | null {
  if (activeVersionId) {
    const match = versions.find((v) => v.id === activeVersionId || v.versionId === activeVersionId);
    if (match?.version) return match.version;
  }
  const activeByFlag = versions.find((v) => v.active);
  if (activeByFlag?.version) return activeByFlag.version;
  return versions[versions.length - 1]?.version ?? null;
}

// ============================================================================
// fetchServerPrimitives
// ============================================================================

/**
 * Fetches all primitive types from the server in parallel.
 * Each fetch failure is caught individually — a partial result is returned
 * rather than failing the entire operation.
 *
 * @param apiKey - Developer API key used for authentication.
 * @param agentId - The agent whose primitives to fetch.
 * @returns Normalised server primitives grouped by type.
 */
export async function fetchServerPrimitives(apiKey: string, agentId: string): Promise<ServerPrimitives> {
  const skillApi = new SkillApi(BASE_URLS.API, apiKey, agentId);
  const webhookApi = new WebhookApi(BASE_URLS.API, apiKey, agentId);
  const jobApi = new JobApi(BASE_URLS.API, apiKey, agentId);
  const preProcessorApi = new PreProcessorApi(BASE_URLS.API, apiKey, agentId);
  const postProcessorApi = new PostProcessorApi(BASE_URLS.API, apiKey, agentId);
  const developerApi = new DeveloperApi(BASE_URLS.API, apiKey, agentId);

  const [skillsRes, webhooksRes, jobsRes, preprocessorsRes, postprocessorsRes, mcpServersRes] = await Promise.all([
    skillApi.getSkills().catch(() => null),
    webhookApi.getWebhooks().catch(() => null),
    jobApi.getJobs().catch(() => null),
    preProcessorApi.getPreProcessors().catch(() => null),
    postProcessorApi.getPostProcessors().catch(() => null),
    developerApi.getMCPServers().catch(() => null),
  ]);

  const skills: ServerPrimitive[] =
    skillsRes?.success && skillsRes.data?.skills
      ? skillsRes.data.skills.map((s) => ({
          id: s.id,
          name: s.name,
          activeVersion: resolveActiveVersion(s.versions as ServerVersionEntry[]),
        }))
      : [];

  const webhooks: ServerPrimitive[] =
    webhooksRes?.success && webhooksRes.data?.webhooks
      ? webhooksRes.data.webhooks.map((w) => ({
          id: w.id,
          name: w.name,
          activeVersion: resolveActiveVersion(w.versions as ServerVersionEntry[], w.activeVersionId),
        }))
      : [];

  const jobs: ServerPrimitive[] =
    jobsRes?.success && jobsRes.data?.jobs
      ? jobsRes.data.jobs.map((j) => ({
          id: j.id,
          name: j.name,
          activeVersion: resolveActiveVersion(j.versions as ServerVersionEntry[], j.activeVersionId),
        }))
      : [];

  const preprocessors: ServerPrimitive[] =
    preprocessorsRes?.success && preprocessorsRes.data?.preprocessors
      ? preprocessorsRes.data.preprocessors.map((p) => ({
          id: p.id,
          name: p.name,
          activeVersion: resolveActiveVersion(p.versions as ServerVersionEntry[], p.activeVersionId),
        }))
      : [];

  const postprocessors: ServerPrimitive[] =
    postprocessorsRes?.success && postprocessorsRes.data?.postprocessors
      ? postprocessorsRes.data.postprocessors.map((p) => ({
          id: p.id,
          name: p.name,
          activeVersion: resolveActiveVersion(p.versions as ServerVersionEntry[], p.activeVersionId),
        }))
      : [];

  // Integration-sourced (e.g. UnifiedTo) and deactivated servers are excluded from drift —
  // the handler's isActive() encodes both rules and stays the single source of truth.
  const mcpServers: ServerPrimitive[] =
    mcpServersRes?.success && mcpServersRes.data
      ? mcpServersRes.data
          .filter((m) => mcpServerHandler.isActive(m))
          .map((m) => ({ id: m.id, name: m.name, activeVersion: null }))
      : [];

  return { skills, webhooks, jobs, preprocessors, postprocessors, mcpServers };
}

// ============================================================================
// comparePrimitives
// ============================================================================

/**
 * Compares one primitive type across local and server lists.
 * Returns items that have drifted (version mismatch, missing locally, or missing on server).
 */
export function comparePrimitives(
  type: PrimitiveDriftItem['type'],
  localItems: Array<{ name: string; version: string | null; entityId: string | null }>,
  serverItems: Array<{ id: string; name: string; activeVersion: string | null }>
): PrimitiveDriftItem[] {
  const items: PrimitiveDriftItem[] = [];
  const serverByName = new Map(serverItems.map((s) => [s.name, s]));
  const localByName = new Map(localItems.map((l) => [l.name, l]));

  for (const local of localItems) {
    const serverItem = serverByName.get(local.name);
    if (!serverItem) {
      items.push({
        name: local.name,
        type,
        status: 'missing-on-server',
        localVersion: local.version,
        serverVersion: null,
        entityId: local.entityId,
      });
    } else if (serverItem.activeVersion && serverItem.activeVersion !== local.version) {
      items.push({
        name: local.name,
        type,
        status: 'version-mismatch',
        localVersion: local.version,
        serverVersion: serverItem.activeVersion,
        entityId: serverItem.id,
      });
    }
  }

  for (const serverItem of serverItems) {
    if (!localByName.has(serverItem.name)) {
      items.push({
        name: serverItem.name,
        type,
        status: 'missing-locally',
        localVersion: null,
        serverVersion: serverItem.activeVersion,
        entityId: serverItem.id,
      });
    }
  }

  return items;
}

// ============================================================================
// checkPrimitiveDrift
// ============================================================================

/**
 * Compares all primitive types in the local YAML config against the server
 * and returns items that have drifted.
 */
export async function checkPrimitiveDrift(
  apiKey: string,
  agentId: string,
  localConfig: YamlConfig
): Promise<PrimitiveDrift> {
  const server = await fetchServerPrimitives(apiKey, agentId);
  const items: PrimitiveDriftItem[] = [
    ...comparePrimitives(
      'skill',
      (localConfig.skills ?? []).map((s) => ({ name: s.name, version: s.version, entityId: s.skillId })),
      server.skills
    ),
    ...comparePrimitives(
      'webhook',
      (localConfig.webhooks ?? []).map((w) => ({ name: w.name, version: w.version, entityId: w.webhookId })),
      server.webhooks
    ),
    ...comparePrimitives(
      'job',
      (localConfig.jobs ?? []).map((j) => ({ name: j.name, version: j.version, entityId: j.jobId })),
      server.jobs
    ),
    ...comparePrimitives(
      'preprocessor',
      (localConfig.preprocessors ?? []).map((p) => ({ name: p.name, version: p.version, entityId: p.preprocessorId })),
      server.preprocessors
    ),
    ...comparePrimitives(
      'postprocessor',
      (localConfig.postprocessors ?? []).map((p) => ({
        name: p.name,
        version: p.version,
        entityId: p.postprocessorId,
      })),
      server.postprocessors
    ),
    ...comparePrimitives(
      'mcpServer',
      (localConfig.mcpServers ?? []).map((m) => ({ name: m.name, version: null, entityId: m.mcpServerId })),
      server.mcpServers
    ),
  ];

  return { items, hasDrift: items.length > 0 };
}

export interface GovernanceDrift {
  hasDrift: boolean;
  serverGovernance: any | null;
  localGovernance: any | null;
}

export async function checkGovernanceDrift(
  apiKey: string,
  agentId: string,
  prefetchedAgent?: Record<string, any> | null
): Promise<GovernanceDrift | null> {
  const localGovernance = getAgentGovernance() ?? null;
  const agent = prefetchedAgent !== undefined ? prefetchedAgent : await fetchServerAgent(apiKey, agentId);
  if (agent === null) return null; // API failure

  const serverGovernance = agent.governance ?? null;
  const hasDrift = canonify(serverGovernance) !== canonify(localGovernance);
  if (!hasDrift) return null;

  return { hasDrift: true, serverGovernance, localGovernance };
}
