/**
 * Source Writer
 *
 * Utilities for modifying Lua agent source code via AST manipulation.
 * All ts-morph write operations are centralized here.
 *
 * ## Current Implementation
 *
 * Currently only supports updating `LuaAgent` config properties (name, persona)
 * in the entry point file. This covers the main use cases:
 * - `lua init` - setting initial agent config
 * - `lua sync` - syncing agent name/persona from server
 * - `lua persona` - updating persona
 *
 * ## Future Extensibility
 *
 * To support modifying other primitives (skills, jobs, webhooks, etc.),
 * this module could be extended with a generic API like:
 *
 * ```typescript
 * // Generic primitive update
 * updatePrimitiveConfig({
 *   kind: 'LuaSkill',           // Target class: LuaSkill, LuaJob, LuaWebhook, etc.
 *   name: 'my-skill',           // Find by name property
 *   file: 'src/skills/my.ts',   // Or specify file directly
 *   updates: {
 *     description: 'New desc',
 *     context: 'New context',
 *   }
 * });
 *
 * // Or batch updates across files
 * updatePrimitivesFromManifest(manifest, serverData);
 * ```
 *
 * Key considerations for generic implementation:
 * - Support different primitive classes (LuaSkill, LuaJob, LuaWebhook, LuaMCPServer)
 * - Find primitives across multiple files (not just entry point)
 * - Handle different value types (strings, numbers, objects, arrays)
 * - Support adding/removing properties, not just updating
 * - Preserve code formatting and comments where possible
 *
 * @example
 * ```typescript
 * // Current API - agent config only
 * updateAgentConfig({ name: 'New Name', persona: 'New persona...' });
 * setAgentName('New Name');
 * setAgentPersona('New persona...');
 * ```
 */

import { Project, Node } from 'ts-morph';
import fs from 'fs';
import path from 'path';
import type { PersonaText } from '@lua/shared-types';
import { personaToLiteral } from '@lua/shared-types';
import { findIndexFile, findEntryPoint } from './utils/file-discovery.js';

/**
 * Options for source writing operations.
 */
export interface SourceWriteOptions {
  /** Project directory to search (defaults to cwd) */
  projectDir?: string;
  /** Override default index file discovery with specific file path */
  indexFile?: string;
}

/**
 * Resolves the entry-point file path for source-writing operations.
 * Checks options.indexFile first, then runs entry-point discovery,
 * falling back to src/index.ts.
 *
 * @returns The resolved path, or null if the file does not exist.
 */
function resolveEntryPath(options?: SourceWriteOptions): string | null {
  let indexPath: string;

  try {
    if (options?.indexFile) {
      indexPath = options.indexFile;
    } else {
      const entryPoint = findEntryPoint(options?.projectDir);
      if (entryPoint) {
        indexPath = entryPoint;
      } else {
        const baseDir = options?.projectDir || process.cwd();
        indexPath = path.join(baseDir, 'src', 'index.ts');
      }
    }
  } catch {
    const baseDir = options?.projectDir || process.cwd();
    indexPath = path.join(baseDir, 'src', 'index.ts');
  }

  if (!fs.existsSync(indexPath)) {
    console.warn(`Warning: Entry file not found at ${indexPath}`);
    return null;
  }

  return indexPath;
}

/**
 * Update properties in the LuaAgent configuration in source code.
 *
 * This writer can update properties including persona (which accepts both
 * string and object forms), name, model, and other string properties.
 *
 * @param updates - Object with property names and their new values (undefined values are skipped)
 * @param options - Optional configuration
 * @returns true if the LuaAgent constructor was found and properties were written, false otherwise
 *
 * @example
 * ```typescript
 * // Update name only
 * updateAgentConfig({ name: 'New Agent Name' });
 *
 * // Update persona (string form)
 * updateAgentConfig({
 *   persona: 'You are a helpful assistant...'
 * });
 *
 * // Update persona (object form)
 * updateAgentConfig({
 *   persona: { base: 'Core', voice: 'Natural' }
 * });
 * ```
 */
export function updateAgentConfig(
  updates: Record<string, string | PersonaText | undefined>,
  options?: SourceWriteOptions
): boolean {
  // Filter out undefined values and pre-format every value as ready-to-insert
  // source text. Object-form persona becomes an object literal via
  // personaToLiteral; everything else (including string-form persona) is
  // wrapped into a string/template literal by formatValueForProperty.
  const filteredUpdates: Record<string, string> = {};
  for (const [key, value] of Object.entries(updates)) {
    if (value === undefined) continue;
    if (key === 'persona' && typeof value !== 'string') {
      filteredUpdates[key] = personaToLiteral(value);
    } else {
      filteredUpdates[key] = formatValueForProperty(key, String(value));
    }
  }

  if (Object.keys(filteredUpdates).length === 0) {
    return true; // Nothing to update
  }

  const indexPath = resolveEntryPath(options);
  if (!indexPath) return false;

  try {
    const project = new Project({ skipAddingFilesFromTsConfig: true });
    const sourceFile = project.addSourceFileAtPath(indexPath);

    let updated = false;

    sourceFile.forEachDescendant((node: any) => {
      if (Node.isNewExpression(node) && node.getExpression().getText() === 'LuaAgent') {
        const args = node.getArguments();
        if (args.length > 0 && Node.isObjectLiteralExpression(args[0])) {
          const configObj = args[0];

          const replacedKeys = new Set<string>();
          let lastReplacedIndex = -1;

          configObj.getProperties().forEach((prop: any, index: number) => {
            if (Node.isPropertyAssignment(prop)) {
              const propName = prop.getName();

              if (Object.prototype.hasOwnProperty.call(filteredUpdates, propName)) {
                const newValue = filteredUpdates[propName as keyof typeof filteredUpdates];
                const init = prop.getInitializer();

                if (init) {
                  init.replaceWithText(newValue);
                  replacedKeys.add(propName);
                  if (index > lastReplacedIndex) lastReplacedIndex = index;
                  updated = true;
                }
              }
            }
          });

          // Insert properties that were requested but don't exist yet.
          // Place them right after the last replaced property (e.g. model after persona)
          // rather than at the end of the object (which would land after comments).
          for (const [key, value] of Object.entries(filteredUpdates)) {
            if (!replacedKeys.has(key)) {
              const insertIdx = lastReplacedIndex >= 0 ? lastReplacedIndex + 1 : configObj.getProperties().length;
              configObj.insertPropertyAssignment(insertIdx, {
                name: key,
                initializer: value,
              });
              lastReplacedIndex = insertIdx;
              updated = true;
            }
          }
        }
      }
    });

    if (updated) {
      sourceFile.saveSync();
    }

    return updated;
  } catch (error) {
    console.warn('Warning: Could not update agent config in source:', error);
    return false;
  }
}

/**
 * Set the agent name in source code.
 *
 * @param name - New agent name
 * @param options - Optional configuration
 * @returns true if update succeeded, false otherwise
 */
export function setAgentName(name: string, options?: SourceWriteOptions): boolean {
  return updateAgentConfig({ name }, options);
}

/**
 * Set the agent persona in source code.
 *
 * @param persona - New agent persona (string or object form)
 * @param options - Optional configuration
 * @returns true if update succeeded, false otherwise
 */
export function setAgentPersona(persona: PersonaText, options?: SourceWriteOptions): boolean {
  return updateAgentConfig({ persona }, options);
}

/**
 * Set the agent model in source code.
 * Only works for static model strings (not function-based resolvers).
 *
 * @param model - New model string (e.g., 'openai/gpt-4o')
 * @param options - Optional configuration
 * @returns true if update succeeded, false otherwise
 */
export function setAgentModel(model: string, options?: SourceWriteOptions): boolean {
  return updateAgentConfig({ model }, options);
}

/**
 * Remove a property from the LuaAgent config object in source code.
 *
 * @param propertyName - Name of the property to remove (e.g. 'model')
 * @param options - Optional configuration
 * @returns true if the LuaAgent constructor was found (property may already be absent), false if not found or on error
 */
export function removeAgentConfigProperty(propertyName: string, options?: SourceWriteOptions): boolean {
  const indexPath = resolveEntryPath(options);
  if (!indexPath) return false;

  try {
    const project = new Project({ skipAddingFilesFromTsConfig: true });
    const sourceFile = project.addSourceFileAtPath(indexPath);

    let foundConstructor = false;
    let removed = false;

    sourceFile.forEachDescendant((node: any) => {
      if (Node.isNewExpression(node) && node.getExpression().getText() === 'LuaAgent') {
        const args = node.getArguments();
        if (args.length > 0 && Node.isObjectLiteralExpression(args[0])) {
          foundConstructor = true;
          const configObj = args[0];
          const props = configObj.getProperties();
          for (const prop of props) {
            if (Node.isPropertyAssignment(prop) && prop.getName() === propertyName) {
              prop.remove();
              removed = true;
              break;
            }
          }
        }
      }
    });

    if (removed) {
      sourceFile.saveSync();
    }

    // Success if we found the constructor (property may or may not have been present)
    return foundConstructor;
  } catch (error) {
    console.warn('Warning: Could not remove agent config property from source:', error);
    return false;
  }
}

/**
 * Remove the model property from the LuaAgent config in source code,
 * causing the platform to fall back to its default model.
 *
 * @param options - Optional configuration
 * @returns true if the LuaAgent constructor was found, false if not found or on error
 */
export function removeAgentModel(options?: SourceWriteOptions): boolean {
  return removeAgentConfigProperty('model', options);
}

