/**
 * Devices Command
 * Manages agent device definitions and tests device communication
 */

import { withErrorHandling, writeProgress, writeSuccess, writeInfo } from '../utils/cli.js';
import { BASE_URLS } from '../config/constants.js';
import { safePrompt } from '../utils/prompt-handler.js';
import { initializeCommand } from '../utils/command-utils.js';
import DeviceApi from '../api/device.api.service.js';
import { trackEvent } from '../services/analytics.js';
import { validateOrSuggest } from '../utils/aliases.js';

interface DevicesOptions {
  deviceName?: string;
  group?: string;
  payload?: string;
  timeout?: string;
}

type DeviceAction = 'list' | 'status' | 'enable' | 'disable' | 'remove' | 'test' | 'test-trigger';

// ─────────────────────────────────────────────────────────────────────────────
// Main Command Entry
// ─────────────────────────────────────────────────────────────────────────────

export async function devicesCommand(action?: string, cmdObj?: any): Promise<void> {
  return withErrorHandling(async () => {
    const options: DevicesOptions = {
      deviceName: cmdObj?.deviceName || null,
      group: cmdObj?.group || null,
      payload: cmdObj?.payload || '{}',
      timeout: cmdObj?.timeout || '30000',
    };

    const { apiKey, agentId } = await initializeCommand();
    const api = new DeviceApi(BASE_URLS.API, apiKey, agentId);

    let selectedAction: DeviceAction;

    if (action) {
      selectedAction = validateOrSuggest('devices.action', action) as DeviceAction;
    } else {
      const answer = await safePrompt<{ action: string }>([
        {
          type: 'list',
          name: 'action',
          message: 'What would you like to do?',
          choices: [
            { name: '📋 List devices', value: 'list' },
            { name: '📊 Device status', value: 'status' },
            { name: '✅ Enable device', value: 'enable' },
            { name: '⛔ Disable device', value: 'disable' },
            { name: '🗑️  Remove device', value: 'remove' },
            { name: '🧪 Test command', value: 'test' },
            { name: '🔔 Test trigger', value: 'test-trigger' },
          ],
        },
      ]);
      if (!answer) return;
      selectedAction = answer.action as DeviceAction;
    }

    switch (selectedAction) {
      case 'list':
        await listDevices(api, options);
        break;
      case 'status':
        await deviceStatus(api, options);
        break;
      case 'enable':
        await enableDevice(api, options);
        break;
      case 'disable':
        await disableDevice(api, options);
        break;
      case 'remove':
        await removeDevice(api, options, cmdObj?.force);
        break;
      case 'test':
        await testCommand(api, options);
        break;
      case 'test-trigger':
        await testTrigger(api, options);
        break;
    }

    trackEvent('cli_devices_completed', {
      action: selectedAction,
      device_name: options.deviceName || undefined,
      non_interactive: !!action,
    });
  }, 'devices');
}

// ─────────────────────────────────────────────────────────────────────────────
// Actions
// ─────────────────────────────────────────────────────────────────────────────

async function listDevices(api: DeviceApi, options: DevicesOptions): Promise<void> {
  writeProgress('Fetching devices...');
  const response = await api.getDevices();

  if (!response.success || !response.data) {
    throw new Error(response.error?.message || 'Failed to fetch devices');
  }

  const devices = (response.data as any).devices || response.data;
  if (!Array.isArray(devices) || devices.length === 0) {
    writeInfo('No devices registered. Connect a device using @lua/device-client.');
    return;
  }

  let filtered = devices;
  if (options.group) {
    filtered = devices.filter((d: any) => d.group === options.group);
    if (filtered.length === 0) {
      writeInfo(`No devices found in group '${options.group}'.`);
      return;
    }
  }

  console.log(`\n  Devices (${filtered.length}):\n`);
  for (const d of filtered) {
    const statusIcon = d.active === false ? '⛔' : '📡';
    console.log(`  ${statusIcon} ${d.name}${d.group ? ` [${d.group}]` : ''}`);
    console.log(`     ID: ${d.id}`);
    if (d.description) console.log(`     ${d.description}`);
    console.log('');
  }
}

async function deviceStatus(api: DeviceApi, options: DevicesOptions): Promise<void> {
  const name = await resolveDeviceName(api, options.deviceName, 'Check status of');
  writeProgress(`Checking status of '${name}'...`);

  const response = await api.getDeviceStatus(name);
  if (!response.success) {
    throw new Error(response.error?.message || 'Failed to get device status');
  }

  const status = (response.data as any).status;
  const icon = status === 'online' ? '🟢' : status === 'disabled' ? '⛔' : '🔴';
  writeSuccess(`${icon} Device '${name}' is ${status}`);
}

async function enableDevice(api: DeviceApi, options: DevicesOptions): Promise<void> {
  const name = await resolveDeviceName(api, options.deviceName, 'Enable');
  writeProgress(`Enabling '${name}'...`);

  const response = await api.enableDevice(name);
  if (!response.success) {
    throw new Error(response.error?.message || 'Failed to enable device');
  }
  writeSuccess(`Device '${name}' enabled`);
}

async function disableDevice(api: DeviceApi, options: DevicesOptions): Promise<void> {
  const name = await resolveDeviceName(api, options.deviceName, 'Disable');
  writeProgress(`Disabling '${name}'...`);

  const response = await api.disableDevice(name);
  if (!response.success) {
    throw new Error(response.error?.message || 'Failed to disable device');
  }
  writeSuccess(`Device '${name}' disabled`);
}

async function removeDevice(api: DeviceApi, options: DevicesOptions, force?: boolean): Promise<void> {
  const name = await resolveDeviceName(api, options.deviceName, 'Remove');

  if (!force) {
    const confirm = await safePrompt<{ yes: boolean }>([
      { type: 'confirm', name: 'yes', message: `Remove device '${name}'? This cannot be undone.`, default: false },
    ]);
    if (!confirm?.yes) {
      console.log('Cancelled.');
      return;
    }
  }

  writeProgress(`Removing '${name}'...`);
  const response = await api.deleteDevice(name);
  if (!response.success) {
    throw new Error(response.error?.message || 'Failed to remove device');
  }
  writeSuccess(`Device '${name}' removed`);
}

async function testCommand(api: DeviceApi, options: DevicesOptions): Promise<void> {
  const name = await resolveDeviceName(api, options.deviceName, 'Test command on');

  let command: string;
  if (cmdHasPositionalCommand(options)) {
    command = (options as any).command;
  } else {
    const answer = await safePrompt<{ command: string }>([
      { type: 'input', name: 'command', message: 'Command name:' },
    ]);
    if (!answer?.command) return;
    command = answer.command;
  }

  let payload: any;
  try {
    payload = JSON.parse(options.payload || '{}');
  } catch {
    throw new Error(`Invalid JSON payload: ${options.payload}`);
  }

  const timeout = parseInt(options.timeout || '30000');
  console.log(`\n  Sending '${command}' to device '${name}'...`);
  const start = Date.now();

  const response = await api.sendCommand(name, command, payload, timeout);
  const latency = Date.now() - start;

  if (response.success && response.data) {
    const data = response.data;
    if (data.success !== false) {
      writeSuccess(`Response received (${latency}ms):`);
      console.log(JSON.stringify(data.data || data, null, 2));
    } else {
      console.log(`\n  ❌ Device returned error (${latency}ms):`);
      console.log(`  ${data.error || 'Unknown error'}`);
    }
  } else {
    const msg = response.error?.message || 'Command failed';
    if (msg.includes('offline')) {
      console.log(`\n  ❌ Device '${name}' is offline`);
    } else if (msg.includes('timed out')) {
      console.log(`\n  ❌ Command timed out after ${timeout}ms`);
    } else {
      throw new Error(msg);
    }
  }
}

async function testTrigger(api: DeviceApi, options: DevicesOptions): Promise<void> {
  const name = await resolveDeviceName(api, options.deviceName, 'Test trigger on');

  let triggerName: string;
  const answer = await safePrompt<{ trigger: string }>([{ type: 'input', name: 'trigger', message: 'Trigger name:' }]);
  if (!answer?.trigger) return;
  triggerName = answer.trigger;

  let payload: any;
  try {
    payload = JSON.parse(options.payload || '{}');
  } catch {
    throw new Error(`Invalid JSON payload: ${options.payload}`);
  }

  console.log(`\n  Simulating trigger '${triggerName}' on device '${name}'...`);
  writeInfo('Note: This sends the trigger through the full execution pipeline on the server.');

  // test-trigger sends a command to the server to simulate a trigger
  // This could be a dedicated endpoint, but for now we use the command endpoint
  // with a special command name that the gateway recognizes
  const response = await api.sendCommand(
    name,
    `__test_trigger__${triggerName}`,
    payload,
    parseInt(options.timeout || '30000')
  );

  if (response.success) {
    writeSuccess('Trigger sent successfully. Check agent logs for execution results.');
  } else {
    console.log(`\n  ❌ ${response.error?.message || 'Failed to send trigger'}`);
  }
}

// ─────────────────────────────────────────────────────────────────────────────
// Helpers
// ─────────────────────────────────────────────────────────────────────────────

async function resolveDeviceName(
  api: DeviceApi,
  name: string | undefined | null,
  actionLabel: string
): Promise<string> {
  if (name) return name;

  const response = await api.getDevices();
  const devices = (response.data as any)?.devices || response.data || [];
  if (!Array.isArray(devices) || devices.length === 0) {
    throw new Error('No devices registered.');
  }

  const answer = await safePrompt<{ device: string }>([
    {
      type: 'list',
      name: 'device',
      message: `${actionLabel} which device?`,
      choices: devices.map((d: any) => ({
        name: `${d.name}${d.group ? ` [${d.group}]` : ''}`,
        value: d.name,
      })),
    },
  ]);
  if (!answer?.device) throw new Error('No device selected.');
  return answer.device;
}

function cmdHasPositionalCommand(options: any): boolean {
  return !!(options as any).command;
}
