/**
 * Job compilation plugin.
 *
 * BACKWARD COMPATIBLE: Detects BOTH patterns:
 * 1. Class-based (legacy): new LuaJob({ ... })
 * 2. Function-based (new): const myJob = defineJob({ ... })
 */

import { ObjectLiteralExpression, ClassDeclaration, SourceFile, Node } from 'ts-morph';
import {
  type JobMetadata,
  type JobMetadataFields,
  type ValidationResult,
  type CompiledPrimitive,
  type ManifestPrimitive,
  type ManifestJob,
} from '../types.js';
import { BasePlugin, readStringMember, deriveNameFromClassName, validationError } from './base.js';
import {
  extractNumberProperty,
  extractObjectProperty,
  extractNestedProperty,
  evaluateNodeAsNumber,
  evaluateNodeAsObject,
} from '../utils/ast-helpers.js';
import { findClassMember } from '../utils/class-hierarchy.js';

/**
 * Plugin for compiling job primitives.
 * Extends BasePlugin for common detection/entry point/postProcess logic.
 */
export class JobPlugin extends BasePlugin<JobMetadataFields> {
  readonly kind = 'job';
  readonly displayName = 'Job';
  readonly defineFunction = 'defineJob';
  readonly legacyClassNames = ['LuaJob'];

  protected readonly supportsClassDefinition = true;

  /**
   * Class-definition extraction. Reads `name`/`description`/`schedule`/
   * `timeout`/`retry`/`execute` off the inheritance chain. The
   * `schedule` and `retry` initializers are evaluated to plain objects
   * via ts-evaluator so subclass-side overrides + cross-file constants
   * work the same as in the config-literal path.
   */
  protected extractFromClassDefinition(classDecl: ClassDeclaration, sourceFile: SourceFile): JobMetadata | null {
    const className = classDecl.getName();
    if (!className) return null;

    const isDefaultExport = classDecl.isDefaultExport();
    const exportName = isDefaultExport ? 'default' : className;

    const name = readStringMember(classDecl, 'name') ?? deriveNameFromClassName(className);
    const description = readStringMember(classDecl, 'description') ?? '';

    // schedule = { type, expression, seconds, executeAt, timezone }
    const scheduleHit = findClassMember(classDecl, 'schedule', 'property');
    const scheduleObj =
      scheduleHit && Node.isPropertyDeclaration(scheduleHit.node)
        ? evaluateNodeAsObject(scheduleHit.node.getInitializer())
        : undefined;
    const scheduleType = extractNestedProperty(scheduleObj, 'type') as string | undefined;
    const scheduleExpression = extractNestedProperty(scheduleObj, 'expression') as string | undefined;
    const scheduleSeconds = extractNestedProperty(scheduleObj, 'seconds') as number | undefined;
    const scheduleExecuteAt = extractNestedProperty(scheduleObj, 'executeAt') as string | undefined;
    const scheduleTimezone = extractNestedProperty(scheduleObj, 'timezone') as string | undefined;

    const timeoutHit = findClassMember(classDecl, 'timeout', 'property');
    const timeoutValue =
      timeoutHit && Node.isPropertyDeclaration(timeoutHit.node)
        ? evaluateNodeAsNumber(timeoutHit.node.getInitializer())
        : undefined;

    const retryHit = findClassMember(classDecl, 'retry', 'property');
    const retryObj =
      retryHit && Node.isPropertyDeclaration(retryHit.node)
        ? evaluateNodeAsObject(retryHit.node.getInitializer())
        : undefined;
    const retryConfig = retryObj
      ? {
          maxAttempts: extractNestedProperty(retryObj, 'maxAttempts') as number | undefined,
          backoffSeconds: extractNestedProperty(retryObj, 'backoffSeconds') as number | undefined,
        }
      : undefined;

    return {
      kind: this.kind,
      name,
      description,
      sourcePath: sourceFile.getFilePath(),
      exportName,
      isDefaultExport,
      line: classDecl.getStartLineNumber(),
      column: 1,
      metadata: {
        pattern: 'class-definition',
        scheduleType,
        scheduleExpression,
        scheduleSeconds,
        scheduleExecuteAt,
        scheduleTimezone,
        hasExecute: findClassMember(classDecl, 'execute', 'either') !== undefined,
        hasTimeout: timeoutHit !== undefined,
        hasRetry: retryHit !== undefined,
        timeoutValue,
        retryConfig,
      },
    };
  }

  /**
   * Project the job class instance onto the standard primitive shape.
   */
  protected getClassDefinitionPrimitiveShape(metadata: JobMetadata): string {
    return `{
    kind: 'job',
    name: __lua_instance__.name ?? ${JSON.stringify(metadata.name)},
    description: __lua_instance__.description ?? ${JSON.stringify(metadata.description)},
    schedule: __lua_instance__.schedule,
    timeout: __lua_instance__.timeout,
    retry: __lua_instance__.retry,
    execute: typeof __lua_instance__.execute === 'function' ? __lua_instance__.execute.bind(__lua_instance__) : undefined,
  }`;
  }

  /**
   * Extract metadata from job config object.
   */
  protected extractFromConfig(
    config: ObjectLiteralExpression,
    exportName: string,
    sourcePath: string,
    position: { line: number; column: number },
    pattern: 'function' | 'class'
  ): JobMetadata | null {
    const common = this.extractCommonFields(config, exportName, sourcePath, position);
    if (!common) return null;

    // Extract schedule (use extractObjectProperty to handle variable references)
    const scheduleObj = extractObjectProperty(config, 'schedule');
    const scheduleType = extractNestedProperty(scheduleObj, 'type') as string | undefined;
    const scheduleExpression = extractNestedProperty(scheduleObj, 'expression') as string | undefined;
    const scheduleSeconds = extractNestedProperty(scheduleObj, 'seconds') as number | undefined;
    const scheduleExecuteAt = extractNestedProperty(scheduleObj, 'executeAt') as string | undefined;
    const scheduleTimezone = extractNestedProperty(scheduleObj, 'timezone') as string | undefined;

    // Extract timeout
    const timeoutValue = extractNumberProperty(config, 'timeout');

    // Extract retry config (use extractObjectProperty to handle variable references)
    const retryObj = extractObjectProperty(config, 'retry');
    const retryConfig = retryObj
      ? {
          maxAttempts: extractNestedProperty(retryObj, 'maxAttempts') as number | undefined,
          backoffSeconds: extractNestedProperty(retryObj, 'backoffSeconds') as number | undefined,
        }
      : undefined;

    return {
      kind: this.kind,
      ...common,
      metadata: {
        pattern,
        scheduleType,
        scheduleExpression,
        scheduleSeconds,
        scheduleExecuteAt,
        scheduleTimezone,
        hasExecute: config.getProperty('execute') !== undefined,
        hasTimeout: config.getProperty('timeout') !== undefined,
        hasRetry: config.getProperty('retry') !== undefined,
        timeoutValue,
        retryConfig,
      },
    };
  }

  validate(metadata: JobMetadata): ValidationResult {
    const { errors, warnings } = this.baseValidation(metadata);

    if (!metadata.metadata.hasExecute) {
      errors.push(validationError('Job must have an execute function', { line: metadata.line }));
    }

    if (!metadata.metadata.scheduleType) {
      errors.push(
        validationError('Job must have a schedule', {
          line: metadata.line,
          suggestion: 'Add a schedule: schedule: { type: "cron", expression: "0 9 * * *" }',
        })
      );
    }

    const validScheduleTypes = ['cron', 'interval', 'once'];
    if (metadata.metadata.scheduleType && !validScheduleTypes.includes(metadata.metadata.scheduleType)) {
      errors.push(
        validationError(
          `Invalid schedule type: ${metadata.metadata.scheduleType}. Must be one of: ${validScheduleTypes.join(', ')}`,
          { line: metadata.line }
        )
      );
    }

    return { valid: errors.length === 0, errors, warnings };
  }

  /**
   * Add runtime validation for executeFunction (LuaJob uses this internally).
   */
  protected getRuntimeValidation(): string {
    return `
  if (typeof primitive.primitive?.execute !== 'function') {
    throw new Error('[Lua] Invalid job artifact: execute is not a function');
  }`;
  }

  toManifestEntry(compiled: CompiledPrimitive, _allPrimitives?: CompiledPrimitive[]): ManifestPrimitive {
    const jobMeta = compiled.metadata as JobMetadataFields;
    return {
      ...this.baseManifestFields(compiled),
      schedule: jobMeta.scheduleType
        ? {
            type: jobMeta.scheduleType,
            expression: jobMeta.scheduleExpression,
            seconds: jobMeta.scheduleSeconds,
            executeAt: jobMeta.scheduleExecuteAt,
            timezone: jobMeta.scheduleTimezone,
          }
        : undefined,
      timeout: jobMeta.timeoutValue,
      retry: jobMeta.retryConfig,
    } as ManifestJob;
  }
}
