import { HttpClient } from './http.client.js';
import { ApiResponse } from '../interfaces/common.js';
import {
  UnifiedToIntegrationResponse,
  UnifiedToAuthUrlResponse,
  UnifiedToConnectionResponse,
  WebhookEventInfo,
  CreateWebhookSubscriptionParams,
  WebhookSubscriptionResponse,
  FinalizeConnectionResponse,
  UpdateConnectionStatusResponse,
} from '../interfaces/unifiedto.js';

/**
 * UnifiedTo API Service
 * Handles all UnifiedTo integration-related API calls
 */
export default class UnifiedToApi extends HttpClient {
  private apiKey: string;

  /**
   * Creates an instance of UnifiedToApi
   * @param baseUrl - The base URL for the API
   * @param apiKey - The API key for authentication
   */
  constructor(baseUrl: string, apiKey: string) {
    super(baseUrl);
    this.apiKey = apiKey;
  }

  /**
   * Gets available third-party integrations
   * @param agentId - When provided, excludes types already connected for this agent
   * @returns Promise resolving to an ApiResponse containing available integrations
   */
  async getAvailableIntegrations(agentId?: string): Promise<ApiResponse<UnifiedToIntegrationResponse[]>> {
    const query = agentId ? `?agentId=${encodeURIComponent(agentId)}` : '';
    return this.httpGet<UnifiedToIntegrationResponse[]>(`/developer/unifiedto/integrations${query}`, {
      Authorization: `Bearer ${this.apiKey}`,
    });
  }

  /**
   * Gets an OAuth authorization URL for a specific integration
   * @param integrationType - The integration type (e.g., "googlecalendar", "linear")
   * @param options - Authorization options
   * @returns Promise resolving to an ApiResponse containing the auth URL
   */
  async getAuthUrl(
    integrationType: string,
    options: {
      successRedirect: string;
      failureRedirect: string;
      scopes?: string[];
      state?: string;
      externalXref?: string;
    }
  ): Promise<ApiResponse<UnifiedToAuthUrlResponse>> {
    const params = new URLSearchParams();
    params.append('integrationType', integrationType);
    params.append('successRedirect', options.successRedirect);
    params.append('failureRedirect', options.failureRedirect);
    if (options.scopes && options.scopes.length > 0) {
      params.append('scopes', options.scopes.join(','));
    }
    if (options.state) {
      params.append('state', options.state);
    }
    if (options.externalXref) {
      params.append('externalXref', options.externalXref);
    }

    return this.httpGet<UnifiedToAuthUrlResponse>(`/developer/unifiedto/auth-url?${params.toString()}`, {
      Authorization: `Bearer ${this.apiKey}`,
    });
  }

  /**
   * Gets all connections for an agent
   * @param agentId - The agent ID
   * @returns Promise resolving to an ApiResponse containing connections
   */
  async getConnections(agentId: string): Promise<ApiResponse<UnifiedToConnectionResponse[]>> {
    return this.httpGet<UnifiedToConnectionResponse[]>(`/developer/unifiedto/connections/${agentId}`, {
      Authorization: `Bearer ${this.apiKey}`,
    });
  }

  /**
   * Deletes a connection
   * @param connectionId - The connection ID
   * @param agentId - The agent ID
   * @returns Promise resolving to an ApiResponse with success status
   */
  async deleteConnection(
    connectionId: string,
    agentId: string
  ): Promise<ApiResponse<{ success: boolean; message: string; deletedWebhooksCount: number }>> {
    return this.httpDelete<{ success: boolean; message: string; deletedWebhooksCount: number }>(
      `/developer/unifiedto/connections/${agentId}/${connectionId}`,
      { Authorization: `Bearer ${this.apiKey}` }
    );
  }

  // ==================== Connection Finalization ====================

  /**
   * Finalize a connection atomically (server-side MCP + webhooks)
   */
  async finalizeConnection(
    agentId: string,
    params: {
      connectionId: string;
      integrationType: string;
      scopes?: string[];
      hideSensitive?: boolean;
      triggers?: Array<{
        objectType: string;
        event: 'created' | 'updated' | 'deleted';
        hookUrl?: string;
        interval?: number;
      }>;
    }
  ): Promise<ApiResponse<FinalizeConnectionResponse>> {
    return this.httpPost<FinalizeConnectionResponse>(`/developer/unifiedto/connections/${agentId}/finalize`, params, {
      Authorization: `Bearer ${this.apiKey}`,
    });
  }

  /**
   * Report an OAuth failure for observability
   */
  async reportAuthFailure(params: {
    integrationType: string;
    error: string;
    logId?: string;
    agentId?: string;
    source?: string;
  }): Promise<ApiResponse<{ received: boolean }>> {
    return this.httpPost<{ received: boolean }>('/developer/unifiedto/auth-failure', params, {
      Authorization: `Bearer ${this.apiKey}`,
    });
  }

  // ==================== Webhook Subscription Methods ====================

  /**
   * Gets available webhook events for an integration type (before connection is created)
   * @param integrationType - The integration type (e.g., "linear", "googlecalendar")
   * @returns Promise resolving to available webhook events
   */
  async getAvailableWebhookEventsByType(integrationType: string): Promise<ApiResponse<WebhookEventInfo[]>> {
    return this.httpGet<WebhookEventInfo[]>(`/developer/unifiedto/integrations/${integrationType}/webhook-events`, {
      Authorization: `Bearer ${this.apiKey}`,
    });
  }

  /**
   * Gets available webhook events for a connection
   * @param agentId - The agent ID
   * @param connectionId - The connection ID
   * @returns Promise resolving to available webhook events
   */
  async getAvailableWebhookEvents(agentId: string, connectionId: string): Promise<ApiResponse<WebhookEventInfo[]>> {
    return this.httpGet<WebhookEventInfo[]>(`/developer/unifiedto/webhooks/${agentId}/available/${connectionId}`, {
      Authorization: `Bearer ${this.apiKey}`,
    });
  }

  /**
   * Gets all webhook subscriptions for an agent
   * @param agentId - The agent ID
   * @returns Promise resolving to webhook subscriptions
   */
  async getWebhookSubscriptions(agentId: string): Promise<ApiResponse<WebhookSubscriptionResponse[]>> {
    return this.httpGet<WebhookSubscriptionResponse[]>(`/developer/unifiedto/webhooks/${agentId}`, {
      Authorization: `Bearer ${this.apiKey}`,
    });
  }

  /**
   * Creates a webhook subscription
   * @param agentId - The agent ID
   * @param params - Webhook subscription parameters
   * @returns Promise resolving to the created webhook subscription
   */
  async createWebhookSubscription(
    agentId: string,
    params: CreateWebhookSubscriptionParams
  ): Promise<ApiResponse<WebhookSubscriptionResponse>> {
    return this.httpPost<WebhookSubscriptionResponse>(`/developer/unifiedto/webhooks/${agentId}`, params, {
      Authorization: `Bearer ${this.apiKey}`,
    });
  }

  /**
   * Deletes a webhook subscription
   * @param agentId - The agent ID
   * @param webhookId - The webhook subscription ID
   * @returns Promise resolving to success status
   */
  async deleteWebhookSubscription(
    agentId: string,
    webhookId: string
  ): Promise<ApiResponse<{ success: boolean; message: string }>> {
    return this.httpDelete<{ success: boolean; message: string }>(
      `/developer/unifiedto/webhooks/${agentId}/${webhookId}`,
      { Authorization: `Bearer ${this.apiKey}` }
    );
  }

  // ==================== User Pause / Resume ====================

  /**
   * User-initiated pause of a webhook subscription
   */
  async pauseWebhookSubscription(
    agentId: string,
    webhookId: string,
    reason?: string
  ): Promise<ApiResponse<WebhookSubscriptionResponse>> {
    return this.httpPatch<WebhookSubscriptionResponse>(
      `/developer/unifiedto/webhooks/${agentId}/${webhookId}`,
      { status: 'paused', ...(reason ? { reason } : {}) },
      { Authorization: `Bearer ${this.apiKey}` }
    );
  }

  /**
   * User-initiated resume of a webhook subscription
   * Returns error with code CREDIT_SUSPENDED if the webhook is credit-suspended
   */
  async resumeWebhookSubscription(
    agentId: string,
    webhookId: string
  ): Promise<ApiResponse<WebhookSubscriptionResponse>> {
    return this.httpPatch<WebhookSubscriptionResponse>(
      `/developer/unifiedto/webhooks/${agentId}/${webhookId}`,
      { status: 'active' },
      { Authorization: `Bearer ${this.apiKey}` }
    );
  }

  /**
   * Pause all non-credit-suspended triggers for a connection
   */
  async pauseConnection(agentId: string, connectionId: string): Promise<ApiResponse<UpdateConnectionStatusResponse>> {
    return this.httpPatch<UpdateConnectionStatusResponse>(
      `/developer/unifiedto/connections/${agentId}/${connectionId}`,
      { status: 'paused' },
      { Authorization: `Bearer ${this.apiKey}` }
    );
  }

  /**
   * Resume all triggers for a connection (skips credit-suspended ones)
   */
  async resumeConnection(agentId: string, connectionId: string): Promise<ApiResponse<UpdateConnectionStatusResponse>> {
    return this.httpPatch<UpdateConnectionStatusResponse>(
      `/developer/unifiedto/connections/${agentId}/${connectionId}`,
      { status: 'active' },
      { Authorization: `Bearer ${this.apiKey}` }
    );
  }
}
