/**
 * Pure helpers for `lua test` output formatting.
 *
 * Extracted into their own module (no side effects, no transitive deps on
 * `cli.ts`) so unit tests can import them without dragging in `import.meta`
 * and other ESM-only utilities.
 */

import { inspect } from 'util';

/**
 * Builds a human-readable shape header for a tool output value.
 * Examples:
 *   "Array[3] of DataEntryInstance — fields: id, title, score"
 *   "Object (DataEntryInstance) — fields: id, data, collectionName, score"
 *   "Object — fields: status, message"
 */
export function buildShapeHeader(result: any): string {
  if (result === null) return 'null';
  if (result === undefined) return 'undefined';

  const typeName = result?.constructor?.name ?? typeof result;

  if (Array.isArray(result)) {
    const first = result.length > 0 ? result[0] : null;
    const itemType =
      first != null ? (first?.constructor?.name ?? typeof first) : result.length > 0 ? 'null' : 'unknown';
    const sampleKeys =
      first != null && typeof first === 'object'
        ? Object.keys(first)
            .filter((k) => !k.startsWith('_'))
            .slice(0, 6)
            .join(', ')
        : '';
    const fieldsPart = sampleKeys ? ` — fields: ${sampleKeys}` : '';
    return `Array[${result.length}] of ${itemType}${fieldsPart}`;
  }

  if (typeof result === 'object') {
    const keys = Object.keys(result)
      .filter((k) => !k.startsWith('_'))
      .slice(0, 8)
      .join(', ');
    const namePart = typeName !== 'Object' ? ` (${typeName})` : '';
    return `Object${namePart} — fields: ${keys}`;
  }

  return `${typeName}: ${String(result)}`;
}

/**
 * Prints tool/primitive output with a shape header + util.inspect body.
 * Pass `asJson: true` (from --json flag) to emit raw JSON to stdout instead
 * (so `lua test --json | jq` works).
 *
 * The `label` is shown in the shape line (e.g. "Tool returned: Array[3]...").
 */
export function printToolOutput(label: string, result: any, asJson: boolean): void {
  if (asJson) {
    // Final canonical output — only this goes to stdout in --json mode.
    console.log(JSON.stringify(result, null, 2));
    return;
  }

  const header = buildShapeHeader(result);
  console.log(`\n${label} returned: ${header}`);
  console.log('Output:');
  console.log(inspect(result, { depth: 4, colors: true, getters: true, breakLength: 120 }));
}
