/**
 * Governance Command
 * Interactive wizard that creates a governance config file and tells the user
 * to import it into their LuaAgent — same pattern as skills, webhooks, etc.
 */

import { writeFileSync, existsSync, unlinkSync } from 'fs';
import { resolve, join } from 'path';
import { withErrorHandling, writeSuccess, writeInfo } from '../utils/cli.js';
import { initializeCommand } from '../utils/command-utils.js';
import { trackEvent } from '../services/analytics.js';
import { safePrompt } from '../utils/prompt-handler.js';
import { agentHandler } from '../primitives/agent.handler.js';
import { loadManifest, hasCompilationOutput, getPrimitivesByKind } from '../utils/artifact-loader.js';
import { PrimitiveKind, type ManifestTool } from '../compiler/types.js';
import { validateOrSuggest } from '../utils/aliases.js';

type GovernanceMode = 'sdk' | 'api';

interface GovernanceSetup {
  mode: GovernanceMode;
  blockTools?: string[];
  requireApproval?: string[];
  tokenLimit?: number;
  serverUrl?: string;
}

function getProjectToolNames(): string[] {
  if (!hasCompilationOutput(process.cwd())) return [];
  try {
    const manifest = loadManifest();
    return getPrimitivesByKind<ManifestTool>(manifest, PrimitiveKind.TOOL)
      .map((t) => t.name)
      .filter((n): n is string => typeof n === 'string' && n.length > 0)
      .sort();
  } catch {
    return [];
  }
}

function generateFile(setup: GovernanceSetup): string {
  if (setup.mode === 'api') {
    return `/**
 * Governance Policy (API mode)
 * Enforcement is handled remotely via the Governance Cloud.
 * Import this into your LuaAgent config.
 *
 * The API key is resolved on the platform at runtime from the
 * GOVERNANCE_API_KEY env var. Never put the raw key in source.
 */

export const governance = {
  mode: 'api' as const,
  serverUrl: process.env.GOVERNANCE_API_URL ?? '${setup.serverUrl}',
};
`;
  }

  const ruleLines: string[] = [];
  if (setup.blockTools && setup.blockTools.length > 0) {
    const list = setup.blockTools.map((t) => `'${t}'`).join(', ');
    ruleLines.push(`    blockTools: [${list}],`);
  }
  if (setup.requireApproval && setup.requireApproval.length > 0) {
    const list = setup.requireApproval.map((t) => `'${t}'`).join(', ');
    ruleLines.push(`    requireApproval: [${list}],`);
  }
  if (setup.tokenLimit && setup.tokenLimit > 0) {
    ruleLines.push(`    tokenBudget: ${setup.tokenLimit},`);
  }

  return `/**
 * Governance Policy (SDK mode)
 * Policies are enforced locally at the platform level.
 * Import this into your LuaAgent config.
 */

export const governance = {
  mode: 'sdk' as const,
  rules: {
${ruleLines.join('\n')}
  },
};
`;
}

export async function governanceCommand(action?: string): Promise<void> {
  return withErrorHandling(async () => {
    if (action) {
      action = validateOrSuggest('governance.action', action);
    }
    if (action === 'remove') {
      await governanceRemove();
      return;
    }

    // Determine where to write the file
    const srcDir = resolve(process.cwd(), 'src');
    const targetDir = existsSync(srcDir) ? srcDir : process.cwd();
    const filePath = join(targetDir, 'governance.ts');

    if (existsSync(filePath)) {
      const { overwrite } = await safePrompt([
        {
          type: 'confirm',
          name: 'overwrite',
          message: 'governance.ts already exists. Overwrite?',
          default: false,
        },
      ]);
      if (!overwrite) {
        console.log('Aborted.');
        trackEvent('cli_governance_action', { action: 'add', result: 'aborted_existing' });
        return;
      }
    }

    // Choose mode
    const { mode } = await safePrompt([
      {
        type: 'list',
        name: 'mode',
        message: 'How would you like to configure governance?',
        choices: [
          { name: 'SDK (local, in-memory policies — no server required)', value: 'sdk' },
          { name: 'API (remote enforcement via Governance Cloud)', value: 'api' },
        ],
      },
    ]);

    let setup: GovernanceSetup;

    if (mode === 'api') {
      const answers = await safePrompt([
        {
          type: 'input',
          name: 'serverUrl',
          message: 'Governance API URL:',
          default: 'https://api.heygovernance.ai',
        },
      ]);
      setup = { mode: 'api', serverUrl: answers.serverUrl };
    } else {
      const toolNames = getProjectToolNames();

      if (toolNames.length === 0) {
        writeInfo(
          'No compiled tools found (run `lua compile` first). Emitting an empty rules block — re-run `lua governance add` after compilation to pick specific tools.'
        );
        setup = {
          mode: 'sdk',
          blockTools: [],
          requireApproval: [],
          tokenLimit: 0,
        };
      } else {
        // NOTE: `tokenBudget` is intentionally NOT offered here. The SDK
        // reads it from a host-supplied `sessionTokensUsed` field that the
        // lua-core integration does not yet populate, so the rule would
        // silently never fire. Power users who want it can still add it by
        // hand to governance.ts; we'll re-enable the prompt once the
        // per-session token counter is wired in.
        const answers = await safePrompt([
          {
            type: 'checkbox',
            name: 'blockTools',
            message: 'Tools to BLOCK (space to toggle, enter to confirm):',
            choices: toolNames.map((name) => ({ name, value: name })),
            default: [],
          },
          {
            type: 'checkbox',
            name: 'requireApproval',
            message: 'Tools that REQUIRE APPROVAL before running:',
            choices: toolNames.map((name) => ({ name, value: name })),
            default: [],
          },
        ]);
        setup = {
          mode: 'sdk',
          blockTools: Array.isArray(answers.blockTools) ? answers.blockTools : [],
          requireApproval: Array.isArray(answers.requireApproval) ? answers.requireApproval : [],
          tokenLimit: 0,
        };
      }
    }

    // Write the governance file
    const content = generateFile(setup);
    writeFileSync(filePath, content, 'utf-8');

    const relativePath = filePath.replace(process.cwd() + '/', '');
    writeSuccess(`Created ${relativePath}`);
    console.log('');

    if (setup.mode === 'api') {
      writeInfo('Set GOVERNANCE_API_KEY on the platform (lua env) — never commit it:');
      console.log('');
      console.log('  lua env set GOVERNANCE_API_KEY <your-key>');
      console.log('');
    }

    writeInfo('Import it in your LuaAgent:');
    console.log('');
    const importPath = './' + relativePath.replace(/\.ts$/, '').replace(/^src\//, '');
    console.log(`  import { governance } from '${importPath}';`);
    console.log('');
    console.log('  export const agent = new LuaAgent({');
    console.log('    name: "my-agent",');
    console.log('    persona: "...",');
    console.log('    governance,');
    console.log('    skills: [...],');
    console.log('  });');
    console.log('');
    writeInfo('Then compile and push as usual:');
    console.log('');
    console.log('  lua compile && lua push');
    console.log('');

    trackEvent('cli_governance_action', {
      action: 'add',
      mode: setup.mode,
      block_tools_count: setup.blockTools?.length ?? 0,
      require_approval_count: setup.requireApproval?.length ?? 0,
      token_limit: setup.tokenLimit,
    });
  }, 'governance');
}

/**
 * Remove governance from the user's project and clear it from the server.
 * Deletes the local governance.ts and sends `governance: null` to the API
 * so the SubAgent document has the field cleared explicitly.
 */
async function governanceRemove(): Promise<void> {
  const srcDir = resolve(process.cwd(), 'src');
  const targetDir = existsSync(srcDir) ? srcDir : process.cwd();
  const filePath = join(targetDir, 'governance.ts');
  const hasLocal = existsSync(filePath);

  const { confirm } = await safePrompt([
    {
      type: 'confirm',
      name: 'confirm',
      message: hasLocal
        ? 'This will delete governance.ts AND clear governance on the server. Continue?'
        : 'No local governance.ts found — this will still clear governance on the server. Continue?',
      default: false,
    },
  ]);
  if (!confirm) {
    console.log('Aborted.');
    trackEvent('cli_governance_action', { action: 'remove', result: 'aborted' });
    return;
  }

  if (hasLocal) {
    unlinkSync(filePath);
    writeSuccess(`Deleted ${filePath.replace(process.cwd() + '/', '')}`);
  }

  const { agentId, apiKey } = await initializeCommand({ showProgress: false });
  const ok = await agentHandler.pushGovernance({ apiKey, agentId }, null);
  if (ok) {
    writeSuccess('✅ Governance cleared on server');
  } else {
    console.error('❌ Failed to clear governance on server');
  }

  writeInfo('Remember to remove the governance import from your LuaAgent:');
  console.log('');
  console.log('  // Remove this import:');
  console.log("  import { governance } from './governance';");
  console.log('');
  console.log('  // And remove the `governance` property from your LuaAgent config.');
  console.log('');
  writeInfo('Then recompile and push:');
  console.log('');
  console.log('  lua compile && lua push');
  console.log('');

  trackEvent('cli_governance_action', {
    action: 'remove',
    local_deleted: hasLocal,
    server_cleared: ok,
  });
}
