/**
 * Authentication Flow Utilities
 * Handles different authentication methods (API key and email OTP)
 */

import inquirer from 'inquirer';
import { saveApiKey, checkApiKey, requestEmailOTP, verifyOTPAndGetToken, generateApiKey } from '../services/auth.js';
import { clearIdentityCache } from '../services/analytics.js';
import { clearPromptLines, writeError, writeProgress, writeSuccess, writeInfo } from './cli.js';

/**
 * Configuration for OTP verification
 */
const OTP_CONFIG = {
  MAX_ATTEMPTS: 3,
  OTP_LENGTH: 6,
} as const;

// ============================================================================
// SHARED HELPERS
// ============================================================================

/**
 * Clears stale identity cache and saves the API key to ~/.lua-cli/credentials.
 */
function persistApiKey(apiKey: string): void {
  clearIdentityCache();
  saveApiKey(apiKey);
}

/**
 * Fetches user data for the given API key and displays a Welcome message
 * followed by onboarding next steps. Best-effort — failures are silenced.
 */
async function showPostAuthWelcome(apiKey: string): Promise<void> {
  try {
    const userData = await checkApiKey(apiKey);
    writeInfo(`   Welcome, ${userData.fullName || userData.email}!`);
  } catch {
    // Non-fatal — key is saved, identity display is best-effort
  }

  writeInfo("\n🎉 You're all set! Here's what to do next:\n");
  writeInfo('   1️⃣  Create a new project directory:');
  writeInfo('      mkdir my-agent && cd my-agent\n');
  writeInfo('   2️⃣  Initialize your agent:');
  writeInfo('      lua init\n');
  writeInfo('   3️⃣  Follow the prompts to create or select an agent\n');
  writeInfo("💡 Tip: Run 'lua --help' to see all available commands\n");
}

// ============================================================================
// INTERACTIVE AUTHENTICATION FLOWS
// ============================================================================

/**
 * Handles API key authentication flow (interactive).
 * Prompts for API key, validates it, and saves it securely.
 *
 * @returns Promise that resolves when authentication is complete
 * @throws Error if API key is invalid or save fails
 */
export async function handleApiKeyAuth(): Promise<void> {
  const answers = await inquirer.prompt([
    {
      type: 'password',
      name: 'apiKey',
      message: 'Enter your API key',
      mask: '*',
    },
  ]);

  const data = await checkApiKey(answers.apiKey);
  if (!data) {
    throw new Error('Invalid API key');
  }

  persistApiKey(answers.apiKey);
  writeSuccess('✅ API key saved securely.');
  writeInfo(`   Welcome, ${data.fullName || data.email}!`);
}

// ============================================================================
// NON-INTERACTIVE AUTHENTICATION FLOWS
// ============================================================================

/**
 * Handles API key authentication (non-interactive).
 * Validates the provided API key and saves it securely.
 *
 * @param apiKey - The API key to validate and save
 * @returns Promise that resolves when authentication is complete
 * @throws Error if API key is invalid or save fails
 */
export async function handleApiKeyAuthNonInteractive(apiKey: string): Promise<void> {
  writeProgress('🔐 Validating API key...');

  const data = await checkApiKey(apiKey);
  if (!data) {
    throw new Error('Invalid API key. Please check your key and try again.');
  }

  persistApiKey(apiKey);
  writeSuccess('✅ API key validated and saved securely.');
  writeInfo(`   Welcome, ${data.fullName || data.email}!`);
}

/**
 * Handles email OTP request (non-interactive step 1).
 * Sends OTP to the provided email address.
 *
 * @param email - Email address to send OTP to
 * @returns Promise that resolves when OTP is sent
 * @throws Error if email is invalid or OTP sending fails
 */
export async function handleEmailOtpRequest(email: string): Promise<void> {
  // Validate email format
  const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  if (!emailRegex.test(email)) {
    throw new Error('Invalid email address format.');
  }

  writeProgress(`📧 Sending OTP to ${email}...`);

  const otpSent = await requestEmailOTP(email);
  if (!otpSent) {
    throw new Error('Failed to send OTP. Please check your email address and try again.');
  }

  writeSuccess('✅ OTP sent successfully!');
  writeInfo('\n📬 Check your email for the 6-digit code, then run:');
  writeInfo(`   lua auth configure --email ${email} --otp <code>\n`);
}

/**
 * Handles email OTP verification (non-interactive step 2).
 * Verifies the OTP, generates an API key, and saves it.
 *
 * @param email - Email address the OTP was sent to
 * @param otp - The OTP code received via email
 * @returns Promise that resolves when authentication is complete
 * @throws Error if OTP is invalid, API key generation fails, or save fails
 */
export async function handleEmailOtpVerify(email: string, otp: string): Promise<void> {
  if (otp.length !== OTP_CONFIG.OTP_LENGTH) {
    throw new Error(`OTP must be ${OTP_CONFIG.OTP_LENGTH} digits.`);
  }

  writeProgress('🔐 Verifying OTP...');

  const signInToken = await verifyOTPAndGetToken(email, otp);
  if (!signInToken) {
    throw new Error('Invalid OTP. Please check the code and try again.');
  }

  writeSuccess('✅ OTP verified successfully!');

  writeProgress('🔑 Generating API key...');
  const apiKey = await generateApiKey(signInToken);
  if (!apiKey) {
    throw new Error('Failed to generate API key. Please try again.');
  }

  persistApiKey(apiKey);
  writeSuccess('✅ API key generated and saved securely.');
  await showPostAuthWelcome(apiKey);
}

/**
 * Handles email authentication flow with OTP verification.
 * Sends OTP to email, verifies it, generates API key, and saves it.
 *
 * @returns Promise that resolves when authentication is complete
 * @throws Error if verification fails, API key generation fails, or save fails
 */
export async function handleEmailAuth(): Promise<void> {
  // Step 1: Collect email
  const { email } = await inquirer.prompt([
    {
      type: 'input',
      name: 'email',
      message: 'Enter your email address:',
      validate: (input: string) => {
        const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
        return emailRegex.test(input) || 'Please enter a valid email address';
      },
    },
  ]);

  clearPromptLines(2);

  // Step 2: Send OTP (await to avoid dangling promise, but don't gate on result —
  // the server may queue the OTP even when the response indicates failure.
  // Real validation happens at the verify step.)
  writeProgress('📧 Sending OTP to your email...');
  await requestEmailOTP(email);

  // Step 3: Verify OTP with retry logic
  const signInToken = await verifyOTPWithRetry(email);

  // Step 4: Generate API key
  writeProgress('🔑 Generating API key...');
  const apiKey = await generateApiKey(signInToken);
  if (!apiKey) {
    throw new Error('Failed to generate API key. Please try again.');
  }

  // Step 5: Save API key
  persistApiKey(apiKey);
  writeSuccess('✅ API key generated and saved securely.');
  await showPostAuthWelcome(apiKey);
}

/**
 * Verifies OTP with retry logic.
 * Allows multiple attempts to enter the correct OTP.
 *
 * @param email - Email address for OTP verification
 * @returns Sign-in token from successful verification
 * @throws Error if maximum attempts are exceeded
 */
async function verifyOTPWithRetry(email: string): Promise<string> {
  let attempts = 0;
  let signInToken: string | null = null;

  while (!signInToken && attempts < OTP_CONFIG.MAX_ATTEMPTS) {
    const { pin } = await inquirer.prompt([
      {
        type: 'input',
        name: 'pin',
        message: 'Enter the OTP sent to your email:',
        validate: (input: string) => {
          return input.length === OTP_CONFIG.OTP_LENGTH || `OTP must be ${OTP_CONFIG.OTP_LENGTH} digits`;
        },
      },
    ]);

    clearPromptLines(2);

    writeProgress('🔐 Verifying OTP...');
    signInToken = await verifyOTPAndGetToken(email, pin);

    if (signInToken) {
      writeProgress('✅ OTP verified successfully!');
    } else {
      attempts++;
      if (attempts < OTP_CONFIG.MAX_ATTEMPTS) {
        console.log(`❌ Invalid OTP. ${OTP_CONFIG.MAX_ATTEMPTS - attempts} attempts remaining.`);
      } else {
        throw new Error('Invalid OTP. Maximum attempts reached. Please try again later.');
      }
    }
  }

  if (!signInToken) {
    throw new Error('OTP verification failed');
  }

  return signInToken;
}

/**
 * Prompts user to choose authentication method.
 *
 * @returns Selected authentication method ('api-key' or 'email')
 */
export async function promptAuthMethod(): Promise<'api-key' | 'email'> {
  const { authMethod } = await inquirer.prompt([
    {
      type: 'list',
      name: 'authMethod',
      message: 'Choose authentication method:',
      choices: [
        { name: 'API Key', value: 'api-key' },
        { name: 'Email', value: 'email' },
      ],
    },
  ]);

  return authMethod;
}
