/**
 * Terminal audio bridge for `lua voice --terminal`. Connects to the
 * LiveKit room as a participant, captures mic audio via `sox`, plays
 * back the agent's audio through `sox`, and pipes 16-bit PCM frames
 * back and forth through @livekit/rtc-node.
 *
 * Why sox: a single, widely-installed binary handles both mic capture
 * and speaker playout cross-platform without pulling native node-gyp
 * deps into lua-cli's distribution. Devs install via brew/apt; the
 * command surfaces an actionable error if it's missing.
 */

import { spawn, spawnSync, type ChildProcess } from 'child_process';
import { platform } from 'os';
import { Readable } from 'stream';
import {
  AudioFrame,
  AudioSource,
  AudioStream,
  LocalAudioTrack,
  RemoteAudioTrack,
  Room,
  RoomEvent,
  TrackKind,
  TrackPublishOptions,
  TrackSource,
} from '@livekit/rtc-node';
import { safePrompt } from '../utils/prompt-handler.js';
import { parseJoinUrl } from './voice-shared.js';

const SAMPLE_RATE = 48000;
const CHANNELS = 1;
const FRAME_MS = 20;
const FRAME_SAMPLES = (SAMPLE_RATE * FRAME_MS) / 1000; // 960 samples / 1920 bytes

export async function runTerminalMode(joinUrl: string): Promise<void> {
  if (!hasSox()) {
    const installed = await offerSoxInstall();
    if (!installed) {
      throw new Error('sox is required for --terminal mode. Install it and re-run.');
    }
  }

  const { wsUrl, token } = parseJoinUrl(joinUrl);

  const room = new Room();
  const source = new AudioSource(SAMPLE_RATE, CHANNELS);
  const localTrack = LocalAudioTrack.createAudioTrack('lua-voice-mic', source);

  // Spawn capture (mic → stdout) and playback (stdin → speaker) procs.
  // Both use raw signed 16-bit little-endian PCM at 48 kHz mono so the
  // byte layout exactly matches LiveKit's AudioFrame.data (Int16Array).
  const capture = spawnCapture();
  const playback = spawnPlayback();

  let stopping = false;
  const cleanup = async (): Promise<void> => {
    if (stopping) return;
    stopping = true;
    try {
      capture.kill('SIGTERM');
    } catch {
      /* ignore */
    }
    try {
      playback.stdin?.end();
    } catch {
      /* ignore */
    }
    try {
      await room.disconnect();
    } catch {
      /* ignore */
    }
  };

  const sigHandler = (): void => {
    // Cap cleanup at 2s so a hung disconnect doesn't strand the user's
    // terminal. Sox children get SIGTERM regardless via cleanup(); LK
    // reaps the room itself on its empty-timeout if disconnect lags.
    const force = setTimeout(() => process.exit(0), 2000);
    force.unref();
    void cleanup().then(() => process.exit(0));
  };
  process.once('SIGINT', sigHandler);
  process.once('SIGTERM', sigHandler);

  // Wire remote audio → speaker. LiveKit emits `trackSubscribed` for
  // every published remote track; we only feed the speaker for audio
  // tracks (the agent never publishes video).
  room.on(RoomEvent.TrackSubscribed, (track) => {
    if (track.kind !== TrackKind.KIND_AUDIO) return;
    void pumpRemoteAudioToSpeaker(track as RemoteAudioTrack, playback);
  });

  console.log(`   Connecting to ${wsUrl}…`);
  await room.connect(wsUrl, token);
  console.log('   ✅ Connected. Speak into your mic; press Ctrl+C to hang up.');

  await room.localParticipant!.publishTrack(
    localTrack,
    new TrackPublishOptions({ source: TrackSource.SOURCE_MICROPHONE })
  );

  // Pump mic stdin chunks → AudioFrames → AudioSource. Sox writes PCM
  // continuously; we re-frame to 20 ms blocks because `captureFrame`
  // expects a fixed-size frame and LiveKit prefers stable cadence.
  await pumpMicToSource(capture, source);
  await cleanup();
}

function hasSox(): boolean {
  const r = spawnSync('sox', ['--version'], { stdio: 'ignore' });
  return r.status === 0;
}

interface SoxInstallPlan {
  /** Human label for the prompt: "Homebrew", "apt", "winget", etc. */
  manager: string;
  /** Argv form actually invoked. First element is the binary on PATH. */
  argv: string[];
  /** Note shown alongside the prompt (e.g. "may prompt for sudo password"). */
  note?: string;
}

function detectSoxInstaller(): SoxInstallPlan | null {
  const os = platform();
  const has = (bin: string): boolean => spawnSync(bin, ['--version'], { stdio: 'ignore' }).status === 0;

  if (os === 'darwin') {
    if (has('brew')) return { manager: 'Homebrew', argv: ['brew', 'install', 'sox'] };
    return null;
  }

  if (os === 'linux') {
    // Order: prefer the manager whose binary is in PATH. Each may need sudo
    // — we let it fall through to the user's terminal so a TTY password
    // prompt works naturally instead of trying to capture it ourselves.
    if (has('apt-get'))
      return {
        manager: 'apt',
        argv: ['sudo', 'apt-get', 'install', '-y', 'sox'],
        note: 'may prompt for sudo password',
      };
    if (has('apt'))
      return { manager: 'apt', argv: ['sudo', 'apt', 'install', '-y', 'sox'], note: 'may prompt for sudo password' };
    if (has('dnf'))
      return { manager: 'dnf', argv: ['sudo', 'dnf', 'install', '-y', 'sox'], note: 'may prompt for sudo password' };
    if (has('yum'))
      return { manager: 'yum', argv: ['sudo', 'yum', 'install', '-y', 'sox'], note: 'may prompt for sudo password' };
    if (has('pacman'))
      return {
        manager: 'pacman',
        argv: ['sudo', 'pacman', '-S', '--noconfirm', 'sox'],
        note: 'may prompt for sudo password',
      };
    if (has('apk'))
      return { manager: 'apk', argv: ['sudo', 'apk', 'add', 'sox'], note: 'may prompt for sudo password' };
    return null;
  }

  if (os === 'win32') {
    if (has('winget'))
      return { manager: 'winget', argv: ['winget', 'install', '--id', 'ChrisBagwell.SoX', '-e', '--silent'] };
    if (has('choco')) return { manager: 'Chocolatey', argv: ['choco', 'install', 'sox.portable', '-y'] };
    if (has('scoop')) return { manager: 'Scoop', argv: ['scoop', 'install', 'sox'] };
    return null;
  }

  return null;
}

async function offerSoxInstall(): Promise<boolean> {
  console.error('❌ sox is required for --terminal mode but was not found in PATH.');
  const plan = detectSoxInstaller();
  if (!plan) {
    console.error('   Could not detect a supported package manager on this platform.');
    console.error('   macOS: brew install sox  |  Debian/Ubuntu: apt install sox');
    console.error('   Fedora: dnf install sox  |  Arch: pacman -S sox');
    console.error('   Windows: winget install sox  |  WSL2 (recommended) → use Linux path');
    return false;
  }

  const cmdLabel = plan.argv.join(' ');
  const answer = await safePrompt<{ go: boolean }>([
    {
      type: 'confirm',
      name: 'go',
      message: `Install sox via ${plan.manager}? Will run: \`${cmdLabel}\`${plan.note ? ` (${plan.note})` : ''}`,
      default: true,
    },
  ]);
  if (!answer?.go) {
    console.error(`   Run \`${cmdLabel}\` yourself, then re-run lua voice --terminal.`);
    return false;
  }

  console.log(`   → ${cmdLabel}`);
  const r = spawnSync(plan.argv[0], plan.argv.slice(1), { stdio: 'inherit' });
  if (r.status !== 0) {
    console.error('   Install failed. Re-run the command manually if needed.');
    return false;
  }
  if (!hasSox()) {
    console.error('   Installer succeeded but sox is still not on PATH. Open a new shell and try again.');
    return false;
  }
  console.log('   ✅ sox installed.');
  return true;
}

function spawnCapture(): ChildProcess {
  // -d = default input device, -t raw with explicit format flags so the
  // pipe is signed 16-bit little-endian PCM at 48 kHz mono — the exact
  // shape LiveKit's AudioFrame expects.
  const args = [
    '-q',
    '-d',
    '-t',
    'raw',
    '-r',
    String(SAMPLE_RATE),
    '-c',
    String(CHANNELS),
    '-b',
    '16',
    '-e',
    'signed-integer',
    '-L',
    '--buffer',
    String(FRAME_SAMPLES * 2),
    '-',
  ];
  const proc = spawn('sox', args, { stdio: ['ignore', 'pipe', 'pipe'] });
  proc.stderr?.on('data', (b) => {
    const msg = b.toString();
    if (/FAIL|error/i.test(msg)) process.stderr.write(`[sox-mic] ${msg}`);
  });
  return proc;
}

function spawnPlayback(): ChildProcess {
  const args = [
    '-q',
    '-t',
    'raw',
    '-r',
    String(SAMPLE_RATE),
    '-c',
    String(CHANNELS),
    '-b',
    '16',
    '-e',
    'signed-integer',
    '-L',
    '-',
    '-d',
  ];
  const proc = spawn('sox', args, { stdio: ['pipe', 'ignore', 'pipe'] });
  proc.stderr?.on('data', (b) => {
    const msg = b.toString();
    if (/FAIL|error/i.test(msg)) process.stderr.write(`[sox-out] ${msg}`);
  });
  return proc;
}

async function pumpMicToSource(capture: ChildProcess, source: AudioSource): Promise<void> {
  const stream = capture.stdout as Readable | null;
  if (!stream) return;
  const frameBytes = FRAME_SAMPLES * 2;
  let buf = Buffer.alloc(0);
  for await (const chunk of stream as AsyncIterable<Buffer>) {
    buf = buf.length === 0 ? Buffer.from(chunk) : Buffer.concat([buf, chunk]);
    while (buf.length >= frameBytes) {
      const slice = buf.subarray(0, frameBytes);
      buf = buf.subarray(frameBytes);
      // Copy into a typed Int16Array view so the AudioFrame owns its data.
      const data = new Int16Array(FRAME_SAMPLES);
      for (let i = 0; i < FRAME_SAMPLES; i++) {
        data[i] = slice.readInt16LE(i * 2);
      }
      const frame = new AudioFrame(data, SAMPLE_RATE, CHANNELS, FRAME_SAMPLES);
      try {
        await source.captureFrame(frame);
      } catch {
        return;
      }
    }
  }
}

async function pumpRemoteAudioToSpeaker(track: RemoteAudioTrack, playback: ChildProcess): Promise<void> {
  if (!playback.stdin) return;
  const sink = playback.stdin;
  const stream = new AudioStream(track, SAMPLE_RATE, CHANNELS);
  const reader = stream.getReader();
  while (true) {
    const { value, done } = await reader.read();
    if (done) return;
    if (!value) continue;
    // AudioFrame.data is Int16Array; copy to a tight ArrayBuffer-backed
    // buffer (avoids the SharedArrayBuffer | ArrayBuffer typing split).
    const out = Buffer.allocUnsafe(value.data.byteLength);
    out.set(new Uint8Array(value.data.buffer, value.data.byteOffset, value.data.byteLength));
    if (!sink.write(out)) {
      await new Promise<void>((res) => sink.once('drain', () => res()));
    }
  }
}
