/**
 * @lua/compiler - Compiler for Lua AI agent primitives
 *
 * This package provides the compilation infrastructure for Lua agents.
 * It transforms TypeScript source code into optimized, sandboxed artifacts.
 *
 * @example
 * ```typescript
 * import { compile } from '@lua/compiler';
 *
 * const result = await compile({
 *   rootDir: process.cwd(),
 *   outDir: 'dist',
 * });
 *
 * if (result.success) {
 *   console.log(`Compiled ${result.stats.totalPrimitives} primitives`);
 * }
 * ```
 */

// Main compiler
export { Compiler, compile } from './compiler.js';

// All types from central types file
export type {
  // Compiler types
  CompilerOptions,
  CompilationResult,
  CompilationManifest,
  CompilationError,
  CompilationWarning,
  CompilationStats,
  CompiledPrimitive,
  ProjectFile,
  // Manifest primitives (discriminated union)
  ManifestPrimitive,
  ManifestTool,
  ManifestSkill,
  ManifestJob,
  ManifestWebhook,
  ManifestPreProcessor,
  ManifestPostProcessor,
  ManifestMCPServer,
  ManifestAgent,
  // Metadata types
  BaseMetadataFields,
  PrimitiveMetadata,
  ToolMetadataFields,
  SkillMetadataFields,
  JobMetadataFields,
  WebhookMetadataFields,
  PreProcessorMetadataFields,
  PostProcessorMetadataFields,
  MCPServerMetadataFields,
  AgentMetadataFields,
  ToolMetadata,
  SkillMetadata,
  JobMetadata,
  WebhookMetadata,
  PreProcessorMetadata,
  PostProcessorMetadata,
  MCPServerMetadata,
  AgentMetadata,
  // Validation types
  ValidationResult,
  ValidationMessage,
  // Schema types
  SchemaSet,
  JSONSchema,
  // Artifact types
  BundledArtifact,
} from './types.js';

