import path from 'path';
import fs from 'fs';
import { EnvCommandContext, EnvVariable } from '../commands/env';

/**
 * Parse a .env file and return environment variables as a Record.
 * This is the shared parser used by both sandbox execution and env commands.
 *
 * @param filePath - Absolute path to the .env file
 * @returns Record of key-value pairs from the .env file
 */
export function parseEnvFile(filePath: string): Record<string, string> {
  if (!fs.existsSync(filePath)) {
    return {};
  }

  try {
    const content = fs.readFileSync(filePath, 'utf8');
    if (!content.trim()) return {};

    const envVars: Record<string, string> = {};

    content
      .split('\n')
      .map((line) => line.trim())
      .filter((line) => line && !line.startsWith('#'))
      .forEach((line) => {
        const [key, ...valueParts] = line.split('=');
        if (key && valueParts.length > 0) {
          // Remove surrounding quotes if present
          const value = valueParts.join('=').replace(/^["']|["']$/g, '');
          envVars[key.trim()] = value;
        }
      });

    return envVars;
  } catch (error) {
    console.warn('Warning: Could not read .env file:', error);
    return {};
  }
}

/**
 * Load environment variables based on context
 */
export async function loadEnvironmentVariables(context: EnvCommandContext): Promise<EnvVariable[]> {
  if (context.environment === 'sandbox') {
    return loadSandboxEnvVariables();
  } else {
    return loadProductionEnvVariables(context);
  }
}

/**
 * Load sandbox environment variables from .env file.
 * Returns as EnvVariable[] for display in the env command.
 */
export function loadSandboxEnvVariables(): EnvVariable[] {
  const envFilePath = path.join(process.cwd(), '.env');
  const envMap = parseEnvFile(envFilePath);

  return Object.entries(envMap).map(([key, value]) => ({ key, value }));
}

/**
 * Load production environment variables from API
 */
async function loadProductionEnvVariables(context: EnvCommandContext): Promise<EnvVariable[]> {
  try {
    if (!context.developerApi) {
      throw new Error('Developer API not initialized');
    }

    const response = await context.developerApi.getEnvironmentVariables();

    if (!response.success) {
      throw new Error(response.error?.message || 'Failed to load environment variables');
    }

    // The API returns environment variables nested in a 'data' property
    // Response structure: { success: true, data: { data: { KEY: "value", ... }, _id: "...", ... } }
    const envData = response.data?.data || response.data;

    if (envData && typeof envData === 'object') {
      // Filter out metadata fields like _id, agentId, createdAt, updatedAt, __v
      const metadataKeys = ['_id', 'agentId', 'data', 'createdAt', 'updatedAt', '__v'];

      return Object.entries(envData)
        .filter(([key]) => !metadataKeys.includes(key))
        .map(([key, value]) => ({
          key,
          value: String(value),
        }));
    }

    return [];
  } catch (error) {
    console.error('❌ Error loading production env variables:', error);
    return [];
  }
}
