/**
 * Features Command
 * Manages agent features (RAG, webSearch, inquiry)
 */

import { withErrorHandling, writeProgress, writeSuccess, writeInfo } from '../utils/cli.js';
import { BASE_URLS } from '../config/constants.js';
import { safePrompt } from '../utils/prompt-handler.js';
import { initializeCommand } from '../utils/command-utils.js';
import AgentApi from '../api/agent.api.service.js';
import { trackEvent } from '../services/analytics.js';
import { validateOrSuggest } from '../utils/aliases.js';

interface FeaturesCommandContext {
  agentId: string;
  apiKey: string;
  agentApi: AgentApi;
}

interface AgentFeature {
  name: string;
  title: string;
  context: string;
  active: boolean;
}

interface FeaturesOptions {
  featureName?: string;
}

type FeatureAction = 'list' | 'enable' | 'disable' | 'view';

// ─────────────────────────────────────────────────────────────────────────────
// Main Command Entry
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Main features command - manages agent features.
 *
 * Supports both interactive and non-interactive modes:
 * - Interactive: prompts for action and feature selection
 * - Non-interactive: use action argument with -i flag
 */
export async function featuresCommand(action?: string, cmdObj?: any): Promise<void> {
  return withErrorHandling(async () => {
    const options: FeaturesOptions = {
      featureName: cmdObj?.featureName || null,
    };

    // Initialize command (validates config + auth)
    const { agentId, apiKey } = await initializeCommand();

    // Create API instance
    const agentApi = new AgentApi(BASE_URLS.API, apiKey);

    const context: FeaturesCommandContext = {
      agentId,
      apiKey,
      agentApi,
    };

    // Determine mode
    if (action) {
      await executeNonInteractive(context, action, options);
    } else {
      await manageFeaturesInteractive(context);
    }
    trackEvent('cli_features_action', {
      action: action || 'interactive',
      feature_name: options.featureName || null,
      non_interactive: !!action,
    });
  }, 'features');
}

// ─────────────────────────────────────────────────────────────────────────────
// Shared Core Functions
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Fetches all features from the API.
 */
async function fetchFeaturesCore(context: FeaturesCommandContext): Promise<AgentFeature[] | null> {
  try {
    const response = await context.agentApi.getAgentFeatures(context.agentId);
    if (!response.data) {
      console.error('❌ No data returned from API');
      return null;
    }
    return response.data.features;
  } catch (error) {
    console.error('❌ Error loading features:', error);
    return null;
  }
}

/**
 * Displays all features with their status.
 */
function displayFeaturesCore(features: AgentFeature[]): void {
  console.log('\n' + '='.repeat(60));
  console.log('🎯 Agent Features');
  console.log('='.repeat(60) + '\n');

  if (features.length === 0) {
    console.log('ℹ️  No features available for this agent.\n');
    return;
  }

  features.forEach((feature, index) => {
    const status = feature.active ? '✅' : '❌';
    console.log(`${index + 1}. ${status} ${feature.title}`);
    console.log(`   Name: ${feature.name}`);
    console.log(`   Status: ${feature.active ? 'Active' : 'Inactive'}`);
    console.log();
  });

  console.log('='.repeat(60));
}

/**
 * Displays detailed information about a feature.
 */
function viewFeatureCore(feature: AgentFeature): void {
  console.log('\n' + '='.repeat(60));
  console.log(`🎯 ${feature.title}`);
  console.log('='.repeat(60));
  console.log(`Name: ${feature.name}`);
  console.log(`Status: ${feature.active ? '✅ Active' : '❌ Inactive'}`);
  console.log('\nContext/Instructions:');
  console.log('─'.repeat(60));
  console.log(feature.context);
  console.log('='.repeat(60));
}

/**
 * Enables a feature.
 */
async function enableFeatureCore(context: FeaturesCommandContext, feature: AgentFeature): Promise<boolean> {
  if (feature.active) {
    console.log(`ℹ️  Feature "${feature.title}" is already enabled.`);
    return true;
  }

  writeProgress(`🔄 Enabling feature "${feature.title}"...`);

  try {
    await context.agentApi.updateAgentFeature(context.agentId, {
      featureName: feature.name,
      active: true,
    });
    writeSuccess(`✅ Feature "${feature.title}" enabled successfully`);
    return true;
  } catch (error) {
    console.error(`❌ Failed to enable feature: ${error}`);
    return false;
  }
}

/**
 * Disables a feature.
 */
async function disableFeatureCore(context: FeaturesCommandContext, feature: AgentFeature): Promise<boolean> {
  if (!feature.active) {
    console.log(`ℹ️  Feature "${feature.title}" is already disabled.`);
    return true;
  }

  writeProgress(`🔄 Disabling feature "${feature.title}"...`);

  try {
    await context.agentApi.updateAgentFeature(context.agentId, {
      featureName: feature.name,
      active: false,
    });
    writeSuccess(`✅ Feature "${feature.title}" disabled successfully`);
    return true;
  } catch (error) {
    console.error(`❌ Failed to disable feature: ${error}`);
    return false;
  }
}

/**
 * Finds a feature by name (case-insensitive).
 */
function findFeature(features: AgentFeature[], featureId: string): AgentFeature | null {
  const normalizedId = featureId.toLowerCase();
  return features.find((f) => f.name.toLowerCase() === normalizedId || f.title.toLowerCase() === normalizedId) || null;
}

/**
 * Prompts user to select a feature from a list.
 */
async function promptFeatureSelection(features: AgentFeature[], message: string): Promise<AgentFeature | null> {
  const answer = await safePrompt<{ selectedFeature: AgentFeature }>([
    {
      type: 'list',
      name: 'selectedFeature',
      message,
      choices: features.map((feature) => ({
        name: `${feature.active ? '✅' : '❌'} ${feature.title}`,
        value: feature,
      })),
    },
  ]);
  return answer?.selectedFeature || null;
}

// ─────────────────────────────────────────────────────────────────────────────
// Non-Interactive Mode
// ─────────────────────────────────────────────────────────────────────────────

async function executeNonInteractive(
  context: FeaturesCommandContext,
  action: string,
  options: FeaturesOptions
): Promise<void> {
  const normalizedAction = validateOrSuggest('features.action', action);

  writeProgress('🔄 Loading features...');
  const features = await fetchFeaturesCore(context);
  if (!features) throw new Error('Operation failed');

  // List action doesn't require feature selection
  if (normalizedAction === 'list') {
    displayFeaturesCore(features);
    return;
  }

  // All other actions require feature selection
  if (!options.featureName) {
    console.error(`❌ --feature-name is required for action "${normalizedAction}"`);
    console.log(`\nUsage: lua features ${normalizedAction} --feature-name <name>`);
    if (features.length > 0) {
      console.log('\nAvailable features:');
      features.forEach((f) => console.log(`  - ${f.name} (${f.title})`));
    }
    throw new Error('Operation failed');
  }

  const selectedFeature = findFeature(features, options.featureName);
  if (!selectedFeature) {
    console.error(`❌ Feature "${options.featureName}" not found`);
    console.log('\nAvailable features:');
    features.forEach((f) => console.log(`  - ${f.name} (${f.title})`));
    throw new Error('Feature');
  }

  switch (normalizedAction as FeatureAction) {
    case 'view':
      viewFeatureCore(selectedFeature);
      break;
    case 'enable': {
      const success = await enableFeatureCore(context, selectedFeature);
      if (!success) throw new Error('Operation failed');
      break;
    }
    case 'disable': {
      const success = await disableFeatureCore(context, selectedFeature);
      if (!success) throw new Error('Operation failed');
      break;
    }
  }
}

// ─────────────────────────────────────────────────────────────────────────────
// Interactive Mode
// ─────────────────────────────────────────────────────────────────────────────

async function manageFeaturesInteractive(context: FeaturesCommandContext): Promise<void> {
  let continueManaging = true;

  while (continueManaging) {
    writeProgress('🔄 Loading features...');

    const features = await fetchFeaturesCore(context);
    if (!features) {
      await safePrompt([{ type: 'input', name: 'continue', message: 'Press Enter to try again...' }]);
      continue;
    }

    displayFeaturesCore(features);

    const actionAnswer = await safePrompt<{ action: string }>([
      {
        type: 'list',
        name: 'action',
        message: 'What would you like to do?',
        choices: [
          { name: '👁️  View feature details', value: 'view' },
          { name: '✏️  Manage a feature', value: 'manage' },
          { name: '🔄 Refresh list', value: 'refresh' },
          { name: '❌ Exit', value: 'exit' },
        ],
      },
    ]);

    if (!actionAnswer) return;
    const { action } = actionAnswer;

    switch (action) {
      case 'view':
        await viewFeatureInteractive(context, features);
        break;
      case 'manage':
        await manageFeatureInteractive(context, features);
        break;
      case 'refresh':
        break;
      case 'exit':
        continueManaging = false;
        console.log('\n👋 Goodbye!\n');
        break;
    }
  }
}

async function viewFeatureInteractive(context: FeaturesCommandContext, features: AgentFeature[]): Promise<void> {
  if (features.length === 0) {
    console.log('\nℹ️  No features available.\n');
    return;
  }

  const feature = await promptFeatureSelection(features, 'Select a feature to view:');
  if (!feature) return;

  viewFeatureCore(feature);
  console.log();
  await safePrompt([{ type: 'input', name: 'continue', message: 'Press Enter to continue...' }]);
}

async function manageFeatureInteractive(context: FeaturesCommandContext, features: AgentFeature[]): Promise<void> {
  if (features.length === 0) {
    console.log('\nℹ️  No features available.\n');
    return;
  }

  const feature = await promptFeatureSelection(features, 'Select a feature to manage:');
  if (!feature) return;

  console.log('\n' + '─'.repeat(60));
  console.log(`Feature: ${feature.title}`);
  console.log(`Current Status: ${feature.active ? '✅ Active' : '❌ Inactive'}`);
  console.log('─'.repeat(60) + '\n');

  const actionAnswer = await safePrompt<{ action: string }>([
    {
      type: 'list',
      name: 'action',
      message: 'What would you like to do?',
      choices: [
        {
          name: feature.active ? '❌ Deactivate feature' : '✅ Activate feature',
          value: 'toggle',
        },
        { name: '✏️  Update context/instructions', value: 'context' },
        { name: '🔄 Update both status and context', value: 'both' },
        { name: '⬅️  Back', value: 'back' },
      ],
    },
  ]);

  if (!actionAnswer || actionAnswer.action === 'back') return;

  try {
    switch (actionAnswer.action) {
      case 'toggle':
        await toggleFeatureInteractive(context, feature);
        break;
      case 'context':
        await updateFeatureContextInteractive(context, feature);
        break;
      case 'both':
        await updateBothInteractive(context, feature);
        break;
    }
  } catch (error) {
    console.error('\n❌ Error updating feature:', error);
    await safePrompt([{ type: 'input', name: 'continue', message: 'Press Enter to continue...' }]);
  }
}

async function toggleFeatureInteractive(context: FeaturesCommandContext, feature: AgentFeature): Promise<void> {
  const newStatus = !feature.active;
  const action = newStatus ? 'activate' : 'deactivate';

  const confirmAnswer = await safePrompt<{ confirm: boolean }>([
    {
      type: 'confirm',
      name: 'confirm',
      message: `Are you sure you want to ${action} "${feature.title}"?`,
      default: true,
    },
  ]);

  if (!confirmAnswer || !confirmAnswer.confirm) {
    return;
  }

  if (newStatus) {
    await enableFeatureCore(context, feature);
  } else {
    await disableFeatureCore(context, feature);
  }

  await safePrompt([{ type: 'input', name: 'continue', message: 'Press Enter to continue...' }]);
}

async function updateFeatureContextInteractive(context: FeaturesCommandContext, feature: AgentFeature): Promise<void> {
  console.log('\n📝 Current context:');
  console.log('─'.repeat(60));
  console.log(feature.context);
  console.log('─'.repeat(60) + '\n');

  const contextAnswer = await safePrompt<{ newContext: string }>([
    {
      type: 'editor',
      name: 'newContext',
      message: 'Edit feature context (will open in your default editor):',
      default: feature.context,
      validate: (input: string) => {
        if (!input || !input.trim()) {
          return 'Context cannot be empty';
        }
        return true;
      },
    },
  ]);

  if (!contextAnswer) return;

  const confirmAnswer = await safePrompt<{ confirm: boolean }>([
    {
      type: 'confirm',
      name: 'confirm',
      message: 'Save updated context?',
      default: true,
    },
  ]);

  if (!confirmAnswer || !confirmAnswer.confirm) {
    console.log('\n❌ Update cancelled.\n');
    return;
  }

  writeProgress('🔄 Updating feature context...');

  try {
    await context.agentApi.updateAgentFeature(context.agentId, {
      featureName: feature.name,
      featureContext: contextAnswer.newContext.trim(),
    });
    writeSuccess(`✅ Context for "${feature.title}" updated successfully`);
  } catch (error) {
    console.error(`❌ Failed to update context: ${error}`);
  }

  await safePrompt([{ type: 'input', name: 'continue', message: 'Press Enter to continue...' }]);
}

async function updateBothInteractive(context: FeaturesCommandContext, feature: AgentFeature): Promise<void> {
  const statusAnswer = await safePrompt<{ active: boolean }>([
    {
      type: 'confirm',
      name: 'active',
      message: 'Should this feature be active?',
      default: feature.active,
    },
  ]);

  if (!statusAnswer) return;

  console.log('\n📝 Current context:');
  console.log('─'.repeat(60));
  console.log(feature.context);
  console.log('─'.repeat(60) + '\n');

  const contextAnswer = await safePrompt<{ newContext: string }>([
    {
      type: 'editor',
      name: 'newContext',
      message: 'Edit feature context (will open in your default editor):',
      default: feature.context,
      validate: (input: string) => {
        if (!input || !input.trim()) {
          return 'Context cannot be empty';
        }
        return true;
      },
    },
  ]);

  if (!contextAnswer) return;

  console.log('\n📋 Summary of changes:');
  console.log(
    `Status: ${feature.active ? '✅ Active' : '❌ Inactive'} → ${statusAnswer.active ? '✅ Active' : '❌ Inactive'}`
  );
  console.log(`Context: ${contextAnswer.newContext === feature.context ? 'No change' : 'Updated'}`);
  console.log();

  const confirmAnswer = await safePrompt<{ confirm: boolean }>([
    {
      type: 'confirm',
      name: 'confirm',
      message: 'Save all changes?',
      default: true,
    },
  ]);

  if (!confirmAnswer || !confirmAnswer.confirm) {
    console.log('\n❌ Update cancelled.\n');
    return;
  }

  writeProgress('🔄 Updating feature...');

  try {
    await context.agentApi.updateAgentFeature(context.agentId, {
      featureName: feature.name,
      active: statusAnswer.active,
      featureContext: contextAnswer.newContext.trim(),
    });
    writeSuccess(`✅ Feature "${feature.title}" updated successfully`);
  } catch (error) {
    console.error(`❌ Failed to update feature: ${error}`);
  }

  await safePrompt([{ type: 'input', name: 'continue', message: 'Press Enter to continue...' }]);
}
