/**
 * Agent Plugin
 *
 * Compiles the LuaAgent primitive — same pipeline as all other primitives:
 * detect → validate → entry point → bundle → artifact → manifest entry.
 *
 * Agent-specific metadata: persona, model (string or function).
 * The model function is bundled as part of the agent artifact (full-file bundling),
 * so outer-scope captures and imports work the same as in tool/skill execute functions.
 */

import { ObjectLiteralExpression, SourceFile, Node, ClassDeclaration } from 'ts-morph';
import { flattenPersonaTextAll } from '@lua/shared-types';
import {
  type AgentMetadata,
  type AgentMetadataFields,
  type ValidationResult,
  type CompiledPrimitive,
  type ManifestPrimitive,
  type ManifestAgent,
} from '../types.js';
import { BasePlugin, readStringMember, deriveNameFromClassName } from './base.js';
import {
  extractStringProperty,
  extractSchemaProperty,
  extractFunctionProperty,
  extractObjectProperty,
  extractPolymorphicProperty,
  evaluateNodeAsString,
  evaluateNodeAsObject,
  isFunction,
} from '../utils/ast-helpers.js';
import { findClassMember } from '../utils/class-hierarchy.js';
import { formatSarifWarning, resolveArrayRefs, reportDeopt } from '../utils/reference-resolver.js';
import type { ManifestVoice } from '../types.js';

/**
 * Plugin for compiling agent primitives.
 * Extends BasePlugin for common detection/entry point/postProcess logic.
 */
export class AgentPlugin extends BasePlugin<AgentMetadataFields> {
  readonly kind = 'agent';
  readonly displayName = 'Agent';
  readonly defineFunction = ''; // Agent only uses class-based detection (new LuaAgent)
  readonly legacyClassNames = ['LuaAgent'];

  protected readonly supportsClassDefinition = true;

  /**
   * Class-definition extraction. Reads the agent's own metadata
   * (name, description, persona, model, batching, governance) off the
   * inheritance chain.
   *
   * Limitation: primitive-reference arrays (skills/webhooks/jobs/etc.)
   * declared as class field initializers are NOT resolved here.
   * `AgentTraverser` consumes the legacy `detectWithConfig` path, which
   * is bound to the `new LuaAgent({...})` config-literal shape. A
   * subclass-style Agent that registers primitives via class fields
   * would need an `AgentTraverser` extension to walk those fields —
   * out of scope for the initial class-definition rollout.
   */
  protected extractFromClassDefinition(classDecl: ClassDeclaration, sourceFile: SourceFile): AgentMetadata | null {
    const className = classDecl.getName();
    if (!className) return null;

    const isDefaultExport = classDecl.isDefaultExport();
    const exportName = isDefaultExport ? 'default' : className;

    const name = readStringMember(classDecl, 'name') ?? deriveNameFromClassName(className);
    const baseDescription = readStringMember(classDecl, 'description') ?? '';

    // persona: support string OR { base, voice, text } object — same
    // shapes as `extractPolymorphicProperty` accepts on a config literal.
    const personaHit = findClassMember(classDecl, 'persona', 'property');
    let persona: AgentMetadataFields['persona'] = '';
    if (personaHit && Node.isPropertyDeclaration(personaHit.node)) {
      const init = personaHit.node.getInitializer();
      const asString = evaluateNodeAsString(init);
      if (asString !== undefined) {
        persona = asString;
      } else {
        const asObject = evaluateNodeAsObject(init);
        if (asObject) persona = asObject as AgentMetadataFields['persona'];
      }
    }

    // model: string => static; function => resolver. Same precedence
    // ladder as `extractModelInfo` on a config literal.
    let model: string | undefined;
    let hasModelResolver = false;
    const modelHit = findClassMember(classDecl, 'model', 'either');
    if (modelHit) {
      if (Node.isMethodDeclaration(modelHit.node)) {
        hasModelResolver = true;
      } else if (Node.isPropertyDeclaration(modelHit.node)) {
        const init = modelHit.node.getInitializer();
        if (init && isFunction(init)) {
          hasModelResolver = true;
        } else {
          model = evaluateNodeAsString(init);
        }
      }
    }

    const batchingHit = findClassMember(classDecl, 'batching', 'property');
    const batchingObj =
      batchingHit && Node.isPropertyDeclaration(batchingHit.node)
        ? evaluateNodeAsObject(batchingHit.node.getInitializer())
        : undefined;
    const batching = batchingObj ? this.shapeBatching(batchingObj) : undefined;

    const governanceHit = findClassMember(classDecl, 'governance', 'property');
    const governanceObj =
      governanceHit && Node.isPropertyDeclaration(governanceHit.node)
        ? evaluateNodeAsObject(governanceHit.node.getInitializer())
        : undefined;
    const governance =
      governanceObj && typeof governanceObj.mode === 'string'
        ? (governanceObj as unknown as AgentMetadataFields['governance'])
        : undefined;

    return {
      kind: this.kind,
      name,
      description: flattenPersonaTextAll(persona) || baseDescription,
      sourcePath: sourceFile.getFilePath(),
      exportName,
      isDefaultExport,
      line: classDecl.getStartLineNumber(),
      column: 1,
      metadata: {
        pattern: 'class-definition',
        persona,
        model,
        hasModelResolver,
        batching,
        governance,
      },
    };
  }

  /**
   * Reshape a runtime-evaluated batching object to the same narrow
   * `BatchingMetadata` projection `extractBatchingInfo` produces.
   */
  private shapeBatching(batching: Record<string, unknown>): AgentMetadataFields['batching'] {
    const result: NonNullable<AgentMetadataFields['batching']> = {};
    if (typeof batching.firstMessageDelayMs === 'number') result.firstMessageDelayMs = batching.firstMessageDelayMs;
    if (typeof batching.debounceWindowMs === 'number') result.debounceWindowMs = batching.debounceWindowMs;
    if (typeof batching.maxBatchMessages === 'number') result.maxBatchMessages = batching.maxBatchMessages;
    if (typeof batching.serializeProcessing === 'boolean') result.serializeProcessing = batching.serializeProcessing;
    return Object.keys(result).length > 0 ? result : undefined;
  }

  /**
   * Extract metadata from agent config object.
   */
  protected extractFromConfig(
    config: ObjectLiteralExpression,
    exportName: string,
    sourcePath: string,
    position: { line: number; column: number },
    pattern: 'function' | 'class'
  ): AgentMetadata | null {
    const common = this.extractCommonFields(config, exportName, sourcePath, position);
    if (!common) return null;

    const persona = extractPolymorphicProperty(config, 'persona', ['base', 'voice', 'text'] as const) ?? '';
    const { model, hasModelResolver } = this.extractModelInfo(config);
    const batching = this.extractBatchingInfo(config);
    const governance = this.extractGovernanceInfo(config);
    const { voiceRefNames, voiceRefSourcePaths } = this.extractVoiceRefs(config);

    return {
      kind: this.kind,
      ...common,
      // Use persona as description (agent's "description" IS its persona).
      // Description is channel-agnostic agent metadata, so concat all
      // channels — text-default flatten would silently drop voice-only
      // personas here.
      description: flattenPersonaTextAll(persona) || common.description,
      metadata: {
        pattern,
        persona,
        model,
        hasModelResolver,
        batching,
        governance,
        voiceRefNames,
        voiceRefSourcePaths,
      },
    };
  }

  /**
   * Read the `voices` array property and return both the identifiers and
   * the resolver-discovered source file for each.
   *
   * Goes through the same `resolveArrayRefs` pipeline skills use for
   * `tools: [...]`, so imports / re-exports / namespace specifiers /
   * `as const` / `satisfies` all follow the same rules. The earlier
   * shallow walk (bare-identifier collection + name-only matching)
   * silently failed for `export default new LuaVoice(...)` because the
   * local binding (`mattVoice`) matches neither the voice's `exportName`
   * (`default`) nor `name` (`matt-line`). Carrying the sourcePath through
   * lets `resolveVoiceRefs` match on that instead.
   *
   * Order is preserved (first entry is the channel default when no
   * `channelConfig.<kind>.voiceId` is bound).
   */
  private extractVoiceRefs(config: ObjectLiteralExpression): {
    voiceRefNames?: string[];
    voiceRefSourcePaths?: Record<string, string>;
  } {
    const prop = config.getProperty('voices');
    if (!prop || !Node.isPropertyAssignment(prop)) return {};
    const value = prop.getInitializer();
    if (!value || !Node.isArrayLiteralExpression(value)) return {};

    const project = config.getSourceFile().getProject();
    const result = resolveArrayRefs(value, { project });
    if (!result.confident) {
      console.warn(reportDeopt(result, 'voices'));
    }

    const names: string[] = [];
    const sourcePaths: Record<string, string> = {};
    for (const ref of result.value) {
      names.push(ref.identifierName);
      sourcePaths[ref.identifierName] = ref.sourceFile.getFilePath();
    }

    return {
      voiceRefNames: names.length > 0 ? names : undefined,
      voiceRefSourcePaths: Object.keys(sourcePaths).length > 0 ? sourcePaths : undefined,
    };
  }

  /**
   * Extract batching config from agent config.
   * Returns a plain object with only the fields that were explicitly set.
   */
  private extractBatchingInfo(config: ObjectLiteralExpression):
    | {
        firstMessageDelayMs?: number;
        debounceWindowMs?: number;
        maxBatchMessages?: number;
        serializeProcessing?: boolean;
      }
    | undefined {
    const batching = extractObjectProperty(config, 'batching');
    if (!batching) return undefined;

    const result: {
      firstMessageDelayMs?: number;
      debounceWindowMs?: number;
      maxBatchMessages?: number;
      serializeProcessing?: boolean;
    } = {};

    if (typeof batching.firstMessageDelayMs === 'number') result.firstMessageDelayMs = batching.firstMessageDelayMs;
    if (typeof batching.debounceWindowMs === 'number') result.debounceWindowMs = batching.debounceWindowMs;
    if (typeof batching.maxBatchMessages === 'number') result.maxBatchMessages = batching.maxBatchMessages;
    if (typeof batching.serializeProcessing === 'boolean') result.serializeProcessing = batching.serializeProcessing;

    return Object.keys(result).length > 0 ? result : undefined;
  }

  /**
   * Extract governance config from agent config.
   * Returns the full governance object or undefined if not set.
   */
  private extractGovernanceInfo(config: ObjectLiteralExpression): AgentMetadataFields['governance'] {
    const governance = extractObjectProperty(config, 'governance') as any;
    if (!governance || !governance.mode) return undefined;
    return governance;
  }

  /**
   * Extract model info from agent config.
   * Returns the static model string (if any) and whether a resolver function exists.
   */
  private extractModelInfo(config: ObjectLiteralExpression): { model?: string; hasModelResolver: boolean } {
    // Try as a string literal first
    const modelString = extractStringProperty(config, 'model');
    if (modelString) {
      return { model: modelString, hasModelResolver: false };
    }

    // Check if model property is a function via AST
    const modelProp = extractSchemaProperty(config, 'model');
    if (modelProp && isFunction(modelProp)) {
      return { hasModelResolver: true };
    }

    // Check if model property is a variable reference to a function (via ts-evaluator)
    const modelFnEvaluated = extractFunctionProperty(config, 'model');
    if (modelFnEvaluated !== undefined) {
      return { hasModelResolver: true };
    }

    return { hasModelResolver: false };
  }

  validate(metadata: AgentMetadata): ValidationResult {
    const { errors, warnings } = this.baseValidation(metadata);

    const persona = metadata.metadata.persona;
    if (!persona || (typeof persona === 'object' && !persona.base && !persona.voice && !persona.text)) {
      warnings.push({
        message: 'Agent should have a persona',
        line: metadata.line,
      });
    }

    return { valid: errors.length === 0, errors, warnings };
  }

  /**
   * Detect the agent and return both metadata and the config AST node.
   * Used by AgentTraverser to extract primitive refs from the config.
   * The standard detect() (inherited from BasePlugin) is used by the compiler's fallback scan.
   */
  detectWithConfig(sourceFile: SourceFile): { metadata: AgentMetadata; configNode: ObjectLiteralExpression } | null {
    let result: { metadata: AgentMetadata; configNode: ObjectLiteralExpression } | null = null;

    sourceFile.forEachDescendant((node) => {
      if (result) return;

      if (Node.isNewExpression(node)) {
        const expr = node.getExpression();
        if (expr.getText() === 'LuaAgent') {
          const args = node.getArguments();
          if (args.length > 0 && Node.isObjectLiteralExpression(args[0])) {
            const config = args[0];

            // Find variable name for the export
            const parent = node.getParent();
            const exportName = parent && Node.isVariableDeclaration(parent) ? parent.getName() : 'default';

            const pos = sourceFile.getLineAndColumnAtPos(node.getStart());
            const metadata = this.extractFromConfig(config, exportName, sourceFile.getFilePath(), pos, 'class');
            if (metadata) {
              result = { metadata, configNode: config };
            }
          }
        }
      }
    });

    return result;
  }

  toManifestEntry(compiled: CompiledPrimitive, allPrimitives?: CompiledPrimitive[]): ManifestPrimitive {
    const agentMeta = compiled.metadata as AgentMetadataFields;
    const voiceRefs = this.resolveVoiceRefs(agentMeta.voiceRefNames, agentMeta.voiceRefSourcePaths, allPrimitives);

    return {
      ...this.baseManifestFields(compiled),
      persona: agentMeta.persona,
      model: agentMeta.model,
      hasModelResolver: agentMeta.hasModelResolver || undefined,
      batching: agentMeta.batching,
      governance: agentMeta.governance,
      voiceRefs,
    } as ManifestAgent;
  }

  /**
   * Map the AST-level identifiers (`[supportVoice, billingVoice]`) to real
   * LuaVoice names, preserving order. Matching priority:
   *
   *   1. `sourcePath` — the resolver-discovered source file for the
   *      identifier. Wins for default exports, where the local binding
   *      can't match `exportName` (`default`) or the runtime `name`.
   *   2. `exportName` / `name` — fallback for named exports where the
   *      identifier already matches the voice primitive directly.
   *
   * Unresolved entries are dropped (the resolver already emitted SARIF
   * warnings for those). Duplicate matches surface a warning so name
   * collisions don't silently win.
   */
  private resolveVoiceRefs(
    voiceRefNames: string[] | undefined,
    voiceRefSourcePaths: Record<string, string> | undefined,
    allPrimitives?: CompiledPrimitive[]
  ): { name: string }[] | undefined {
    if (!voiceRefNames?.length || !allPrimitives) return undefined;
    const out: { name: string }[] = [];
    for (const refName of voiceRefNames) {
      const refSourcePath = voiceRefSourcePaths?.[refName];
      let matches: CompiledPrimitive[] = [];
      if (refSourcePath) {
        matches = allPrimitives.filter((p) => p.kind === 'voice' && p.sourcePath === refSourcePath);
        // Multiple voices in the same source file — refine by export
        // name. For `export default new LuaVoice(...)` only one voice
        // lives in the file, so the unrefined match wins and the
        // identifier-vs-exportName mismatch is handled.
        if (matches.length > 1) {
          const refined = matches.filter((p) => p.exportName === refName || p.name === refName);
          if (refined.length > 0) matches = refined;
        }
      }
      if (matches.length === 0) {
        matches = allPrimitives.filter((p) => p.kind === 'voice' && (p.exportName === refName || p.name === refName));
      }
      if (matches.length === 0) continue;
      if (matches.length > 1) {
        console.warn(
          `[agent.plugin] voiceRef "${refName}" matched ${matches.length} voices ` +
            `(${matches.map((m) => `${m.name}@${m.sourcePath}`).join(', ')}). ` +
            `Picking the first; rename to disambiguate.`
        );
      }
      const voice = matches[0];
      const voiceManifest = voice as unknown as ManifestVoice;
      out.push({ name: voiceManifest.name ?? voice.name });
    }
    return out.length > 0 ? out : undefined;
  }

  /**
   * Strip `voiceRefSourcePaths` from the persisted metadata shape. The
   * field holds absolute build-machine paths — baking them into the
   * sidecar JSON / artifact would (a) make content hashes non-reproducible
   * across machines, (b) leak filesystem layout to downstream consumers.
   * Mirrors `SkillPlugin.sanitizeForPersistence`.
   */
  sanitizeForPersistence(metadata: AgentMetadataFields): AgentMetadataFields {
    const agent = metadata as AgentMetadataFields;
    if (!agent.voiceRefSourcePaths) return agent;
    const { voiceRefSourcePaths: _stripped, ...rest } = agent;
    return rest as AgentMetadataFields;
  }
}

export const agentPlugin = new AgentPlugin();
