/**
 * API Key Display Command
 * Displays the stored API key with user confirmation
 */

import inquirer from 'inquirer';
import { getToken } from '../services/auth.js';
import { withErrorHandling, clearPromptLines, writeProgress, writeSuccess } from '../utils/cli.js';
import { trackEvent } from '../services/analytics.js';

export async function apiKeyCommand(options?: { force?: boolean }): Promise<void> {
  return withErrorHandling(async () => {
    let apiKey: string;
    try {
      apiKey = getToken();
    } catch {
      writeProgress('ℹ️  No API key found. Run `lua auth configure` first.');
      trackEvent('cli_apikey_displayed', { key_found: false });
      return;
    }

    if (options?.force) {
      console.log(apiKey);
      trackEvent('cli_apikey_displayed', { key_found: true, force_mode: true, user_confirmed: true });
      return;
    }

    const { confirm } = await inquirer.prompt([
      {
        type: 'confirm',
        name: 'confirm',
        message: 'This will display your API key. Are you sure you want to continue?',
        default: false,
      },
    ]);

    if (confirm) {
      writeSuccess('🔑 Your API key:');
      console.log(apiKey);
    } else {
      writeProgress('ℹ️  API key display cancelled.');
    }
    trackEvent('cli_apikey_displayed', { key_found: true, force_mode: false, user_confirmed: confirm });
  }, 'key display');
}
