/**
 * Agents Command
 * Lists all organizations and agents accessible to the authenticated user
 */

import { withErrorHandling, writeSuccess, writeInfo } from '../utils/cli.js';
import { getToken, checkApiKey } from '../services/auth.js';
import { readYamlConfig } from '../utils/files.js';
import { trackEvent } from '../services/analytics.js';

/**
 * Main agents command - retrieves and displays organization/agent information.
 *
 * This command:
 * 1. Authenticates with the API
 * 2. Displays all organizations and their agents in a formatted view
 * 3. Highlights the currently configured agent (if any)
 *
 * Use this command to:
 * - View all organizations you have access to
 * - Get agent IDs for configuration
 * - See which agent is currently configured
 *
 * @param cmdObj - Command options (--json for raw output)
 */
export async function agentsCommand(cmdObj?: { json?: boolean }): Promise<void> {
  return withErrorHandling(async () => {
    const apiKey = getToken();
    const userData = await checkApiKey(apiKey);

    // Get current config to highlight active agent
    const config = readYamlConfig();
    const currentAgentId = config?.agent?.agentId;
    const currentOrgId = config?.agent?.orgId;

    // JSON output mode
    if (cmdObj?.json) {
      console.log(JSON.stringify(userData.admin.orgs, null, 2));
      return;
    }

    // Formatted output
    writeSuccess(`✅ Authenticated as ${userData.fullName || userData.email}\n`);

    console.log('============================================================');
    console.log('🏢 Organizations & Agents');
    console.log('============================================================\n');

    const orgs = userData.admin?.orgs || [];

    if (orgs.length === 0) {
      writeInfo('No organizations found.');
      return;
    }

    for (const org of orgs) {
      const isCurrentOrg = org.id === currentOrgId;
      const orgMarker = isCurrentOrg ? ' ⭐' : '';

      console.log(`📁 ${org.registeredName}${orgMarker}`);
      console.log(`   ID: ${org.id}`);
      console.log(`   Type: ${org.type}`);

      if (org.agents && org.agents.length > 0) {
        console.log(`   Agents:`);
        for (const agent of org.agents) {
          const isCurrentAgent = agent.agentId === currentAgentId;
          const agentMarker = isCurrentAgent ? ' ← current' : '';
          console.log(`     🤖 ${agent.name}${agentMarker}`);
          console.log(`        ID: ${agent.agentId}`);
        }
      } else {
        console.log(`   Agents: (none)`);
      }
      console.log('');
    }

    console.log('============================================================');
    console.log(`Total: ${orgs.length} organization(s)`);

    if (currentAgentId) {
      console.log(`\n💡 Currently configured: ${currentAgentId}`);
    } else {
      console.log(`\n💡 No agent configured. Run 'lua init' to set up.`);
    }
    trackEvent('cli_agents_listed', {
      json_output: cmdObj?.json || false,
      orgs_count: orgs.length,
      total_agents_count: orgs.reduce((sum: number, org: any) => sum + (org.agents?.length || 0), 0),
      has_configured_agent: !!currentAgentId,
    });
  }, 'agents listing');
}
