/**
 * Configure Command
 * Orchestrates the authentication setup process
 */

import { withErrorHandling, clearPromptLines, writeError, writeInfo } from '../utils/cli.js';
import {
  promptAuthMethod,
  handleApiKeyAuth,
  handleEmailAuth,
  handleApiKeyAuthNonInteractive,
  handleEmailOtpRequest,
  handleEmailOtpVerify,
} from '../utils/auth-flows.js';
import { trackEvent } from '../services/analytics.js';

/**
 * Options for the configure command
 */
interface ConfigureCommandOptions {
  apiKey?: string; // Direct API key (non-interactive)
  email?: string; // Email for OTP flow
  otp?: string; // OTP code (non-interactive verification)
}

/**
 * Main configure command - sets up authentication credentials.
 *
 * This command performs the following steps:
 * 1. Prompts user to choose authentication method (API key or email)
 * 2. Executes the appropriate authentication flow
 * 3. Saves credentials to ~/.lua-cli/credentials
 *
 * Authentication Methods:
 * - **API Key**: Direct entry of existing API key
 * - **Email**: OTP-based authentication that generates a new API key
 *
 * Non-Interactive Modes:
 * - **--api-key <key>**: Set API key directly without prompts
 * - **--email <email>**: Request OTP to be sent to email
 * - **--email <email> --otp <code>**: Verify OTP and generate API key
 *
 * Features:
 * - Credential storage in ~/.lua-cli/credentials (owner-only permissions)
 * - Email validation
 * - OTP verification with retry logic
 * - Automatic API key generation for email auth
 * - Full non-interactive mode for CI/CD and automation
 *
 * @param options - Command options for non-interactive mode
 * @returns Promise that resolves when configuration is complete
 */
export async function configureCommand(options: ConfigureCommandOptions = {}): Promise<void> {
  return withErrorHandling(async () => {
    const { apiKey, email, otp } = options;

    // Determine auth method for tracking
    let authMethod: string;
    let nonInteractive = false;

    // Non-interactive mode: Direct API key
    if (apiKey) {
      authMethod = 'api-key';
      nonInteractive = true;
      await handleApiKeyAuthNonInteractive(apiKey);
    } else if (email) {
      // Non-interactive mode: Email OTP flow
      authMethod = 'email';
      nonInteractive = true;
      if (otp) {
        await handleEmailOtpVerify(email, otp);
      } else {
        await handleEmailOtpRequest(email);
      }
    } else {
      // Interactive mode: Prompt for auth method
      authMethod = await promptAuthMethod();
      clearPromptLines(2);

      if (authMethod === 'api-key') {
        await handleApiKeyAuth();
      } else if (authMethod === 'email') {
        await handleEmailAuth();
      }
    }

    trackEvent('cli_auth_completed', {
      auth_method: authMethod,
      non_interactive_mode: nonInteractive,
      otp_step: email ? (otp ? 'verify' : 'request') : null,
    });
  }, 'configuration');
}
