/**
 * Destroy Command
 * Securely deletes stored authentication credentials
 */

import inquirer from 'inquirer';
import { getToken, deleteApiKey } from '../services/auth.js';
import { withErrorHandling, clearPromptLines, writeProgress, writeSuccess } from '../utils/cli.js';
import { trackEvent } from '../services/analytics.js';

export async function destroyCommand(options?: { force?: boolean }): Promise<void> {
  return withErrorHandling(async () => {
    let apiKey: string;
    try {
      apiKey = getToken();
    } catch {
      writeProgress('ℹ️  No API key found to delete.');
      trackEvent('cli_logout_completed', { key_found: false });
      return;
    }

    if (options?.force) {
      const deleted = deleteApiKey();
      if (deleted) {
        writeSuccess('✅ API key deleted successfully.');
      } else {
        writeProgress('❌ Failed to delete API key.');
      }
      trackEvent('cli_logout_completed', {
        key_found: true,
        force_mode: true,
        user_confirmed: true,
        delete_succeeded: deleted,
      });
      return;
    }

    const { confirm } = await inquirer.prompt([
      {
        type: 'confirm',
        name: 'confirm',
        message: 'Are you sure you want to delete your API key? This action cannot be undone.',
        default: false,
      },
    ]);

    clearPromptLines(2);

    let deleted = false;
    if (confirm) {
      deleted = deleteApiKey();
      if (deleted) {
        writeSuccess('✅ API key deleted successfully.');
      } else {
        writeProgress('❌ Failed to delete API key.');
      }
    } else {
      writeProgress('ℹ️  API key deletion cancelled.');
    }
    trackEvent('cli_logout_completed', {
      key_found: true,
      force_mode: false,
      user_confirmed: confirm,
      delete_succeeded: deleted,
    });
  }, 'logout');
}
