/**
 * AST helper functions for extracting and evaluating values from ts-morph nodes.
 *
 * Organized into sections:
 * 1. EVALUATION ENGINE    — ts-evaluator core with lua-cli passthrough shims
 * 2. NODE EVALUATION      — resolve a raw AST Node to a typed runtime value
 * 3. PROPERTY EXTRACTION  — get typed values from ObjectLiteralExpression properties
 * 4. NODE INSPECTION      — type checks and utilities for AST nodes
 * 5. IDENTIFIER RESOLUTION — follow variable/import reference chains to declarations
 * 6. IMPORT RESOLUTION    — locate source files for imported identifiers
 */

import { Node, ObjectLiteralExpression, SourceFile, VariableDeclaration } from 'ts-morph';
import ts from 'typescript';
import { evaluate } from 'ts-evaluator';
import { PRIMITIVE_SHIMS } from '../../config/compile.constants.js';

// =============================================================================
// 1. EVALUATION ENGINE
//
// Core ts-evaluator wrapper with lua-cli passthrough shims.
// Shims are defined in config/compile.constants.ts (single source of truth)
// and shared with utils/sandbox.ts.
// =============================================================================

/**
 * Evaluate any AST expression node using ts-evaluator.
 * Handles ALL expression types: literals, concatenation, variables,
 * imported constants, template literals, function calls, etc.
 *
 * Provides lua-cli primitive shims so that expressions like
 * `defineTool({name: 'foo'})` evaluate successfully.
 */
function evaluateNode(node: Node | undefined): unknown {
  if (!node) return undefined;

  try {
    const tsNode = node.compilerNode as ts.Expression;
    const typeChecker = node.getSourceFile().getProject().getTypeChecker().compilerObject;

    const result = evaluate({
      node: tsNode,
      typeChecker,
      typescript: ts,
      environment: {
        preset: 'NODE',
        extra: PRIMITIVE_SHIMS,
      },
      policy: {
        deterministic: false,
        network: false,
        console: false,
        io: { read: true, write: false },
        process: { exit: false, spawnChild: false },
      },
    });

    if (result.success) return result.value;
  } catch {
    // ts-evaluator failed — return undefined
  }

  return undefined;
}

// =============================================================================
// 2. NODE EVALUATION
//
// Evaluate a raw AST Node to a typed runtime value.
// Primary path: ts-evaluator. Fallback: resolveIdentifier() + literal check.
// =============================================================================

/** Evaluate an AST node as a string. Falls back to AST resolution if ts-evaluator fails. */
export function evaluateNodeAsString(node: Node | undefined): string | undefined {
  const val = evaluateNode(node);
  if (typeof val === 'string') return val;

  // AST fallback: resolve identifier chain → check for string literal
  if (node) {
    const resolved = resolveIdentifier(node);
    if (resolved && Node.isStringLiteral(resolved)) return resolved.getLiteralValue();
  }
  return undefined;
}

/** Evaluate an AST node as a number. Falls back to AST resolution if ts-evaluator fails. */
export function evaluateNodeAsNumber(node: Node | undefined): number | undefined {
  const val = evaluateNode(node);
  if (typeof val === 'number') return val;

  // AST fallback: resolve identifier chain → check for numeric literal
  if (node) {
    const resolved = resolveIdentifier(node);
    if (resolved && Node.isNumericLiteral(resolved)) return resolved.getLiteralValue();
  }
  return undefined;
}

/** Evaluate an AST node as a boolean. Falls back to AST resolution if ts-evaluator fails. */
export function evaluateNodeAsBoolean(node: Node | undefined): boolean | undefined {
  const val = evaluateNode(node);
  if (typeof val === 'boolean') return val;

  // AST fallback: resolve identifier chain → check for boolean literal
  if (node) {
    const resolved = resolveIdentifier(node);
    if (resolved && Node.isTrueLiteral(resolved)) return true;
    if (resolved && Node.isFalseLiteral(resolved)) return false;
  }
  return undefined;
}

// =============================================================================
// 3. PROPERTY EXTRACTION
//
// All functions that read a named property from an ObjectLiteralExpression.
//
// Primitives:    extractStringProperty, extractNumberProperty, extractBooleanProperty
// Complex:       extractObjectProperty, extractFunctionProperty
// Raw AST:       extractSchemaProperty (returns Node for downstream Zod processing)
// Arrays:        use resolveArrayRefs() in utils/reference-resolver.ts instead
// Post-eval:     extractNestedProperty (plain key lookup on already-extracted object)
// Introspection: hasProperty, getPropertyNames
// =============================================================================

/**
 * Extract a string value from an object property.
 * Delegates to evaluateNodeAsString for full expression evaluation + AST fallback.
 */
export function extractStringProperty(obj: ObjectLiteralExpression, propertyName: string): string | undefined {
  const prop = obj.getProperty(propertyName);
  if (!prop || !Node.isPropertyAssignment(prop)) return undefined;

  const value = prop.getInitializer();
  if (!value) return undefined;

  return evaluateNodeAsString(value);
}

/**
 * Extract a boolean value from an object property.
 * Delegates to evaluateNodeAsBoolean for full expression evaluation + AST fallback.
 */
export function extractBooleanProperty(obj: ObjectLiteralExpression, propertyName: string): boolean | undefined {
  const prop = obj.getProperty(propertyName);
  if (!prop || !Node.isPropertyAssignment(prop)) return undefined;

  return evaluateNodeAsBoolean(prop.getInitializer());
}

/**
 * Extract a number value from an object property.
 * Delegates to evaluateNodeAsNumber for full expression evaluation + AST fallback.
 */
export function extractNumberProperty(obj: ObjectLiteralExpression, propertyName: string): number | undefined {
  const prop = obj.getProperty(propertyName);
  if (!prop || !Node.isPropertyAssignment(prop)) return undefined;

  return evaluateNodeAsNumber(prop.getInitializer());
}

/**
 * Extract a schema node from an object property.
 * Returns the raw AST node (not evaluated) for downstream Zod processing.
 */
export function extractSchemaProperty(obj: ObjectLiteralExpression, propertyName: string): Node | undefined {
  const prop = obj.getProperty(propertyName);
  if (!prop || !Node.isPropertyAssignment(prop)) return undefined;

  return prop.getInitializer();
}

/**
 * Extract nested property from an already-evaluated object (not AST).
 * Use after extractObjectProperty() to drill into nested values.
 *
 * Example:
 *   const schedule = extractObjectProperty(config, 'schedule');
 *   const type = extractNestedProperty(schedule, 'type');
 */
export function extractNestedProperty(obj: Record<string, unknown> | undefined, propertyName: string): unknown {
  if (!obj || typeof obj !== 'object') return undefined;
  return obj[propertyName];
}

/**
 * Evaluate any AST node to a plain object (or undefined if it doesn't
 * evaluate cleanly to one). Same evaluator as `extractObjectProperty`,
 * but operates on a raw Node — useful for reading a class property's
 * initializer (e.g. `schedule = { type: 'cron', ... }`) without going
 * through a property-of-ObjectLiteralExpression step.
 */
export function evaluateNodeAsObject(node: Node | undefined): Record<string, unknown> | undefined {
  if (!node) return undefined;
  const evaluated = evaluateNode(node);
  if (evaluated && typeof evaluated === 'object' && !Array.isArray(evaluated)) {
    return evaluated as Record<string, unknown>;
  }
  return undefined;
}

/**
 * Extract an object property, evaluated to its runtime value.
 *
 * Handles three input shapes the dev might use:
 *   1. Inline: `pronunciations: { 'API': 'A P I' }`
 *   2. Same-file const: `const p = {...}; pronunciations: p`
 *   3. Cross-file const: `import { p } from './p'; pronunciations: p`
 *   4. Shorthand: `import { pronunciations } from './p'; { pronunciations }`
 *
 * Strategy: pull the value node, walk through identifier chains (same-
 * file or cross-file via TypeChecker definitions), then evaluate the
 * resolved node with ts-evaluator. The resolveIdentifier walk fills the
 * gap where ts-evaluator alone can't follow imports cleanly.
 */
export function extractObjectProperty(
  obj: ObjectLiteralExpression,
  propertyName: string
): Record<string, unknown> | undefined {
  const prop = obj.getProperty(propertyName);
  if (!prop) return undefined;

  let value: Node | undefined;
  if (Node.isShorthandPropertyAssignment(prop)) {
    // `{ pronunciations }` — the property is its own identifier.
    value = prop.getNameNode();
  } else if (Node.isPropertyAssignment(prop)) {
    value = prop.getInitializer();
  } else {
    return undefined;
  }
  if (!value) return undefined;

  // Walk identifier chains (same-file + cross-file via TypeChecker) so
  // an imported `const pronunciations = {...}` resolves to the inline
  // object before evaluation. For non-Identifier inputs (inline literal)
  // resolveIdentifier returns the input unchanged.
  const resolved = Node.isIdentifier(value) ? resolveIdentifier(value) : value;
  const evaluated = evaluateNode(resolved ?? value);

  if (evaluated && typeof evaluated === 'object' && !Array.isArray(evaluated)) {
    return evaluated as Record<string, unknown>;
  }

  return undefined;
}

/**
 * Extract a function property, evaluated to its runtime value.
 * Detects both inline function expressions and variable references to functions.
 */
export function extractFunctionProperty(obj: ObjectLiteralExpression, propertyName: string): Function | undefined {
  const prop = obj.getProperty(propertyName);
  if (!prop || !Node.isPropertyAssignment(prop)) return undefined;

  const value = prop.getInitializer();
  if (!value) return undefined;

  const evaluated = evaluateNode(value);
  return typeof evaluated === 'function' ? evaluated : undefined;
}

/**
 * Extract a property that may be a string OR an object literal with string values
 * for specified keys. Used for persona/context that accept both forms.
 *
 * @template K - Union of allowed key names
 * @param obj - ObjectLiteralExpression to extract from
 * @param propertyName - Property name to extract
 * @param allowedKeys - List of allowed keys (e.g., ['base', 'voice', 'text'])
 * @returns string | Partial<Record<K, string>> | undefined
 */
export function extractPolymorphicProperty<K extends string>(
  obj: ObjectLiteralExpression,
  propertyName: string,
  allowedKeys: readonly K[]
): string | Partial<Record<K, string>> | undefined {
  const s = extractStringProperty(obj, propertyName);
  if (s !== undefined && s !== '') return s;

  const o = extractObjectProperty(obj, propertyName);
  if (o && typeof o === 'object' && !Array.isArray(o)) {
    const result: Partial<Record<K, string>> = {};
    for (const k of allowedKeys) {
      const v = (o as Record<string, unknown>)[k];
      if (typeof v === 'string') result[k] = v;
    }
    if (Object.keys(result).length > 0) return result;
  }

  return undefined;
}

/** Check if a property exists on an object literal. */
export function hasProperty(obj: ObjectLiteralExpression, propertyName: string): boolean {
  return obj.getProperty(propertyName) !== undefined;
}

/** Extract all property names from an object literal. */
export function getPropertyNames(obj: ObjectLiteralExpression): string[] {
  return obj
    .getProperties()
    .filter((prop) => Node.isPropertyAssignment(prop))
    .map((prop) => (prop as any).getName());
}

// =============================================================================
// 4. NODE INSPECTION
//
// Type checks and utilities for individual AST nodes.
// =============================================================================

/** Check if a node is a function (arrow or regular). */
export function isFunction(node: Node | undefined): boolean {
  if (!node) return false;
  return Node.isArrowFunction(node) || Node.isFunctionExpression(node);
}

/** Get the text of a function body. */
export function getFunctionBody(node: Node | undefined): string | undefined {
  if (!node) return undefined;

  if (Node.isArrowFunction(node)) {
    const body = node.getBody();
    return body.getText();
  }

  if (Node.isFunctionExpression(node)) {
    const body = node.getBody();
    return body?.getText();
  }

  return undefined;
}

// =============================================================================
// 5. IDENTIFIER RESOLUTION
//
// Follow variable reference chains (same-file and cross-file via imports)
// to find the underlying declaration/initializer.
// =============================================================================

/**
 * Recursively resolve an Identifier node to its underlying initializer.
 *
 * Follows variable reference chains, including across files:
 *   const a = [x, y];
 *   const b = a;       // resolveIdentifier(b) → ArrayLiteralExpression [x, y]
 *   const c = b;       // resolveIdentifier(c) → ArrayLiteralExpression [x, y]
 *
 * Resolution strategy:
 * 1. Same-file lookup via getVariableDeclaration() (fast path)
 * 2. Cross-file lookup via getDefinitionNodes() (follows imports)
 *
 * Stops at non-Identifier initializers (literals, call expressions, etc.)
 * or when the declaration can't be found.
 * Max depth of 10 to prevent infinite loops on circular references.
 */
export function resolveIdentifier(node: Node, maxDepth = 10): Node | undefined {
  if (!Node.isIdentifier(node)) return node;

  let identNode = node;

  for (let i = 0; i < maxDepth; i++) {
    // Fast path: same-file variable declaration
    let varDecl: VariableDeclaration | undefined = identNode
      .getSourceFile()
      .getVariableDeclaration(identNode.getText());

    // Cross-file: follow imports via TypeChecker symbol resolution
    if (!varDecl) {
      try {
        const defs = identNode.getDefinitionNodes();
        varDecl = defs.find((d) => Node.isVariableDeclaration(d)) as VariableDeclaration | undefined;
      } catch {
        /* symbol resolution unavailable — file not in project */
      }
    }

    if (!varDecl) return identNode; // Can't resolve further

    const init = varDecl.getInitializer();
    if (!init) return undefined;

    // If the initializer is another Identifier, keep following the chain
    if (Node.isIdentifier(init)) {
      identNode = init;
      continue;
    }

    // Reached a non-Identifier node — this is the resolved value
    return init;
  }

  return identNode;
}

// =============================================================================
// 6. IMPORT RESOLUTION
//
// Find which source file an imported identifier comes from.
// =============================================================================

/**
 * Find the source file path for an imported identifier.
 *
 * Checks both default and named imports for the given identifier name.
 * Falls back to the current source file if not found in imports (for local definitions).
 *
 * @param identifier - The identifier name to find (e.g., 'MyTool', 'searchTool')
 * @param sourceFile - The source file containing the imports
 * @param resolveImportPath - Function to resolve module specifier to absolute path
 * @returns Absolute path to the source file, or sourceFile path for local definitions
 */
export function findImportSource(
  identifier: string,
  sourceFile: SourceFile,
  resolveImportPath: (specifier: string, fromFile: string) => string | null
): string | null {
  for (const importDecl of sourceFile.getImportDeclarations()) {
    const defaultImport = importDecl.getDefaultImport();
    const namedImports = importDecl.getNamedImports();

    // Check if identifier matches default import or any named import
    const isMatch =
      (defaultImport && defaultImport.getText() === identifier) ||
      namedImports.some((named) => named.getName() === identifier);

    if (isMatch) {
      return resolveImportPath(importDecl.getModuleSpecifierValue(), sourceFile.getFilePath());
    }
  }

  // Not found in imports - assume local definition in same file
  return sourceFile.getFilePath();
}
