/**
 * Sends a chat message to the API with skill and processor overrides for sandbox testing.
 *
 * @param apiKey - User's API key
 * @param agentId - Agent ID
 * @param skillId - Skill ID
 * @param sandboxId - Sandbox skill ID
 * @param message - Message to send
 * @param persona - Optional persona override
 * @param yamlConfig - YAML config containing skills and processors
 * @returns The chat response text or null if failed
 */
export async function sendChatMessage(
  apiKey: string,
  agentId: string,
  skillId: string,
  sandboxId: string,
  message: string,
  persona: PersonaText | undefined,
  yamlConfig: YamlConfig
): Promise<string | null> {
  try {
    // Get all sandbox skill IDs for skill override (uses YAML config)
    const allSkillOverrides = await getAllSandboxSkillIds(yamlConfig);

    // If no skills found, fallback to the provided skillId and sandboxId
    const skillOverride =
      allSkillOverrides.length > 0
        ? allSkillOverrides
        : [
            {
              skillId: skillId,
              sandboxId: sandboxId,
            },
          ];

    // Get sandbox processor overrides from YAML config
    const preprocessorOverride = await getAllSandboxPreProcessorIds(yamlConfig);
    const postprocessorOverride = await getAllSandboxPostProcessorIds(yamlConfig);

    const chatRequest: ChatRequest = {
      messages: [
        {
          type: 'text',
          text: message,
        },
      ],
      navigate: true,
      skillOverride: skillOverride,
      preprocessorOverride: preprocessorOverride,
      postprocessorOverride: postprocessorOverride,
    };

    // Add persona override if provided
    if (persona) {
      chatRequest.personaOverride = persona;
    }

    const chatApi = new ChatApi(BASE_URLS.CHAT, apiKey);
    const response = await chatApi.sendMessage(agentId, chatRequest);

    if (!response.success) {
      console.error(`❌ Chat API error: ${response.error?.message || 'Unknown error'}`);
      return null;
    }

    return response.data?.text || null;
  } catch (error) {
    console.error('❌ Error sending chat message:', error);
    return null;
  }
}

/**
 * Updates an existing sandbox version.
 *
 * @param apiKey - User's API key
 * @param agentId - Agent ID
 * @param skillId - Skill ID
 * @param sandboxVersionId - Existing sandbox version ID
 * @param versionData - Version data to update
 * @returns Update response
 */
export async function updateDevVersion(
  apiKey: string,
  agentId: string,
  skillId: string,
  sandboxVersionId: string,
  versionData: any
): Promise<UpdateDevVersionResponse> {
  try {
    const skillsApi = new SkillApi(BASE_URLS.API, apiKey, agentId);
    const response = await skillsApi.updateDevSkill(skillId, sandboxVersionId, versionData);

    if (response.success) {
      return {
        success: true,
        data: response.data as UpdateDevVersionResponse['data'],
      };
    } else {
      return {
        success: false,
        error: {
          message: response.error?.message || 'Unknown error',
          error: response.error?.message || 'Unknown error',
          statusCode: response.error?.statusCode || 500,
        },
      };
    }
  } catch (error) {
    console.error('Network error updating dev version:', error);
    return {
      success: false,
      error: {
        message: 'Network error',
        error: error instanceof Error ? error.message : 'Failed to connect to server',
        statusCode: 500,
      },
    };
  }
}

/**
 * Creates a new sandbox version.
 *
 * @param apiKey - User's API key
 * @param agentId - Agent ID
 * @param skillId - Skill ID
 * @param versionData - Version data to create
 * @returns Dev version response
 */
export async function pushDevVersion(
  apiKey: string,
  agentId: string,
  skillId: string,
  versionData: any
): Promise<DevVersionResponse> {
  try {
    const skillsApi = new SkillApi(BASE_URLS.API, apiKey, agentId);
    const response = await skillsApi.pushDevSkill(skillId, versionData);

    if (response.success) {
      return {
        success: true,
        data: response.data as DevVersionResponse['data'],
      };
    } else {
      return {
        success: false,
        error: {
          message: response.error?.message || 'Unknown error',
          error: response.error?.message || 'Unknown error',
          statusCode: response.error?.statusCode || 500,
        },
      };
    }
  } catch (error) {
    console.error('❌ Network error pushing dev version:', error);
    return {
      success: false,
      error: {
        message: 'Network error',
        error: error instanceof Error ? error.message : 'Failed to connect to server',
        statusCode: 500,
      },
    };
  }
}

/**
 * Pushes a single skill to the sandbox.
 * Attempts to update existing sandbox version, creates new one if update fails.
 *
 * @param apiKey - User's API key
 * @param agentId - Agent ID
 * @param skillId - Skill ID
 * @param skillData - Skill data to push
 * @param isInitial - Whether this is the initial push (affects logging)
 * @returns True if successful, false otherwise
 */
export async function pushSingleSkillToSandbox(
  apiKey: string,
  agentId: string,
  skillId: string,
  skillData: any,
  isInitial: boolean = false
): Promise<boolean> {
  const skillName = skillData.name || 'Unknown Skill';
  const sandboxSkillId = await getSandboxSkillId(skillName);

  // Load environment variables
  const envVars = loadEnvironmentVariables();

  const payloadWithNameAndEnv = {
    ...skillData,
    name: skillName,
    env: envVars,
  };

  if (sandboxSkillId) {
    // Try to update existing sandbox version
    if (!isInitial) {
      writeProgress('🔄 Updating existing sandbox version...');
    }
    const updateResult = await updateDevVersion(apiKey, agentId, skillId, sandboxSkillId, payloadWithNameAndEnv);

    if (updateResult.success && updateResult.data) {
      if (!isInitial) {
        // writeSuccess(`✅ Version ${updateResult.data.version} updated in sandbox successfully`);
        // writeSuccess(`🔑 Sandbox Skill ID: ${updateResult.data.skillId}`);
      }
      return true;
    } else if (updateResult.error) {
      writeProgress('⚠️  Failed to update existing sandbox, creating new one...');
      console.error(`❌ Sandbox update failed: ${updateResult.error.message}`);
      if (updateResult.error.error) {
        console.error(`   Details: ${updateResult.error.error}`);
      }

      // Only show the "run lua push first" guidance when the error is literally
      // "Skill not found" (the parent skill doesn't exist on the server). Other
      // 4xx responses (e.g. an expired sandbox version, validation errors) shouldn't
      // trigger this misleading prompt — the fall-through CREATE below will handle
      // the recoverable cases silently.
      if (updateResult.error.message.includes('Skill not found')) {
        console.error("\n💡 The skill doesn't exist on the server.");
        console.error('   Please run "lua push" first to deploy your skill, then try "lua dev" again.\n');
      }
      // Fall through to create new sandbox
    }
  }

  // Create new sandbox version (either no existing ID or update failed)
  if (!isInitial) {
    writeProgress('🔄 Creating new sandbox version...');
  }
  const result = await pushDevVersion(apiKey, agentId, skillId, payloadWithNameAndEnv);

  if (result.success && result.data) {
    // Store the new sandbox skill ID
    await setSandboxSkillId(result.data.skillId, skillName);
    if (!isInitial) {
      writeSuccess(`✅ Version ${result.data.version} pushed to sandbox successfully`);
      writeSuccess(`🔑 Sandbox Skill ID: ${result.data.skillId}`);
    }
    return true;
  } else if (result.error) {
    console.error(`❌ Sandbox creation failed: ${result.error.message}`);
    if (result.error.error) {
      console.error(`   Details: ${result.error.error}`);
    }
    if (result.error.statusCode) {
      console.error(`   Status Code: ${result.error.statusCode}`);
    }

    // If skill not found, give helpful guidance
    if (
      result.error.message.includes('Skill not found') ||
      result.error.statusCode === 400 ||
      result.error.statusCode === 404
    ) {
      console.error("\n💡 The skill hasn't been deployed to the server yet.");
      console.error('   Please run "lua push" first to deploy your skill, then try "lua dev" again.');
    }
    return false;
  } else {
    console.error('❌ Failed to push version to sandbox. Please try again.');
    return false;
  }
}

/**
 * Pushes multiple skills to the sandbox using manifest format.
 *
 * @param apiKey - User's API key
 * @param agentId - Agent ID
 * @param manifest - Compilation manifest
 * @param yamlConfig - YAML config with skill IDs
 * @param isInitial - Whether this is the initial push
 * @returns Map of skill names to their sandbox IDs
 */
export async function pushSkillsToSandbox(
  apiKey: string,
  agentId: string,
  manifest: CompilationManifest,
  yamlConfig: YamlConfig,
  isInitial: boolean = false
): Promise<SandboxIdsMap> {
  const sandboxIds: SandboxIdsMap = {};

  const skills = getPrimitivesByKind<ManifestSkill>(manifest, PrimitiveKind.SKILL);
  const yamlSkills = skillHandler.getFromYaml(yamlConfig);

  if (skills.length === 0) {
    throw new Error('No skills found in manifest');
  }

  for (const skill of skills) {
    // Get skillId from YAML config
    const yamlSkill = yamlSkills.find((s) => s.name === skill.name);
    const skillId = yamlSkill?.skillId;

    if (!skillId) {
      console.warn(`⚠️  Skipping skill ${skill.name} - no skillId found in lua.skill.yaml`);
      continue;
    }

    // BAC-196: accumulate raw bundles, upload via presigned PUT, and emit
    // codeS3Hash on each tool. Falls back to inline `code` if no bundles.
    const bundleAccumulator = new Map<string, Buffer>();
    const prepared = skillHandler.prepareForPush(manifest, skill.name, undefined, bundleAccumulator);
    if (!prepared) {
      console.warn(`⚠️  Skipping skill ${skill.name} - prepareForPush returned null`);
      continue;
    }

    if (bundleAccumulator.size > 0) {
      try {
        await ensureBundlesUploaded(apiKey, agentId, bundleAccumulator);
      } catch (error) {
        console.error(`❌ Failed to upload bundles for skill ${skill.name}:`, error);
        continue;
      }
    }

    const baseVersion = yamlSkill?.version || '1.0.0';
    const sandboxVersion = baseVersion.endsWith('-sandbox') ? baseVersion : `${baseVersion}-sandbox`;

    const skillData = {
      ...prepared,
      version: sandboxVersion,
    };

    try {
      const success = await pushSingleSkillToSandbox(apiKey, agentId, skillId, skillData, isInitial);
      if (success) {
        const sandboxId = await getSandboxSkillId(skill.name);
        if (sandboxId) {
          sandboxIds[skill.name] = sandboxId;
        }
      }
    } catch (error) {
      console.error(`❌ Failed to push skill ${skill.name}:`, error);
    }
  }

  return sandboxIds;
}

/**
 * Pushes a single preprocessor to the sandbox.
 * Attempts to update existing sandbox version, creates new one if update fails.
 *
 * @param apiKey - User's API key
 * @param agentId - Agent ID
 * @param preprocessorId - PreProcessor ID
 * @param preprocessorData - PreProcessor data to push
 * @param isInitial - Whether this is the initial push (affects logging)
 * @returns True if successful, false otherwise
 */
export async function pushSinglePreProcessorToSandbox(
  apiKey: string,
  agentId: string,
  preprocessorId: string,
  preprocessorData: any,
  isInitial: boolean = false
): Promise<boolean> {
  const preprocessorName = preprocessorData.name || 'Unknown PreProcessor';
  const sandboxPreProcessorId = await getSandboxPreProcessorId(preprocessorName);

  // Ensure version has -sandbox postfix
  const baseVersion = preprocessorData.version || '1.0.0';
  const sandboxVersion = baseVersion.endsWith('-sandbox') ? baseVersion : `${baseVersion}-sandbox`;

  const payload = {
    name: preprocessorName,
    version: sandboxVersion,
    description: preprocessorData.description,
    ...(preprocessorData.codeS3Hash ? { codeS3Hash: preprocessorData.codeS3Hash } : { code: preprocessorData.code }),
    async: Boolean(preprocessorData.async ?? false),
  };

  if (sandboxPreProcessorId) {
    // Try to update existing sandbox version
    if (!isInitial) {
      writeProgress(`🔄 Updating existing preprocessor sandbox version...`);
    }

    const api = new PreProcessorApi(BASE_URLS.API, apiKey, agentId);
    const updateResult = await api.updateDevPreProcessor(preprocessorId, sandboxPreProcessorId, payload);

    if (updateResult.success && updateResult.data) {
      return true;
    } else {
      if (!isInitial) {
        writeProgress('⚠️  Failed to update preprocessor sandbox, creating new one...');
      }
    }
  }

  // Create new sandbox version
  if (!isInitial) {
    writeProgress(`🔄 Creating new preprocessor sandbox version...`);
  }

  const api = new PreProcessorApi(BASE_URLS.API, apiKey, agentId);
  const result = await api.pushDevPreProcessor(preprocessorId, payload);

  if (result.success && result.data) {
    // Store the new sandbox preprocessor ID
    await setSandboxPreProcessorId(result.data.versionId, preprocessorName);
    return true;
  } else if (result.error) {
    console.error(`❌ PreProcessor sandbox push failed: ${result.error.message}`);
    return false;
  }

  return false;
}

