/**
 * Pushes preprocessors and postprocessors to sandbox using manifest format.
 *
 * @param apiKey - User's API key
 * @param agentId - Agent ID
 * @param manifest - Compilation manifest
 * @param yamlConfig - YAML config with processor IDs
 * @param isInitial - Whether this is the initial push
 * @returns Object with counts of pushed processors
 */
export async function pushProcessorsToSandbox(
  apiKey: string,
  agentId: string,
  manifest: CompilationManifest,
  yamlConfig: YamlConfig,
  isInitial: boolean = false
): Promise<{ preprocessors: number; postprocessors: number }> {
  let preprocessorCount = 0;
  let postprocessorCount = 0;

  const preprocessors = getPrimitivesByKind<ManifestPreProcessor>(manifest, PrimitiveKind.PREPROCESSOR);
  const postprocessors = getPrimitivesByKind<ManifestPostProcessor>(manifest, PrimitiveKind.POSTPROCESSOR);
  const configPreProcessors = yamlConfig?.preprocessors || [];
  const configPostProcessors = yamlConfig?.postprocessors || [];

  // Phase 1: build bundle map + per-processor payloads (no server calls yet).
  const bundleAccumulator = new Map<string, Buffer>();

  type PreProcessorPayload = {
    preprocessorId: string;
    data: { name: string; description: string; version: string; codeS3Hash: string };
  };
  type PostProcessorPayload = {
    postprocessorId: string;
    data: { name: string; description: string; version: string; codeS3Hash: string };
  };
  const prePayloads: PreProcessorPayload[] = [];
  const postPayloads: PostProcessorPayload[] = [];

  for (const processor of preprocessors) {
    const configProcessor = configPreProcessors.find((p) => p.name === processor.name);
    const preprocessorId = configProcessor?.preprocessorId;

    if (!preprocessorId) {
      console.warn(`⚠️  Skipping preprocessor ${processor.name} - no preprocessorId found`);
      continue;
    }

    const code = loadArtifact(processor, process.cwd());
    const rawGzip = compressForPushRaw(code);
    const hash = hashBundle(rawGzip);
    bundleAccumulator.set(hash, rawGzip);

    prePayloads.push({
      preprocessorId,
      data: {
        name: processor.name,
        description: processor.description,
        version: configProcessor?.version || '1.0.0',
        codeS3Hash: hash,
      },
    });
  }

  for (const processor of postprocessors) {
    const configProcessor = configPostProcessors.find((p) => p.name === processor.name);
    const postprocessorId = configProcessor?.postprocessorId;

    if (!postprocessorId) {
      console.warn(`⚠️  Skipping postprocessor ${processor.name} - no postprocessorId found`);
      continue;
    }

    const code = loadArtifact(processor, process.cwd());
    const rawGzip = compressForPushRaw(code);
    const hash = hashBundle(rawGzip);
    bundleAccumulator.set(hash, rawGzip);

    postPayloads.push({
      postprocessorId,
      data: {
        name: processor.name,
        description: processor.description,
        version: configProcessor?.version || '1.0.0',
        codeS3Hash: hash,
      },
    });
  }

  // Phase 2: upload bundles BEFORE submitting versions (server validates blob
  // exists). On failure, log + skip the per-processor POSTs and return zero
  // counts so the caller's outer `lua dev` / `lua test` flow degrades like a
  // per-item failure rather than crashing the whole run with an unhandled
  // exception. The old (per-processor) upload path had the same isolation via
  // its inner try/catch — keep that property after the batching refactor.
  if (bundleAccumulator.size > 0) {
    if (!isInitial) {
      writeProgress(`📤 Uploading processor bundles to S3...`);
    }
    try {
      await ensureBundlesUploaded(apiKey, agentId, bundleAccumulator);
    } catch (error) {
      console.error('❌ Failed to upload processor bundles to S3:', error);
      return { preprocessors: 0, postprocessors: 0 };
    }
    if (!isInitial) {
      writeSuccess(`✅ Processor bundles uploaded`);
    }
  }

  // Phase 3: now POST each version with codeS3Hash; server hydrates from S3.
  for (const { preprocessorId, data } of prePayloads) {
    try {
      const success = await pushSinglePreProcessorToSandbox(apiKey, agentId, preprocessorId, data, isInitial);
      if (success) preprocessorCount++;
    } catch (error) {
      console.error(`❌ Failed to push preprocessor ${data.name}:`, error);
    }
  }

  for (const { postprocessorId, data } of postPayloads) {
    try {
      const success = await pushSinglePostProcessorToSandbox(apiKey, agentId, postprocessorId, data, isInitial);
      if (success) postprocessorCount++;
    } catch (error) {
      console.error(`❌ Failed to push postprocessor ${data.name}:`, error);
    }
  }

  return { preprocessors: preprocessorCount, postprocessors: postprocessorCount };
}
