/**
 * PreProcessors Command
 * Manages agent preprocessors for production environment
 */

import { withErrorHandling, writeProgress, writeSuccess, writeInfo, writeHintBlock } from '../utils/cli.js';
import { BASE_URLS } from '../config/constants.js';
import { safePrompt } from '../utils/prompt-handler.js';
import { initializeCommand } from '../utils/command-utils.js';
import PreProcessorApi from '../api/preprocessor.api.service.js';
import { preprocessorHandler } from '../primitives/preprocessor.handler.js';
import { YamlConfig } from '../types/yaml.types.js';
import { trackEvent } from '../services/analytics.js';
import { validateOrSuggest } from '../utils/aliases.js';

interface PreProcessorsCommandContext {
  agentId: string;
  apiKey: string;
}

interface PreProcessorsOptions {
  preprocessorName?: string;
  preprocessorVersion?: string;
}

type PreProcessorAction = 'view' | 'versions' | 'deploy' | 'activate' | 'deactivate' | 'delete';

// ─────────────────────────────────────────────────────────────────────────────
// Main Command Entry
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Main preprocessors command - manages agent preprocessors.
 *
 * Supports both interactive and non-interactive modes:
 * - Interactive: prompts for action and preprocessor selection
 * - Non-interactive: use action argument with -i and -v flags
 */
export async function preprocessorsCommand(action?: string, cmdObj?: any): Promise<void> {
  return withErrorHandling(async () => {
    const options: PreProcessorsOptions = {
      preprocessorName: cmdObj?.preprocessorName || null,
      preprocessorVersion: cmdObj?.preprocessorVersion || null,
    };

    // Initialize command (validates config + auth)
    const { config, agentId, apiKey } = await initializeCommand();

    const context: PreProcessorsCommandContext = {
      agentId,
      apiKey,
    };

    // Determine mode
    if (action) {
      await executeNonInteractive(context, config, action, options);
    } else {
      await managePreProcessorsInteractive(context, config);
    }
    trackEvent('cli_preprocessors_action', {
      action: action || 'interactive',
      preprocessor_name: options.preprocessorName || null,
      non_interactive: !!action,
    });
  }, 'preprocessors');
}

// ─────────────────────────────────────────────────────────────────────────────
// Shared Core Functions
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Displays all preprocessors with their current status.
 */
async function displayPreProcessorsCore(context: PreProcessorsCommandContext, preprocessors: any[]): Promise<void> {
  console.log('\n' + '='.repeat(60));
  console.log('⚙️  Production PreProcessors');
  console.log('='.repeat(60) + '\n');

  const api = new PreProcessorApi(BASE_URLS.API, context.apiKey, context.agentId);

  for (const preprocessor of preprocessors) {
    try {
      const response = await api.getPreProcessorVersions(preprocessor.preprocessorId);

      if (response.success && response.data) {
        const versions = response.data.versions || [];
        const activeVersionId = response.data.activeVersionId;
        const activeVersion = versions.find((v: any) => v.versionId === activeVersionId);

        console.log(`📥 ${preprocessor.name}`);
        console.log(`   PreProcessor ID: ${preprocessor.preprocessorId}`);

        if (activeVersion) {
          console.log(`   Deployed Version: ${activeVersion.version} ⭐`);
          console.log(`   Deployed: ${new Date(activeVersion.createdAt).toLocaleString()}`);
        } else {
          console.log(`   Deployed Version: Not deployed`);
        }

        console.log(`   Total Versions: ${versions.length}`);
        console.log();
      } else {
        displayPreProcessorError(preprocessor, 'Unable to fetch version info');
      }
    } catch {
      displayPreProcessorError(preprocessor, 'Error loading versions');
    }
  }

  console.log('='.repeat(60));
}

function displayPreProcessorError(preprocessor: any, status: string): void {
  console.log(`📥 ${preprocessor.name}`);
  console.log(`   PreProcessor ID: ${preprocessor.preprocessorId}`);
  console.log(`   Status: ${status}`);
  console.log();
}

/**
 * Fetches and returns sorted preprocessor versions.
 */
async function fetchVersionsCore(
  context: PreProcessorsCommandContext,
  preprocessor: any
): Promise<{ versions: any[]; activeVersionId: string | undefined } | null> {
  const api = new PreProcessorApi(BASE_URLS.API, context.apiKey, context.agentId);
  const response = await api.getPreProcessorVersions(preprocessor.preprocessorId);

  if (!response.success || !response.data) {
    console.error(`❌ Failed to fetch versions: ${response.error?.message || 'Unknown error'}`);
    return null;
  }

  const versions = (response.data.versions || []).sort(
    (a: any, b: any) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime()
  );

  return { versions, activeVersionId: response.data.activeVersionId };
}

/**
 * Displays versions for a preprocessor.
 */
function displayVersionsCore(preprocessor: any, versions: any[], activeVersionId: string | undefined): void {
  console.log('\n' + '='.repeat(60));
  console.log(`📜 Versions for ${preprocessor.name}`);
  console.log('='.repeat(60) + '\n');

  versions.forEach((version: any, index: number) => {
    const isActive = version.versionId === activeVersionId;
    console.log(`${index + 1}. Version ${version.version}${isActive ? ' ⭐ DEPLOYED' : ''}`);
    console.log(`   Created: ${new Date(version.createdAt).toLocaleString()}`);
    console.log();
  });

  console.log('='.repeat(60));
}

/**
 * Deploys a specific version of a preprocessor.
 */
async function deployVersionCore(
  context: PreProcessorsCommandContext,
  preprocessor: any,
  version: string
): Promise<boolean> {
  writeProgress(`🔄 Deploying version ${version} of "${preprocessor.name}"...`);

  const api = new PreProcessorApi(BASE_URLS.API, context.apiKey, context.agentId);
  const deployResponse = await api.publishPreProcessorVersion(preprocessor.preprocessorId, version);

  if (!deployResponse.success) {
    console.error(`❌ Deploy Error: ${deployResponse.error?.message || 'Unknown error'}`);
    return false;
  }

  writeSuccess(`✅ Version ${version} of "${preprocessor.name}" deployed successfully`);
  writeHintBlock({
    headline: 'Preprocessor is live. Send a test message to trigger it:',
    lines: [
      { label: 'Test:', command: 'lua chat -e production -m "test"' },
      { label: 'Inspect:', command: `lua logs --type preprocessor --name ${preprocessor.name} --limit 10` },
    ],
    when: 'success',
  });
  return true;
}

/**
 * Activates a preprocessor.
 */
async function activatePreProcessorCore(context: PreProcessorsCommandContext, preprocessor: any): Promise<boolean> {
  writeProgress(`🔄 Activating preprocessor "${preprocessor.name}"...`);

  const api = new PreProcessorApi(BASE_URLS.API, context.apiKey, context.agentId);
  const response = await api.activatePreProcessor(preprocessor.preprocessorId);

  if (response.success) {
    writeSuccess(`✅ PreProcessor "${preprocessor.name}" activated successfully`);
    writeInfo('💡 The preprocessor is now enabled and will process all incoming messages.');
    return true;
  } else {
    console.error(`❌ Failed to activate preprocessor: ${response.error?.message || 'Unknown error'}`);
    return false;
  }
}

/**
 * Deactivates a preprocessor.
 */
async function deactivatePreProcessorCore(context: PreProcessorsCommandContext, preprocessor: any): Promise<boolean> {
  writeProgress(`🔄 Deactivating preprocessor "${preprocessor.name}"...`);

  const api = new PreProcessorApi(BASE_URLS.API, context.apiKey, context.agentId);
  const response = await api.deactivatePreProcessor(preprocessor.preprocessorId);

  if (response.success) {
    writeSuccess(`✅ PreProcessor "${preprocessor.name}" deactivated successfully`);
    writeInfo('💡 The preprocessor is now disabled.');
    return true;
  } else {
    console.error(`❌ Failed to deactivate preprocessor: ${response.error?.message || 'Unknown error'}`);
    return false;
  }
}

/**
 * Deletes a preprocessor.
 */
async function deletePreProcessorCore(context: PreProcessorsCommandContext, preprocessor: any): Promise<boolean> {
  writeProgress(`🔄 Deleting preprocessor "${preprocessor.name}"...`);

  const api = new PreProcessorApi(BASE_URLS.API, context.apiKey, context.agentId);
  const response = await api.deletePreProcessor(preprocessor.preprocessorId);

  if (response.success) {
    if (response.data?.deleted) {
      writeSuccess(`✅ PreProcessor "${preprocessor.name}" deleted successfully`);
    } else if (response.data?.deactivated) {
      writeInfo(
        `⚠️  PreProcessor "${preprocessor.name}" has versions and cannot be deleted. It has been deactivated instead.`
      );
    }
    return true;
  } else {
    console.error(`❌ Failed to delete preprocessor: ${response.error?.message || 'Unknown error'}`);
    return false;
  }
}

/**
 * Resolves a version string to an actual version, supporting "latest".
 */
function resolveVersion(versions: any[], versionArg: string): string | null {
  if (versionArg.toLowerCase() === 'latest') {
    return versions[0].version;
  }

  const exists = versions.some((v: any) => v.version === versionArg);
  if (!exists) {
    console.error(`❌ Version "${versionArg}" not found`);
    console.log('\nAvailable versions:');
    versions.slice(0, 5).forEach((v: any) => console.log(`  - ${v.version}`));
    return null;
  }
  return versionArg;
}

/**
 * Prompts user to select a preprocessor from a list.
 */
async function promptPreProcessorSelection(preprocessors: any[], message: string): Promise<any | null> {
  const answer = await safePrompt<{ selected: any }>([
    {
      type: 'list',
      name: 'selected',
      message,
      choices: preprocessors.map((p: any) => ({
        name: `${p.name} (${p.preprocessorId})`,
        value: p,
      })),
    },
  ]);
  return answer?.selected || null;
}

/**
 * Prompts user to select a version from a list.
 */
async function promptVersionSelection(versions: any[], activeVersionId: string | undefined): Promise<any | null> {
  const answer = await safePrompt<{ selectedVersion: any }>([
    {
      type: 'list',
      name: 'selectedVersion',
      message: 'Select a version to deploy:',
      choices: versions.map((version: any) => {
        const isActive = version.versionId === activeVersionId;
        return {
          name: `Version ${version.version} (${new Date(version.createdAt).toLocaleDateString()})${isActive ? ' ⭐ CURRENT' : ''}`,
          value: version,
        };
      }),
    },
  ]);
  return answer?.selectedVersion || null;
}

// ─────────────────────────────────────────────────────────────────────────────
// Non-Interactive Mode
// ─────────────────────────────────────────────────────────────────────────────

async function executeNonInteractive(
  context: PreProcessorsCommandContext,
  config: YamlConfig,
  action: string,
  options: PreProcessorsOptions
): Promise<void> {
  const normalizedAction = validateOrSuggest('preprocessors.action', action);

  const preprocessors = config.preprocessors || [];

  // View action doesn't require preprocessor selection
  if (normalizedAction === 'view') {
    if (preprocessors.length === 0) {
      console.log('ℹ️  No preprocessors found in configuration.');
      return;
    }
    await displayPreProcessorsCore(context, preprocessors);
    return;
  }

  // All other actions require preprocessor selection
  if (!options.preprocessorName) {
    console.error(`❌ --preprocessor-name is required for action "${normalizedAction}"`);
    console.log(`\nUsage: lua preprocessors ${normalizedAction} --preprocessor-name <name>`);
    throw new Error(`--preprocessor-name is required for action "${normalizedAction}"`);
  }

  let selected = preprocessors.find(
    (p) => p.preprocessorId === options.preprocessorName || p.name === options.preprocessorName
  );

  if (!selected && normalizedAction === 'delete') {
    const api = new PreProcessorApi(BASE_URLS.API, context.apiKey, context.agentId);
    const serverResponse = await api.getPreProcessors();
    if (serverResponse.success && serverResponse.data?.preprocessors) {
      const serverPre = serverResponse.data.preprocessors.find(
        (p) => p.id === options.preprocessorName || p.name === options.preprocessorName
      );
      if (serverPre) {
        const activeVersion = serverPre.versions.find((v) => v.isActive) ?? serverPre.versions[0];
        selected = { name: serverPre.name, preprocessorId: serverPre.id, version: activeVersion?.version ?? '' };
      }
    }
  }

  if (!selected) {
    console.error(`❌ PreProcessor "${options.preprocessorName}" not found`);
    console.log('\nAvailable preprocessors:');
    preprocessors.forEach((p) => console.log(`  - ${p.name} (${p.preprocessorId})`));
    throw new Error(`PreProcessor "${options.preprocessorName}" not found`);
  }

  switch (normalizedAction as PreProcessorAction) {
    case 'versions': {
      const data = await fetchVersionsCore(context, selected);
      if (!data) throw new Error('Failed to fetch preprocessor versions');
      if (data.versions.length === 0) {
        console.log(`ℹ️  No versions found for ${selected.name}.`);
        console.log("💡 Push a version first using 'lua push preprocessor'.");
        return;
      }
      displayVersionsCore(selected, data.versions, data.activeVersionId);
      break;
    }
    case 'deploy': {
      if (!options.preprocessorVersion) {
        console.error('❌ --preprocessor-version is required for deploy action');
        console.log('\nUsage: lua preprocessors deploy --preprocessor-name myPre --preprocessor-version 1.0.3');
        console.log('       lua preprocessors deploy -i myPre -v latest');
        throw new Error('--preprocessor-version is required for deploy action');
      }
      const data = await fetchVersionsCore(context, selected);
      if (!data) throw new Error('Failed to fetch preprocessor versions');
      if (data.versions.length === 0) {
        console.error(`❌ No versions found for ${selected.name}.`);
        console.log("💡 Push a version first using 'lua push preprocessor'.");
        throw new Error(`No versions found for ${selected.name}`);
      }
      const resolvedVersion = resolveVersion(data.versions, options.preprocessorVersion);
      if (!resolvedVersion) throw new Error('Failed to resolve preprocessor version');
      const success = await deployVersionCore(context, selected, resolvedVersion);
      if (!success) throw new Error('Failed to deploy preprocessor version');
      break;
    }
    case 'activate': {
      const success = await activatePreProcessorCore(context, selected);
      if (!success) throw new Error('Failed to activate preprocessor');
      break;
    }
    case 'deactivate': {
      const success = await deactivatePreProcessorCore(context, selected);
      if (!success) throw new Error('Failed to deactivate preprocessor');
      break;
    }
    case 'delete': {
      const success = await deletePreProcessorCore(context, selected);
      if (!success) throw new Error('Failed to delete preprocessor');
      break;
    }
  }
}

// ─────────────────────────────────────────────────────────────────────────────
// Interactive Mode
// ─────────────────────────────────────────────────────────────────────────────

async function managePreProcessorsInteractive(context: PreProcessorsCommandContext, config: YamlConfig): Promise<void> {
  let continueManaging = true;

  while (continueManaging) {
    console.log('\n' + '='.repeat(60));
    console.log('🚀 Production PreProcessors');
    console.log('='.repeat(60) + '\n');

    const actionAnswer = await safePrompt<{ action: string }>([
      {
        type: 'list',
        name: 'action',
        message: 'What would you like to do?',
        choices: [
          { name: '👁️  View deployed preprocessors', value: 'view' },
          { name: '📜 View preprocessor versions', value: 'versions' },
          { name: '🚀 Deploy a version', value: 'deploy' },
          { name: '✅ Activate a preprocessor', value: 'activate' },
          { name: '🚫 Deactivate a preprocessor', value: 'deactivate' },
          { name: '🗑️  Delete a preprocessor', value: 'delete' },
          { name: '❌ Exit', value: 'exit' },
        ],
      },
    ]);

    if (!actionAnswer) return;
    const { action } = actionAnswer;

    switch (action) {
      case 'view':
        await viewPreProcessorsInteractive(context, config);
        break;
      case 'versions':
        await viewVersionsInteractive(context, config);
        break;
      case 'deploy':
        await deployVersionInteractive(context, config);
        break;
      case 'activate':
        await activatePreProcessorInteractive(context, config);
        break;
      case 'deactivate':
        await deactivatePreProcessorInteractive(context, config);
        break;
      case 'delete':
        await deletePreProcessorInteractive(context, config);
        break;
      case 'exit':
        continueManaging = false;
        console.log('\n👋 Goodbye!\n');
        break;
    }
  }
}

async function viewPreProcessorsInteractive(context: PreProcessorsCommandContext, config: YamlConfig): Promise<void> {
  writeProgress('🔄 Loading preprocessor information...');
  const preprocessors = config.preprocessors || [];

  if (preprocessors.length === 0) {
    console.log('\nℹ️  No preprocessors found in configuration.\n');
  } else {
    await displayPreProcessorsCore(context, preprocessors);
    console.log();
  }

  await safePrompt([{ type: 'input', name: 'continue', message: 'Press Enter to continue...' }]);
}

async function viewVersionsInteractive(context: PreProcessorsCommandContext, config: YamlConfig): Promise<void> {
  const preprocessors = config.preprocessors || [];

  if (preprocessors.length === 0) {
    console.log('\nℹ️  No preprocessors found in configuration.\n');
    await safePrompt([{ type: 'input', name: 'continue', message: 'Press Enter to continue...' }]);
    return;
  }

  const selected = await promptPreProcessorSelection(preprocessors, 'Select a preprocessor to view versions:');
  if (!selected) return;

  writeProgress(`🔄 Loading versions for ${selected.name}...`);
  const data = await fetchVersionsCore(context, selected);

  if (!data) {
    await safePrompt([{ type: 'input', name: 'continue', message: 'Press Enter to continue...' }]);
    return;
  }

  if (data.versions.length === 0) {
    console.log(`\nℹ️  No versions found for ${selected.name}.\n`);
    console.log("💡 Push a version first using 'lua push preprocessor'.\n");
  } else {
    displayVersionsCore(selected, data.versions, data.activeVersionId);
    console.log();
  }

  await safePrompt([{ type: 'input', name: 'continue', message: 'Press Enter to continue...' }]);
}

async function deployVersionInteractive(context: PreProcessorsCommandContext, config: YamlConfig): Promise<void> {
  const preprocessors = config.preprocessors || [];

  if (preprocessors.length === 0) {
    console.log('\nℹ️  No preprocessors found in configuration.\n');
    await safePrompt([{ type: 'input', name: 'continue', message: 'Press Enter to continue...' }]);
    return;
  }

  const selected = await promptPreProcessorSelection(preprocessors, 'Select a preprocessor to deploy:');
  if (!selected) return;

  writeProgress(`🔄 Loading versions for ${selected.name}...`);
  const data = await fetchVersionsCore(context, selected);

  if (!data) {
    await safePrompt([{ type: 'input', name: 'continue', message: 'Press Enter to continue...' }]);
    return;
  }

  if (data.versions.length === 0) {
    console.log(`\nℹ️  No versions found for ${selected.name}.\n`);
    console.log("💡 Push a version first using 'lua push preprocessor'.\n");
    await safePrompt([{ type: 'input', name: 'continue', message: 'Press Enter to continue...' }]);
    return;
  }

  const selectedVersion = await promptVersionSelection(data.versions, data.activeVersionId);
  if (!selectedVersion) return;

  // Show warning and confirm
  console.log('\n⚠️  WARNING: You are about to deploy to PRODUCTION!');
  console.log('⚠️  This will affect ALL users immediately.\n');
  console.log(`PreProcessor: ${selected.name}`);
  console.log(`Version: ${selectedVersion.version}\n`);

  const confirmAnswer = await safePrompt<{ confirm: boolean }>([
    {
      type: 'confirm',
      name: 'confirm',
      message: 'Are you absolutely sure you want to deploy this version?',
      default: false,
    },
  ]);

  if (!confirmAnswer || !confirmAnswer.confirm) {
    console.log('\n❌ Deployment cancelled.\n');
    return;
  }

  await deployVersionCore(context, selected, selectedVersion.version);
  await safePrompt([{ type: 'input', name: 'continue', message: 'Press Enter to continue...' }]);
}

async function activatePreProcessorInteractive(
  context: PreProcessorsCommandContext,
  config: YamlConfig
): Promise<void> {
  const preprocessors = config.preprocessors || [];

  if (preprocessors.length === 0) {
    console.log('\nℹ️  No preprocessors found.\n');
    return;
  }

  const selected = await promptPreProcessorSelection(preprocessors, 'Select a preprocessor to activate:');
  if (!selected) return;

  await activatePreProcessorCore(context, selected);
}

async function deactivatePreProcessorInteractive(
  context: PreProcessorsCommandContext,
  config: YamlConfig
): Promise<void> {
  const preprocessors = config.preprocessors || [];

  if (preprocessors.length === 0) {
    console.log('\nℹ️  No preprocessors found.\n');
    return;
  }

  const selected = await promptPreProcessorSelection(preprocessors, 'Select a preprocessor to deactivate:');
  if (!selected) return;

  const confirmAnswer = await safePrompt<{ confirm: boolean }>([
    {
      type: 'confirm',
      name: 'confirm',
      message: `Are you sure you want to deactivate "${selected.name}"? Messages will not be preprocessed.`,
      default: false,
    },
  ]);

  if (!confirmAnswer || !confirmAnswer.confirm) {
    console.log('\n❌ Deactivation cancelled.\n');
    return;
  }

  await deactivatePreProcessorCore(context, selected);
}

async function deletePreProcessorInteractive(context: PreProcessorsCommandContext, config: YamlConfig): Promise<void> {
  const { merged, orphanIds, serverFailed } = await preprocessorHandler.fetchMergedForInteraction(
    context.apiKey,
    context.agentId,
    config
  );
  if (serverFailed) {
    console.log('\n⚠️  Could not reach server. Showing local items only.\n');
  }

  if (merged.length === 0) {
    console.log('\nℹ️  No preprocessors found.\n');
    return;
  }

  const answer = await safePrompt<{ selected: (typeof merged)[number] }>([
    {
      type: 'list',
      name: 'selected',
      message: 'Select a preprocessor to delete:',
      choices: merged.map((item) => ({
        name: orphanIds.has(item.preprocessorId)
          ? `${item.name} (${item.preprocessorId}) [server only]`
          : `${item.name} (${item.preprocessorId})`,
        value: item,
      })),
    },
  ]);
  const selected = answer?.selected ?? null;
  if (!selected) return;

  const confirmAnswer = await safePrompt<{ confirm: boolean }>([
    {
      type: 'confirm',
      name: 'confirm',
      message: `⚠️  Are you sure you want to DELETE "${selected.name}"? This cannot be undone.`,
      default: false,
    },
  ]);

  if (!confirmAnswer || !confirmAnswer.confirm) {
    console.log('\n❌ Deletion cancelled.\n');
    return;
  }

  await deletePreProcessorCore(context, selected);
}
